  AwakerStory_100416_Content = {
    Text = "সমাধি-অস্থি নগর থেকে সেই আমন্ত্রণ পাওয়ার আগে, পিকম্যান ভেবেছিল এই পৃথিবীতে তার মতো মানুষের জন্য কোনো আশ্রয়স্থল কখনোই থাকবে না।\nরাজপ্রাসাদের ভোজসভায় যে চরম উন্মাদনার দৃশ্য সে দেখেছিল, তা তাকে রাতের পর রাত নিদ্রাহীন করে রেখেছিল। ভিন্ন জগতের দৃশ্য দেখতে সক্ষম সেই চোখদুটি এই ভোজসভায় প্রকৃত তৃপ্তি লাভ করেছিল।\nযখন সে স্বপ্ন থেকে জেগে উঠল এবং সমাধি-অস্থি নগর তার চোখের সামনে থেকে মিলিয়ে গেল, পিকম্যানের আক্ষেপ দ্রুতই অন্তহীন আকাঙ্ক্ষায় রূপ নিল — সে আকুল হয়ে উঠল আবার সেই স্বপ্নের নগরীতে যেতে, আবার সেই অন্তহীন উন্মাদনার অপরূপ দৃশ্য দেখতে। এই আকাঙ্ক্ষার পথ ধরে সে সমস্ত উন্মত্ত কাজ করার চেষ্টা করল। অবশেষে, সে ক্ষয়-ফাটলে ঝাঁপ দিল, ক্ষয়-তরল দিয়ে ছবি আঁকল, নিজেকে সম্পূর্ণরূপে সেই ভয়ংকর কালো অন্ধকারের কাছে উন্মুক্ত করল।\nপ্রত্যেকেরই নিজের সম্পন্ন করার মতো কাজ আছে। তার কাছে এমন চোখ ছিল যা পৃথিবীর উন্মাদ সত্য দেখতে পেত, সে দৃঢ়ভাবে বিশ্বাস করত যে সে জন্মগ্রহণ করেছে শিল্পের জন্য দগ্ধ হতে — এটাই তার নিয়তি।\nতার ইচ্ছানুসারে, ক্ষয় তার জন্য উন্মাদনা ও যন্ত্রণা নিয়ে এল, এবং তাকে আবার সমাধি-অস্থি নগরে অনুভব করা সেই দৃশ্যগুলো দেখাল। তার চোখে সেই বিপর্যস্ত জগৎ ক্ষয়ের আগ্রাসনে আরও বন্য ও বর্ণময় হয়ে উঠল। দীর্ঘ যন্ত্রণার মধ্যে সে তুলি তুলে নিল, দিনের পর দিন, এক মুহূর্তও না থেমে আঁকতে লাগল। সে ছিল একজন কর্তব্যনিষ্ঠ বাস্তববাদী চিত্রশিল্পী, তাকে অবশ্যই এই কেবল তার দেখা দৃশ্যগুলো নথিবদ্ধ করতে হবে।\nযন্ত্রণা ক্রমশ তীব্রতর হলো, যখন পিকম্যান আর হাতের তুলি শক্ত করে ধরতে পারছিল না, সে বুঝতে পারল তার সময় ফুরিয়ে আসছে। শেষ চিত্রকর্মের শেষ আঁচড় সম্পন্ন করার পর, সে আগে থেকেই প্রস্তুত করে রাখা কফিনে শুয়ে পড়ল, মৃত্যুর আগমনের অপেক্ষায়।\nক্ষয়ের আনা যন্ত্রণা ও বিশৃঙ্খলা পিকম্যানের মস্তিষ্ককে ঘোলাটে করে দিল, মৃত্যুর শীতল আলিঙ্গনে সে শান্তভাবে চোখ বন্ধ করল। কিন্তু পরদিন, উজ্জ্বল চাঁদের আলো আবার তাকে জাগিয়ে তুলল। ক্ষয়ের চিহ্ন ও যন্ত্রণা অলৌকিকভাবে মিলিয়ে গেল। কয়েক দিনব্যাপী রূপান্তরে তার অঙ্গ-প্রত্যঙ্গ দীর্ঘ ও বাঁকা হয়ে গেল, তার শ্বদন্ত ও ধারালো নখর কঠিন ও তীক্ষ্ণ হয়ে উঠল। সে কবর ও আত্মার গন্ধ পেল, পৃথিবীর উন্মাদ বিশৃঙ্খল দৃশ্য তার চোখে আগে কখনো হয়নি এমন স্পষ্ট হয়ে উঠল।\nসে আনন্দে তার অর্ধ-মানব অর্ধ-ঘূল দেহের দিকে তাকাল, বিপুল সুখানুভূতি তার হৃদয়ে ঢেউ তুলল। ভাগ্য তার উপর অভিশাপ নামিয়ে এনেছিল, আবার সেই অভিশাপের ক্ষতিপূরণ হিসেবে তাকে দিয়েছিল বিরল প্রতিভা। সমাধি-অস্থি নগরের অভিজ্ঞতা তার দেহের ভেতরে ঘূলের ক্ষীণ রক্তধারাকে জাগ্রত করেছিল, এবং ক্ষয়ের প্রভাবে সে তার রূপান্তর সম্পন্ন করেছিল।\nচারপাশের সমাধিপাথরগুলো যেন উৎসবে মিলিত জনতার মতো, তাকে ঘিরে আনাড়ি নৃত্য করছিল। বিশাল রক্তচাঁদ তার রক্তবর্ণ চোখ মেলে তার দিকে হাসল। তার শিল্প এই পৃথিবীর নয়, এখন সে জানে সে কোথায় যাবে।\nপিকম্যান তার নিজের কফিনের উপর শুয়ে পড়ল, দুই বাহু প্রসারিত করে এই নিঃসঙ্গ উৎসবে যোগ দিল।\nসে মানুষের শহর ছেড়ে যাবে, সেই প্রতিশ্রুত ভূমিতে যাবে যা তার জন্যই।\nসে জানে, সে যা কিছু অন্বেষণ করেছে, সবই সেখানে তার জন্য অপেক্ষা করছে।"
  },
  AwakerStory_100416_Title = {
    Text = "গল্প: ৩"
