  AwakerStory_100416_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_100417_Content = {
    Text = "অর্ধ-মানব অর্ধ-ঘূল এই চিত্রকর এমন এক প্রতিভার অধিকারী যা অন্যদের পক্ষে অর্জন করা প্রায় অসম্ভব। তাঁর আঁকা ঘূলের চিত্রকর্মগুলো চিত্রের জগৎ ও বাস্তব জগতের সীমানা ঝাপসা করে দিতে পারে, দর্শকদের সত্যিকার অর্থেই সেই দৃশ্যের মধ্যে নিয়ে যায়।\nতবে পিকম্যান কখনোই উন্মাদ পরাবাস্তববাদী চিত্রকর এই উপাধি মেনে নেননি। তাঁর ঘোষণায়, শুরু থেকে শেষ পর্যন্ত, তিনি সর্বদাই একজন বাস্তববাদী শিল্পী যিনি কেবল বাস্তব জগৎকেই চিত্রিত করেন।"
  },
  AwakerStory_100417_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_100417_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_100418_Content = {
    Text = "ভিন্নজাতি। বিকৃত। দানবের রক্ত বহনকারী কুলাঙ্গার। শিল্পকে কলুষিত করা এক পাগল……\nপিকম্যানের চোখের সামনে একটি ক্যানভাস মেলে ধরা হলো, গালাগালি আর অন্যান্য শব্দ মিলে ক্যানভাসে উজ্জ্বল রঙের প্রলেপ দিল।\nসে এই বর্ণিল জগতে ঝাঁপ দিল, উন্মত্ত রঙের মাঝে বিচরণ করল। সে আকুলভাবে চাইত অন্যদের নিজের চিত্রকর্মে নিয়ে আসতে, তাদের দেখাতে পৃথিবীর সবচেয়ে সত্যিকার রূপ।\nবাস্তবের অসংখ্য কাঁটা বারবার তার হৃদয় বিদীর্ণ করেছে, মানুষে মানুষে পারস্পরিক বোঝাপড়া দুই জগতের সীমানা খোলার চেয়েও কঠিন।\nমানুষ থেকে ঘূল, মানব নগর থেকে সমাধি নগরী—এই পথ আঁকাবাঁকা ও সুদীর্ঘ। সে বারবার আঘাত পেয়েছে, আবার বারবার উঠে দাঁড়িয়েছে। সে অনেক আগেই বুঝে গেছে, সত্য বলেও কিছু নেই, মিথ্যা বলেও কিছু নেই। যন্ত্রণা আর উন্মাদনাই পৃথিবীর প্রকৃত সত্য। আর তার দায়িত্ব হলো এই সবকিছু বিশ্বস্তভাবে চিত্রিত করা।\nচিত্রণের অর্থ কেবল চিত্রণেই নিহিত।\nসে তার সমস্ত জীবন ও আবেগ চিত্রকলায় উৎসর্গ করেছে। তার প্রত্যাশায় সাড়া মেলে কদাচিৎ, তার অন্বেষণ কখনো থামেনি।"
  },
