  AwakerStory_100418_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_100419_Content = {
    Text = "চারুকলা একাডেমির চিত্রকলা বিভাগের পাঠ্যক্রম ছিল দীর্ঘ ও একঘেয়ে, এর অধিকাংশই আমার জীবনে সামান্যতম ছাপও রেখে যায়নি। কিন্তু A.F.3@2 সালের সেই অনুকরণ চিত্রকলার ক্লাসটি আমি আজও মনে করতে পারি।\nমিস্টার ম্যাথু শিল্প সমিতিতে অত্যন্ত সম্মানিত ছিলেন, তাঁর ক্লাসরুম সর্বদা শিক্ষার্থীতে ঠাসা থাকত। আমরা মাতিসের 'বিলাসিতা, প্রশান্তি ও আনন্দ'-এর সামনে ভিড় করে দাঁড়িয়েছিলাম, তখনই আমি হঠাৎ লক্ষ্য করলাম, কোণায় একজন রোগা যুবক তার স্কেচবুকে উন্মত্তের মতো কিছু আঁকছে। আমি তার কাছে গেলাম, তার অনুকরণ চিত্রটি দেখতে চাইলাম, কিন্তু দেখলাম এক সমাধিক্ষেত্রের বিশৃঙ্খল প্রস্তরমূর্তি।\n「দেখো! প্রসবরত শবভক্ষক রানি, একটি শিশুর রক্তভোজের আয়োজন করছে... কী উন্মাদনা, কী মার্জিত!」\nসে উত্তেজিতভাবে মাথা তুলে আমার দিকে তাকাল, গ্যাসবাতির আলোয় তার চোখের মণি এক অদ্ভুত রক্তবর্ণ ধারণ করেছিল, যেন লাল শ্যাওলায় ঢাকা কোনো কফিন। আমি ভয় পেলাম, মাথা ঘুরে গেল, তবু কিছুতেই চোখ সরাতে পারলাম না। সেই চোখদুটিতে আমি দেখলাম এমন দৃশ্য যা এই পৃথিবীর নয়।\nপিকম্যান, প্রথমবার তাকে দেখার মুহূর্তেই আমি জানতাম, সে আমাদের মতো নয়, তার জীবন কঠিন ও অসাধারণ হতে বাধ্য।\nপরিচয় গভীর হওয়ার পর, আমি মাঝে মাঝে তার স্টুডিওতে যেতাম। আমি নিজের চোখে দেখেছি সে পচা মৃতদেহকে মডেল হিসেবে ব্যবহার করত, নিজের রক্ত দিয়ে রং বানাত। সেই উন্মত্ত চিত্রকর্মগুলোর সামনে দাঁড়ালে আমার মনে হতো ক্যানভাসের ভেতর থেকে কিছু কুরে কুরে খাওয়ার শব্দ ভেসে আসছে।\nশিল্পজগতের কোনো গোষ্ঠীই পিকম্যানের সৃষ্টিকে স্বীকৃতি দেয়নি, সমস্ত প্রদর্শনী ও সালোঁ তাকে প্রত্যাখ্যান করেছে। সে বাহ্যত কিছুই মনে করত না, আশাবাদী ও দৃঢ়ভাবে তার শিল্পের পথে এগিয়ে যেত, কিন্তু তার বিশুদ্ধতাই তাকে কখনো তার হতাশা ও যন্ত্রণা লুকাতে দেয়নি। তার প্রতিভা ছিল বিস্ময়কর এবং ভীতিকর, কেউ সত্যিকার অর্থে তা মেনে নিতে পারেনি, আমিও না।\nচলে যাওয়ার আগের শেষ সময়টুকুতে, পিকম্যান তীব্র যন্ত্রণা ও উত্তেজনার মিশ্র এক অবস্থায় নিমজ্জিত হয়েছিল। আমি ভেবেছিলাম এটা মানসিক সমস্যা যা অবশ্যম্ভাবী ছিল, যতক্ষণ না একদিন আমি নিজের চোখে দেখলাম তার বাঁকানো অঙ্গ-প্রত্যঙ্গ ও ধারালো নখর, নিজের চোখে দেখলাম তার চোখের সেই উন্মত্ত জগৎ। সেই আতঙ্কের মোকাবেলা করার ক্ষমতা আমার ছিল না, আমি কেবল তা ভুলে যাওয়ার চেষ্টা করতে পারতাম। আমি পিকম্যানের সাথে সম্পূর্ণ সম্পর্কচ্ছেদ করার প্রস্তুতি নেওয়ার আগেই, সে নিজে আমাকে খুঁজে বের করল এবং বিদায় জানাল।\nআজ আমি আধুনিক শিল্প জাদুঘরের ঝকঝকে প্রদর্শনী কক্ষে দাঁড়িয়ে, কোণায় ফেলে রাখা পিকম্যানের আসল চিত্রকর্মটির দিকে তাকিয়ে, এখনও ক্যানভাসের গভীর থেকে নখের আঁচড়ের শব্দ শুনতে পাই। 'ভূগর্ভের উন্মত্ত উৎসব'—এটাই সেই ছবি যা পিকম্যান আঁকছিল যখন আমি তাকে প্রথম দেখেছিলাম, এবং এটাই ছিল সে আমাকে দেওয়া বিদায়ের উপহার। পিকম্যানের মধ্যে হয়তো কিছু নিষিদ্ধ রহস্য ছিল যার কাছে যাওয়া উচিত নয়, তবু আমি এই ছবিটি রেখে দিয়েছি। তার সাথে যাই ঘটুক না কেন যা আমার জানা উচিত নয়, অন্তত একটি বিষয় নিশ্চিত—সে আমার দেখা সবচেয়ে প্রতিভাবান শিল্পী।\nগতরাতে, আমি আবার স্বপ্নে দেখলাম প্রথম বর্ষের চিত্রকলার ক্লাসরুম। তরুণ পিকম্যান ঘরের কোণায়, আমার দিকে তাকিয়ে উচ্চস্বরে হাসছে।\n「শবভক্ষক? না, এভার, শুরু থেকে শেষ পর্যন্ত, আমি যা এঁকেছি তা হলো সত্য, মানুষ!」\nচাঁদের আলো তার চোখে ভেঙে গেল অসংখ্য বিবর্ণ লাল তারার বিন্দুতে। সেই প্রথমবার অতল আমার দিকে তাকিয়ে হেসেছিল।\n\n——'চিত্রশিল্পী এভারের স্মৃতিকথা' থেকে উদ্ধৃত"
  },
