  AwakerStory_11159_Content = {
    Text = "রুপোর ঘণ্টার মতো মিষ্টি হাসি শূন্যতায় প্রতিধ্বনিত হয়, ক্ষীণ মোমবাতির আলোয় এক খর্বকায় দেহ ভেসে ওঠে। সে পাপীদের ভয় ও আকাঙ্ক্ষা, মুমূর্ষুদের অমৃত ও বিষপান, নিয়ে আসে মধুর যন্ত্রণা ও উন্মত্ত রোমাঞ্চ। তার হাত থেকে কখনো বিচ্ছিন্ন না হওয়া চাবুকের চামড়ায় আঘাতের 'চটাচট' শব্দ, অন্ধকারে বেজে ওঠা এক অশুভ সুরলহরী।"
  },
