  AwakerStory_11161_Content = {
    Text = "মিসাগের বিশ্ববিদ্যালয়ে, 「প্রাক-শিক্ষার্থীদের তদন্তকারী হতে হলে অবশ্যই রোটানের সাথে যুদ্ধ করতে হবে「 এই ক্যাম্পাস কিংবদন্তি ক্রমশ তীব্র হচ্ছে, যা শিক্ষার্থীদের কালো পোশাকের মহিলা তলোয়ারবাজের প্রতি ভয়কে চরমে পৌঁছে দিয়েছে। তাত্ত্বিক গবেষণায় বিশেষজ্ঞ অনেক শিক্ষার্থী কালো স্কার্টের কোণা দেখলেই ঠান্ডা ঘামে ভিজে যায়, 「যুদ্ধ-পাগল「 এর দৃষ্টির সামনে পড়ে প্রশিক্ষণ মাঠে প্রাণ হারানোর ভয়ে।\nপ্রধান সম্পাদক হান্না·পিসলি সংশ্লিষ্ট ব্যক্তির সাথে একটি সংক্ষিপ্ত বিশেষ সাক্ষাৎকার নিয়েছেন, সাক্ষাৎকারে রোটান নিম্নলিখিত বক্তব্য দিয়েছেন：\n「শিশুদের সাথে ঘরোয়া খেলা খেলার এত সময় আমার নেই।「\n「দুর্বলরা আমার প্রতিপক্ষ হওয়ার যোগ্য নয়——তুমি কি তাদের একজন? নাকি তোমারও বিশৃঙ্খলার মুখোমুখি হওয়ার সাহস আছে?「\n\n——প্রকাশনার তারিখের আগ পর্যন্ত, প্রধান সম্পাদক ছাত্রাবাস ছেড়ে বের হননি। এই সংখ্যার 《M বিশ্ববিদ্যালয় সংবাদপত্র》 ইন্টার্ন সম্পাদক হাওয়ার্ড দ্বারা মুদ্রিত ও প্রকাশিত হয়েছে।"
  },
  AwakerStory_11161_Title = {
