  AwakerStory_11163_Content = {
    Text = "যারা আহ্বান পায়নি তারা করুণার পাত্র, কারণ তারা অমরত্বের প্রকৃত অর্থ বুঝতে অক্ষম। জাগতিক দ্বন্দ্ব অর্থহীন, কারণ তা কেবল যাত্রাপথের ক্ষণস্থায়ী বিনোদন।\nআমি সরাসরি দর্শন করেছি, আমি আস্বাদন করেছি, আমি বহু আগেই এই দেহের ব্রত উপলব্ধি করেছি।\nকিন্তু, কিন্তু হায়……ভাগ্য কতই না নিষ্ঠুর! আপনি কেন……আপনার সবচেয়ে বিশ্বস্ত পুরোহিতকে আবার বেছে নিলেন না?\n——নিশ্চয়ই আপনি আমাকে পরীক্ষায় ফেলেছেন, আমার বিশ্বাসকে যাচাই করছেন। মাতৃভূমি থেকে সুদূরতম প্রান্তে, আপনার কৃপাবিহীন মুহূর্তে, আমার বিশ্বাস সহস্র বছর ধরে কখনো বদলায়নি।\nআমি সেই ব্যক্তি হতে পারিনি যে আপনার পুনর্জন্মকে স্বাগত জানাবে, তবে আমি আপনার পুনর্জন্মের জন্য সকল প্রস্তুতি সম্পন্ন করেছি। আমি আপনার জন্য আরেকটি চিরন্তন রাজ্য খুঁজে বের করব……অতৃপ্তি ও সম্মান দুই-ই আমার উপর বর্তায়, এই দায়িত্ব আমাকে একাই বহন করতে হবে……\nআমার কুৎসিত ঈর্ষা ক্ষমা করুন। যদি আবার আপনার মহিমা দর্শন করতে পারি, যদি আবার আপনার রাজ্য গড়ে তুলতে পারি, আমি যেকোনো কিছু করতে রাজি।"
  },
  AwakerStory_11163_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11163_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11164_Content = {
    Text = "মাথা ভরা মণিমুক্তা, হালকা শিফনের কোমল আবরণ, অন্তরের সত্তা চরম সৌন্দর্যের আড়ালে লুকানো।\nঅনেকেই মনে করে তাইয়িসি একজন অহংকারী ও চপল মেয়ে, কিন্তু হয়তো এটাও তার পরিধান করা মুখোশগুলোর একটি মাত্র।\n「আরে, ভাইয়া কী লিখছ? আমাকেও সাহায্য করতে দাও——」"
  },
  AwakerStory_11164_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11164_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11165_Content = {
    Text = "ব্যবহৃত ফ্লাস্ক নতুনের মতো পরিষ্কার করতে হবে, পরীক্ষায় পোড়া টেবিল ঘষে চকচকে করতে হবে, তিন দিন পরপর তুলাযন্ত্র পুনরায় ক্যালিব্রেট করতে হবে। বিজ্ঞান ও বিশ্বের রহস্যের প্রতি উন্মত্ত আবেগ ও সম্মানের কারণে, সে তার চারপাশের মানুষ ও বিষয়ের প্রতি অত্যন্ত উচ্চ মান বজায় রাখে।\nঅবশ্যই, এই মান তার নিজের ক্ষেত্রেও প্রযোজ্য——সর্বোপরি, সবাই শান্তভাবে মৃত্যুকে আলিঙ্গন করে স্বেচ্ছায় জাগ্রত সত্তা হওয়ার অনুরোধ করতে পারে না।"
  },
  AwakerStory_11165_Title = {
    Text = "প্রাথমিক তথ্য"
