  AwakerStory_11165_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11166_Content = {
    Text = "A.F. 315 সাল @1 মাস @2 দিন, 08:13 a.m.\nপর্যালোচনা পরিষদ তাৎক্ষণিক প্রতিক্রিয়া তৃতীয় দল ও ক্ষয়কারী বস্তু নিয়ন্ত্রণ ও ব্যবস্থাপনা (এরপর DISM) β7 গ্রুপের সদস্যরা ক্ষয় অঞ্চল L-E-933 (অর্থাৎ সাউথওয়ার্ক স্ট্রিট @2 নম্বর, রজার্স মোমের মূর্তি জাদুঘরের মূল স্থান) এ পৌঁছে, প্রথম দল ও DISM α2 গ্রুপের কাজ গ্রহণ করে, অঞ্চল নিরাপদকরণ কাজ শুরু করে।\n09:24 a.m.\nDISM সদস্য জেমস মোমের মূর্তি জাদুঘরের ভূগর্ভ পরিষ্কার করার সময় মাথাব্যথা, বমি বমি ভাব, মাথা ঘোরা ইত্যাদি লক্ষণ দেখা দেয়।\n10:47 a.m.\nতৃতীয় দলের সদস্য রোল্যান্ড, DISM সদস্য জ্যাকারি, বোল্টন ভূগর্ভ থেকে পালিয়ে আসেন। তিনজন জানান যে, ভূগর্ভের অন্ধকার তাদের গ্রাস করে একটি নক্ষত্রময় শূন্যতায় ভাসিয়ে দিয়েছিল, আকৃতিবিশিষ্ট রঙ মহাকাশে পরস্পর জড়িয়ে ছিল, মনোরম হলেও সারা শরীর হিম করে দিচ্ছিল। তারপর এই রঙগুলো অসংখ্য ইঁদুরে রূপ নিয়ে দ্রুত তাদের দিকে ধেয়ে আসে।\nবোল্টন কাজ চালিয়ে যেতে অস্বীকার করেন, পর্যালোচনা পরিষদের লন্ডিনিয়েন অফিসে ফিরে যান। তৃতীয় দলের রোল্যান্ড ও DISM এর জ্যাকারি তৃতীয় দলের দলনেতা ফিশারের সাথে আবার ভূগর্ভে প্রবেশ করে সংশ্লিষ্ট পরীক্ষা-নিরীক্ষা করেন।\n13:03 p.m.\nপরীক্ষা ও অনুসন্ধানের পর, তৃতীয় দলের দলনেতা ফিশার ভূগর্ভে অবশিষ্ট ক্ষয়কারী মোমের মধ্যে সিলভার কোর L3202 খুঁজে পেয়ে উদ্ধার করেন। পরবর্তী ব্যবস্থার জন্য মিসাগ বিশ্ববিদ্যালয়ে হস্তান্তর করা হয়েছে।\n——《ক্ষয় অঞ্চল L-E-933 নিরাপদকরণ প্রতিবেদন》"
  },
