  AwakerStory_11167_UnlockDesc_1 = {
    Text = "নরমাল কঠিনতায় 2য় অধ্যায় 「মোমের প্রতিকৃতির নামে」 সম্পন্ন করো"
  },
  AwakerStory_11168_Content = {
    Text = "আমাদের প্রিয় বন্ধু, কৌশলী হান্না পিজলি, কোনোভাবে সেলেস্ট‑সংক্রান্ত গবেষণা নথিগুলো খুঁড়ে বের করেছে। এই দুর্দান্ত সাংবাদিকের কল্যাণে, মূলত গোপনীয় সেই নথি এবং সেলেস্টের সঙ্গে তার সংক্ষিপ্ত সাক্ষাৎকার এখন সর্বত্র ছড়িয়ে পড়েছে।\n\nগোপন নথিগুলো পড়া শেষ করে, হান্না তার সাধারণত অনুভূতিহীন মুখের দিকে একটি প্রশ্ন ছুড়ে দেয়।\n\n「বেশিরভাগ অ্যাওয়াকেনারের কিছু অপূর্ণ ইচ্ছা থাকে, যা বিশ্ববিদ্যালয়ের সঙ্গে সহযোগিতার মূল প্রেরণা হিসেবে কাজ করে। কিন্তু এই নথিতে তোমার ইচ্ছা‑সংক্রান্ত অংশটি ফাঁকা। তুমি কি কিছু অর্জন করার কোনো আকাঙ্ক্ষাই রাখো না? নাকি অ্যাওয়াকেনার হিসেবে তোমার অর্থটাই বা কী?」\n\n「আছে, আমার আছে।」\n\nমেয়েটির অভিব্যক্তিতে কোনো ফাটল ধরা পড়ল না, আগের মতোই অতিলৌকিক ও মহিমান্বিত। যদি না সেই সংক্ষিপ্ত উত্তর আর অন্তর্গত অস্থিরতা থাকত, তবে সাংবাদিক প্রায়ই ভেবে বসতেন যে সে প্রশ্নটাই বুঝতে পারেনি।\n\n\n「আমি আমার ইচ্ছা খুঁজে পাব... সবাই তো তাই চায়। তাই আমিও তা খুঁজে পাব।」\n\nতার কোমল কণ্ঠ প্রতিধ্বনিত হলো, সহজেই ভেঙে যাওয়া স্বপ্নের মতো সূক্ষ্ম ও ভঙ্গুর।"
  },
  AwakerStory_11168_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11168_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11169_Content = {
    Text = "প্রতিটি কথায় ও কাজে বিশ্বস্ততার অনুশীলন, প্রতিটি পদক্ষেপে সদ্গুণের বাস্তবায়ন।\nযদিও 「শিষ্টাচার ও ন্যায়পরায়ণতা মেনে চলা, নিজের প্রতি কঠোর হওয়া」 তার আত্মায় গভীরভাবে খোদিত, তবুও এই সদ্গুণের নাইট নিঃসন্দেহে এখনও একটি শিশুর রূপ ধারণ করে আছে।\nতবে চিন্তা করবেন না, এমনকি চিরন্তন বিলুপ্তির মূল্যেও, অজিল তার প্রভুর আদেশ পূরণে সর্বশক্তি দিয়ে লড়বে।\nসেই দিন যেন কখনো না আসে।"
  },
  AwakerStory_11169_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11169_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11170_Content = {
    Text = "যুবরাজ রাজা তার সিংহাসনে তন্দ্রাচ্ছন্ন। জেগে উঠলে তিনি ফরমান জারি করেন, তার কর্তৃত্ব ছড়িয়ে পড়ে বিশ্বের প্রতিটি কোণে।\nকিন্তু সূর্য ডোবার আগেই রাজা আবার ক্লান্ত হয়ে পড়েন। তিনি ক্লান্ত নিজের শক্তি ও অতিক্রম করা প্রজ্ঞা থেকে; ক্লান্ত তার অনুসারীদের উন্মত্ত উপাসনা থেকে, আর সেই দীর্ঘ স্বপ্নগুলো থেকে, যা যুগের পর যুগ ধরে টেনে এসেছে তাকে।\nতার দীর্ঘ নিদ্রার মাঝে তিনি কী দেখেছিলেন, কেউ জানে না; তবু তাদের নিজস্ব অজ্ঞতার পরম সুখের জন্য কৃতজ্ঞ হওয়াই উচিত।"
  },
  AwakerStory_11170_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11170_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11171_Content = {
    Text = "「দয়ালু পিতৃদেবতা একদা উপদেশ দিয়েছিলেন：তোমরা আকাশের, মাটির, জলের, মৃত্তিকার সকল কিছুকে ভালোবাসো। কারণ সকল সৃষ্টিই আমার সন্তান।」\n「তাই, আমি বলি：সকল দুঃখ আমার উপর চাপিয়ে দাও, যারা জীবনের কষ্টে, মহামারীর যন্ত্রণায় জর্জরিত তাদের মুক্তি দাও, সেই সব ব্যথা, সেই সব উন্মাদনা, সব বরফের মতো গলে যাক। তোমরা, আমার ভাই-বোনেরা, চিরস্থায়ী সুখ লাভ করো।\n」আমাকে পোড়াও, আমার হাড় গুঁড়ো করো, আমার মাংস ধ্বংস করো। যতক্ষণ তোমরা সান্ত্বনা পাও, আমারও কোনো অভিযোগ নেই।「\n——B. F. 1@1, 30 মে, সালভা@1দো·মার্টিন@2·ই@1আস, @3 বিচারালয়ে রেখে যাওয়া"
  },
  AwakerStory_11171_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11171_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11172_Content = {
    Text = "ফিন্ট একটি বিবর্ণ, খোলস ভাঙতে অক্ষম বীজ।\nমানুষ তার অসম্পূর্ণতার জন্য তাকে করুণা করত, তার দুর্বলতার জন্য তাকে স্নেহ করত।\nযারা জানত সে স্বেচ্ছায় খোলসের মধ্যে রয়ে গেছে, তারা ইতিমধ্যে ধূলিকণায় পরিণত হয়ে নক্ষত্রের ধূলায় মিশে গেছে।"
  },
  AwakerStory_11172_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11172_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11173_Content = {
    Text = "@3@1 ঘটনার পর, লেক মিসাগার্ড বিশ্ববিদ্যালয়ের বিশেষ আমন্ত্রিত উপদেষ্টা হয়ে ওঠেন।\nলেক একজন দক্ষ উপদেষ্টা ছিলেন। অধ্যাপকদের রহস্যজনক অন্তর্ধান বা যন্ত্রপাতির অব্যাখ্যাত ক্ষতি থেকে শুরু করে হারানো বিড়াল-কুকুর খোঁজার মতো তুচ্ছ বিষয় পর্যন্ত, লেক সবকিছুই ধৈর্য ও তৎপরতার সাথে সন্তোষজনকভাবে সমাধান করতে পারতেন।\nখুব শীঘ্রই, তাঁর অনন্য চেহারা, মার্জিত ও ভদ্র আচরণ এবং মানুষকে সাহায্য করার সুঅভ্যাসের কারণে লেক মিসাগার্ডের অসংখ্য তরুণ-তরুণীর কাছে একজন আইডল হয়ে উঠলেন।\nপ্রফেসর ডেক্সটার একবার আক্ষেপ করে বলেছিলেন: 「সব জনপ্রিয়তা তরুণদের কাছে চলে গেল।」\nকিন্তু ক্যাম্পাসে ধীরে ধীরে মিশে যাওয়ার পর, সবাই লক্ষ্য করল যে লেকের জনসমক্ষে আসার সময় ক্রমশ কমে যাচ্ছে।\nএকই সময়ে, মিসাগার্ডের একটি পরিত্যক্ত ভূগর্ভস্থ কক্ষ থেকে ঘন ঘন পাশা গড়ানোর শব্দ ভেসে আসতে শুরু করল।"
  },
  AwakerStory_11173_Title = {
    Text = "গল্প: ২"
  },
  AwakerStory_11173_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11174_Content = {
    Text = "যে তাকে প্রথমবার দেখে, তার মনে কাছে যাওয়া বা কথা বলার কোনো চিন্তাই জাগে না—বেঁচে থাকার প্রবৃত্তি মরিয়া হয়ে দূরে সরে যাওয়ার সতর্কবার্তা পাঠায়।\nসে একজন সম্পূর্ণ উন্মাদ মানুষ, অথবা বলা ভালো, একটি পুরোদস্তুর বন্য পশু।\nযদি আবার বেছে নেওয়ার সুযোগ পেত, সে হয়তো বরং একটি পশু হতেই বেশি চাইত—মানুষ হিসেবে যা কিছু সহ্য করেছে তার চেয়ে সেটাই ভালো।\nসে কখনো কাউকে বিশ্বাস করে না। যখন তার রক্তলাল চোখ তোমার দিকে তাকায়, সেই চোখে সন্দেহ নেই—আছে শুধু নির্বিকার শীতলতা আর হত্যার অভিপ্রায়।\nসন্দেহ করাটাকেও সে অনেক আগেই তুচ্ছ মনে করে; তার চোখে সবাই সমানভাবে নীচ।\nযদি তার সাথে মেলামেশার একটি উপদেশ দিতে হয়, তাহলে সেটা হলো—একটি সত্যিকারের বন্য পশুকে বশ মানানোর চেষ্টা কোরো না। সে কোনো বিনয়ী সত্তা নয়; সামান্যতম সুযোগ পেলেই তার ধারালো নখর আর বিষদাঁত তোমার গলা ভেদ করে যাবে।\nসে তোমাকে লক্ষ্য করার আগেই যত তাড়াতাড়ি সম্ভব পালাও, আর প্রার্থনা করো যে তার পরবর্তী শিকার তুমি নও।"
  },
  AwakerStory_11174_Title = {
    Text = "গল্প: ২"
