  AwakerStory_11175_Content = {
    Text = "চলো নাচি! একটা আনন্দের নাচ, একটা উন্মাদ নাচ! তার সাথে হাসো, উত্তেজনাকে চরম পর্যায়ে নিয়ে যাও।\nতারপর, মূল চরিত্রের মঞ্চে আসার পালা।\nসেই স্পটলাইটের মিলনবিন্দুতে, উন্মাদ জাদুকর ইতিমধ্যেই তার লম্বা টুপির ভেতরে হাত ঢুকিয়েছে। আর সেই অন্তহীন শূন্যতা থেকে সে যা বের করবে, তা কি রঙিন ফিতা, নাকি ডানা মেলা সাদা পায়রা, নাকি ভয়ংকর দানবের ধারালো নখর... সম্ভবত শুধু সে নিজেই জানে।"
  },
  AwakerStory_11175_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11175_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11176_Content = {
    Text = "সেটি ছিল অধ্যাপক ডেক্সটার ফেভার উপকূল ভ্রমণ থেকে ফেরার সময় আনা স্মারক।\nফেভারের মৃদু সামুদ্রিক জলবায়ু আরামদায়ক ও মনোরম, শতবর্ষী ইতিহাসের সেভাদা স্বাস্থ্যনিবাস সমুদ্রতীরে অবস্থিত, প্রতি বছর অসংখ্য পর্যটক সেখানে ছুটি কাটাতে আসে।\nজলের দাগ ও সামুদ্রিক শৈবালে জড়ানো এই কাচের বোতলে সামান্য স্বচ্ছ গুঁড়ো রয়েছে। এটি জাহাজডুবির শিকারের রেখে যাওয়া ভাসমান বোতল নয়, স্থানীয় বালির কারুশিল্পও নয়। অধ্যাপক ডেক্সটার স্পষ্টতই লক্ষ্য করেছিলেন, সেই বোতলে সিলভার কোরের গুঁড়ো আছে, অন্যভাবে বলতে গেলে, এর মধ্যে একটি ইচ্ছাশক্তি বাস করছে।\nতিনি বলেন সেটি স্থানীয় জেলেদের কাছ থেকে কেনা, জেলে ইতস্তত করে সম্প্রতি ঘটা অদ্ভুত ঘটনা বর্ণনা করে। কয়েকদিন আগের ভোরে, জেলে সমুদ্রে যাওয়ার সময় একটি অদ্ভুত মাছের ঢল দেখে। এটি ডিম পাড়া বা শীতকালীন স্থানান্তরের মৌসুম নয়, তবুও মাছের ঝাঁক এক জায়গায় জড়ো হয়ে দীর্ঘক্ষণ থাকে। ভারী জাল টেনে তুলতে গিয়ে দেখা যায় জালে একটি অদ্ভুত বোতল ধরা পড়েছে। জেলে কৌতূহলী হয়, আবার অস্পষ্ট অস্বস্তি অনুভব করে, যেন এই অদ্ভুত বোতল তাকে অভিশাপ দেবে, দুর্ভাগ্য বয়ে আনবে। এরপর কয়েকদিন, এই সমুদ্র এলাকায় আর কোনো মাছ ধরা পড়েনি।"
  },
  AwakerStory_11176_Title = {
    Text = "গল্প: ১"
