  AwakerStory_11177_Content = {
    Text = "গণিত：শূন্য। অরিটা এমনকি 2 নম্বর পেয়েছে।\nইংরেজি：অকৃতকার্য। 「শিফট」 আর 「শিট」 এর মধ্যে পার্থক্য বুঝতে অনেক সময় লেগেছে\n…\nইতিহাস：অকৃতকার্য। দাবি করেছে ক্যালিগুলা সবচেয়ে মহান রোমান সম্রাট ছিলেন, কারণ তিনি অনেক কলোসিয়াম নির্মাণ করেছিলেন\n\nবিপদ মাত্রা：C। অন্যান্য জাগ্রত সত্তাদের সাথে থাকার সময়, একটি নির্দিষ্ট মাত্রার আক্রমণাত্মকতা দেখায়। হুমকি বড় নয়, বিশেষ মনোযোগের প্রয়োজন নেই\nমন্তব্য：এই ছাত্রীর আত্মনির্ভরতা প্রায় শূন্য (দাসপ্রথায় ক্ষতিগ্রস্ত আরেকজন), সবসময় নজর রাখতে হবে, তাকে আর স্নো ক্রিম দাঁত মাজার পেস্ট হিসেবে ব্যবহার করতে দেওয়া যাবে না।\n——A.F.313 সাল, 《মিসাগ বার্ষিক ছাত্র নথি》থেকে উদ্ধৃত"
  },
  AwakerStory_11177_Title = {
    Text = "গল্প: ২"
  },
  AwakerStory_11177_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11178_Content = {
    Text = "@2 সাল, আকা প্রাচীন নগরী।\nহাজার বছরের তৃষ্ণা অবশেষে বিস্ফোরিত হলো—হত্যা, রক্তপান, হত্যা, রক্তপান—শেষ পর্যন্ত, তার সামনে শুধু অন্তহীন মরুভূমি আর অগণিত শুকিয়ে যাওয়া মৃতদেহ পড়ে রইল, এমনকি শকুনরাও তার কাছে আসতে ভয় পেল।\nসে হলুদ বালুতে হাঁটু গেড়ে বসে উচ্চস্বরে হেসে উঠল: কী তৃপ্তি! সত্যিই@1তৃপ্তিকর!\nএবার, সে নিজেই এই হত্যাযজ্ঞের মহোৎসবে পরিপূর্ণ সমাপ্তি টানবে।\nযোদ্ধা নিজের কব্জি কামড়ে ছিঁড়ল, নিজের রক্ত শেষ বিন্দু পর্যন্ত পান করল, এবং সেও এই রক্তলাল পুকুরে লুটিয়ে পড়ল।"
  },
  AwakerStory_11178_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11178_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11179_Content = {
    Text = "「ওরলা, আজ থেকে তোমার সব কবিতা আমি যত্ন করে সংরক্ষণ করব। এখন থেকে, আমি আমার ফুলের বিনিময়ে তোমার কবিতা নেব!」\n「কোলেট, তুমি অবশ্যই আমাকে বাঁচাতে ফিরে আসবে……তাই না?」"
  },
  AwakerStory_11179_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11179_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11180_Content = {
    Text = "গতকাল সন্ধ্যা 6টায়, মিসাগ বিশ্ববিদ্যালয়ের প্রিন্স বিল্ডিংয়ের ভূগর্ভস্থ CB-101 কক্ষটি অজ্ঞাত ব্যক্তিদের দ্বারা ক্ষতিগ্রস্ত হয়। শক্তিশালী দরজাটি মারাত্মকভাবে ভাঙা হয়েছে, কক্ষের ভেতরে ও বাইরের দেয়ালে কালো বজ্রপাতের মতো পোড়া দাগ ছড়িয়ে আছে এবং ঘটনাস্থল সম্পূর্ণ বিধ্বস্ত।\n「তাৎক্ষণিক অতি-শক্তিশালী বৈদ্যুতিক প্রবাহ এই ধরনের দাগ তৈরি করতে পারে,」 দেয়ালের পোড়া দাগ সম্পর্কে বৈদ্যুতিক প্রকৌশল বিশেষজ্ঞ ড. অ্যাডামস মন্তব্য করেন, 「এর জন্য অত্যন্ত উচ্চ ভোল্টেজ প্রয়োজন। যদি সাধারণ যন্ত্রপাতি হয়, তাহলে তা অত্যন্ত বিশাল হবে এবং লুকানো কঠিন হবে। কিন্তু যদি সিলভার কোর হয়... তাহলে সবকিছুই সম্ভব।」\nসিলভার কোর দীর্ঘদিন ধরে উদ্বোধন বিভাগের কঠোর তত্ত্বাবধানে থাকায়, কেউ যে গোপনে সিলভার কোর ব্যবহার করতে পারবে তা কল্পনা করা কঠিন। তাই বেশিরভাগ দৃষ্টি এখন শরীরে সিলভার কোরের শক্তি ধারণকারী উদ্বোধিত সত্তাদের দিকে ঘুরে গেছে।\n「আমি বলব, এটা নিশ্চিতভাবে সে-ই করেছে।」 নাম প্রকাশে অনিচ্ছুক উদ্বোধন বিভাগের এক শিক্ষার্থী সাংবাদিককে এভাবে জানান। নির্দিষ্টভাবে কার কথা জিজ্ঞেস করা হলে তিনি কিছুটা নার্ভাস দেখান, 「মানে 'সে'-ই, 'টিক-টক মানুষ' নামে পরিচিত সেই ব্যক্তি! তার শরীর থেকে অবিরাম বৈদ্যুতিক প্রবাহের শব্দ শোনেননি? বিদ্যুৎ প্রবাহের কথা বললেই আমার তার কথা মনে পড়ে, নিশ্চিতভাবে সে-ই।」\nঅনেক শিক্ষার্থী একই ধরনের সন্দেহ প্রকাশ করেছেন। কিন্তু এই যান্ত্রিক পুতুলের মতো চলাফেরা করা এবং রহস্যময় হাসি মুখে রাখা উদ্বোধিত সত্তাটি একা নয়, কয়েকজন তদন্তকারী প্রকাশ্যে এরিকার পক্ষ নিয়েছেন এবং সবাইকে তথ্যকে প্রাধান্য দিতে, প্রমাণের ভিত্তিতে সিদ্ধান্ত নিতে এবং ব্যক্তিগত পক্ষপাতের কারণে অন্যদের ক্ষতি না করার আহ্বান জানিয়েছেন।\nএ বিষয়ে উদ্বোধন বিভাগের ভারপ্রাপ্ত প্রধান ড. সোকোলোভা মন্তব্য করতে অস্বীকার করেছেন। ঘটনাটি এখনও তদন্তাধীন।\n——《মিসাগ ডেইলি》 থেকে উদ্ধৃত, 《CB-101 কক্ষের বিস্ফোরণ ঘটনার প্রাথমিক অনুসন্ধান》"
  },
  AwakerStory_11180_Title = {
