  AwakerStory_11180_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11181_Content = {
    Text = "সে সবসময় অহংকারের সাথে নিজেকে 「ঈশ্বরের জননী」 বলে পরিচয় দেয়, ঠান্ডা ও শত্রুভাবাপন্ন মনোভাবে প্রত্যেককে তার নিরাপদ সীমানার বাইরে রাখে। প্রথমবার দেখা হলে, কেউ সহজে তাকে সেই বেপরোয়া ছোট্ট রাজকুমারীর সাথে মেলাতে পারে না।\n「কিন্তু মূলত তারা একই মানুষ, 」 রহস্যরক্ষক সবসময় জেদের সাথে সবাইকে বলে, 「একবার যদি তাকে একা একা গোগ্রাসে ছোট কেক গিলতে দেখতে, তাহলেই বুঝতে পারবে।」"
  },
  AwakerStory_11181_Title = {
