  AwakerStory_11182_Content = {
    Text = "প্রতিভা আর পাগলামোর মধ্যে পার্থক্য শুধু একটি সরু রেখা। মিসাগারের একসময়ের সবচেয়ে উজ্জ্বল প্রতিভা হিসেবে, তার পতনও ছিল একটি সুউচ্চ প্রাসাদের ধ্বংসের মতো—সেই যুক্তির ধ্বংসস্তূপ থেকে যা বেরিয়ে এসেছিল, তা ছিল কেবল এক পরম উন্মত্ত দানব।\nসে যথারীতি বিজ্ঞানের আবরণ গায়ে জড়িয়ে, জীবন, মানবতা, ভালোবাসা আর ধ্বংসকে একটি মূষায় ঢেলে দিয়ে, তৈরি করেছিল পৃথিবী ধ্বংসের বিষ।"
  },
  AwakerStory_11182_Title = {
    Text = "প্রাথমিক তথ্য"
