  AwakerStory_11183_Content = {
    Text = "জেলিফিশের বুদ্ধিমত্তা থেকে বেশি কিছু আশা করা যায় না; অরিটা সে যা কিছু অভিজ্ঞতা করেছে, তা বোঝার ক্ষমতাই রাখে না। সে শুধু এটুকুই নিশ্চিত করে বলতে পারে যে, সে কোনো এক সময়ে সেই পরিত্যক্ত গ্রামটিতে বাস করত। অতীতের গল্পের প্রসঙ্গ উঠলেই, অরিটা ভান করে বোঝার অভিনয় করে কথাটা এড়িয়ে যায়, তাই D-প্রপঞ্চ বা ক্লেড-বিশৃঙ্খলা নিয়ে গবেষণায় অরিটার অবদান খুবই সামান্য।\nতবে, বিরল এক নিরীহ জাগ্রত-সত্তা হিসেবে অরিটা জাগরণ-ব্যবস্থার কর্মী ও ছাত্রদের গভীর স্নেহের পাত্র, আর ডিজলিউশন জীববিজ্ঞান গবেষণার নেতৃত্বে থাকা চোর্ট বিশেষভাবে তার ব্যাপারে চিন্তিত।\nউল্লেখ্য, জেলিফিশের সমষ্টিগত চেতনার সঙ্গে একীভূত হওয়ার পর সে বিভাজিত বংশবিস্তার করার সক্ষমতা অর্জন করেছে। যদিও যা বংশবিস্তার করে, তা কেবল সাধারণ জেলিফিশ, তবু অরিটা উচ্ছ্বসিত হয়ে তার এই 「সঙ্গীদের」 একে একে হাতে তুলে ধরে বাড়ি বাড়ি গিয়ে গর্ব করে দেখায়—যদিও সে বুঝতেই পারে না, প্রতিবার সে যে জেলিফিশটা দেখায়, সেটি আসলে একই জেলিফিশ।"
  },
  AwakerStory_11183_Title = {
    Text = "গল্প: ২"
