  AwakerStory_11183_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11184_Content = {
    Text = "■নথি নম্বর: AF315-C01\n■অ্যাওয়েকেনড কোডনেম: @2পথিক\nএই অ্যাওয়েকেনড সত্তাটি A. F. 315 সালের @1 মাসে প্রথমবার পর্যবেক্ষণ করা হয়েছিল।\nপ্রথম 「কৃত্রিম গোপন অঞ্চল」 পরীক্ষা পরিচালনার সময়, সমজাতীয় বস্তুর আধ্যাত্মিক অনুরণনের প্রভাবে, আমাদের প্রতিষ্ঠানের @2 স্তরের শিক্ষার্থী রামোনা ডেক্সটারের আধ্যাত্মিক ক্ষেত্রকে ভিত্তি করে গড়ে তোলা 「কৃত্রিম গোপন অঞ্চল」 অপ্রত্যাশিতভাবে মাত্রার সীমানা ভেদ করে ফেলেছিল।\nতৎকালীন গোপনীয়তার রক্ষক সেই 「কৃত্রিম গোপন অঞ্চলে」 প্রথমবারের মতো মাত্রার বাইরের জগতের অস্তিত্ব নিশ্চিত করেছিলেন, এবং একই সাথে নিশ্চিত করেছিলেন যে @2-এর শক্তি রামোনা ডেক্সটারের উপর কী ধরনের প্রভাব ফেলবে।\nএরপর, অ্যাওয়েকেনিং বিভাগের গবেষণা প্রতিষ্ঠান আনুষ্ঠানিকভাবে 「মূল অ্যাওয়েকেনড সত্তা」 সম্পর্কিত গবেষণা শুরু করেছিল।\nএকই সাথে, রামোনা ডেক্সটারের শক্তি নিয়ন্ত্রণ কোর্সের পাঠ্যক্রম পরিকল্পনাও কার্যসূচিতে অন্তর্ভুক্ত করা হচ্ছিল।"
  },
  AwakerStory_11184_Title = {
