  AwakerStory_11185_Content = {
    Text = "কালো পর্দায় আবৃত, দীর্ঘ পোশাকের নিচে লুকিয়ে আছে মিরিয়ামের হাড্ডিসার শরীর।\nসে নীরব, নিশ্চুপ, তার মুখে ভক্তি ও বেদনার এক মিশ্র অভিব্যক্তি, যেন দেয়ালচিত্রের সেই মাতা মেরির প্রতিকৃতির মতো, অন্তহীন রহস্যময় তাৎপর্যে পরিপূর্ণ।\nসে তার সমস্ত হৃদয় ও আত্মা ঢেলে দিয়ে অপেক্ষা করছে এক বিশেষ মুহূর্তের জন্য।\nপ্রায় এসে গেছে, সেই প্রতিশ্রুত দিন আসন্ন……"
  },
  AwakerStory_11185_Title = {
    Text = "প্রাথমিক তথ্য"
