  AwakerStory_11185_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11186_Content = {
    Text = "বিশ্ববিদ্যালয়ে যোগদানের মুহূর্তেই ডল-এর হাতে ধরা পড়ে সেলেস্টকে পেরোতে হয়েছে এক ধারাবাহিক বিস্তৃত মূল্যায়ন।\nঅপ্রচলিত প্রক্রিয়ায় আহ্বানকৃত এক Awakener হিসেবে, সেলেস্টের মানসিক অবস্থা অবিশ্বাস্যভাবে স্থিতিশীল। কিন্তু তার আত্মার তীব্রতা, আর সিলভারকোরের শক্তি পরিমাপক নস্টিক সূচক—কোনোটিই Awakener-এর মানদণ্ডে পৌঁছায় না।\nতবু সে তবুও এই জগতে উদ্ভাসন ঘটিয়েছে Awakener রূপে, যেন অতল শূন্যতায় অদৃশ্য পাপড়িওয়ালা এক ফুল হঠাৎ ফেটে ফুটে ওঠে।\nদৈনন্দিন কাজকর্ম বা মাঠের মিশনে কোনো অস্বাভাবিকতা দেখা না গেলেও, তথ্য-রেকর্ড সেলেস্টের উদ্বেগজনক অবস্থা প্রকাশ করে: তার ইচ্ছাশক্তি, যা আগেই ছিল ক্ষীণ, ক্রমাগত ক্ষয়ে যাচ্ছে।\nএই মুহূর্তে, Awakening বিভাগ সেলেস্টের অস্তিত্ব টিকিয়ে রাখতে ধর্মীয় বিশ্বাসের জোগান দিয়ে এক ক্ষুদ্র অর্ডার গঠনের আয়োজন করছে। যারা এতে যোগ দিতে আগ্রহী এবং জলজ কার্যকলাপে পারদর্শী, তারা আরও তথ্যের জন্য শিক্ষক সিলভিয়ার সঙ্গে যোগাযোগ করতে পারেন।"
  },
  AwakerStory_11186_Title = {
    Text = "গল্প: ২"
