  AwakerStory_11187_Content = {
    Text = "তার গলাজুড়ে আঁকাবাঁকা এক দাগ। তার জাতির জন্য মৃত্যুর ঘোষণা, আর তার নিজের জন্য মহিমান্বিত শক্তির অভিষেক।\nনির্বাসন যখন তার ব্যর্থতার ছাপ হয়ে গায়ে বসে, তিক্ততা তখন তার শ্বাসকে ডুবিয়ে ফেলে; আত্মসমর্পণের জন্য যখন হতাশা ভেতরটা ফাঁপা করে দেয়, আর জোয়ার যখন উৎসর্গের দাবি তুলে গর্জে ওঠে—তখন সে ঈশ্বরের কাছে শক্তি প্রার্থনা করে। তার 「অতিক্রান্ত শক্তি」।\nঅতঃপর ঈশ্বরের অ্যাপোস্টল তার প্রার্থনা গ্রহণ করে, তার মাথা শিরশ্ছেদ আঘাতে কেটে নিবেদিত কবিতা করে।\nঅতঃপর ঈশ্বরের অ্যাপোস্টল তার প্রার্থনা স্বীকার করে, তার উন্মুক্ত ঘাড়ের কশেরুকায় অমরত্বের অবশিষ্টাংশ স্থাপন করে।\nঅতঃপর ঈশ্বরের অ্যাপোস্টল তার প্রার্থনার জবাব দেয়, তাকে চিরন্তনতার পবিত্র গর্ভগৃহে প্রবেশ করিয়ে।"
  },
  AwakerStory_11187_Title = {
    Text = "গল্প: ৩"
