  AwakerStory_11189_Content = {
    Text = "ডোরের যোগদান ছিল বাইরের দুনিয়ার চোখে মিসাগার্ড বিশ্ববিদ্যালয়ের একমাত্র গৌরবময় মুহূর্ত।\nশিক্ষাজগতের অসংখ্য মানুষ আক্ষেপ করেছিল, আক্ষেপ করেছিল যে স্বর্গপ্রদত্ত প্রতিভাও জাগতিক শৃঙ্খল থেকে মুক্তি পায়নি——সে নাকি সম্পদের লোভে একটি অখ্যাত বিশ্ববিদ্যালয়ের কাছে নিজেকে বিকিয়ে দিয়েছে, অর্থের কলুষে কলুষিত হয়েছে।\nবাইরের জগৎ যখন তার স্বেচ্ছা পতনের জন্য তীব্র সমালোচনা করছিল, ডোর মিসাগার্ডে সোনার চেয়েও মূল্যবান কিছু পেয়েছিল।\nসে বস্তুবিজ্ঞানের সীমানা অতিক্রম করে বাস্তবতার রাজ্যের আবরণ স্পর্শ করতে পেরেছিল, সেই আবরণের নিচে লুকিয়ে ছিল এমন কিছু যার জন্য সে জীবন উৎসর্গ করতেও রাজি ছিল।\n'সিলভার কোর টেকনোলজি' নিয়ে গবেষণার বিপদ ছুরির ধারে নৃত্যের চেয়ে কম নয়, আর ডোর হয়ে উঠেছিল সবচেয়ে নিষ্ঠাবান, সবচেয়ে পরিশ্রমী, সবচেয়ে দক্ষ নর্তকী।\nযখন ক্ষয়চিহ্ন দেখা দিয়েছিল, বিজ্ঞানের এই নর্তকী তবুও নৃত্য থামায়নি, বরং সীমিত সময়কে আঁকড়ে ধরে ঘুরতে থেকেছিল, কখনো পরিশোধন কখনো স্ফটিকায়নের মাধ্যমে তার নিজস্ব অনন্য নৃত্যভঙ্গি রচনা করেছিল।\nযতক্ষণ না ক্ষয় প্রক্রিয়া দেহকে বিধ্বস্ত করেছিল, মনে ছড়িয়ে পড়েছিল, যুক্তিবোধকে গ্রাস করেছিল।\nতা সত্ত্বেও, সে সত্যের কেন্দ্র থেকে এখনও অনেক দূরে ছিল।\nতাই, সেই নক্ষত্র—যার জীবনের আগুন ইতিমধ্যে ম্লান হয়ে এসেছিল, কিন্তু জ্ঞানের আলো এখনও উজ্জ্বল ছিল—এই অন্তিম বাণী রেখে গিয়েছিল: 'পৃথিবী আমাকে ভুলে যাওয়ার আগে, আমাকে জাগাও।'"
  },
  AwakerStory_11189_Title = {
