  AwakerStory_11190_Content = {
    Text = "বিশপ মহোদয় প্রতিবার স্কুল পরিদর্শনে এলে শিক্ষক ও শিক্ষার্থীদের কাছ থেকে উষ্ণ অভ্যর্থনা পেতেন।\nকোমলমতি জাগ্রত সত্তারা তাঁর হাত ধরে টানতো, মহাপ্লাবনের আগের আরও কিছু গল্প শোনাতে বলতো। শিক্ষার্থীরা নিজে থেকে এগিয়ে এসে জিজ্ঞেস করতো বিশপ তাদের দুশ্চিন্তা ও সমস্যার কথা শুনতে রাজি কিনা। এমনকি সেইসব কঠিন ও শক্তিশালী দেখতে জাগ্রত সত্তারা এবং অভিজ্ঞ অধ্যাপকরাও বিশপের অবসর সময়ে এগিয়ে এসে কথা বলতেন: কেউ নিজের দুঃস্বপ্নের কথা বলতেন, কেউ আত্মার প্রকৃত সত্য নিয়ে আলোচনা করতেন।\nতিনি সর্বদা এতটাই ধৈর্যশীল ছিলেন, কখনো বিরক্ত হতেন না। যে-ই হোক না কেন, তাঁর কাছে গ্রহণযোগ্যতা ও উষ্ণতা পেতো।\n「অবশ্যই, আমার সন্তান, আমি কি তোমার জন্য কিছু করতে পারি?」"
  },
  AwakerStory_11190_Title = {
    Text = "গল্প: ২"
