  AwakerStory_11192_Content = {
    Text = "সে সকলের প্রতি, সকল জাগ্রত সত্তার প্রতি অত্যন্ত বন্ধুত্বপূর্ণ, কখনো আক্রমণাত্মক প্রবণতা দেখায়নি।\nবেশিরভাগ সময়, সে শুধু চুপচাপ ঘরে থাকে, জানালার বাইরে তাকিয়ে থাকে। তার বিছানার পাশে আমরা কয়েকটি বারবার পড়া ক্লাসিক উপন্যাস পেয়েছি, আর নোটপ্যাডে লেখা সূক্ষ্ম হাতের কয়েকটি কবিতা।\n「সেই মেয়েটির তুলনায়, আমি স্পষ্টতই ভাগ্যবান।」 সে সূর্যাস্তের দিকে মুখ করে, ক্যাম্পাসের ঝিলমিল পুকুরের কাছে ফিসফিস করে বলে।\nসে খুব কমই বাইরের কার্যকলাপে অংশ নেয়, অংশ নিতে অনিচ্ছুক বলার চেয়ে বরং বলা ভালো যে সে জানে না কীভাবে অংশ নিতে হয়…… সেই কিশোরী রূপের জাগ্রত সত্তাটির অনেক দৈনন্দিন জ্ঞানের অভাব রয়েছে বলে মনে হয়।\nআমরা আরও বেশ কয়েকবার তাকে ফোয়ারার মাছদের সাথে কথা বলতে দেখেছি, এক অদ্ভুত কণ্ঠে, যেন বুদবুদ ছাড়ছে বা ডুবন্ত মানুষের কর্কশ গর্জনের মতো। কিন্তু তার মুখ শান্ত ও প্রশান্ত, যেন ঘনিষ্ঠ বন্ধুর সাথে পরস্পরকে সান্ত্বনা দিচ্ছে, কথা বলছে। সেই মুহূর্তে, আমরা সবাই বিশ্বাস করেছিলাম যে সে সত্যিকারের শান্তি পেয়েছে।"
  },
  AwakerStory_11192_Title = {
    Text = "গল্প: ২"
