  AwakerStory_11193_Content = {
    Text = "এতদিন পর, আমার সাথে আবার 'নিজের জীবন' নিয়ে কথা বলা—হয়তো একটু বেশিই কঠিন।\nআমি অভ্যস্ত হয়ে গেছি উচ্চ আকাশের ওপারে মিলিয়ে যেতে, তারার সাগরে লুকিয়ে থাকতে।\nসেই দর্শকদের দৃষ্টি আমার দিকে নয়, মিউজিক বক্সের মতো উপভোগ করা হচ্ছে সেটাও আমি নই, জনশূন্য নক্ষত্রলোকে ভেসে বেড়াচ্ছে সেও আমি নই। সেটা জীবিকার জন্য কণ্ঠ বিক্রি করা একটা হাতিয়ার, ফিন্টকে খুঁজে বেড়ানো এক জীবন্ত লাশ। কেবল অন্যের মূল্য নিজের চেয়ে অনেক বেশি—এই বিশ্বাসেই এই সমস্ত ত্যাগকে সার্থক মনে করা যায়।\nতাই, এতদিন পর, দয়া করে আমাকে আর আমার দিকে তাকাতে দিও না।\n\n「কিন্তু, ছোট বোন, যা অতীত হয়ে গেছে তাতে আর ডুবে থেকো না।\nচোখ মেলে দেখো, তোমার অনন্য সেই গান—সেটা কিন্তু ইতিমধ্যেই সমগ্র মহাবিশ্বে ছড়িয়ে পড়েছে।」"
  },
  AwakerStory_11193_Title = {
