  AwakerStory_11195_Content = {
    Text = "এলভা তার কৃত্রিম অঙ্গ নিয়ে অত্যন্ত সন্তুষ্ট।\n「সেই যুদ্ধের পর, আমি কখনো ভাবিনি যে আবার দাঁড়াতে পারব। ন্যায়বিচারের জন্য আবার লড়াই করার সুযোগ পাওয়া আমার সৌভাগ্য।」\nআর মধ্যরাতে ডরমিটরি থেকে ভেসে আসা চাপা গোঙানির শব্দ — নতুন সূর্য দিগন্তে উঠে আসার পর, ধরে নেওয়া যাক সেসব কখনো ছিলই না।"
  },
  AwakerStory_11195_Title = {
    Text = "প্রাথমিক তথ্য"
