  AwakerStory_11195_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11196_Content = {
    Text = "মিরিয়াম ক্যাম্পাসে সরল কঠোর জীবনযাপন করে। একাকীত্ব, ধ্যান, নীরব প্রার্থনা, পরিচ্ছন্নতা, শ্রম, বারবার, দিনের পর দিন।\nঅন্যদের ভয় ও সতর্কতা, আলোচনা ও কৌতূহল, সে সব উদাসীনভাবে মোকাবেলা করে। স্বদেশ থেকে দূরে এই ক্যাম্পাসে, সে যেন নতুন আধ্যাত্মিক সাধনার পথ খুঁজে পেয়েছে।\nআসলে, সে মানুষের সাথে কথা বলতে আপত্তি করে না। শুধু তুমি যদি একটু সময় দাও, তার সেই অমর দেবতার মহিমার কথা শুনতে, প্রাগৈতিহাসিক সুদূর সভ্যতা ও প্রজ্ঞাবান বাল রাজার শাসিত চিরন্তন রাজ্যের কথা শুনতে। এসব বলার সময়, তার চোখে এমন করুণা ফুটে ওঠে যা শ্রোতারা আগে কখনো দেখেনি।\nলক্ষণীয় যে, মিরিয়াম তুরুর প্রতি অস্বাভাবিক আনুগত্য ও শ্রদ্ধা পোষণ করে, যদিও তুরু তার প্রতি কোনো বিশেষ মনোভাব দেখায়নি।\nযদি মিরিয়ামের সাথে আলোচনার প্রয়োজন হয়, তুরুর সাহায্য চাইলে পরিস্থিতি অনুকূলে পরিবর্তিত হতে পারে।"
  },
  AwakerStory_11196_Title = {
    Text = "গল্প: ২"
