  AwakerStory_11197_Content = {
    Text = "জাগ্রত হওয়ার তৃতীয় মাসে, তদন্তকারীরা এবং গোপনরক্ষক মিলে নোদিলার জন্য একটি পার্টির আয়োজন করলো। তবে এটা তার এখানে আসার উদযাপন ছিল না, বরং সে অবশেষে মিসাগ বিশ্ববিদ্যালয়ের নাম মনে রাখতে পেরেছে — এটাই উদযাপনের কারণ ছিল।\nযদিও পরের দিনই সে আবার ভুলে গেল, তবে পার্টি তো আবারও করা যায়। কে জানে, হয়তো আরও তিন মাস পরে সে সত্যিই মনে রাখতে পারবে।\nনোদিলার সোনামাছের মতো স্মৃতিশক্তি ক্ষয়ের পরবর্তী প্রভাব, নাকি সিলভার কোরের ত্রুটির ফলাফল — তা বলা কঠিন। তবে স্বল্পমেয়াদী স্মৃতি সবসময় খারাপ কিছু নয়। একজন কাজে নিষ্ঠাবান মেকানিকের জন্য, কোন স্ক্রুটা শেষবার টাইট করেছে তা ভুলে যাওয়ার মানে হলো সব স্ক্রু আবার টাইট করা — দুইবার, তিনবার... তাই নোদিলার হাতে মেরামত করা যন্ত্রপাতি সাধারণত অন্যান্য যন্ত্রপাতির চেয়ে অনেক বেশি মজবুত গঠন এবং দীর্ঘ ব্যবহারকাল পায়।\nদোর্ল এই কারণে তাকে খুবই পছন্দ করতো, কারণ একবার মেরামত করলে দশ বছর টেকে — এমন দক্ষতা তো সবার থাকে না।"
  },
