  AwakerStory_11198_Content = {
    Text = "ডোর একবার তার উপর অত্যন্ত বিস্তারিত গবেষণা চালিয়েছিলেন, কিন্তু দেহকাণ্ড হোক বা অঙ্গ-প্রত্যঙ্গ, মাথার খুলি হোক বা শ্রোণিগহ্বর — কোথাও তার কণ্ঠস্বর উৎপাদনে সহায়ক কোনো যন্ত্রাংশ খুঁজে পাওয়া যায়নি। সে আসলে কীভাবে কথা বলে — এটি মিসাগের অসংখ্য অমীমাংসিত রহস্যের মধ্যে একটি হয়ে রইল।\nবেশিরভাগ সময় সে মানুষের সাথে স্বাভাবিকভাবে যোগাযোগ করতে পারে, কিন্তু মাঝে মাঝে সেই রহস্যময় কণ্ঠস্বর উৎপাদনকারী যন্ত্রাংশটি যেন নিজস্ব চেতনা ধারণ করে, এবং এমন কিছু কথা বলে যা শুনলে গা শিউরে ওঠে, সারা শরীরে শীতল স্রোত বয়ে যায়।"
  },
