  AwakerStory_11200_Content = {
    Text = "অসাধারণ স্বচ্ছ জলের মাছধরা গ্রাম, মধ্যগ্রীষ্মের রাতে ছায়াপথের মতো সজ্জিত উপকূল, ভ্রাম্যমাণ গাড়ি থেকে ভেসে আসা প্রাণবন্ত হাসির ধ্বনি——সেসব হারিয়ে যাওয়া স্মৃতি মাঝে মাঝে ফিরে আসে, আবার সঙ্গে সঙ্গেই মন থেকে মুছে যায়।\nযতক্ষণ পাশে নতুন সঙ্গীরা আসতে থাকবে, ততক্ষণ নতুন স্মৃতি তৈরি করা সম্ভব, তাছাড়া জেলিফিশরাও তো আছে——অরিটা এমনটাই মনে করে।\nসর্বোপরি, স্রোতের সাথে ভেসে বংশবিস্তার করা, সংখ্যা বাড়িয়ে শক্তিশালী শত্রুর মোকাবেলা করা——এটাই জেলিফিশের স্বভাব ও নিয়তি।"
  },
