  AwakerStory_11201_Content = {
    Text = "「প্যান্ডিয়ার ব্যাপারে সাবধান থেকো, তার বিপজ্জনকতা আর বাহ্যিক রূপ সম্পূর্ণ আলাদা। সে একটা দানব।」\nএটি অসংখ্য তদন্তকারীর রক্ত ও অশ্রুর অভিজ্ঞতা থেকে জন্ম নেওয়া হৃদয়ের কথা।\nপ্যান্ডিয়া সবসময় মধুর ফাঁদ তৈরি করে, অন্যান্য গবেষক বা জাগরিতদের প্রলুব্ধ করে তার সাথে প্রভু-দাস চুক্তিতে আবদ্ধ করে, তারপর যথেচ্ছভাবে তাদের আবেগ ও আত্মাকে পদদলিত ও নিয়ে খেলা করে।\nপ্যান্ডিয়ার সাথে আলোচনা নিষ্ফল হয়েছে, সে জোর দিয়ে বলে যে সে কেবল তার নতুন প্রেমিকদের সাথে আনন্দের বীজ তৈরি, ভাগাভাগি ও ছড়িয়ে দিচ্ছে, এবং সেই চুক্তিগুলো সবই উভয় পক্ষের স্বেচ্ছায় হয়েছে। সর্বোপরি, সে সেই দাসদেরও মধুর ফলের স্বাদ গ্রহণ করিয়েছে।\nতবে, স্কুলের মধ্যে প্যান্ডিয়ার দুর্বলতাও বিদ্যমান। যখন সোরেল প্যান্ডিয়ার ছাত্রাবাসের দরজার সামনে দিয়ে যায়, তখন যে বিষয়েই আলোচনা চলুক না কেন, প্যান্ডিয়া হঠাৎ চুপ হয়ে যায়। গুজব আছে যে, প্যান্ডিয়া একবার সোরেলকে প্রলুব্ধ করতে গিয়ে গুরুতর আঘাত পেয়েছিল, কিন্তু প্রকৃত সত্য কী, তা আজও এক অমীমাংসিত রহস্য।"
  },
  AwakerStory_11201_Title = {
