  AwakerStory_11202_Content = {
    Text = "A.F. 297 সাল@1মাস@1দিন 03:47 মিনিট, ইয়াগ্রো প্রজাতন্ত্রের@3রাজ্যের@1@2@1শহরের দক্ষিণ-পূর্বে একটি অজানা বিস্ফোরণ ঘটে। শকওয়েভ স্থানীয়ভাবে 3.8 মাত্রার ভূমিকম্প সৃষ্টি করে, যার কম্পন স্পষ্টভাবে অনুভূত হয় এবং@1@2@1শহর থেকে 5 কিলোমিটার দূরের গ্রাম পর্যন্ত প্রভাব ফেলে।\nঘটনার পর@1@2@1শহর অন্যান্য অঞ্চলের সাথে যোগাযোগ হারায়, এবং আশেপাশের বাসিন্দারা শহরটির অবস্থান স্মরণ করতে অক্ষম হয়। এর ভিত্তিতে, পরিদর্শন পরিষদ তদন্তের জন্য সদস্য প্রেরণ করে এবং@1@2@1শহরের প্রান্তে ক্ষয়কারী পদার্থ শনাক্ত করে।\nশহরটি অবরুদ্ধ করার পর, মিসাগ বিশ্ববিদ্যালয়ের তদন্তকারীরা ক্ষয়কারী সত্তা অপসারণের কাজ সম্পন্ন করে এবং সন্দেহজনক বিস্ফোরণ কেন্দ্রের তীব্র ক্ষয় অঞ্চল থেকে E-1929 নম্বর সিলভার কোর উদ্ধার করে।\nE-1929 বেশ বিশেষ, এর নথোস সূচক দীর্ঘদিন ধরে অনিয়মিত ওঠানামার অবস্থায় থাকে এবং এটি স্বতঃস্ফূর্তভাবে গিয়ারের ঘূর্ণনের মতো টিকটিক শব্দ করে, কেবলমাত্র তীব্র ক্ষয় অঞ্চল থেকে উদ্ধারকৃত যান্ত্রিক টুকরোর সাথে সংযুক্ত হলেই সংক্ষিপ্ত স্থিতিশীলতা বজায় রাখতে পারে। এই বৈশিষ্ট্যের ভিত্তিতে, মিসাগ বিশ্ববিদ্যালয়ের জাগরণ ব্যবস্থা যান্ত্রিক টুকরো দিয়ে E-1929 কে আবৃত করে এবং নথোস সূচক স্থিতিশীল হওয়ার দিকে ঝুঁকলে দ্রুত জাগরণ সম্পন্ন করে।\n——《E-1929 সিলভার কোর অধিগ্রহণ ও জাগরণ প্রতিবেদন সারসংক্ষেপ》"
  },
  AwakerStory_11202_Title = {
