  AwakerStory_11203_Content = {
    Text = "ইতিহাসের ক্রোধের আগুন সবকিছু পুড়িয়ে ছারখার করার আগে, আগ্রিপা ছিল কাপুয়ার সবচেয়ে উজ্জ্বল মুক্তা।\nসে যথেচ্ছাচারী, তার চাবুক সর্বদা নীরব গ্ল্যাডিয়েটরদের উপর নির্মমভাবে আঘাত করত; সে চায় না কেউ তার চোখে সরাসরি তাকাক, কারণ তা তার অন্তরের দুর্বলতা প্রকাশ করে দেবে। তবে দাস প্রশিক্ষণের কথা বলতে গেলে, আগ্রিপা একজন বিশেষজ্ঞ। হয়তো তুমি তার শোবার ঘরে রাখা বিশটি ভিন্ন ভিন্ন ধরনের চাবুক দেখতে আগ্রহী হবে——বিশেষভাবে তোমার জন্যই প্রস্তুত করা হয়েছে।"
  },
