  },
  AwakerStory_11204_Content = {
    Text = "নরম কালো চুল, পূর্ণ গাল, রত্নের মতো উজ্জ্বল দুই চোখ, লাল ঠোঁট——ছোটবেলা থেকেই, কারেন জন্মগত সৌন্দর্যের কারণে বিশেষ সুবিধা পেয়ে আসছে, বড় হওয়ার পর, পুরুষরা প্রতিদিন যে উপহার ও ফুল পাঠায় তা তার বাড়ির দরজায় ছোট পাহাড় তৈরি করে। তাই, যখন রাজপ্রাসাদের তত্ত্বাবধায়ক ঘোষণা করে যে তাকে রাজপ্রাসাদে নিয়ে যাওয়া হবে, মহান রাজার পরিচারিকা হিসেবে প্রশিক্ষণ দেওয়া হবে, সে অবাক হয়নি। এটা কি স্বাভাবিক নয়? সে জন্মগতভাবেই ঈর্ষার পাত্র, জন্মগতভাবেই অনন্য, জন্মগতভাবেই সবার দৃষ্টির কেন্দ্রবিন্দু।\nকিন্তু রাজপ্রাসাদে সৌন্দর্যের কোনো অভাব নেই, ছোট শহরের ফুল যতই চমকপ্রদ হোক, এখানে সাধারণ ও সরল মনে হয়। বাহ্যিক রূপ আর তাকে বিশেষ সুবিধা এনে দিতে পারে না, এমনকি তার মনের আকাঙ্ক্ষা, শতবর্ষী ভোজসভায় মহাকক্ষে সেবা করার সুযোগও অন্য একটি মেয়ে কেড়ে নেয়।\nকেন? সেই মেয়ের যা আছে তার কারেনেরও আছে, কেন সে নয়?\nতারপর সে প্রতিপক্ষের কানে ঝুলন্ত রূপালী কানের দুল দেখে, হঠাৎ বুঝতে পারে।\nভোজসভার দিন, সে মেয়েটিকে হ্রদে ডুবিয়ে মারে এবং সেই রূপালী সাদা কানের দুল পরে নেয়। সে ইচ্ছামতো পরিচারিকাদের মধ্যে সবচেয়ে উজ্জ্বল হয়ে ওঠে, এমনকি রাজার পাশে সেবা করার অনুমতিও পায়। ঈর্ষা বা হিংসার দৃষ্টি তাকে অত্যন্ত আনন্দিত করে——হ্যাঁ, হ্যাঁ, সবকিছু এমনই হওয়া উচিত, এটা তার জীবনের সবচেয়ে সুখের দিন।\nতারপর, সমগ্র রাজনগরীকে গ্রাস করা সবুজ ঘন কুয়াশায় সে তার জীবনের সমাপ্তি বরণ করে।"
  },
  AwakerStory_11204_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_11204_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11205_Content = {
    Text = "স্বপ্ন হলো স্মৃতির প্রক্ষেপণ, দৈনন্দিন জীবনের সংক্ষিপ্ত রূপ, মানুষের সত্তার সামগ্রিক প্রতিফলন।\nছোটবেলা থেকেই রামোনা বারবার একই স্বপ্ন দেখত।\nউষ্ণ আর ঘোলা জলে নিমজ্জিত হয়ে, সে কোনো এক অজানা সত্তার সাথে অবিচ্ছেদ্যভাবে জড়িয়ে থাকত, আর একঘেয়ে ফাঁকা ঢোলের তালে জলে ছড়িয়ে পড়ত বৃত্তাকার তরঙ্গ।\nঘুম ভাঙার পর, হৃদয়ের কোনো এক কোণে সবসময় একটা শূন্যতা অনুভব হতো, যেন কোনো অস্তিত্বকে তার জীবন থেকে কেড়ে নেওয়া হয়েছে, মুছে ফেলা হয়েছে।\nকিন্তু বাবার মুখে উদ্বেগের ছায়া না ফেলতে, ইতিমধ্যেই ব্যস্ত গুরুজনদের আর বিরক্ত না করতে, রামোনা গলা পর্যন্ত উঠে আসা প্রশ্নগুলো গিলে ফেলে আবার দৈনন্দিন জীবনে ফিরে যেত।"
  },
  AwakerStory_11205_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_11205_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11206_Content = {
    Text = "এই পৃথিবীতে আসার পর থেকে তার সমস্ত অভিজ্ঞতা যেন শুধু তাকে যন্ত্রণা দেওয়ার জন্যই ছিল। দয়া, সহনশীলতা, সহানুভূতি, বিশ্বাস... মানবতার সমস্ত কোমল দিক তার হৃদয় থেকে উপড়ে ফেলা হয়েছে, রক্তমাখা মাংসের সাথে জড়িয়ে সব ছুড়ে ফেলা হয়েছে।\nতার অভিধানে ক্ষমা বলে কোনো শব্দ কখনো ছিল না। রক্ত আর ঘৃণাকে মোচন করতে পারে কেবল অন্যের রক্ত আর ঘৃণাই।\nরক্তের বদলে রক্ত — এটাই সবচেয়ে ন্যায্য নিয়ম, যোদ্ধা হোক বা দাস, সকলেই যা মেনে চলে।\nহাজার বছর ধরে চাপা আগ্নেয়গিরি এক রাতেই বিস্ফোরিত হলো, পাতালের অন্ধকার থেকে একটি হাত বেরিয়ে এলো, মর্ত্যের মাটিতে উঠে এলো।\nসেটি ছিল এক প্রতিশোধপরায়ণ অশুভ আত্মা, যে রক্তলাল নদী বইয়ে দিতে চায় সমগ্র মানবজগতে।"
  },
  AwakerStory_11206_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11206_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11207_Content = {
    Text = "「মা, মা, লিলি ইনজেকশন নেওয়ার সময় কাঁদেনি!」\n「লিলি তো খুব সাহসী!」\n「হুঁ, লিলির ব্যথা লাগেনি, লিলি ভেবেছে মা ফিরে এসে লিলির সাথে থাকবে, তাই আর ব্যথা লাগেনি!」\n……\n「মালিক, আমাকে আদেশ দিন।」\n「অপারেশন টেবিলে গিয়ে শুয়ে পড়ো, পনেরো মিনিট পর অপারেশন শুরু হবে। ওষুধ সব সময়মতো খেয়েছ?」\n「খেয়েছি, মালিক।」\n「এখানে কাটছি, ব্যথা লাগছে না তো?」\n「……লাগছে না, মালিক।」"
  },
  AwakerStory_11207_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_11207_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
