  AwakerStory_11207_UnlockDesc_1 = {
    Text = "নরমাল কঠিনতায় ৪র্থ অধ্যায় \"নীরবতা-র মাঝে\" সম্পন্ন করো"
  },
  AwakerStory_11208_Content = {
    Text = "অরলার শরীরে যেন এক অদ্ভুত জাদুকরী আকর্ষণ ছিল। কবিতা ও সৌন্দর্যের প্রতি আকাঙ্ক্ষী শিক্ষক-শিক্ষার্থীরা সবসময় অজান্তেই তার প্রতি আকৃষ্ট হয়ে তার পাশে এসে জড়ো হতো।\nঅরলা নিজের কবিতা প্রকাশ করতে পছন্দ করতেন না, তবু মিসাগের শিক্ষার্থীরা নানা উপায়ে তার লেখার টুকরো টুকরো অংশ দেখতে সক্ষম হতো। তার কলমের ডগা থেকে প্রবাহিত কবিতাগুলো প্রতিবারই অতি অল্প সময়ের মধ্যে পুরো ক্যাম্পাসে ছড়িয়ে পড়ত।\nভোরের শিশির যখন জমতে শুরু করত, কেউ ঘণ্টাঘরের নিচে দাঁড়িয়ে আস্তে আস্তে তার পঙ্ক্তিগুলো আবৃত্তি করত; গোধূলিবেলায়, নিমফিয়া মিসাগ বিশ্ববিদ্যালয়ের চত্বরের বেঞ্চে বসে তার সংকলন উল্টে দেখত; রাতের আঁধার নামলে, শিক্ষার্থীরা সভাগৃহে জড়ো হয়ে তার রচিত অধ্যায়গুলো মঞ্চস্থ করার মহড়া দিত।\nকিন্তু আন্তরিক আমন্ত্রণ পেলেও, অরলা এসব কার্যক্রমের দিকে খুব কমই দৃষ্টি দিতেন, ব্যক্তিগতভাবে অংশগ্রহণ তো দূরের কথা। সেই বিষাদময় সুরের বাক্যগুলো, অশ্রুসিক্ত মুহূর্তগুলো, প্রায়ই তাকে অস্বস্তিতে ফেলত।\n「আমি কি আবার নতুন বিষাদ ছড়িয়ে দিলাম?」"
  },
  AwakerStory_11208_Title = {
    Text = "গল্প: ২"
  },
  AwakerStory_11208_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11209_Content = {
    Text = "রামোনা যখন প্রথম ক্যাম্পাসে আবির্ভূত হয়, তখন বিশাল আলোড়ন সৃষ্টি হয়।\nজাগ্রত সত্তায় পরিপূর্ণ ও অদ্ভুত মানুষে ভরা মিসাগের বিশ্ববিদ্যালয়ে, রূপালী চুল ও ভিন্ন রঙের চোখ তেমন উল্লেখযোগ্য বৈশিষ্ট্য নয়। রামোনাকে আলোচনার বিষয় করে তোলে তার 「অধ্যাপকের কন্যা」 পরিচয়।\nসবাই গণিত বিভাগের অফিসের সামনে ভিড় করে, ডেক্সটার পরিবারের মেয়ের এক ঝলক দেখতে চায়। মানুষ এতই বেশি যে অধ্যাপককে রোটানের সাহায্য চাইতে হয়, তবেই সবাই অনিচ্ছায় চলে যায়।\nরামোনা যখন একটু বড় হয়, এবং অধ্যাপকও অবশেষে নিশ্চিন্তে তাকে ক্যাম্পাসে ছুটে বেড়াতে দেন, তখনই রোটানের তাড়ানো সেই শিক্ষার্থীরা আবার তার সাথে কথা বলার সুযোগ পায়।\n「ব্যারনেস কেমন মানুষ? দুঃখিত, এই চরিত্রটি এখনও অস্তিত্বে নেই। আমি একজন এতিম, বাবা দয়া করে আমাকে দত্তক নিয়েছেন।」\nজ্বালাতন থেকে মুক্তি পেতে, ছোট্ট মেয়েটি শান্তভাবে সত্যি কথা বলে, এবং সবাই অপরাধবোধে ডুবে যাওয়ার সময়, স্বচ্ছন্দে চলে যায়।"
  },
  AwakerStory_11209_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_11209_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11210_Content = {
    Text = "সেটা ছিল……চোখ ধাঁধানো আকাশের আলো আর তাপদাহ, উন্মত্ত আনন্দের চরম উল্লাস।\nউল্লাসের ধ্বনি সমুদ্রের ঢেউয়ের মতো কানে গুঞ্জরিত হচ্ছিল, যোদ্ধারা রণক্ষেত্রে রক্তের গৌরবে স্নান করছিল।\nমেয়েটি বিরক্ত হয়ে ঘরে ফিরল, সে যথারীতি চাবুক ঘোরাতে লাগল, নির্দয়ভাবে সামনের নির্বোধ গ্ল্যাডিয়েটরকে আঘাত করতে লাগল।\n\nএটাই ছিল তার যুদ্ধক্ষেত্র।\n\nকোনো উত্তেজনাপূর্ণ দ্বন্দ্বযুদ্ধ নেই, কোনো ফুল বা করতালি নেই। বিশালদেহী বীরেরা ছিল সবচেয়ে বশ্য হরিণের মতো, তার সমস্ত গালিগালাজ আর ক্রোধ যেন এক অন্ধকার শূন্যতায় শোষিত হয়ে যেত, একটুকরো বাতাসও অবশিষ্ট থাকত না।"
  },
  AwakerStory_11210_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11210_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11211_Content = {
    Text = "এক নজরেই বোঝা যায় এমন ক্ষুদ্রাকৃতির দিদির বিপরীতে, টিংক্তের বিকৃতি অন্যদিকে প্রকাশ পায়।\nপরগাছাই হোক, হার্মিট ক্র্যাবই হোক, টিংক্ত যেন এমন এক আত্মিক সত্তা যে অন্য কারো ছাড়া বেঁচে থাকতে পারে না।\nপ্রান্তর তারায় থাকাকালীন, সে যা কিছু করেছে সবই ছিল ফিন্তের রোগ সারানোর জন্য, দিদির জীবন টিকিয়ে রাখার যেকোনো উপায় সে চেষ্টা করতে রাজি ছিল, এমনকি সাধারণ মানুষের অসহনীয় মূল্য দিতে হলেও।\nঅভিজাতদের উপহাস ও অপমান সে মোটেও পরোয়া করত না, সবসময় শান্ত ও নম্রভাবে তাদের সাথে অসম লেনদেন করত, এমনকি তাদের করুণা ভিক্ষা করত——সেই করুণা তাকে প্রান্তর তারা থেকে পালানোর একটি আসন এনে দিয়েছিল, আর সে হাতে পাওয়ার মুহূর্তেই বিন্দুমাত্র দ্বিধা না করে ফিন্তেকে দিয়ে দিয়েছিল।\nকিন্তু ফিন্ত শেষ মুহূর্তে টিংক্তকে প্রান্তর তারা থেকে পালানোর স্টার ফ্লোতে ঠেলে দিয়েছিল——আশা করেছিল বোন এরপর থেকে তার কাছ থেকে মুক্ত হয়ে নতুন গ্রহে নিজের জীবন শুরু করবে।\nতবে প্রান্তর তারা ধ্বংসের পর, টিংক্ত আবার ফিন্তেকে খুঁজতে সম্পূর্ণ আত্মবিহীন ভ্রমণে বেরিয়ে পড়েছিল, অন্যদের দ্বারা চালিত ও ব্যবহৃত হওয়াতেও কিছু মনে করেনি। এমন টিংক্তকে @2 চার্চ আবিষ্কার করে, তারপর ঘুরতে ঘুরতে @3 এর হাতে পড়ে।\nটিংক্ত কখনো প্রতিরোধ করেনি। বরং বলা যায়, টিংক্ত বেশি চায় যে কেউ এসে তাকে বলুক কী করলে সবচেয়ে ভালো হবে——এমনকি সেটা মিথ্যা হোক, প্রতারণা হোক, ক্ষণস্থায়ী স্বপ্ন হোক, তবুও অসহায়ভাবে জমে দাঁড়িয়ে থাকার চেয়ে ভালো।\nঅন্তত, তার মানে ফিন্তের ভবিষ্যতে এখনও আশা আছে।"
  },
