  AwakerStory_11215_Content = {
    Text = "「P-063 অপেরা হাউস @2 ইভেন্ট」‑এ, পুড়ে যাওয়া ব্যাকস্টেজের এক কোণে একটি ধাতব বাক্স আবিষ্কৃত হয়, এবং তার ভেতরের সিলভার উদ্ধার করা হয়।\nমিথাগ বিশ্ববিদ্যালয়ের বর্তমান যন্ত্রপাতি দিয়ে বাক্সটির উপাদান শনাক্ত করা যায়নি। @2 নথি পর্যালোচনা এবং এর অলংকরণ খোদাই বিশ্লেষণের পর, অধ্যাপক ডল সিদ্ধান্তে পৌঁছান যে বাক্সটি কয়েক শতাব্দী আগে বিস্ফোরণে বিলুপ্ত হয়ে যাওয়া এক প্রাগৈতিহাসিক সভ্যতা থেকে আসতে পারে।\nসিলভারটি বাক্সের ভেতরে থাকলে নীরব ও লক্ষণহীন থাকে, কিন্তু বাইরে আনা হলে অবিরাম গুঞ্জনধ্বনি ছড়ায়। অধ্যাপক ডল সন্দেহ করেন, ধাতব বাক্সটি এক ধরনের সংকেত‑নিরোধক, যা বিশেষ ফ্রিকোয়েন্সির সংকেতকে সিলভারের সঙ্গে অনুরণন সৃষ্টি করতে বাধা দেয়।\nঅনুরণনশীল সিলভারের মডেলটিও শনাক্ত করা হয়েছে।"
  },
  AwakerStory_11215_Title = {
