  AwakerStory_11215_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11216_Content = {
    Text = "জাগরণকারী আইডি: MA-C06\nবিপদস্তর: A\nবিশেষ সংরক্ষণ প্রোটোকল: MA-C06 বর্তমানে মৃদু আলোযুক্ত জাগরণকারী পর্যবেক্ষণ কক্ষ 7-এ আবদ্ধ। @3-এর মস্তিষ্ক নিয়ন্ত্রণের ভয়ে MA-C06 ঘুমাতে অস্বীকার করে, তাকে কেবল একটি চেয়ার সরবরাহ করা হয়েছে।\nভাল আচরণ ও বন্ধুত্বপূর্ণ মনোভাবের কারণে, MA-C06-কে গ্রীনহাউস ব্যবহার এবং অনুসন্ধান কর্মকর্তা প্রহরীর সঙ্গে ক্যাম্পাসের কিছু অংশ ঘুরে দেখার অনুমতি দেওয়া হয়েছে।\n—「জাগরণকারী সংরক্ষণ নথি MA-C06」"
  },
  AwakerStory_11216_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_11216_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11217_Content = {
    Text = "মিথাগ মৃতদের শরীর থেকে নিষ্কাশিত সিলভার ব্যবহার করে জাগরণকারী তৈরি করে।\nভাস্করদের সমিতি জীবিত মানুষের শরীর থেকে সিলভার উৎপন্ন করে এবং তা দিয়ে জাগরণকারী তৈরি করে।\nএই দুটি ধারণা সম্পূর্ণ আলাদা। পরবর্তীটির সম্ভাবনার সীমা অত্যন্ত উচ্চ হলেও, এটি স্পষ্টতই নৈতিকতার বিরুদ্ধে, তাই এটি বারবার নিষিদ্ধ হওয়া সত্ত্বেও থামানো যায়নি এমন একটি নিষিদ্ধ গবেষণায় পরিণত হয়েছে।\nমোম জাদুঘরের ঘটনার পর, 24 কে মিথাগে ফিরিয়ে আনা হয়েছিল। সে দীর্ঘদিন ক্যাম্পাসের পর্যবেক্ষণ কক্ষ ও গবেষণাগারে ঘুরে বেড়িয়েছে, এবং বাইরে যাওয়ার সময় সবসময় বিশেষ সঙ্গী প্রয়োজন হতো।\nনিঃসন্দেহে, এটি একটি অত্যন্ত অনিয়ন্ত্রণযোগ্য জীবিত জাগরণকারী। পরবর্তী প্রায় অর্ধ বছরের পর্যবেক্ষণে, 24-এর শরীরে একের পর এক অনেক ব্যক্তিত্বের বিভাজন ঘটতে থাকে।\nসে হঠাৎ করে অপরিচিত বন্ধু ও শত্রু পেয়ে যেত, অনেক অদ্ভুত জিনিস কিনত, এমনকি না জেনেই চীনা ভাষা বলতে শিখে গিয়েছিল।\nতার জীবনে কখনো 「বিস্ময়」-এর অভাব হয় না।\n「24 হলো একটি বিচ্ছিন্ন ফাংশন যা একগুচ্ছ বিচ্ছিন্ন বিন্দু দিয়ে গঠিত।」 ডল মন্তব্য করল, 「সে যা বলে তার প্রতিটি কথা বিশ্বাস করো না।」"
  },
