  AwakerStory_11218_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11219_Content = {
    Text = "রামোনার শরীর দখল করার সময়, 「রামোনা」 কখনো ক্যাম্পাসে পা রাখেনি।\nরোটানের উদার মহানুভবতা, অজিয়ারের লাজুক আনুগত্য, উইলিয়ামের শান্ত আত্মসংযম, ডোরের কঠোর নিষ্ঠা... তার চেয়ে বেশি কেউ এই মুহূর্তগুলো হৃদয়ে গেঁথে রাখেনি।\nকিন্তু সে সবসময় মনে রেখেছে: এই সুন্দর জিনিসগুলো আর তার নয়।\nএখন তাকে সম্পূর্ণ মনোযোগ দিয়ে আরেকজন নিয়তি-নির্ধারিত ব্যক্তিকে রক্ষা করতে হবে... এটাও আরেকটি বিপন্ন বিশ্বকে রক্ষা করার জন্য, আরেকটি নিষ্পাপ নিজেকে রক্ষা করার জন্য।"
  },
  AwakerStory_11219_Title = {
