  AwakerStory_11220_Content = {
    Text = "জেনকিনের অত্যন্ত দক্ষ হাতদুটো একসময় সবাইকে চিন্তিত করেছিল যে সে হয়তো মিসাগার্ড বিশ্ববিদ্যালয়ের《দৈনিক পত্রিকা》-র নতুন নিয়মিত হয়ে উঠবে——সাক্ষাৎকারের বিষয় হিসেবে নয়, বরং একাধিক চুরির ঘটনার মূল পরিকল্পনাকারী হিসেবে।\nযদিও শেষ পর্যন্ত সে সত্যিই《মিসাগার্ড দৈনিক》-এর নিয়মিত হয়ে উঠেছিল, তবে তা অভ্যাস বদলাতে না পারার কারণে নয়——যথেষ্ট পরিমাণ ছোট কেক পেলে, রাস্তায় টিকে থাকার ওস্তাদও খুশি মনে অতীতের কৌশল ছেড়ে দিয়ে, তার ইঁদুর সঙ্গীর সাথে দুর্লভ অবসর জীবন উপভোগ করতে রাজি।\nসে বারবার খবরে আসার কারণ একটাই: 《দৈনিক》-এর ভালো সম্পাদক তাকে বেশি বেশি দিয়ে থাকেন।\nশ্শ——একটু আস্তে, তুমি কখনো জানো না সে কোন কোণায় লুকিয়ে আছে, শোনা তথ্য দিয়ে হান্নার কাছ থেকে আরও বেশি মিষ্টি আর কেক আদায় করতে প্রস্তুত।"
  },
  AwakerStory_11220_Title = {
    Text = "গল্প: ২"
