  AwakerStory_11221_Content = {
    Text = "বিজ্ঞান ও জ্ঞানের নতুন তারা, একটি সাধারণ শ্রমিক পরিবারে উদিত হয়।\nডোরের শৈশবের বেশিরভাগ সময় সিলিন্ডারের স্পন্দন ও গিয়ারের ঘূর্ণনের শব্দে পরিপূর্ণ ছিল।\nকিন্তু যন্ত্রের প্রতি ভালোবাসা, বিজ্ঞানের দুর্গম পর্বতে আরোহণের জন্য যথেষ্ট ছিল না।\nতাকে জ্ঞানের পথে নিয়ে যায় একটি মহামারী।\nঅজানা উন্মাদনা শহরকে গ্রাস করে, হাসপাতাল রোগীতে উপচে পড়ে, মর্গ ভারাক্রান্ত, সবাই আতঙ্কিত।\n「পুরো শহরের কবরস্থান যথেষ্ট নয়, দাদিকে খুঁড়ে বের করা আর মাকে পুড়িয়ে ফেলা——তোমাকে একটা বেছে নিতেই হবে।」\nতাই, ডোর তার মাকে আগুনে বিলীন হতে দেখে।\nঅন্যান্য দাহকৃতদের থেকে ভিন্ন, সেই মুঠো ভাঙা হাড় ও ছাই যাকে সে একদা 「মা」 বলে ডাকত, তার মধ্যে একটি উজ্জ্বল রৌপ্য পদার্থ প্রবাহিত হচ্ছিল।\n「আমি জানতে চাই, আমি কি আবার তাকে দেখতে পাব।」\n「আমি জানতে চাই, সেখানে তার দয়ালু আত্মা আছে কিনা।」\n「আমি জানতে চাই, সেই রৌপ্য পদার্থ জীবনের মূল উৎস কিনা, আত্মার সারাংশ কিনা।」\n「আমি জানতে চাই, বিশ্বের সকল কিছুর একটি সাধারণ সূচনাবিন্দু আছে কিনা।」\nউত্তর পাওয়ার আগে, ডোর ক্ষয় প্রপঞ্চের কাছে মাথা নত করবে না।"
  },
  AwakerStory_11221_Title = {
