  AwakerStory_11221_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11222_Content = {
    Text = "তার অস্পষ্ট ছায়া দেখে মনে পড়ে ডানা মেলে উড়তে চাওয়া সামুদ্রিক পাখির কথা, সাদা পোশাক যখন প্রবল সমুদ্রের বাতাসে উড়ে, দর্শক সর্বদা একটি ইউটোপিয়ার দিকে উড়ে যাওয়া পাখির ছবি আঁকতে পারে।\nজানি না সেই মাস্তুলের আড়াআড়ি কাঠে বসে থাকা কিশোরী, সেও কি কখনো নিজের উড়ে বেড়ানোর রূপ কল্পনা করেছিল?"
