  AwakerStory_11222_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11223_Content = {
    Text = "রুবি কানের দুল, নীলকান্তমণির নেকলেস, গার্নেট আর ম্যালাকাইট দিয়ে বোনা সুন্দর চুলের অলংকার……এগুলো কতটা উজ্জ্বল, কতটা সুন্দর, কতটা অপরিসীম মোহনীয়। এগুলো যেখানেই যায়, মানুষ পাগলের মতো ছুটে আসে।\nএই রত্নখচিত অলংকারগুলো কোনো 'সাজসজ্জার সামগ্রী' নয়, না, এগুলোই জগতের প্রকৃত নায়ক। ফিরোজা নেকলেস পরা অভিজাত তরুণীদের কবিরা গানে বেঁধে গেয়ে বেড়ান; কানে পান্না ঝোলানো বৃদ্ধ মহিলারাও আভিজাত্যের প্রতীক হিসেবে সম্মানিত হন। এমনকি তার মতো নীচু বংশের মেয়েরাও কব্জিতে একটা সস্তা ব্রেসলেট পরেই 'মুক্তা-কন্যা' আদুরে নাম পেয়ে যায়, অগণিত মানুষের দৃষ্টি আকর্ষণ করে।\nশুকনো গাছের ডাল হোক, পচা হাড়গোড় হোক, শুধু একগুচ্ছ সুন্দর রত্ন ঝুলিয়ে দিলেই সবার আকাঙ্ক্ষার বস্তু হয়ে ওঠে।\nযদি সেও সেই নেকলেস-কানের দুল, সেই ব্রেসলেট-মাথার অলংকার পরতে পারত, তাহলে নিশ্চয়ই সেও সবার দৃষ্টির কেন্দ্রবিন্দু হয়ে উঠত।"
  },
  AwakerStory_11223_Title = {
    Text = "গল্প: ৪"
