  AwakerStory_11223_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11224_Content = {
    Text = "মধুর বাক্চাতুর্য হলো কুঁড়ি থেকে ছড়িয়ে পড়া মধুর সুবাস, আর রাজসভাসদেরা হলো দোলায়মান পুষ্পকেশরের চারপাশে ঘিরে থাকা মৌমাছি ও প্রজাপতি।\nলালসায় সিক্ত কণ্টকলতা, অজান্তেই রঙিন জানালাকে শক্ত করে জড়িয়ে ধরেছে।\nযদিও তার চরিত্র জনসাধারণের নিন্দার পাত্র, যদিও মুকুটের ধারে তার হাত রক্তাক্ত, তবুও তিনি কখনো সেই ক্ষমতা ছেড়ে দেবেন না যা ইতিমধ্যে তার আলিঙ্গনে এসেছে।\nসর্বোপরি, এটাই হলো গোলাপের প্রস্ফুটনের জন্য প্রয়োজনীয় প্রকৃত পুষ্টি।"
  },
