  AwakerStory_11225_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11226_Content = {
    Text = "সে সবকিছু জানে।\nসে জানে ঘণ্টাঘর জরুরি মুহূর্তে বাজবে, জানে এরিদানাস উল্কাবৃষ্টি দশ বছর পর আসবে, জানে তার শরীরে ভিন্ন ধরনের শক্তি প্রবাহিত হচ্ছে।\nসে কিছুই জানে না।\nসে জানে না ক্যান্টিনের কারি রেসিপির গোপন মশলা, জানে না একটি গ্রহ ধ্বংসের পর এর ব্যাসার্ধ কীভাবে গণনা করতে হয়, জানে না তার ভবিষ্যৎ কোন দিকে টানা হবে।\nসে তার চারপাশের সবকিছু ছাড়তে পারে না, আবার তার অন্তর্দৃষ্টি যে পথ দেখায় তাও প্রতিরোধ করতে পারে না।\nসত্য ও সত্যের দিকে যাত্রায়, রামোনার দৃঢ়প্রতিজ্ঞ সঙ্গীর প্রয়োজন, যে তার দৈনন্দিন জীবনে ফেরার পথ রক্ষা করবে।"
  },
  AwakerStory_11226_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11226_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11227_Content = {
    Text = "যদি জেগে না উঠত তাহলেই ভালো হতো। অতল গহ্বরে নিমজ্জিত ব্যক্তির উচিত নয় চোখ মেলে উজ্জ্বল সূর্যের দিকে তাকানো।\nসে হওয়ার কথা ছিল অসাড় এক পরীক্ষামূলক উপাদান, এই পৃথিবী যাকে কবর দিয়ে দিয়েছে—তার যন্ত্রণার অনুভূতি বা ভালোবাসা পাওয়ার আকাঙ্ক্ষা থাকার কথা নয়।\nমায়ের মোহ ও অনিচ্ছা তার সারাজীবনের বিয়োগান্তক পরিণতি তৈরি করেছে, আর লিলি এখনও 「বিশ্বের নির্ধারিত পথ মেনে চলা উচিত কি না」 সেই দ্বিধায় আটকে আছে।\nহয়তো কোনো একদিন, ভাগ্যের বিরুদ্ধে লড়াই করা কারো কাছ থেকে সে উত্তর খুঁজে পাবে।"
  },
  AwakerStory_11227_Title = {
    Text = "গল্প: ৪"
