  AwakerStory_11227_UnlockDesc_1 = {
    Text = "নরমাল কঠিনতায় ৪র্থ অধ্যায় \"নীরবতা-র মাঝে\" সম্পন্ন করো"
  },
  AwakerStory_11228_Content = {
    Text = "মনে হচ্ছে আমি কোনো অতিপ্রাকৃত ঘটনায় জড়িয়ে পড়েছি, এখানে আমার সমস্ত আবিষ্কার লিপিবদ্ধ করছি……\nআমরা মূলত এভরোটাসের প্রত্নতাত্ত্বিক খননের চূড়ান্ত পর্যায়ে ছিলাম, কিন্তু একদিন ঘুম থেকে উঠে দেখি প্রত্নতাত্ত্বিক দলের অন্য সব সদস্য উধাও হয়ে গেছে, আর এই শহরটি যেন রাতারাতি হাজার বছর পিছিয়ে গেছে।\nবহু আগে ধ্বংসপ্রাপ্ত প্রাচীন স্থাপনাগুলো মাটি ফুঁড়ে জেগে উঠেছে, শহরটির প্রকৃত রূপ ফিরিয়ে এনেছে, সেই সাথে শহরের অগণিত বাসিন্দাদের কঙ্কালও।\nউত্তেজনা, বিস্ময় আর ভয় একসাথে আমার মস্তিষ্ককে আঁকড়ে ধরেছে। যদিও আমি অসংখ্য কঙ্কাল দেখেছি, তবুও চোখের সামনের এই দৃশ্যে আমি ক্রমাগত কাঁপছি। যদি অন্য কেউ আমার এই অভিজ্ঞতার মধ্য দিয়ে যেত, সে আমার চেয়েও বেশি আতঙ্কিত হতো।\nএই শহরের সবাইকে মনে হচ্ছে একই ব্যক্তি নৃশংসভাবে হত্যা করেছে, অগণিত কঙ্কাল রাস্তায় ছড়িয়ে আছে, ঘরের মধ্যে পড়ে আছে। শহরের দরজা কোনো কারণে শক্তভাবে বন্ধ, দরজার পাশে ভিড় করে আছে সেইসব কঙ্কাল যারা পালাতে চেষ্টা করেও নৃশংসভাবে নিহত হয়েছে, যেন হাড়ের তৈরি একটি ছোট টিলা।\nআমি একটিও ব্যতিক্রম খুঁজে পাইনি — পুরুষ, নারী, বৃদ্ধ, শিশু…… অসংখ্য মানুষের দেহ বা মাথার খুলি কোনো বিশাল ভোঁতা অস্ত্র দিয়ে চূর্ণ করা হয়েছে। শুকিয়ে যাওয়া সাদা হাড়গুলোর দিকে তাকাতে তাকাতে আমি ক্ষণিকের জন্য যেন পুরো শহর জুড়ে রক্তের স্রোত বয়ে যেতে দেখলাম।\nএখানে আসলে কী ঘটেছিল?\n……\nআমি হতবিহ্বল হয়ে চারদিকে খুঁজেছি, কিন্তু কোনো সূত্র পাইনি, যতক্ষণ না আমি শহরের কারাগারে প্রবেশ করলাম।\nএখানকার দৃশ্য বিশেষভাবে ভয়াবহ, খুনি প্রচণ্ড ক্রোধে পুরো কারাগার ধ্বংস করেছে। দেয়ালে শুকনো বাদামি রঙের বিকৃত লেখা আছে, মনে হচ্ছে কেউ মৃত্যুর আগে রক্ত দিয়ে অভিযোগ লিখে গেছে। আমি মনোযোগ দিয়ে পড়ার চেষ্টা করলাম, মনে হলো সেটা \"দুষ্ট আত্মা\" শব্দ দুটো।\nদুষ্ট আত্মা? এটা কি গণহত্যাকারী খুনিকে বোঝাচ্ছে, নাকি এই শহর সত্যিই কোনো অতিপ্রাকৃত ঘটনার সম্মুখীন হয়েছিল?\nসত্যিই, একজন মানুষের পক্ষে পুরো শহর হত্যা করা অকল্পনীয়, সম্ভবত কেবল একটি প্রকৃত দুষ্ট আত্মাই এত নৃশংসভাবে এতগুলো প্রাণ সংহার করতে পারে।\nকারাগার থেকে বের হওয়ার পর, শহরটিতে কোনো এক সূক্ষ্ম পরিবর্তন ঘটেছে বলে মনে হলো, আমার নাক ক্রমাগত একটা ক্ষীণ রক্তের গন্ধ পাচ্ছে।\nআমি যখন বের হওয়ার পথ খুঁজছিলাম, হঠাৎ একটা অপ্রত্যাশিত শিকলের শব্দ শহরে প্রতিধ্বনিত হলো, যেন কেউ কোনো ভারী জিনিস টেনে এগিয়ে আসছে।\nদুষ্ট আত্মা! সেই দুষ্ট আত্মা…… দুষ্ট আত্মা আমাকে খুঁজে পেয়েছে! আমি প্রাণপণে দৌড়ালাম, কিন্তু যেখানেই দৌড়াই না কেন, সেই ভয়ংকর শিকল টানার শব্দ সবসময় আমাকে অনুসরণ করছে।\nআমি আর দৌড়াতে পারছি না, একটা বাড়ির টেবিলের নিচে লুকিয়ে আছি, দরজা তালা দিয়েছি, কিন্তু সেই শিকলের শব্দ এখনও আমাকে তাড়া করছে। আমি শুনতে পাচ্ছি সে আসছে, সে এখানে ক্রমশ কাছে আসছে……\nআমি কতটাই না চাই এসব শুধু আমার একটা স্বপ্ন হোক, জেগে উঠলেই সব মিলিয়ে যাবে, একটু দাঁড়াও…… মনে হচ্ছে শব্দটা থেমে গেছে, দুষ্ট আত্মা হয়তো চলে গেছে?\n……\nগবেষক টীকা: স্বাভাবিক হাতের লেখা এখানেই শেষ, শুধু শেষের বিকৃত তিনটি শব্দ অবশিষ্ট আছে, পরীক্ষা-নিরীক্ষার পর সেই তিনটি শব্দ সম্ভবত:\nদরজা খুলে গেছে\n——এভরোটাস প্রত্নতাত্ত্বিক দলের প্রয়াত প্রত্নতত্ত্ববিদের ডায়েরি থেকে উদ্ধৃত"
  },
