  AwakerStory_11228_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11229_Content = {
    Text = "এমনকি যখন গ্ল্যাডিয়েটররা প্রশিক্ষণ মাঠ সম্পূর্ণ পুড়িয়ে দিয়েছিল, তার বাবা-মায়ের মাথা উঁচু দেয়ালে ঝুলিয়ে দিয়েছিল, তখনও আগ্রিপ্পা বিশ্বাস করতে পারেনি——এই নীচ, বশ্য দাসদের এমন সাহস কীভাবে হতে পারে?\nরোমে, মানুষ দুই ধরনের：যারা অন্যদের দাস বানায়, আর যারা অন্যদের দাস হয়।\nআগ্রিপ্পা ছিল ভাগ্যবান। সে ছিল কাপুয়ার সবচেয়ে বড় গ্ল্যাডিয়েটর প্রশিক্ষণ মাঠের মালিকের মেয়ে। সে যথেচ্ছাচার করত, দাপটের সাথে চলত, এমন কিছু ছিল না যা সে করতে সাহস করত না বা পারত না।\nকিন্তু এখন, সে একটি আতঙ্কিত খরগোশের মতো, ভূগর্ভের কোণে কুঁকড়ে আছে, বাইরের উল্লাস তার কাছে নরকের সমান।\nদাস বিদ্রোহ। কী অপরিচিত শব্দ। আগ্রিপ্পার বয়স মাত্র পনেরো, এই পৃথিবীতে এখনও অনেক কিছু আছে যা সে বোঝে না।\nসে ছায়ায় এক জোড়া লাল আভাযুক্ত চোখ দেখতে পেল। সেটা ছিল ইউউহাশি, প্রশিক্ষণ মাঠের সবচেয়ে বড় অর্থ উপার্জনকারী, অত্যন্ত বিপজ্জনক হওয়ায় সারা বছর ভূগর্ভে শৃঙ্খলিত থাকত।\nদুজনের মধ্যে সবসময়ই বিরোধ ছিল, সেই রাতে তারা কী কথা বলেছিল কেউ জানে না। আগুনে চাটা রক্তাক্ত রাত শেষ হওয়ার পর, আগ্রিপ্পাকে অন্ধকার ভূগর্ভে মৃত অবস্থায় পাওয়া গেল, তার পাশে কেউ ছিল না। সে দাসদের হাতে মারা যায়নি——কেউ তার রক্ত শুষে নিয়েছিল, একটি ফোঁটাও বাকি রাখেনি।\nঅবশ্যই, তার মাথাও শেষ পর্যন্ত কেটে ফেলা হয়েছিল, তার বাবা-মায়ের পাশেই ঝোলানো হয়েছিল, একসাথে বাতাসে দুলছিল, রোমের দিকে মুখ করে।"
  },
  AwakerStory_11229_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_11229_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11230_Content = {
    Text = "হান্না: আপনার দৃষ্টিতে, স্বয়ংক্রিয় পুতুল থাকাকালীন আপনি এবং বর্তমান আপনার মধ্যে কোনো পার্থক্য আছে কি?\nএরিকা: সেই সময়ের আমার মধ্যে 「আবেগ」 সংরক্ষিত ছিল।\nহান্না: সেটা ঠিক কেমন ধরনের আবেগ ছিল, যদি আপনি শেয়ার করতে চান?\nএরিকা: দুঃখিত, আমি আপনার প্রশ্নটি বুঝতে পারছি না।\nহান্না: আহ, মানে, যদি আপনি মনে করেন প্রশ্নটি ব্যক্তিগত, তাহলে উত্তর না দিলেও চলবে।\nএরিকা: আমি 「ইচ্ছা বা অনিচ্ছা」 অনুভব করতে পারি না, অত্যন্ত দুঃখিত।\nহান্না: তাহলে... সেই সময়ের আপনার আবেগগুলো আমাকে বলুন?\nএরিকা: রক্তমাংসের আমি বিস্ফোরণের পরেও বেঁচে ছিলাম: আনন্দ, উল্লাস।\nনিজের চেতনা যান্ত্রিক পুতুলে স্থানান্তরিত ও সংরক্ষিত হয়েছে জানতে পেরে: উত্তেজনা, উদ্দীপনা।\nচেতনা ধীরে ধীরে নিয়ন্ত্রণের বাইরে যাচ্ছে এবং তীব্র ধ্বংসাত্মক ইচ্ছা জন্মাচ্ছে বুঝতে পেরে: উত্তেজনা, ভয়, সুরক্ষা।\nহান্না: সুরক্ষা?\nএরিকা: অত্যন্ত দুঃখিত, বিস্তারিত তথ্য হারিয়ে গেছে।\nহান্না: তাহলে অন্য একটি প্রশ্ন করি, এটা এই পত্রিকার পাঠকরাও জানতে চান — আপনার এখন আর আবেগ নেই কেন? কী হয়েছিল?\nএরিকা: অজ্ঞাত কারণে মানসিক সংযোগের মাধ্যমে বিবেক পুনরুদ্ধার করা সম্ভব হয়নি, বিশ্ববিদ্যালয় প্রয়োজনীয় পদক্ষেপ নিয়েছে — সিলভার কোর সহায়ক যন্ত্রের মাধ্যমে সমস্ত আবেগ দমন করা হয়েছে, আক্রমণাত্মকতা ও বিপদ হ্রাস করা হয়েছে, বুদ্ধিমত্তা ও কার্যকারিতা বজায় রাখা হয়েছে।\n——《মিসাগ ডেইলি》 থেকে উদ্ধৃত, 《উদ্বোধিত শিক্ষক কর্মীর বিশেষ সাক্ষাৎকার: টিক-টক মানুষ》"
  },
  AwakerStory_11230_Title = {
    Text = "গল্প: ৩"
