  AwakerStory_11231_Content = {
    Text = "কর্নওয়াল কাউন্টির দক্ষিণ উপকূলে জরিপ চালানোর সময়, আমি একটি পরিত্যক্ত ছোট গ্রাম আবিষ্কার করি যা কোনো মানচিত্রে নেই। পরীক্ষা-নিরীক্ষার পর, আমরা নিশ্চিত করি যে এটি ক্ষয়ীভবন ঘটনার প্রাদুর্ভাবে 「অস্তিত্ব মুছে যাওয়া「 একটি গ্রাম।\nগ্রামে আমরা প্রচুর পরিমাণে অস্বাভাবিক সামুদ্রিক জীবের নমুনা সংগ্রহ করি, যার মধ্যে রয়েছে: মাংসাশী বৈশিষ্ট্যযুক্ত জায়ান্ট ক্ল্যাম, তাপ-সহনশীল বরফ সমুদ্রের দেবদূত, এবং সবচেয়ে অস্বাভাবিক হলো সর্বত্র ছড়িয়ে থাকা 「উভচর জেলিফিশ「।\nএকটি পুরনো বাড়িতে যা ইতিমধ্যে জেলিফিশের বাসায় পরিণত হয়েছে, আমরা তরল অবস্থায় একটি সিলভার কোর উদ্ধার করি, ওজন প্রায় 11.85 ড্রাম। এই সিলভার কোর সরিয়ে আনার সময়, জরিপ দলের সদস্যরা রূপান্তরিত জেলিফিশের আক্রমণের শিকার হয়, সৌভাগ্যবশত, এই অস্বাভাবিক উভচর জেলিফিশের সকল গ্রন্থি ইতিমধ্যে পচে গেছে, আর স্নায়ু বিষাক্ততা নেই।\n——《A.F.308 সালের তৃতীয় জীববিজ্ঞান বিভাগ মাঠ জরিপ রেকর্ড》"
  },
  AwakerStory_11231_Title = {
    Text = "গল্প: ১"
