  AwakerStory_11231_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11232_Content = {
    Text = "আলোকে ভয়, দৃষ্টিকে ভয়, ভালোবাসাকে ভয়, আলিঙ্গনকে ভয়।\nআলোর জন্য তৃষ্ণা, দৃষ্টির জন্য তৃষ্ণা, ভালোবাসার জন্য তৃষ্ণা, আলিঙ্গনের জন্য তৃষ্ণা।\nযদি আমি অন্যদের কষ্ট না দিতাম তাহলে কতই না ভালো হতো, যদি আমি অন্যদের বিরক্ত না করতাম তাহলে কতই না ভালো হতো, যদি আমি টিউগের মতো একটা বুদ্ধিমান শিশু হতাম, যদি আমি জেনকিনের মতো একটা সাহসী শিশু হতাম, যদি আমি যেন……\nতাহলে, প্রখর রোদে পুড়তে হতো না, অন্যদের ঘৃণার পাত্র হতে হতো না, তাই না?\nঅবাস্তব উদ্বেগ বুকে নিয়ে পুতুলটি, ছায়ার ভেতর থেকে, আলোর সীমানার দিকে ভীরুভাবে তার প্রায় স্বচ্ছ ফ্যাকাশে ছোট্ট হাতটি বাড়িয়ে দিল।"
  },
  AwakerStory_11232_Title = {
