  AwakerStory_11233_Content = {
    Text = "সে সবুজ শিখার মাঝে নৃত্য করে, মৃদু আলো নর্তকীর কোমল ও ভক্তিপূর্ণ মুখমণ্ডল আলোকিত করে। শেনের ঘূর্ণায়মান নৃত্যপদক্ষেপের সাথে সাথে, পান্না শিখা সকল দুষ্কৃতকারীর আত্মাকে প্রজ্বলিত করে, মঞ্চের সমস্ত কলুষ দগ্ধ করে ভস্মীভূত করে।"
