  AwakerStory_11234_Content = {
    Text = "মার্চ\nআটলান্টিস ভ্রাম্যমাণ অ্যাকোয়ারিয়ামে স্বাগতম! আমি এবারের ভাষ্যকার ওরেটা, জেলিফিশ গাড়িতে ওঠার সময় পায়ের দিকে খেয়াল রেখো!\nজলের ট্যাঙ্কে গ্রীষ্মমণ্ডলীয় সমুদ্রের বিরল জেলিফিশ প্রদর্শিত হচ্ছে, ঝনঝন! দেখো——\nএপ্রিল\nএ, এটা কী হলো…… সবাই কোথায় গেল…… পরিচালক! পরিচালক! জেলিফিশরা, ওরেটার জেলিফিশরা সব অদৃশ্য হয়ে গেছে!\nঅ্যাকোয়ারিয়ামে কখনো জেলিফিশ প্রদর্শনী ছিল না? কিন্তু আমি স্পষ্ট মনে করতে পারছি……\nমে\nপ্রদর্শনী খুব কম বলে, কোনো দর্শক নেই তাই চালানো যাচ্ছে না…… উহু…… সবাইকে বিদায়……\nযদি, যদি আবার ভ্রাম্যমাণ প্রদর্শনী করা যায়, অবশ্যই আবার ওরেটাকে খুঁজে আসবে কিন্তু!\nজুন\nওরেটা খুব ক্লান্ত…… অসুস্থ হয়ে গেছে কি……\nআরে…… জেলিফিশরা! দুঃখিত, ওরেটা সবার জন্য ডায়াটম ছিটাতে পারছে না।\nওরেটা সুস্থ হলে, সবাই আবার একসাথে সাঁতার কাটবো……"
  },
