  AwakerStory_11238_Content = {
    Text = "সেই বছর নভেম্বরের এক তুষারপাতের দিনে, 24 অসুস্থ হয়ে পড়ল।\nটানা এক সপ্তাহ তীব্র কাজের চাপের পর, তার প্রচণ্ড জ্বর হলো এবং সে বাড়িতে কয়েকদিন শুয়ে রইল।\nঘোরের মধ্যে সে যেন কানের কাছে একটা ছোট ইঁদুরের করুণ ডাক শুনতে পেল। কতক্ষণ পর জানা নেই, কেউ একজন এসে তার পাশে দাঁড়াল।\nসে ওই চোখ দুটো চিনতে পারল — সেই নর্দমার ভেতরের শিশুটি। তার সারা গায়ে কাদা, হাতে ধরা ময়লা ওষুধের বড়িগুলো সে 24-এর দিকে বাড়িয়ে দিল।\n「এই নাও, খেয়ে নাও।」 ছোট্ট মেয়েটি শক্ত গলায় বলল, কণ্ঠস্বরটা বেশ মিষ্টি — দেখা গেল সে একটি মেয়ে।\n24 তার কনুই আর মুখের ক্ষতগুলোর দিকে তাকাল, জিজ্ঞেস করল না এই ওষুধগুলো কোথা থেকে এসেছে। সে মেয়েটির হাত শক্ত করে ধরে রাখল।\nমেয়েটি অস্বস্তিতে কয়েকবার গুনগুন করল, তারপর ছোট বাচ্চাকে ভোলানোর মতো দুর্দান্ত ভঙ্গিতে বলল: 「আমি যাচ্ছি না। তুমি সুস্থ হলে তবেই যাব।」\nসুস্থ হলেও যেও না।\n24 মনে মনে উত্তর দিল।\nশীতের শুরুতে লন্ডিনিয়ামে পুরো এক সপ্তাহ ধরে তুষারপাত হলো। যেদিন তুষারপাত থামল, 24 খুব খুশি হলো, কারণ শুধু তার জ্বরই সারেনি, সে একটি ছোট বোনও পেয়েছিল।"
  },
  AwakerStory_11238_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11238_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11238_UnlockDesc_1 = {
    Text = "নরমাল কঠিনতায় 2য় অধ্যায় 「মোমের প্রতিকৃতির নামে」 সম্পন্ন করো"
  },
  AwakerStory_11239_Content = {
    Text = "「পাপ করেছ যারা, এটি লোভের অতল, নরকের তলদেশ। কালো কুকুর এখানে গর্জন করে, দুর্গন্ধ এখানে ছড়িয়ে পড়ে, মৃত্যুঘণ্টা এখানে বাজে। তোমরা তোমাদের লাগামহীন লোভ ও নিষ্ঠুর কর্মের কারণে এখানে একত্রিত হয়েছ, তোমাদের জন্য অপেক্ষা করছে কষ্ট ও মৃত্যু।」\nপ্যান্ডিয়া নিউগেট কারাগারে কর্মরত ছিলেন, সেটি ছিল সমগ্র লন্ডিনিয়েনের সবচেয়ে অবদমিত, সবচেয়ে অন্ধকার, সবচেয়ে আলোহীন কলুষিত কোণ। একসময় রক্তমাখা হাতের ভারী অপরাধীরা শিকল ও বেড়ি পরে, মর্যাদা কেড়ে নেওয়া হয়ে, গোলকধাঁধার মতো কারাকক্ষে তার কাছে হাঁটু গেড়ে ক্ষমা চাইত, তার চামড়ার বুটে চুমু খেত, বিনয়ের সাথে নিজেদের তার দাস বলে পরিচয় দিত।\nযখনই নতুন ফাঁসি কার্যকর হতো, সে নতুন মৃত্যুদণ্ডপ্রাপ্তদের ডেকে আনত, তাদের নিজেদের পরিণতি দেখতে বলত। যখন দণ্ডিত ব্যক্তি দড়িতে ছটফট করতে করতে মারা যেত, সে উঁচুতে বসে, চরম দুষ্ট অপরাধীদের ভয় ও হতাশার যন্ত্রণায় কাঁপতে দেখে উপভোগ করত।\nকিন্তু 「নরকের বিড়াল」রাও লক্ষ্য করেছে, প্যান্ডিয়া অসংখ্যবার নিউগেট কারাগারের লোহার দরজার কাছে এসে, পায়ের আঙুলে ভর দিয়ে লন্ডিনিয়েন শহরের বাইরে তাকিয়ে থাকত, যেন দূর থেকে আসা কোনো দর্শনার্থীর অপেক্ষায়।\n「আসলে আমিও তো, এই অন্ধকার স্যাঁতসেঁতে দুঃখময় কারাগার থেকে চিরকাল বের হতে না পারা, সেই বন্দীদেরই একজন মাত্র।」"
  },
