  AwakerStory_11240_Content = {
    Text = "A.F.3@1 সালের 3 জুলাই, ন্যাথানিয়েল ফরবস গ্রিন ফাউন্ডেশনের আমন্ত্রণে, মিথাগ বিশ্ববিদ্যালয় 「ভূত জাহাজ「 সোনা-নিল‑এর তদন্তে অংশগ্রহণ করে।\nদশ বছর আগে ডুবে যাওয়া ঘোষণা করা সেই বার্কে আরোহনের পরপরই, অনুসন্ধান কর্মকর্তা ফিঙ্গাল·ইয়োহানসেন‑এর যোগাযোগ সংকেত সঙ্গে সঙ্গে অদৃশ্য হয়ে যায়।\nA.F.3@1 সালের 10 জুলাই, বিশ্ববিদ্যালয় অবশেষে তার সাথে যোগাযোগ স্থাপন করতে সক্ষম হয়। লিও হাইটসের উত্তর উপকূলে, মূল গন্তব্য থেকে 300 নটিক্যাল মাইল দূরে অবস্থানরত অনুসন্ধান কর্মকর্তা ইয়োহানসেন ঘোষণা করেন যে সোনা-নিলে পা রাখার মুহূর্তেই তিনি সময় ও স্থানের অনুভূতি হারিয়ে ফেলেছিলেন এবং জাহাজে ঘটে যাওয়া কোনো কিছুই স্মরণ করতে পারছেন না।\nএ পর্যন্ত অনুসন্ধান কর্মকর্তা ইয়োহানসেন কেবলমাত্র অস্পষ্টভাবে একটি শব্দ মনে করতে পারেন: এলিসিয়ান।\nভূত জাহাজটির নিজস্ব নিরীহ প্রকৃতির কারণে, মিথাগ বিশ্ববিদ্যালয় আজ (A.F.3@1 বছর, 24 ডিসেম্বর) তদন্ত সমাপ্ত করার সিদ্ধান্ত নিয়েছে।\n「ফাইল: সোনা-নিল দুর্ঘটনা তদন্ত।「"
  },
  AwakerStory_11240_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_11240_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11241_Content = {
    Text = "রাস্তার জীবন তার জন্য কঠিন কিছু ছিল না।\nখিদে পেলে কাজ খুঁজত, কাজ না পেলে নিজের দুই হাতে জীবিকা নির্বাহ করত। ব্রাউনের সাথে তার বোঝাপড়া এতটাই নিখুঁত ছিল যে অন্য কারও সাহায্য ছাড়াই খাওয়া-দাওয়ার ব্যবস্থা করে নিতে পারত।\n「আমাদের কারও দরকার নেই,」 সে তার ইঁদুর সঙ্গীর কাছে শপথ করেছিল, 「আমাদের শুধু একে অপরকে দরকার।」\nকিন্তু তুষারপাতের রাতে, সে নিজেকে থামাতে পারত না সেই জানালাগুলোর দিকে তাকাতে যেখানে হলদে আলো জ্বলত, যেখানে মানুষেরা অল্প খাবারের পাশে একে অপরকে জড়িয়ে ধরে শুভকামনা জানাত।\nসত্যিই তার মাথার ওপর ছাদের দরকার ছিল না, বিলাসবহুল নরম বিছানা-বালিশের দরকার ছিল না, সত্যিই তার একজন বিশ্বস্ত সঙ্গী ছিল, তবুও সে জানতে চাইত, দীর্ঘদিন ধরে একটা ঘর বলে কিছু থাকলে সেটা কেমন অনুভূতি হতো?\nএই প্রশ্নের উত্তর সে পেয়েছিল যখন মেসন তাকে দত্তক নিয়েছিল।"
  },
  AwakerStory_11241_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11241_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11242_Content = {
    Text = "「রামোনা」 তার আবির্ভাবের বিষয়ে অত্যন্ত সংযত। সে যেমনটা বলেছিল, কেবল গোপনরক্ষক তাকে ডাকলেই সে রামোনার দেহ ধার করে এই জগতে আসে।\nসে সবসময় তাড়াহুড়ো করে আসে আর চলে যায়, যুদ্ধ ছাড়া আমাদের জগতের সাথে আর কোনো সম্পর্ক রাখতে চায় না বলে মনে হয়।\nসে কি তাকে তাড়া করা দুঃস্বপ্নগুলোকে ভয় পায়? নাকি সে যা হারিয়েছে তার প্রতি আসক্ত হয়ে পড়ার ভয়ে এমন করে……আমরা জানি না।"
  },
  AwakerStory_11242_Title = {
    Text = "গল্প: ২"
