  AwakerStory_11242_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11243_Content = {
    Text = "A.F.1@2 সাল@1 মাস@1 তারিখ 10:31, পুলিশ একটি রিপোর্ট পায়, @1@1 ম্যানরের ভেতরে একাধিক স্থানে রক্তের দাগ পাওয়া গেছে। থানার গোয়েন্দা বেলফোর্ড অবিলম্বে ঘটনাস্থলে যান এবং তদন্ত শুরু করেন, রক্তের দাগের মধ্যে অজানা উপাদানের সবুজাভ-নীল আঠালো তরল আবিষ্কার করেন।\n13:44, গোয়েন্দা বেলফোর্ড রিপোর্ট জমা দেন, মিস্টিরিয়া চুক্তি পর্যালোচনা পরিষদ তৎক্ষণাৎ মামলাটি গ্রহণ করে।\n14:25, পর্যালোচনা পরিষদের সপ্তম সাড়াদান দল ম্যানরে পৌঁছায়, সংশ্লিষ্ট ব্যক্তিদের নিয়ন্ত্রণে নেয় এবং ঘটনাস্থল সিলগালা করে। পরিস্থিতি বিচার করে, দলনেতা অনুমান করেন যে ম্যানরের ভেতরে কমপক্ষে 5 জন শিকার রয়েছে এবং ম্যানরে বিভিন্ন মাত্রার ক্ষয়ীভবন ঘটেছে।\n18:00, মিসাগার বিশ্ববিদ্যালয়ের তদন্তকারী ঘটনাস্থলে পৌঁছান, ক্ষয়ীভবন ঘটনার অস্তিত্ব নিশ্চিত করেন এবং জাগ্রত সত্তা সঙ্গে নিয়ে ম্যানরে প্রবেশ করে পরিষ্কার ও তদন্ত পরিচালনা করেন।\n23:11, ম্যানর পরিষ্কার সম্পন্ন। তদন্তকারী ম্যানরের ভূগর্ভস্থ কক্ষ ও পাঠকক্ষের গোপন ঘরে বিপুল পরিমাণ রহস্যবিদ্যা সংক্রান্ত নথি ও আচার-অনুষ্ঠানের উপকরণ আবিষ্কার করেন এবং একটি অসম্পূর্ণ জাগ্রত সত্তা খুঁজে পান। জাগ্রত সত্তাটি নিজেকে 'পরিচারিকা কারেন' বলে পরিচয় দেয়, সে @3 ডিউকের প্রধান দাসী। আবিষ্কারের সময় জাগ্রত সত্তাটি পরিচারিকার পোশাক পরিহিত ছিল, বিভিন্ন ধরনের অলংকার পরা ছিল এবং অত্যন্ত উদ্যমের সাথে ভূগর্ভস্থ কক্ষ পরিষ্কার করছিল। এই জাগ্রত সত্তাটির মানবাকৃতি রয়েছে, সবুজাভ-নীল ত্বক, চার অঙ্গের প্রান্তভাগ অর্ধস্বচ্ছ আঠালো অবস্থায় রয়েছে, সম্ভবত অসম্পূর্ণ বা ত্রুটিপূর্ণ আহ্বানের ফলাফল। তার শরীর থেকে নিঃসৃত আঠালো তরল এবং ছিন্ন অঙ্গে পাওয়া পদার্থের গঠন ও রঙ সম্পূর্ণ মিলে যায়।\nতদন্তকারী তাকে জিজ্ঞাসাবাদ করেন, পরিচারিকা কারেন @1 সত্য স্বীকার করে এবং জানায় যে সবকিছু তার মনিবের দৃষ্টি আকর্ষণের জন্য করা হয়েছিল। @3 ডিউককে গ্রেপ্তার করা হবে জানার পর, সে বিড়বিড় করে বলে: 'তাহলে আমার নতুন মনিব কোথায়?' এরপর জেলিতে পরিণত হয়ে বিলীন হয়ে যায়, রেখে যায় একটি রৌপ্য মূল।\n01:37, পর্যালোচনা পরিষদের সপ্তম সাড়াদান দলের দলনেতা সংশ্লিষ্ট ব্যক্তিদের জিজ্ঞাসাবাদ করেন এবং 《চুক্তি》 অনুসারে @1@1 ম্যানরের মালিক @3 ডিউককে আটক করেন।\n03:09, তদন্তকারী মিসাগার বিশ্ববিদ্যালয়ে ফিরে আসেন এবং K-033 নম্বর রৌপ্য মূলটি নথিভুক্ত করে সংরক্ষণাগারে জমা দেন।\n——《@1@1 ম্যানর ঘটনার নথি》"
  },
  AwakerStory_11243_Title = {
    Text = "গল্প: ১"
