  AwakerStory_11243_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11244_Content = {
    Text = "A.F.3@2 সালে, ইয়াগ্রো প্রজাতন্ত্রের উপকূলীয় শহরে ক্ষয়ীভবন ঘটনা দেখা দেয়। এই ক্ষয়ীভবন ঘটনা বন্দরকে কেন্দ্র করে সর্পিলাকারে ছড়িয়ে পড়ে, কয়েকশো মিটার এলাকা জুড়ে বিস্তৃত হয়, @1 জনের মৃত্যু ঘটায়।\nতদন্তে জানা যায়, ক্ষয়ীভবন ঘটনা প্রথম বন্দরের মাছ ধরার নৌকায় দেখা দেয়। সেই নৌকাটি A.F.3@2 সালের @1 মাসের @1@1 তারিখে সমুদ্রে মাছ ধরতে গিয়ে রূপালি সর্পিল নকশাযুক্ত একটি কড মাছ-সদৃশ জীব ধরে।\nসেই জীবটির দেহ নরম ছিল, ধারালো যন্ত্র দিয়ে কাটার পর সম্পূর্ণ ভেঙে যায়, শামুক ও অন্যান্য অবশিষ্টাংশ মিশ্রিত তরল পদার্থ বের হয়। নৌকা বন্দরে পৌঁছানোর পর, ধরা মাছের উপর ইতিমধ্যে শামুক-জাতীয় বৃদ্ধি দেখা দিয়েছিল, কিন্তু কেউ মনোযোগ দেয়নি, যতক্ষণ না একজন জেলে নিজেকে শামুকের খোল মনে করে শরীর মোচড়ানোর চেষ্টা করে গুরুতর আহত হয়ে হাসপাতালে ভর্তি হয়, তখনই ঘটনাটি রিপোর্ট করা হয়।\nপরবর্তীতে, মিসাগের সংশ্লিষ্ট কর্মীরা @4 ক্যানিং কারখানায় ক্ষয়ীভবনের উৎস খুঁজে পান, তা নির্মূল করার পর O-36 সিলভার কোর উদ্ধার করেন।\n——《জাগ্রত সত্তা সিলভার কোর সংগ্রহ প্রতিবেদন: O-36》"
  },
