  AwakerStory_11246_Content = {
    Text = "উইনকোরের একসময় নিজের একটি নাম ছিল।\nসেই নামটি বাবা-মায়ের ভালোবাসায় সিক্ত ছিল,\nবন্ধুরা বারবার সেটি লিখত, স্মৃতিতে গেঁথে রাখত,\nজন্মদিনের সাথে ক্যালেন্ডারে চিহ্নিত করত।\n\nউইনকোরের একসময় নিজের একটি মুখ ছিল।\nসেই চেহারা বাবা-মায়ের দৃষ্টিতে বেড়ে উঠেছিল,\nবন্ধুদের সঙ্গে আনন্দে হেসেছিল, দুঃখে কেঁদেছিল,\nস্মৃতির সাথে ছবিতে চিরকালের জন্য ধরা পড়েছিল।\n\nউইনকোরের একসময় নিজের একটি ঘর ছিল,\nকার্দাস থেকে বহু দূরে, সম্পূর্ণ ভিন্ন।\nশেষপর্যন্ত বাবা-মায়ের অস্তিত্বের সাথে তা বিলীন হয়ে গেল।\nকালো @2 গ্রাস করেছিল, তারপর সম্পূর্ণ বিলীন।\n\nউইনকোরের একটি গভীর ভয় আছে।\nতা ঘোর কালো, ভয়ংকর, সবকিছু গ্রাস করে, কোনো যুক্তি মানে না।\nতা সবকিছু গলিয়ে দেয়, ক্ষয় করে, নিঃশেষ করে,\nএকবার স্পর্শ করলে অস্তিত্বই ছাইয়ে পরিণত হয়।\n\nউইনকোরের কাছে এখন শুধু একটি নাম অবশিষ্ট, যা একসময় তার নিজের ছিল।\nমানুষের দেহ তা উচ্চারণ করতে পারে না, এমনকি অনুকরণও করতে পারে না,\nসে কেবল চরম ক্লান্তির সময় চোখ বন্ধ করে,\nপরিচিত ডাক শোনা যায় এমন একটি স্বপ্নের জন্য প্রার্থনা করে।"
  },
