  AwakerStory_11248_Content = {
    Text = "বেঁচে থাকা যেমন সহজাত প্রবৃত্তি, তেমনি এক অপরিত্যাজ্য বোঝাও। মৃত্যুর সামনে, যেখানে স্মৃতিটুকুও টিকে থাকে না, কেবল সে-ই তাদের অস্তিত্বের প্রমাণ — তার বাবা-মা, তার প্রিয় বন্ধুরা, তার জন্মভূমির সবকিছু।\nতাই সে পালিয়েছিল, কালো রঙে রঞ্জিত হয়নি এমন এক জগতের দিকে, সমুদ্রে আচ্ছাদিত এই গ্রহের দিকে, এক মৃত মানব কিশোরীর দেহে নতুন জীবন লাভ করেছিল।\nকিন্তু কালো মৃত্যুদূতের ধৈর্যের কোনো অভাব নেই।\nমানুষের চোখ ক্ষয়কে দেখতে পায় না, কিন্তু সে জানত চেতনার প্রান্তে সেই শীতলতার অর্থ কী, মনের ভেতরের অন্ধকার কীসের ইঙ্গিত — মানুষ যাকে ক্ষয় বলে ডাকে, সেই মৃত্যু তাকে ধরে ফেলেছিল, তার অজান্তেই তার আত্মা ও দেহকে একসাথে গেঁথে দিয়েছিল।\nসে বারবার পালানোর চেষ্টা করেছিল, বারবার ব্যর্থ হয়েছিল, অবশেষে সে ক্লান্ত-বিধ্বস্ত হয়ে পড়েছিল, তার মানসিক শক্তি চরম সীমায় ছিন্নভিন্ন হয়ে গিয়েছিল, শুধু শরীর টেনে টেনে সেই একমাত্র জায়গার দিকে এগিয়ে গিয়েছিল যেখানে হয়তো তার মুক্তি মিলতে পারে।\nযেভাবেই হোক, সে বেঁচে থাকতে চেয়েছিল।"
  },
  AwakerStory_11248_Title = {
