  AwakerStory_11249_Content = {
    Text = "লেককে তার গোয়েন্দা বন্ধুরা 「ভাগ্যবান গোয়েন্দা」 বলে ডাকে।\nনাম শুনেই বোঝা যায়, সে একজন ভাগ্যবান মানুষ: বাজি ধরলেই মূলধনের দশগুণ ফেরত পায়; আন্দাজে উত্তর দিলেও সবসময় সঠিক উত্তরটাই বেছে নেয়।\nভাগ্যবান গোয়েন্দার আসলে গোয়েন্দা হওয়ার কোনো ইচ্ছা ছিল না, শুধু ঘটনাচক্রে একের পর এক রহস্যময় মামলা সমাধান করে ফেলায় মানুষের ঠেলায় এই পথে এসে পড়েছে।\nসে মামলা সমাধান করে যুক্তি দিয়ে নয়, ভাগ্যের জোরে। ঘটনাস্থলে একবার ঘুরে আসলেই অপরাধীর সাথে ধাক্কা লেগে যায়; রাস্তায় হাঁটতে গেলেই গুরুত্বপূর্ণ প্রমাণ কুড়িয়ে পায়।\nএমন সৌভাগ্যের মধ্যে দিয়ে সে নির্বিঘ্নে পঁচিশটা বছর কাটিয়ে দিয়েছে।\nকখনো গতকালের জন্য চিন্তা করেনি, কখনো আগামীকালের জন্য উদ্বিগ্ন হয়নি।"
  },
