  AwakerStory_11252_Content = {
    Text = "কারাগারে প্রবেশের সেই দিন থেকেই তার স্মৃতি রক্তে রঞ্জিত।\nঅতীতের সাদামাটা ও উষ্ণ স্মৃতিগুলো মিথ্যা স্বপ্নের মতো ঝাপসা হয়ে ফেটে গেছে, ধারালো টুকরো হয়ে একটু একটু করে তার মাংসে গেঁথে গেছে।\nসেই কোমল আলিঙ্গন, উদ্বিগ্ন মুখগুলো আর মনে নেই — হৃদয়ে কেবল চিরন্তন ঘৃণা আর প্রশ্ন রয়ে গেছে।\nযন্ত্রণা, অপমান, বিশ্বাসঘাতকতা…… এত কষ্ট আসলে কেন?\nসে প্রতিদিন প্রশ্ন করেছে, কিন্তু মুক্তির দিন আসা পর্যন্ত কেউ উত্তর দেয়নি।\nতাহলে সে নিজেই উত্তর খুঁজবে — আর্তনাদ ও চিৎকারে ভরা বুকগুলো থেকে, নিজ হাতে প্রতিটি কলুষিত হৃদয়কে জিজ্ঞাসাবাদ করবে।"
  },
  AwakerStory_11252_Title = {
