  AwakerStory_11253_Content = {
    Text = "ইতিহাসের স্রোতে হারিয়ে যাওয়ার কথা ছিল যে ক্ষুদ্র আত্মাটির, মায়ের ইচ্ছার উপর ভর করে, এবং @1@2@1 দ্বারা স্থাপিত আচার বৃত্তের প্রাচুর্যময় আধ্যাত্মিক শক্তির সাহায্যে, এলভোর্সের বরফের নিচে ঘুমন্ত বিশাল জীবের সাথে মিলিত হয়ে, কিশোরী রূপের দানব 「লিলি」 হিসেবে পুনর্জন্ম নেয়।\nজাগরণের অসম্পূর্ণতার কারণে, জাগরণের প্রাথমিক পর্যায়ে লিলির কোনো সংবেদন ছিল না, সে ছিল শুধু আদেশ মানা একটি যুদ্ধ পুতুল।\nভাস্কর সমিতির সদস্য ফ্রান্সিস·অসউড লিলিকে উপাদান হিসেবে ব্যবহার করে @2 বছর ধরে অবৈধ পরীক্ষা-নিরীক্ষা চালিয়েছিলেন। ফ্রান্সিসের ডায়েরি থেকে জানা যায়, সেই সময় লিলির অবস্থা অত্যন্ত অস্থির ছিল, প্রায়ই নিয়ন্ত্রণ হারিয়ে ছোট পরিসরে ধ্বংসযজ্ঞ চালাত, যার ফলে ফ্রান্সিসকে ঘন ঘন বাসস্থান পরিবর্তন করতে হতো।\nআধ্যাত্মিক জ্ঞান ওষুধ গ্রহণ এবং সিলভার কোর স্থাপনের সাথে সাথে, লিলি কোনো এক অনথিভুক্ত দিনে সংবেদন ক্ষমতা ও আংশিক স্মৃতি ফিরে পায়। পরে নানা ঘটনার পর, ফ্রান্সিস দেউলিয়া হওয়ার দ্বারপ্রান্তে থাকা রাই থেরাপি সেন্টারের দায়িত্ব নেন এবং এটিকে পরীক্ষাগারে রূপান্তরিত করেন।\nL-776 নম্বর রাই শহরের 「হেলহাউন্ড」 ঘটনায়, তার মা ফ্রান্সিস·অসউড নিজের তৈরি অস্বাভাবিক মাত্রায় বন্দী হন এবং যোগাযোগ বিচ্ছিন্ন হয়।"
  },
