  AwakerStory_11255_Content = {
    Text = "ওয়ান্ডা বুদ্ধিমতী, ধনী এবং সুন্দরী। তার নিজের কথায়, সে বেঁচে আছে কেবল আনন্দ-উল্লাসের জন্য। সে পুরুষদের তার দাসে পরিণত করে, আর চাঁদের আলোর মতো শীতল পা রাখে দাসদের পিঠের উপর। মাথায় জলপাই পাতার মুকুট পরা ভেনাস, সে মন্দ ও স্বপ্নের মূর্ত প্রতীক। এই ঘন অন্ধকারের ছায়ায়, কেবল তার দীর্ঘ অবয়বই ঝলমল করে জ্বলে।"
  },
