  AwakerStory_11256_Content = {
    Text = "লিলি·অসউডের রেকর্ড অনুসন্ধানের চেষ্টায়, এরিকা 81টি ত্রুটি সতর্কতা জারি করেছে। একসময় পৃথিবীর কাছে বিস্মৃত ব্যক্তি হিসেবে, লিলির জন্ম নথি, চিকিৎসা রেকর্ড সব কালো কাদায় পরিণত হয়েছে।\nতবে আমরা এখনও বিশেষ যন্ত্রের মাধ্যমে তার সিলভার কোরের আকৃতি পর্যবেক্ষণ করতে পারি: সূক্ষ্ম ও কুণ্ডলিত, কয়েক গুচ্ছ জড়ানো চুলের মতো——আরও সঠিকভাবে বলতে গেলে, শিশুর ভ্রূণকেশের মতো।\nবিশেষভাবে লক্ষণীয় যে, লিলি সর্বদা লিংকারের প্রতি বিশেষ আসক্তি প্রকাশ করে, 「সঙ্গী」 বা 「মালিক」 বলার চেয়ে, 「মা」 হিসেবে পরিচয় দিলে হয়তো তার সাথে সম্পর্ক দ্রুত ঘনিষ্ঠ করা যাবে।"
  },
