  AwakerStory_11257_Content = {
    Text = "রামোনা দশ বছর বয়স থেকেই বিশ্ববিদ্যালয়ের প্রশিক্ষণ মাঠের নিয়মিত সদস্য হয়ে উঠেছিল। মানুষের দেহ নিয়ে কৃষ্ণবস্ত্র তরবারিবিদের নির্দেশনা গ্রহণ করার সাহস দেখিয়ে সে অসংখ্য তদন্তকারীর প্রশংসার পাত্র হয়ে উঠেছিল।\nআনুষ্ঠানিকভাবে প্রাক-শিক্ষা কোর্সে ভর্তি হওয়ার পর, অসাধারণ স্মৃতিশক্তি, পূর্ণ নম্বরের পরীক্ষার উত্তরপত্র, এবং মার্জিত অথচ মারাত্মক তরবারি কৌশলের বলে মিসাগে রামোনার মর্যাদা ক্রমশ বৃদ্ধি পেতে থাকে। আত্মশৃঙ্খলা ও শ্রেষ্ঠত্ব তার প্রতিশব্দ হয়ে দাঁড়ায়।\nকিন্তু অনেকের কাছে যা বোধগম্য ছিল না তা হলো, এত অসাধারণ হওয়া সত্ত্বেও রামোনা কখনোই স্বাধীনভাবে মিশন পরিচালনার যোগ্যতা অর্জন করেনি। আগাম ভর্তি হওয়া সত্ত্বেও সে পুরো পাঁচ বছর প্রাক-শিক্ষা কোর্সে কাটিয়েছে, একের পর এক তদন্তকারী দলকে রহস্যবিদ্যার জগতে পা রাখতে দেখেছে।\nসে আসলে কীসের জন্য অপেক্ষা করছিল? তাকে আসলে কী ধরনের দায়িত্ব অর্পণ করা হয়েছিল?\nএই প্রশ্নের উত্তর মিলেছিল নতুন গোপনরক্ষকের ভর্তির পর।"
  },
