  AwakerStory_11259_Content = {
    Text = "A.F.3@2 সালের শুরুতে, সিতে নামক শহরে সংস্কার কাজ চলাকালীন, আগুনে ধ্বংস হওয়া একটি বাগানে অস্বাভাবিক কিছু আবিষ্কৃত হয়: ছাই লতার মতো পুষ্পগৃহের পোড়া দেয়ালে ছড়িয়ে পড়েছিল, আর সেই লতায় ফুটে থাকা ছাই-গোলাপগুলোতে ধাতব দীপ্তি ঝিলিক দিচ্ছিল।\nলতার পথ অনুসরণ করে, মিসাগ বিশ্ববিদ্যালয়ের একজন তদন্তকারী এই রৌপ্য-মূল উদ্ধার করেন। সেই রূপালি গুঁড়ো স্পর্শ করার মুহূর্তে, তার আঙুলের ডগা পুড়ে কুচকুচে কালো হয়ে গেল, কোনো যন্ত্রণা অনুভূত হলো না, তবু অকারণে দুই গাল বেয়ে দুই ধারা অশ্রু গড়িয়ে পড়ল।\nবিলাপ এসেছিল কোনো কারণ ছাড়াই, আর চোখের পলকেই ছাইয়ের মাঝে মিলিয়ে গেল।"
