  AwakerStory_11260_Content = {
    Text = "যখন পর্বতারোহী এলভর্সের শীর্ষচূড়ায় পৌঁছান।\nযখন প্রতিযোগী বিশ্বসেরার ট্রফি তুলে ধরেন।\nযখন ভক্তিমান ব্যক্তি ঘুমের মধ্যে ঐশ্বরিক বাণী শ্রবণ করেন।\nযখন জয় খুব সহজে আসে, তখন তার সাথে আসা তৃপ্তি হয়ে পড়ে নিতান্তই সাধারণ অভ্যাস।\nচারদিকে তাকিয়ে দেখা যায়, কোনো প্রতিদ্বন্দ্বী নেই, কোনো আনন্দ নেই।\nবাহ্যিকভাবে, লেক আকাঙ্ক্ষা করে উত্তেজনাপূর্ণ লড়াইয়ের, আকাঙ্ক্ষা করে সর্বস্ব বাজি রাখার পর গলা পর্যন্ত ধড়ফড় করা হৃদস্পন্দনের, আকাঙ্ক্ষা করে অ্যাড্রেনালিন বিস্ফোরণের সেই মুহূর্তের।\n「এসব বলার দরকার নেই, তোমাকে বোঝে এমন কেউ থাকলে সে শুধু আমি। তুমি আসলে শুধু পরাজয়ই কামনা করো।\nতাহলে আমাকেই তোমায় উপহার দিতে দাও, সবচেয়ে মধুর পরাজয়।」"
