  AwakerStory_11261_Content = {
    Text = "শিলো একটি ধারালো ও শীতল ছুরি।\nতার সাথে মিশন পরিচালনা করা জাগরিতরা সবাই বলে, শিলো একটি অত্যন্ত কার্যকর অস্ত্র। সে যথেষ্ট শক্তিশালী এবং সবসময় মিশন সম্পন্ন করে। হত্যার নির্দেশ পেলে, শত্রু যতই শক্তিশালী হোক না কেন, সে অবশ্যই ঘেরাও ভেদ করে শত্রুর মস্তক ছিন্ন করে আনবে।\nকিন্তু এটুকুই।\nসে হয়তো সঙ্গীদের রক্ষা করে, কিন্তু সেটা কেবল নির্দেশ পালন, সতীর্থদের প্রতি যত্ন নয়। সে তাদের বিশ্বাস করে না, তাই স্বাভাবিকভাবেই তারাও তার কাছে নিজেদের পিঠ সমর্পণ করতে পারে না।\nতারা জানে না যে, তার কাছে নিজের পক্ষের দিকে তাক করা ফলা হলো হীন, নীচ এবং শাস্তি ও ঘৃণার যোগ্য।\nসে বিশ্বাসঘাতকতার জঘন্যতা গভীরভাবে উপলব্ধি করে, তাই কখনোই সঙ্গীর বিরুদ্ধে অস্ত্র তোলে না।"
  },
