  AwakerStory_11262_Content = {
    Text = "অসম্পূর্ণ জাগরণের পার্শ্বপ্রতিক্রিয়া, সেই সাথে লিংকার পরিবর্তনের কারণে সৃষ্ট মানসিক আঘাত—এসবের ফলে লিলির ব্যক্তিত্ব ও মানসিক অবস্থায় কিছুটা অবনতি ঘটেছে। বিশ্ববিদ্যালয়ে তার নীরবতা সকলের চোখে পড়ে।\nসিক্রেটকিপার এবং জাগরিত সত্তা লোটানের পাশে থাকা ছাড়া, লিলি খুব কমই একা ক্যাম্পাসে দেখা যায়। সে ক্লাসরুমে যায় না, কিশোর জাগরিত সত্তাদের খেলায়ও যোগ দেয় না। যুদ্ধে না গেলে সে কেবল ডরমিটরিতে চুপচাপ বসে নির্দেশের অপেক্ষায় থাকে।\nলিলির ঘরের জানালা সরাসরি ক্যাম্পাসের পেছনের চাবি-সমাধিক্ষেত্রের দিকে মুখ করা। সূর্যাস্তের সময়, সে জানালার পাশে দাঁড়িয়ে, হলদে আলোয় ঢাকা চাবি-সমাধিক্ষেত্রের দিকে অপলক তাকিয়ে থাকে।\nরুপালি চাবি আকৃতির সমাধিপাথরগুলো অস্তগামী সূর্যের আলোয় দীর্ঘ ছায়া ফেলে, আর জানালার পাশে দাঁড়িয়ে থাকা লিলিও সেই সমাধিপাথরগুলোর মতোই নীরব।"
