  AwakerStory_11264_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11265_Content = {
    Text = "জাগ্রত হওয়ার পর, আমরা অবশেষে জানতে পারলাম মার্ফি আগে ধর্মসংঘে কেমন জীবনযাপন করত।\nএকটি সানশেড ছাতা ধরে, বাইরে যাওয়ার আগে নিজের সাজসজ্জায় প্রচুর সময় ব্যয় করত। বিকেলের চা হতে হবে ঠিক চারটায়, সাথে দুধ চা এবং স্ট্রবেরি জ্যাম স্কোন। পরিচ্ছন্ন ও মার্জিত থাকা — এটাই একজন ভদ্রমহিলার নিয়তি, সে যেখানেই থাকুক না কেন, সর্বদা একজন ভদ্রমহিলার মতো জীবনযাপন করে চলেছে।\n（আর্কাইভিস্টের টীকা: আমার মনে হয়, খালি হাতে সুয়েট পুডিং ধরে খাওয়ার ধরনটাকে ঠিক ভদ্রমহিলাসুলভ বলা যায় না……）\nযদিও এখন তার হুকুম তামিল করার মতো কোনো চাকর নেই, তবুও সে নিজের পছন্দমতো জীবনযাপন করে চলেছে, এটা সত্যিই একটা সান্ত্বনার বিষয়।\nসেই ঘটনার প্রভাবে, সে জাগ্রত সত্তা মিরিয়াম ও গোলিয়াথের সাথে খুব কমই যোগাযোগ করে, এমনকি ইচ্ছাকৃতভাবে তাদের উপেক্ষা করে। জাগ্রত সত্তা তুলুর সাথে দেখা হলেও, সে অত্যন্ত জটিল একটা অভিব্যক্তি প্রকাশ করে।\nঅতীতের কথা উঠলে তার মেজাজ খুব খারাপ হয়ে যায়। হয়তো, মন শান্ত করতে তার আরও কিছুটা সময় দরকার।"
  },
