  AwakerStory_11267_Content = {
    Text = "সে সবসময় বিষণ্ণ মুখে একা একা হ্রদের তীরে ঘুরে বেড়াত। ধীরে ধীরে, ছাত্ররা হ্রদের তীরকে 'বিষণ্ণ মৎস্যমানবের এলাকা' বলে ডাকতে শুরু করল। তাই সে যেন একজন জমিদারের মতো, প্রতিদিন গম্ভীরভাবে পরিদর্শনে আসত। যখন সে ঝাঁপ দিয়ে হ্রদের তলদেশে নামত, উথলে ওঠা বুদবুদগুলো তাকে কোমলভাবে আলিঙ্গন করত; পানির নিচে, তীরের উপহাসগুলোও যেন আর স্পষ্ট শোনা যেত না।"
