  AwakerStory_11268_Content = {
    Text = "ভক্তির দীপ্তি তার তীর্থযাত্রাকে আলোকিত করে। তার প্রকৃত প্রভুর সর্বাধিক ভক্ত অনুসারীর জন্য এক গৌরবময় অ্যাসেনশন। তার রাজাধিরাজের সর্বাধিক অনুগত প্রজার জন্য এক সোনালি অঙ্গীকার।\nসব ভেঙে পড়ে। দেবলোক এক ডুবে যাওয়া মিথ্যা, ভিত্তিহীন এক দুর্গ, মাটি থেকে বিচ্ছিন্ন এক লতা। তার বেদনা ফুলে ওঠে। তার নিঃসঙ্গতা তোলপাড় তোলে। দেবলোকে অবশিষ্ট যে সামান্য বিশ্বাস ছিল, তা আর ফারোসকে ভাসিয়ে রাখতে পারে না। দরিদ্র পথিক শেষ পর্যন্ত ডুবে যায়।\nসমুদ্রের গভীরে ডুব দিতে দিতে, তার প্রেম ও ঘৃণা ফুলে ওঠা ঢেউয়ে রূপ নেয়। জল ঘূর্ণায়মান, ফেনায়িত, ঘুরপাক খায়, তার স্মৃতির আনুষ্ঠানিক আতশবাজির মতো জাঁকজমকপূর্ণ, এক উৎসব, যা প্রায় সান্ত্বনার সমতুল্য।\nবীরের হাতে শিরশ্ছেদের আগে তার শেষ জ্বলন্ত দৃষ্টি নিশ্চয়ই সেই দেবলোকের সঙ্গেই লেগে ছিল, যাকে সে কোনোভাবেই ত্যাগ করতে পারেনি।"
  },
