  AwakerStory_11269_Content = {
    Text = "সে সবসময় 「ফ্যান্টম」 নামের মোটরসাইকেলটিকে ঘিরে ব্যস্ত থাকে বলে মনে হয়: এখানে একটা স্ক্রু টাইট করা, ওখানে একটা পাইপ অ্যাডজাস্ট করা……এটা একটা শেষ না হওয়া কাজ, যদিও অনেকেই মনে করে সে মেরামতের কাজ সর্বোত্তমভাবে করেছে, তবুও সে দিনের পর দিন এতে মগ্ন থাকে।\nএর কারণ হলো সেই অব্যাখ্যেয় 「কিছু একটা এখনও বাকি আছে」 অনুভূতি।"
