  AwakerStory_11271_Content = {
    Text = "ফিন্ট দেখতে পেল একজন ছাত্রী গবেষণাগারে লুকিয়ে চুপচাপ কাঁদছে।\nএই ছাত্রীটি তার সবচেয়ে প্রিয় ছিল না, কিন্তু এই ছাত্রীটিই তাকে সবচেয়ে বেশি ভালোবাসত।\nমেয়েটি কখনোই ফিন্টের প্রত্যাখ্যান আর দূরত্বে কিছু মনে করেনি, ফিন্টের অনিয়ন্ত্রিত ক্ষমতাকেও ভয় পায়নি।\nসে তার জীবনযাত্রার খরচ দিয়ে সব মিষ্টি কিনে আনত, শুধু এই চিন্তায় যে ফিন্টের শক্তি কমে যেতে পারে; ভারী সুরক্ষা পোশাক পরে নিত, শুধু ঘুমে এলোমেলো হয়ে যাওয়া তার লম্বা চুল আঁচড়ে দেওয়ার জন্য।\n……তাকে প্রতিদান দিতে হবে, ফিন্ট এটাই ভেবেছিল।\nতাই, ফিন্ট তার সাধ্যমতো কিছু করল।\n——যদি শুধু পরীক্ষায় ফেল হওয়ার ভয়ে কাঁদছে, তাহলে অন্যদের হুমকি দিয়ে তাদের নম্বর ছেড়ে দিতে বাধ্য করলেই তো হয়, তাই না?"
  },
  AwakerStory_11271_Title = {
