  AwakerStory_11272_Content = {
    Text = "মিসাগ অনেক জাগ্রত সত্তাকে জাগিয়ে তোলে এবং আশ্রয় দেয়, কিন্তু তাইসিসের মতো অনন্য আর কেউ নেই।\nসে ছাত্রীদের ডেটের জন্য মেকআপ বাছাই করতে সাহায্য করে, সে হতাশ মানুষদের আশা ফিরে পেতে সাহায্য করে, সে মানসিকভাবে ভেঙে পড়া তদন্তকারীদের অন্ধকার থেকে বেরিয়ে আসতে সাহায্য করে।\nপ্রেমিকার মতো, আবার বোনের মতো, আরও বেশি মায়ের মতো। সে সবসময় 「ভালোবাসা」 নামক এক জলাভূমি তৈরি করতে পারে, চুপচাপ মানুষকে তাতে ডুবিয়ে দেয়, অজান্তেই মানুষ তার জন্য সবকিছু দিতে চায়——\nতৃতীয়বার ছাত্রদের তাইসিসের দেওয়া রহস্যময় তরল পান করা থেকে বিরত করার পর, জাগ্রত সত্তা ব্যবস্থাপনা বিভাগ তার বিরুদ্ধে একটি নিষেধাজ্ঞা জারি করেছিল।\n「গোপনরক্ষকের সঙ্গ ছাড়া, তাইসিসকে কোনো ছাত্রের কাছে যেতে কঠোরভাবে নিষেধ।」"
  },
  AwakerStory_11272_Title = {
    Text = "গল্প: ২"
