  AwakerStory_11273_Content = {
    Text = "সমস্ত অর্থ বালুর মতো মিলিয়ে গেল, পৃথিবীর মিথ্যা পর্দা তার চোখের সামনে থেকে সরে গেল, সবকিছু ফিরে গেল আদিম অন্ধকারে।\nএই ঘোর অন্ধকার মঞ্চের শেষ অভিনয়ে, বিজ্ঞানের নর্তকী তবুও সর্বশক্তি দিয়ে নৃত্য করে চলেছে।\nসে আর পরোয়া করে না ক্ষয়ের ধীর গ্রাসের, কারণ সেই নাটকের সমাপ্তি শুরু থেকেই লেখা ছিল।\nচিরকালের মতোই, সে তার প্রতিভার শক্তি নিঃশেষে উৎসর্গ করবে এই পৃথিবীকে, সত্যের সবচেয়ে নিকটতম পথে।\nযদি তুমি একটু জিজ্ঞেস করো, সে জোর দিয়ে বলবে যে মানবজাতি ও পৃথিবীর প্রতি তার ভালোবাসা এখনও অটুট আছে, সে মানবজগতের সকল যন্ত্রণার অবসান ঘটাতে চায়, মানুষকে ফিরিয়ে নিয়ে যেতে চায় তাদের প্রকৃত, আদি আবাসভূমিতে।"
  },
  AwakerStory_11273_Title = {
