  AwakerStory_11274_Content = {
    Text = "A. F. 3@1 সালের @1 মাস।\nইয়াগ্রো প্রজাতন্ত্রের পূর্ব উপকূলের শয়তানের প্রাচীরে, স্থানীয় জেলেরা রিপোর্ট করে যে 「একটি অদ্ভুত আকৃতির মৃতদেহ」 উদ্ধার করা হয়েছে——আকারে ছোট ও কুঁজো, চোখ বেরিয়ে আসা, ত্বক আংশিক শক্ত, আঙুলের মাঝে পর্দা, সবচেয়ে অদ্ভুত হলো গলার দুই পাশে প্রতিসম লাল দাগ। যদি তার গায়ে ছাত্র ইউনিফর্ম না থাকত, হয়তো 「মানুষের মৃতদেহ」 হিসেবে চিহ্নিত করা কঠিন হতো।\nতদন্তকারী পৌঁছানোর সময়, সেই অদ্ভুত মৃতদেহটি ভীত জেলেরা অশুভ বস্তু মনে করে পুড়িয়ে ফেলেছিল, শুধু একটি সেই সময়ে ছাত্রদের মধ্যে বেশ জনপ্রিয় হ্যান্ডব্যাগ পড়ে ছিল। ব্যাগে কোনো পরিবর্তনের কাপড় ছিল না, শুধু কিছু অস্পষ্ট হাতে লেখা পাণ্ডুলিপি, একটি কম্পাস, এবং একজন মধ্যবয়সী মহিলার ছবি।"
  },
  AwakerStory_11274_Title = {
    Text = "গল্প: ১"
