  AwakerStory_11277_Content = {
    Text = "ওয়েনকোরের অফিসকে মিসাগ বিশ্ববিদ্যালয়ের ধ্রুবতারা বলা হয়। সেখানে সর্বদা আলো জ্বলে, ছায়া পড়তে পারে এমন প্রতিটি কোণ নানা ধরনের আলোকসজ্জায় উদ্ভাসিত — লণ্ঠন থেকে কেরোসিন বাতি, টাংস্টেন বাল্ব থেকে মোমবাতি।\nঅন্ধকারের ভয় তাকে এমনকি ঘুম থেকেও বিমুখ করে তুলেছে, তাই তিনি সবসময় সবচেয়ে বড় বাতিটির নিচে সোজা হয়ে বসে থাকেন, মেঝেতে ছড়িয়ে থাকা খসড়া কাগজের উপর দিনরাত এমন সব প্রতীক লিখে চলেন যা কেউ বুঝতে পারে না।"
