  AwakerStory_11278_Content = {
    Text = "কেকেস মানুষদের ঘৃণা করত, যখন সে ছোট ছিল তখন থেকেই সে তাদের ঘৃণা করত।\nসে একবার ডুবন্ত একটি ছোট মেয়েকে বাঁচিয়েছিল, কিন্তু উল্টো অন্য শিশুরা তাকে ক্ষতিকারক দানব বলে অপবাদ দিয়েছিল; সে তাদের থেকে দূরে পালিয়ে থাকত, তবুও তারা তাকে তাড়া করে 'দুর্গন্ধযুক্ত ব্যাঙমানব' বলে চিৎকার করত।\n\nসেই দশকেরও বেশি সময়ের বিষণ্ণ দিনগুলোতে, একমাত্র যা তাকে কিছুটা আশা দিত, তা ছিল চাচা অর্নের চিঠি। তাঁর গভীর জ্ঞানভাণ্ডারে ছিল অসংখ্য ভূত-প্রেতের গল্প, যা ছোট্ট কেকেসকে মুগ্ধ করে রাখত। কিন্তু সুসময় বেশিদিন স্থায়ী হলো না, কয়েক বছরের মধ্যেই চাচা অর্ন রহস্যজনকভাবে নিখোঁজ হয়ে গেলেন।\nঅবশেষে 16 বছর বয়সে কেকেস তার পিতামহের বাড়িতে দেখা করতে গিয়ে, ঘটনাক্রমে অর্নের পাণ্ডুলিপি খুঁজে পেল। সে অবশেষে জানতে পারল তার শরীরের বিকৃত রেখাগুলোর মধ্যে লুকিয়ে থাকা মহান তাৎপর্য।\nহুঁ, মানুষ, শেষ পর্যন্ত নিকৃষ্ট নিম্নশ্রেণির জীব ছাড়া আর কিছুই নয়।\nসেই থেকে, সে আর হতাশ হলো না, বরং ধৈর্য ধরে অপেক্ষা করতে লাগল, সেই দিনের জন্য যেদিন নিয়তি তার দ্বারে এসে উপস্থিত হবে।"
  },
  AwakerStory_11278_Title = {
