  AwakerStory_11279_Content = {
    Text = "কিশোরটিকে একসময় 「মৃত্যু নাইট」 বলে ডাকা হতো — এ কথা স্কুলে এখন আর খুব কম জনই মনে রাখে।\nকেবল মধ্যরাতে, সেই দিনের দৃশ্যগুলো দুঃস্বপ্ন হয়ে কিশোরের ঘুমে হানা দেয়।\nক্যাম্পাসে অনুপ্রবেশকারী ক্ষয়কারী সত্তা, ধ্বংস হওয়া ঘণ্টাঘর, মুমূর্ষু 「গোপনরক্ষক」।\n「কেঁদো না, অজিল, এটা তোমার দোষ নয়...」\nমাতৃভূমিতে আক্রমণকারী অশ্বারোহী বাহিনী, ভেঙে পড়া প্রাসাদ, রাজকুমারীর আঙুলের ফাঁক দিয়ে গড়িয়ে পড়া কালো রক্ত।\n「আমার জন্য নিজেকে বলি দিও না, অজিল, তুমি ইতিমধ্যে যথেষ্ট করেছ...」\nস্মৃতির বালুকণা যন্ত্রণাকে সঙ্গে নিয়ে কিশোরের আত্মাকে ক্ষয় করে চলে।"
  },
  AwakerStory_11279_Title = {
    Text = "গল্প: ৩"
