  AwakerStory_11280_Content = {
    Text = "কিছু জাগ্রত সত্তা জেগে ওঠার পর নতুন দেহ ও নতুন জীবনের সাথে অসামঞ্জস্য দেখায়, আবার কেউ কেউ দ্রুত বর্তমান পরিস্থিতি মেনে নিয়ে বেশ সক্রিয়ভাবে দ্বিতীয় জীবন শুরু করে।\nতুরু এদের কোনোটিতেই পড়ে না, কেউ কখনো তার মতো এত প্রকাশ্যে বর্তমান বিশ্বের প্রতি উদাসীনতা দেখায়নি।\nতার যোগ্যতা অত্যন্ত উৎকৃষ্ট, হয়তো বর্তমান বিশ্বের পরিস্থিতি ও সংকট সম্পর্কেও তার আগে থেকেই অন্তর্দৃষ্টি আছে, কিন্তু সে বেশিরভাগ সময় ঘুমে কাটাতে পছন্দ করে।\nযদিও নিজের ইচ্ছায় নয়, স্কুলের মানুষ ও জাগ্রত সত্তাদের মধ্যে তার বেশ খ্যাতি আছে। গবেষকরা তার প্রতিটি পদক্ষেপ পর্যবেক্ষণ করে, মাঝে মাঝে কয়েকটি গবেষণাপত্র প্রকাশ করে; প্রত্নতত্ত্ব বিভাগ, জ্যোতির্বিজ্ঞান বিভাগ প্রায়ই বিভিন্ন নামে একাডেমিক সেমিনারের আমন্ত্রণ পাঠায়, বেশিরভাগই তাকে নাম ধরে অংশগ্রহণের অনুরোধ করে।\nজাগ্রত সত্তাদের মধ্যেও তুরুর বেশ প্রভাব আছে: মার্ফি তাকে দেখলেই মন খারাপ করে, গোলিয়া যেন সবসময় গোপনে তার সাথে প্রতিযোগিতা করতে চায়, মিরিয়াম তার প্রতিটি কথাকে ঐশ্বরিক আদেশ মনে করে।\nএসবের প্রতি সে কখনো কোনো বিশেষ মনোভাব দেখায়নি, কোনো প্রত্যাশা নেই, কোনো দাবিও নেই।\nকখনো কখনো, সে ইচ্ছামতো কিছু অনুরোধে সাড়া দেয়, কখনো দেয় না।"
  },
  AwakerStory_11280_Title = {
