  AwakerStory_11282_Content = {
    Text = "\n「আমি আঙুরের মদের মতো কালো অ্যামেথিস্ট পরব।」\n「আমি উটপাখির পালক দিয়ে তৈরি জমকালো গাউন পরব।」\n「আমি ভোজসভার একমাত্র আলো হয়ে উঠব।」\nপরিচারিকা তার অ্যাম্বার রঙের চোখ মিটমিট করল, তার আরও অনেক সুন্দর ইচ্ছা ছিল, কিন্তু সে আর সেগুলো উচ্চারণ করতে পারল না। তার জমাট বাঁধা দেহের সামনে, দিগন্তবিস্তৃত সবুজ শিখা ঘন অন্ধকার রাতে নীরবে প্রস্ফুটিত হচ্ছিল।"
  },
