  AwakerStory_11283_Content = {
    Text = "সে তরবারি চালনার গতি হিসাব করছিল, আক্রমণ এড়ানোর কোণ হিসাব করছিল।\nসে পলায়ন পরিকল্পনার সম্ভাব্যতা হিসাব করছিল, পৃথিবী ভবিষ্যতের দিকে এগিয়ে যাওয়ার সম্ভাবনা হিসাব করছিল।\nশেষ মুহূর্ত পর্যন্ত, সে গণনা করা থামায়নি।\nঠিক যেমন সে কখনো এই জনমানবহীন পথে চলা ছেড়ে দেয়নি।"
  },
