  AwakerStory_11284_Content = {
    Text = "সিতে নগরীর সেই শিল্পী অন্য মানুষের প্রতি বিন্দুমাত্র ভ্রুক্ষেপ করেন না। তিনি কেবল অনুসরণ করেন পরিশুদ্ধ সৌন্দর্যের পরম রূপকে, ক্ষণস্থায়ী মুহূর্তগুলোকে খোদাই করে চিরন্তনে স্থির করে দেন।\nযখন তার অনুপ্রেরণা জোয়ারের মতো উথলে ওঠে, তার ছেনি এক মুহূর্তের জন্যও থামে না; যখন তার সৃষ্টিগুলো সম্পূর্ণতার সাক্ষী হয়, তার দেহ ডুবে যায় প্রবাল-রঙা ছায়ায়। কর্মশালার কোণে, যেদিকে তার দৃষ্টি কখনো ফেরে না, সেখানে তার যন্ত্রণা আর উল্লাস জড়িয়ে যায়, অঙ্কুরিত হয় তার অস্তিত্বের গভীরতম স্তর থেকে।"
  },
  AwakerStory_11284_Title = {
