  AwakerStory_11286_Content = {
    Text = "A. F. 2@2 সালের নভেম্বর, বেরেন অঞ্চলে বড় ভূমিকম্প হয়।\nপরদিন, দুজন অধ্যাপক ভূমিকম্প অঞ্চলে যাওয়ার নির্দেশ পান, ভূমিকম্পের পর যোগাযোগ হারানো মিসাগের তদন্তকারী দলকে খুঁজে বের করতে।\nউক্ত দল যোগাযোগ বিচ্ছিন্ন হওয়ার আগে ভূমধ্যসাগরীয় উপকূলে সক্রিয় ছিল, তাদের প্রধান কাজ ছিল ঐতিহাসিক ধ্বংসাবশেষ অনুসন্ধান ও খনন করা এবং 「ক্ষয় প্রপঞ্চ」 সম্পর্কিত সম্ভাব্য সূত্র খোঁজা।\n8 নভেম্বর, দলের সদস্যদের শেষবার দেখা গেছে বলে জানা স্থানে, @2 অধ্যাপক ইতিহাসে অনথিভুক্ত একটি রাজপ্রাসাদের ধ্বংসাবশেষ আবিষ্কার করেন, একটি মিসাগের মানসম্মত রৌপ্য চাবি উদ্ধার করেন, নম্বর I-@2, কিন্তু দলের সদস্যদের খুঁজে পাননি।\n9 নভেম্বর, ধ্বংসাবশেষ থেকে দুটি সিলভার কোর উদ্ধার করা হয়, পরে লেন্টিনিয়েনে নিয়ে যাওয়া হয়, এর ঐতিহাসিক মূল্যের কারণে সংরক্ষিত করা হয় এবং অন্য একদিন জাগ্রত করার সিদ্ধান্ত নেওয়া হয়।"
  },
  AwakerStory_11286_Title = {
    Text = "গল্প: ১"
