  AwakerStory_11287_Content = {
    Text = "ওয়ান্ডা মিসাগে আসার প্রথম দিনেই 「অন্যকে ইচ্ছাকৃতভাবে পদদলিত করার」 গুরুতর অভিযোগের মুখে পড়ল।\nনাম প্রকাশে অনিচ্ছুক এক শিক্ষার্থীর বক্তব্য অনুযায়ী, সে কেবল ঘটনাক্রমে লাইব্রেরির পাশ দিয়ে যাচ্ছিল, ওয়ান্ডার সাথে অনিচ্ছাকৃতভাবে একবার চোখাচোখি হয়, এরপরই সে মাটিতে ছিটকে পড়ে, @2 এবং তাকে পরিয়ে দেওয়া হয় @3(শিক্ষার্থী আর বিস্তারিত জানাতে অস্বীকার করেছে)।\nআঘাতের ঘটনাটি শুরু থেকে শেষ পর্যন্ত পাঁচ মিনিটের বেশি লাগেনি, পরিস্থিতি ছিল অত্যন্ত গুরুতর ও নিন্দনীয়।\nমিসাগ শৃঙ্খলা কমিটি(সংক্ষেপে MDC) এই বিষয়টিকে অত্যন্ত গুরুত্বের সাথে বিবেচনা করছে এবং গভীর সহানুভূতি প্রকাশ করছে। ইতিমধ্যে একটি বিশেষ তদন্ত দল গঠন করা হয়েছে, যা পরবর্তীতে ওয়ান্ডার চিন্তা ও আচরণের পূর্ণ সংস্কারের জন্য ধারাবাহিকভাবে কাজ করবে, যাতে সে দ্রুত ক্যাম্পাস জীবনে মিশে যেতে পারে।"
  },
