  AwakerStory_11288_Content = {
    Text = "「@1 @1 তারিখে বিশ্ববিদ্যালয়ের কবরস্থান আবারও অপবিত্র করা হলো। এ মাসে এটি তৃতীয় কবর খননকারী ঘটনা।\nসপ্তাহব্যাপী তদন্তের পর, জাগ্রত সাঙ্গাকে প্রাথমিকভাবে সন্দেহভাজন হিসেবে চিহ্নিত করেছে সংঘ।\nতার কর্মশালায় যে কেউ প্রবেশ করলে নিঃসন্দেহে স্তম্ভিত হবে সেই সব নানাবিধ গ্রোটেস্ক ও নাস্তিকতাপূর্ণ সমুদ্র-থিমের ভাস্কর্য দেখে, এবং তারপর তাদের উপাদানের উৎস নিয়ে জিজ্ঞাসা তুলবে: নাতাশার সমাধির সময় গলায় পরানো শাঁসের গলার হার; সমাধিফলকের অনুরূপ গঠনবিশিষ্ট অ্যাবারডিন গ্রানাইট। পিকম্যানের মতো নয়, যে নিজের শিল্পভাবনা ব্যাখ্যা করতে ভালোবাসে; সাঙ্গা অনেক বেশি অধরা—আমাদের সব জিজ্ঞাসা কেবল একটি হাসিতেই বিলীন হয়ে যায়।\nতার ছেনি স্পর্শ কোরো না, আর তার কর্মশালায় কখনো একা থেকো না—প্রফেসর ডেক্সটার আমাদের সতর্ক করেছিলেন। কিন্তু কবর খননকারীদের পেছনের সত্য উন্মোচনের জন্য কঠোর পদক্ষেপ অপরিহার্য।\n@1 @1, সময় 00:45। গোয়েন্দা অনুরাগী সংঘের সদস্য @2 সাঙ্গার কর্মশালায় গোপনে প্রবেশ করেছে। আমাকে শুভ @3 জানিও।「\n—「গোয়েন্দা অনুরাগী সংঘ, তদন্ত নথি S-618「 থেকে উদ্ধৃত"
  },
  AwakerStory_11288_Title = {
