  AwakerStory_11289_Content = {
    Text = "রোটানের গায়ে অনেক বেশি তকমা সেঁটে দেওয়া হয়েছে, কেউ জানে না এই কালো পোশাকের তরবারিবাহিনীর সাথে কীভাবে আচরণ করা উচিত।\nঅতিরিক্ত বিনয়ী হলে, সে 'বিরক্তিকর' বলে তোমার হাঁটু গুঁড়িয়ে দেবে; অতিরিক্ত অহংকারী হলে, সে তার বিশাল তরবারি দিয়ে তোমার ধৃষ্টতা কেটে ফেলবে; অতিরিক্ত কঠোর হলে, সে যুদ্ধের মাধ্যমে তোমার আত্মাকে নরম করে দেবে।\nতবে সম্ভবত, এটাই গ্রহের আদিম সন্তানের অহংকার: একজন প্রাক্তন রক্ষক হিসেবে, অহংকারের অধিকার তার প্রাপ্য।"
