  AwakerStory_11291_Content = {
    Text = "মহাপ্লাবন 3@2 সালের গ্রীষ্মকালে, ইরিয়ান দ্বীপে সামুদ্রিক দানবের কিংবদন্তি ছড়িয়ে পড়েছিল।\nকিছু জেলে দাবি করেছিল যে, উপকূলের কাছে তারা প্রায় পাঁচতলা উঁচু একটি সেফালোপড প্রাণী দেখেছে। এর সারা শরীর গাঢ় লাল, আর শুঁড়গুলোতে কালো সমকেন্দ্রিক বলয় ছিল।\nএই দানবের গুজব শোনার সময়, আমি সিনিয়র ইয়োহানসেনের সাথে মেদান অঞ্চলে সন্দেহজনক ক্ষয়ীভবন ঘটনার তদন্ত করছিলাম। পরদিনই সিনিয়র ইরিয়ান দ্বীপে যাওয়ার জন্য জাহাজ প্রস্তুত করে ফেললেন, আর আমি আমিরান্তে মহাসাগরের মাঝখানে বসে এই প্রতিবেদনটি লিখছি।\nযাত্রার তৃতীয় দিনে, সমুদ্রপৃষ্ঠে বিপুল সংখ্যক মৃত মাছ ভেসে উঠল: ম্যাকারেল, ফ্লাউন্ডার, ডলফিন, আমি শপথ করে বলতে পারি যে মৃতদেহের মধ্যে একটি গর্ভবতী স্পার্ম তিমিও দেখেছিলাম! যদিও অভিজ্ঞ নাবিকরা বলেছিল যে অতিরিক্ত প্রজননের ফলে সমুদ্রের পানিতে অক্সিজেনের ঘাটতিই মাছের মৃত্যুর প্রধান কারণ, তবু আমার মনে হচ্ছিল আমরা কিছু একটা উপেক্ষা করছি……\nযাত্রার অষ্টম দিনে, আমার সমুদ্রপীড়া আরও তীব্র হয়ে উঠল, প্রচণ্ড বমিভাবের কারণে আমি প্রায় কিছুই খেতে পারছিলাম না। যদিও আমরা ইরিয়ান দ্বীপের কাছাকাছি পৌঁছে গিয়েছিলাম, তবু ইয়োহানসেন জোর দিয়ে আমাদের ফিরে যেতে বললেন@3……আমি বুঝতে পারিনি, কিন্তু আমি এই সিনিয়রকে বিশ্বাস করার সিদ্ধান্ত নিলাম।\n——বেল কলম্বাস《মহাপ্লাবন 3@2 সালের গ্রীষ্মকালীন ইন্টার্নশিপ প্রতিবেদন》"
  },
