  AwakerStory_11293_Content = {
    Text = "আমি সমুদ্র ভালোবাসি। ফেভারের সমুদ্র। প্রুশিয়ান নীল রঙের সমুদ্র। আর্দ্র উষ্ণ বাতাস বয়ে আনা সমুদ্র। স্যানাটোরিয়ামের জানালার ফাঁক দিয়ে তেলচিত্রের মতো দেখতে সমুদ্র। প্রত্যাবর্তী পালতোলা নৌকা বহনকারী সমুদ্র। মায়ের মতো অসংখ্য প্রাণ লালনকারী সমুদ্র।\nএখন, অবশেষে আমি ফিরে এসেছি শান্ত সমুদ্রে, ফিরে এসেছি জন্মের আগের সেই সময়ে, ফিরে এসেছি মায়ের গর্ভজলে আবৃত সেই গর্ভে। সমুদ্রস্রোত সেই দুর্ভাগ্যের টুকরোগুলো কুড়িয়ে নেয়, সাদা হাড় আর প্রবালের মাঝে জোড়া লাগিয়ে আমাকে গড়ে তোলে। গভীর সমুদ্রের মাছেরা সাঁতরে যায়, আর শোনে সেই ভাগ্যের দুর্দশার দীর্ঘশ্বাস।\nমা গো, যদি আরেকবার এই পৃথিবীতে জন্ম নিতে পারতাম, তাহলে কি আমি একটু বেশি সুখী হতে পারতাম?"
