  AwakerStory_11294_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11295_Content = {
    Text = "রাইকারের জাগরণ থেকে প্রাপ্ত সিলভারটি সুবিখ্যাত রেমুয়াহে স্মৃতিস্তম্ভ, ত্রিভুজাকৃতি দৈত্য টাওয়ারের অভ্যন্তর থেকে উৎখনন করা হয়েছিল। এটি সরলরৈখিক ও নিখুঁত বুলেট-আকৃতির, SAA রিভলভারে ব্যবহৃত গুলির আকার ও গঠনের সঙ্গে সম্পূর্ণ মেলে, এবং এটি এক তরুণ পুরুষের মৃতদেহের করোটির ভেতরে গেঁথে ছিল。\nএই সিলভারকে স্পর্শ করলে ত্রিভুজাকৃতি দৈত্য টাওয়ারের মহিমান্বিত ও বিশাল দৃশ্যাবলি মনের ভেতর জেগে ওঠে, আর দেহ স্বতঃস্ফূর্তভাবে কুঁকড়ে গিয়ে হামাগুড়ি দিতে শুরু করে। যদি স্পর্শকারী প্রাণপণে প্রতিরোধ করে সামনে তাকিয়ে থাকতে পারে, তবে সে পেছন থেকে আলো পড়া এক মুকুটধারী পুরুষের অস্পষ্ট অবয়ব দেখতে পাবে, আর ঠিক পরের মুহূর্তেই চেতনা ছিন্ন হয়ে যাবে, ফলে সিলভারটি স্বাভাবিকভাবেই তার আঙুল ফসকে পড়ে যাবে。\n「ত্রিভুজ টাওয়ারের শীর্ষভাগ এখনো ক্ষয়প্রাপ্ত হয়নি; এটি নিশ্চয়ই নির্মাণ সম্পন্ন হওয়ার অল্প কিছু পরের দৃশ্য।」 — গবেষক বি. আর. লংম্যান\n「আমি অন্ধকার আত্মাদের ভয়াবহ হুইসপার শুনতে পাচ্ছি।」 — গবেষক কে. ওয়াটার্স\n「মিথাগ আমাদের জন্য যে অমানবিক পরীক্ষাগুলো নির্ধারণ করেছে, আমাকে তা নিন্দা করতেই হবে। এই সিলভারকে বারবার স্পর্শ করার পার্শ্বপ্রতিক্রিয়াই দেহের সম্পূর্ণ নিয়ন্ত্রণ হারানোর জন্য যথেষ্ট। সংক্ষেপে বললে, আমি আর কখনো একে স্পর্শ করতে রাজি নই।」 — গবেষক এল. লোপেজ"
  },
  AwakerStory_11295_Title = {
