  AwakerStory_11295_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11296_Content = {
    Text = "A.F.18@1 সাল @1 মাস, @2 পদাতিক রেজিমেন্ট, লেমওয়াশি রাজ্য, আলেকজান্দ্রিয়া বন্দর\nআলেকজান্দ্রিয়া বন্দরের পরিস্থিতি ধীরে ধীরে স্থিতিশীল হচ্ছে, পদাতিক রেজিমেন্টের তৃতীয় ও চতুর্থ ব্যাটালিয়ন, তিনটি কোম্পানির মাস্কেটিয়ারসহ খাল দিয়ে @4-এ পরবর্তী অভিযানে গেছে, বর্তমানে শুধু প্রথম ব্যাটালিয়ন ও এক কোম্পানি মাস্কেটিয়ার আলেকজান্দ্রিয়ায় মোতায়েন আছে।\nএকটি দল টহলের সময় বিদ্রোহী সেনার মুখোমুখি হয়, দ্রুত সমাধান করা হয়েছে। তারা একটি মজার ছোট জিনিস নিয়ে এসেছে, দেখতে রূপার মতো, কিন্তু রূপার চেয়ে অনেক ভারী। আমি এটি সেফে রেখেছি, কমান্ডার এই উপহার পছন্দ করবেন।\n……\nমোতায়েনের 13তম দিন, বিভিন্ন কোম্পানির সৈন্যদের মধ্যে অস্বাভাবিক আচরণ দেখা যাচ্ছে, নির্দিষ্ট কর্মকাণ্ডের মধ্যে রয়েছে সহযোদ্ধাদের আক্রমণ, ঊর্ধ্বতনদের আক্রমণ, রসদ ধ্বংস, সামরিক সরঞ্জাম ধ্বংস ইত্যাদি। এই ব্যক্তিরা, আগের সেই বিশৃঙ্খলাকারীদের সাথে, আমার ব্যক্তিগত তত্ত্বাবধানে আটক করা হয়েছে।\nতাদের চোখ রক্তলাল, মুখ থেকে থুতু ছিটছে, সৈনিকের চেয়ে বরং কোনো করুণ পশুর মতো। এখানে কোনো ধরনের উন্মাদনা ছড়াচ্ছে, আমি আশঙ্কা করছি এটি মহামারীতে পরিণত হবে।\n……\nমোতায়েনের 30তম দিন।\nআজ পর্যন্ত, মোট 370 জন সৈন্য উন্মাদ আচরণ প্রদর্শন করেছে, তাদের মধ্যে 331 জন গুরুতর হিস্টিরিয়া প্রদর্শনের 20 দিন পর অঙ্গ অসাড়তা ও চতুর্পদ পক্ষাঘাতে আক্রান্ত হয়েছে। তাদের আক্রমণাত্মকতা এখনও প্রবল, 2 জন সামরিক চিকিৎসক রোগী চিকিৎসার চেষ্টায় কামড়ের শিকার হয়েছেন।\nউন্মাদনা ছড়াতে থাকছে। আমি পরিস্থিতি ঊর্ধ্বতনদের জানিয়েছি, আশা করি তারা দ্রুত পদক্ষেপ নেবেন।\n……\nনিরীক্ষা পরিষদ আলেকজান্দ্রিয়া গ্যারিসনের দায়িত্ব নিয়েছে 10 দিন হলো, মানুষ এখনও পাগল হচ্ছে, আমার ভাইয়েরা একের পর এক পাগল হচ্ছে। আমি বুঝতে পারছি না, কেন শুধু আমরাই এই অভিশপ্ত মহামারীতে ভুগছি? কেন স্থানীয়দের কিছু হচ্ছে না? যারা সবসময় আমাদের ঝামেলা করে সেই বিদ্রোহীদের কিছু হচ্ছে না?\nআমার মাথাব্যথা ক্রমশ বাড়ছে, কিন্তু সামরিক চিকিৎসকরা অসহায়——তারা আমার আগেই উন্মাদনায় পতিত হয়েছে, ইতিমধ্যে মাটিতে পড়ে কামড়ানো দানবদের একজন হয়ে গেছে।\nআমি আশঙ্কা করছি আমিও উন্মাদনায় পতিত হব।\nওরা বলছে আমাদের মিসাগের বিশ্ববিদ্যালয়ের লোকদের জন্য অপেক্ষা করতে হবে। ধুর, আমরা দেশের জন্য জীবন বাজি রেখেছি, আমাদের সাথে এমন আচরণ করা উচিত নয়।\n……\nআমি জানতে পেরেছি, অবশেষে জানতে পেরেছি। সেটা একটি প্রতিহিংসাপরায়ণ আত্মা, সেই রূপার টুকরোয় বাস করছে, এই ভূমি দখলকারী সবার উপর প্রতিশোধ নিতে চায়। সেই এক পা হারানো নারী আমাদের যেতে বলছে, সে চায় আমরা সবাই চলে যাই, এখানকার সবকিছু আসল মালিকদের ফিরিয়ে দিই। হ্যাঁ, হ্যাঁ, এমনই হওয়া উচিত, এমনই হওয়া উচিত, আমাদের কখনোই এখানে আসা উচিত হয়নি, কখনোই এই যুদ্ধ শুরু করা উচিত হয়নি, আমি@1@3@4@2@1@2@3\n——《@2 পদাতিক রেজিমেন্ট প্রথম ব্যাটালিয়ন ভারপ্রাপ্ত কমান্ডারের দিনলিপি》 থেকে উদ্ধৃত"
  },
