  AwakerStory_11297_Content = {
    Text = "সে রক্তপানে জন্মগ্রহণ করেনি, একসময় সেও রাতের রানীর মতো তীব্র অথচ ক্ষণস্থায়ী উষ্ণতায় স্নান করেছিল। বিশ্বাসঘাতকতা ও কারাবাসের যন্ত্রণা বিদ্রোহের দাবানল জ্বালিয়ে দিয়েছিল, প্রতিশোধের আগুন সমগ্র ম্যাসিয়া জুড়ে ছড়িয়ে পড়েছিল, এবং অন্তহীন ঘৃণার প্রভাবে তার হৃদয় আর কারও জন্য উন্মুক্ত হয়নি……"
