  AwakerStory_11299_Content = {
    Text = "তিনি বাস্তবে বিদ্যমান।\nতিনি দেবতার দৃষ্টিপাত, দেবতার মহাবিশ্বের দিকে প্রসারিত শাখা।\nতিনি ইতিহাসের মহিমা উপভোগ করেন, সভ্যতার সমৃদ্ধি কামনা করেন।\nতিনি শুষ্কতাকে অতিক্রম করতে চান, মৃত্যুকে জয় করতে চান।\nতিনি চান গভীর স্তোত্রপাঠ, বালুকা আর লবণাক্ত বাতাস, চান রূপালি পাতা আর মসুলের চাঁদের আলো।\nডাইনি, মায়াবিনী, যাদুকরী... পৃথিবীর মানুষের দৃষ্টি তো নিছক বাহ্যিক বিষয়।\nযদি একটি রক্তবিন্দুও কালো আক্রমণ থেকে রক্ষা পায়, তাঁরা আবারও অনন্তকালকে আলিঙ্গনে বন্দী করতে পারবেন।"
  },
  AwakerStory_11299_Title = {
    Text = "গল্প: ৪"
