  AwakerStory_11299_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11300_Content = {
    Text = "গোলাপের কাঁটা কবিতার পাতা ভেদ করে, রেখে যায় স্বচ্ছ রক্তের দাগ। মদের গন্ধ ছড়িয়ে পড়ে চারদিকে, বর্ণহীন আগুনের শিখা সর্বত্র বিস্তৃত হয়।\nসেই প্রচণ্ড আগুনের মাঝে, অরলা হাতে তুলে নেয় শেষ কবিতার পাণ্ডুলিপি, ফুলঘরে লুকিয়ে থাকা প্রতিভাবান কবির পরিণতির জন্য লেখে এক নীরব টীকা।"
  },
  AwakerStory_11300_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11300_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11301_Content = {
    Text = "তার কৈশোরকাল কেটেছিল সামরিক শিবিরে।\nসামরিক শিবিরে বেড়ে ওঠা সব শিশুর মতোই, সে সেনাবাহিনীর গৌরবে দৃঢ়ভাবে বিশ্বাস করত এবং এটিকে নিজের জীবনের সবকিছু মনে করত। তার পৃথিবী ছিল সরল: কমান্ডার যা অনুমোদন করেন তা-ই সঠিক, কমান্ডার যা নিষেধ করেন তা-ই ভুল।\n「শত্রুর দিকে তরবারি তাক করো, আমরা এই ভূমিকে প্রকৃত স্বাধীনতা দেব; আক্রমণকারী সেনাদের বিরুদ্ধে আঘাত হানো, তাদের প্রতি কোনো সহানুভূতি রেখো না, বর্তমানের এই আত্মত্যাগ ভবিষ্যতের স্থিতিশীলতা ও সমৃদ্ধির জন্য।」\nসে এই স্লোগানের অধীনে প্রশিক্ষণ নিয়েছিল, এই স্লোগানের অধীনেই যুদ্ধক্ষেত্রে পা রেখেছিল। একটি মরণপণ উদ্ধার অভিযানের পর, সে পেয়েছিল একটি আহত পা এবং যুদ্ধ বীরের উপাধি। এরপর থেকে সে পদক পরে দ্বিতীয় সারিতে সরে গিয়ে নতুন সৈনিকদের প্রশিক্ষক হয়ে ওঠে, সম্পূর্ণ অজানা ছিল যে এই আহত পা তাকে কেমন এক জগতের সন্ধান দেবে।\nতার পঙ্গু অঙ্গ অপমানিত হলে, আইলভা ক্রোধে সেনাবাহিনী ত্যাগ করে। রাস্তায় বেরিয়ে এসে সে প্রথমবারের মতো সত্যিই আবিষ্কার করে, কমান্ডারের মহিমান্বিত ভাষণ কতটা মিথ্যা ছিল — মুক্তি ছিল কেবল আগ্রাসনের ছদ্মবেশ, বিদেশের মানুষেরা চরম যন্ত্রণা ভোগ করছিল।\nএটি তার স্বপ্নের রাষ্ট্র নয়, এটি রক্ত ও অশ্রুবিহীন সেই গৌরবময় ভবিষ্যৎ নয়।\nতাই সে তার পূর্বতন সহযোদ্ধাদের বিরুদ্ধে প্রায়শ্চিত্তের তরবারি তুলে ধরে, এবং প্রকৃত ন্যায়বিচারের জন্য লড়াই করার শপথ নেয়।"
  },
  AwakerStory_11301_Title = {
    Text = "গল্প: ৩"
