  AwakerStory_11302_Content = {
    Text = "「ড্যাফোডিলের বিনিময় দোকানে স্বাগতম, আমরা পণ্য বিনিময় এবং মাথার খুলি ক্রয়ের সেবা প্রদান করি, দাম একেবারে ন্যায্য, কাউকে ঠকানো হয় না।」\nধূসর কুয়াশার আবরণের মধ্যে, মহিলাটি আলতো করে তার প্রাচীন কাঠের পাইপটি ঝেড়ে নিলেন, দোলায়মান টুপির কিনারার নিচে, মাঝে মাঝে দেখা যাওয়া ঠোঁটের কোণে এক রহস্যময় হাসির আভাস ফুটে উঠল।"
  },
  AwakerStory_11302_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11302_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
