  AwakerStory_11303_Content = {
    Text = "সবাই খুব দ্রুত একটি সত্য মেনে নিল: যেখানে জেনকিন, সেখানে ব্রাউন; যেখানে ব্রাউন, সেখানে জেনকিন। আর একবার ব্রাউন একা কাজ করলে, সন্দেহ করো না, তার পেছনে অবশ্যই জেনকিনের ছায়া আছে।\n「কী বলতে চাও আমি চুরি করেছি? আমার কাছে তো অ্যালিবাই আছে!」\nমেয়েটি ব্রাউনের 'সংগ্রহ' করা জিনিসপত্র হাতে নিয়ে এমনটাই বলল।"
  },
  AwakerStory_11303_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11303_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11304_Content = {
    Text = "A.F. 180 সালে, উত্তর গোলার্ধের মহা খরার প্রভাবে কারাসু নদী শুকিয়ে যায়।\nস্থানীয় অধিবাসীরা নদীর তলদেশের পলি থেকে একটি দানবের কঙ্কাল খুঁজে পায়। স্থানীয় সংস্কৃতিতে কারাসু নদীর অর্থ 'ঘোলা জল' হওয়ায়, কঙ্কালটির নামকরণ করা হয় 'বিশৃঙ্খলার অস্থি'।\nসামুদ্রিক জীববিজ্ঞানীদের পরীক্ষায় জানা যায়, এটি একটি হাম্পব্যাক তিমির কঙ্কাল, প্রায় 32 ফুট লম্বা, এবং সম্পূর্ণ দেহ একটি রূপালি পদার্থ দ্বারা আবৃত। পরের বছর, ইসিস নিলামে কঙ্কালটি 13 কোটি লিওফ্যাং মূল্যে বিক্রি হয়।\nট্রেডিং হাউস ক্রেতার প্রকৃত পরিচয় প্রকাশ করতে অস্বীকার করে, তবে গুজব অনুযায়ী, কঙ্কালটি লন্ডিনিয়াম শহরের উপকণ্ঠে একটি বেসরকারি বিশ্ববিদ্যালয়ে পাঠানো হয়েছিল।"
  },
