  AwakerStory_11306_Content = {
    Text = "নিঃসঙ্গতার মাঝে ধ্বংসের মুখোমুখি হওয়া সমুদ্রের এলফ, স্থলভূমিতে অলৌকিকভাবে তার অস্তিত্ব টিকিয়ে রেখেছে।\nজন্মগতভাবে আশাবাদী হোক, কিংবা যন্ত্রণা এড়াতে বিস্মৃতিকে বেছে নিয়ে থাকুক, তার অকপট সারল্য এক অসীম আকর্ষণ ছড়ায়, যা মানুষকে অনায়াসে তার পক্ষে টেনে আনে — হয়তো এটাই তার 'সঙ্গী দল' বাড়ানোর ছোট্ট একটা কৌশল, কে জানে।"
  },
  AwakerStory_11306_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11306_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11307_Content = {
    Text = "বিশৃঙ্খলার মধ্যে জন্ম নেওয়া এক জীবন হিসেবে, সে হলো বিশুদ্ধ বিশৃঙ্খলার শক্তি, অদম্য মুক্ত আত্মা, এবং এখনও সংজ্ঞায়িত হয়নি এমন এক শৃঙ্খলা।\nচ্যালেঞ্জ দরকার, যুদ্ধ দরকার — কেবল যখন তার দুর্দমনীয় ধ্বংসের আকাঙ্ক্ষা মুক্তি পায়, তখনই সে তার সৃষ্টিকর্তার একমাত্র অনুরোধ পূরণ করতে পারে।\n——যুগের শেষ পর্যন্ত গ্রহের প্রহরায় দাঁড়ানোর জন্য, সে অনেক দিন ধরে একটি তীব্র যুদ্ধের জন্য আকুল হয়ে আছে।"
  },
  AwakerStory_11307_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11307_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11308_Content = {
    Text = "আমার কি ইচ্ছা পোষণ করার যোগ্যতা আছে?\nযদি থাকে, তাহলে কি আমাকে ছোট বোনের একটি অংশ করে দেওয়া যায়?\nতাকে পূর্ণ করে তুলতে, আমাদের পূর্ণ করে তুলতে।\nতাহলে আমি নির্দ্বিধায় 「ভালোবাসা」 প্রকাশ করতে পারব, আর সেও নিশ্চিন্তে 「ভালোবাসা」কে আলিঙ্গন করতে পারবে।\nপ্রিয় টিংকট আমার……আগে জন্ম নেওয়া সন্তান হিসেবে, এটাই তো তোমার জন্য আমার করা উচিত।"
  },
  AwakerStory_11308_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11308_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11309_Content = {
    Text = "「নির্মম মন্তব্য」, 「কম নম্বরের পরীক্ষার খাতা」, 「অযোগ্য গবেষণা প্রতিবেদন」\nডোরের কয়েক দশকের শিক্ষকতা জীবনে, তার হাত থেকে সমাপনী সনদ পাওয়া শিক্ষার্থীর সংখ্যা হাতে গোনা যায়। বেশিরভাগ শিক্ষার্থী তার অত্যধিক কঠোর মনোভাবে পিছু হটে অন্য অধ্যাপকের অধীনে চলে যায়। ধীরে ধীরে, ডোর অধ্যাপকের কুখ্যাতি শিক্ষার্থীদের মধ্যে ছড়িয়ে পড়ে।\nকিন্তু কিছু শিক্ষার্থী বিশ্বাস করে, সে শুধু এই মানদণ্ড দিয়ে 「শিষ্য」 বাছাই করছে। শুধুমাত্র সবচেয়ে দৃঢ় ইচ্ছাশক্তির অধিকারীরাই সত্যের দরজা খোলার চাবি ধরার যোগ্য, তার সাথে বিশ্বের প্রকৃত রহস্য উন্মোচন করতে।\nএই বিশ্বাসের সমর্থনে, যদিও ডোরের অধীনে স্নাতক হওয়ার সম্ভাবনা অত্যন্ত ক্ষীণ, ডোরের তত্ত্বাবধানে পড়ার আবেদনপত্র অফিসে অবিরাম আসতে থাকে।\nমাঝে মাঝে, আবেদনপত্র পর্যালোচনার জন্য হঠাৎ ডাকা রামোনা ভাবে, শিক্ষার্থীরা যদি এভাবে বিশ্বাস করে, তাও মন্দ নয়।\nরামোনার দৃষ্টিতে, সে শুধু জাগ্রত সত্তার মানদণ্ডে মানব শিক্ষার্থীদের কাছ থেকে প্রত্যাশা করছে, এটুকুই।"
  },
  AwakerStory_11309_Title = {
    Text = "গল্প: ২"
