  AwakerStory_11309_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11310_Content = {
    Text = "মিসাগার্ড বিশ্ববিদ্যালয়ে ড্যাফোডিলের গতিবিধি ছিল রহস্যময় ও অনুমানের অতীত। সর্বোপরি, সে মাত্রার মধ্যে অবাধে চলাচলের নিষিদ্ধ জ্ঞানের অধিকারী ছিল, স্বাধীনভাবে আসা-যাওয়া করত, ভূগর্ভস্থ কালো পুকুরের সিলভার কোর হাবের বিধিনিষেধের বাইরে।\nসে সবসময় সন্দেহজনক উৎসের রহস্যময় যন্ত্রপাতি বা উপকরণ বিক্রি করত, এবং মাঝে মাঝে অন্যান্য অ্যাওয়েকেনারদের মিসাগার্ড বিশ্ববিদ্যালয়ের নিয়ন্ত্রণ থেকে সাময়িকভাবে পালাতে সাহায্য করত।\nপরবর্তীতে, আলোচনার মাধ্যমে, সে ক্যাম্পাসের এক কোণে, মেডিকেল রুমের পাশের একটি পুরনো ঘরে তার নিজের 'চিন্তামুক্ত ডিপার্টমেন্ট স্টোর'-এর শাখা খুলেছিল।\nঅবশ্যই, বিক্রির সমস্ত পণ্য মিসাগার্ড বিশ্ববিদ্যালয়ের নিবন্ধন ও পরিদর্শনের অধীনে থাকতে হতো।"
  },
