  AwakerStory_11311_Content = {
    Text = "লেখক: এরিখ ফন ভার্নার\nসময়: ১৯@1 সালের ১১ নভেম্বর ৭ তারিখ\nস্থানাঙ্ক: ৬৮°১৪′ দক্ষিণ, ৬৭°১০′ পশ্চিম\n\nযাত্রাপথে অস্বাভাবিকভাবে ভেসে থাকা বিপুল সংখ্যক স্পার্ম হোয়েলের মৃতদেহের কারণে আমরা বাধ্য হয়ে এই অভিশপ্ত তুষার দ্বীপে অবতরণ করলাম। দক্ষিণ উপকূলের ফিয়র্ডের বরফ-জলপ্রপাতের নিচে অভিযাত্রী দল প্রায় পঞ্চাশ ফুট দীর্ঘ একটি সেফালোপডের দেহাবশেষ আবিষ্কার করল। দেহটির রঙ গাঢ় নীলাভ, শরীরের পৃষ্ঠে ফসফরেসেন্ট নীল আলোয় ঘেরা কেন্দ্রীভূত বৃত্তাকার রেখা ঘন হয়ে ছিল, এবং রেখার প্রান্ত থেকে পাতলা আঠালো তরল নিঃসৃত হচ্ছিল। নমুনা সংগ্রহ ও পরিশোধনের পর সেই তরল থেকে উদ্বেগজনক পরিমাণে নীল স্ফটিক পৃথক হলো।\nদেহাবশেষের কর্ষিকার চোষক-চাকতির ব্যাস দুই ফুটেরও বেশি, এবং চোষকের ভেতরের দেয়ালে অজানা লিপির মতো নকশা খোদাই করা। প্রধান স্নায়ুতন্তু অর্ধস্বচ্ছ জেলির মতো অবস্থায় ছিল, মাইনাস ত্রিশ ডিগ্রি তাপমাত্রায়ও ক্ষীণভাবে স্পন্দিত হচ্ছিল (বিস্তারিত সংযুক্ত চিত্র D-7 দেখুন)। সঙ্গী জীববিজ্ঞানী ডক্টর হ্যারিস স্নায়ুতন্তুর টিস্যু নমুনা সংগ্রহের চেষ্টা করলেন, কিন্তু অস্ত্রোপচারের ছুরি স্পর্শ করার মুহূর্তেই পুরো দেহাবশেষটি হঠাৎ গুঁড়ো হয়ে গেল। খালি চোখে দৃশ্যমান নীলাভ ধূলিকণা পুরো পরীক্ষাগারে ভেসে রইল।\n\nফেরার পথে ডক্টর হ্যারিস ক্রমাগত প্রলাপ বকতে শুরু করলেন। তিনি বারবার কেবিনের দেয়ালে সর্পিল ও বহুতলীয় জ্যামিতিক আকৃতি আঁকতে লাগলেন এবং চিৎকার করে বলতে থাকলেন 「তারা অ্যান্টার্কটিকার বরফের নিচে ডিম পাড়ছে「। পরের দিন ভোরে টহলরত নাবিকরা তাকে ব্যালাস্ট ট্যাংকে ডুবে মৃত অবস্থায় পেল; ময়নাতদন্তে দেখা গেল তার ফুসফুসের অ্যালভিওলি নীলাভ অণুজীবে পরিপূর্ণ (অক্টোপাসের দেহ-ধূলির সাথে একই উৎস)। ক্যাপ্টেন নমুনার সংস্পর্শে আসা সমস্ত পোশাক পুড়িয়ে ফেলার নির্দেশ দিলেন।\nআশা করি আর কেউ বরফের নিচে লুকিয়ে থাকা এই দুঃস্বপ্নের সংস্পর্শে আসবে না।\n\n——《অ্যান্টার্কটিক বৈজ্ঞানিক অভিযান দিনলিপি · ৩৭ নম্বর পরিশিষ্ট》"
  },
