  AwakerStory_11311_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11312_Content = {
    Text = "আমরা কীভাবে বীর ইউউহাশিকে ভুলতে পারি? সে ছিল সবচেয়ে অসামান্য পুরুষ। যোদ্ধা সূর্যাস্তের হলুদ বালিতে হাঁটু গেড়ে পড়ল, উষ্ণ রক্ত তার সারা শরীর ভিজিয়ে দিল। শকুন আকাশে চক্কর দিল, তার জন্য শোকগাথা গাইল：\nকেউ অশ্রু দিয়ে তোমাকে সম্মান জানাবে না, কেউ কান্না দিয়ে তোমাকে সমাহিত করবে না, কারণ জীবদ্দশায়ই তুমি রোমে খ্যাতি অর্জন করেছিলে।"
  },
  AwakerStory_11312_Title = {
    Text = "প্রাথমিক তথ্য"
