  AwakerStory_11313_Content = {
    Text = "A.F.@2 সাল @1 মাস\nপ্রিয় লর্ড ক্যাভেন্ডিশ：\n\nদয়া করে ক্ষমা করবেন, আমি ধৃষ্টতার সাথে বাটলার ফ্রেকে আমার জন্য কাগজ-কলম আনতে অনুরোধ করেছি, শেষ বিন্দু বিবেক ও শালীনতা ধরে রেখে এই চিঠিটি লিখছি। যখন থেকে আমি এই ভয়ানক রোগে আক্রান্ত হয়েছি, আর কখনো মা, পবি কিংবা আপনাকে দেখতে পাইনি, এই আকুলতা আমাকে পাগল করে দেওয়ার জন্য যথেষ্ট।\nভূগর্ভে বন্দি হয়ে আছি… 353 দিন? আমি জানি না, হয়তো 326 দিন।\nএখানে খুব ঠান্ডা, সর্বত্র পচা গন্ধ। আমার ক্ষতস্থান থেকে কালো আঠালো তরল বেরোচ্ছে, আবার ইঁদুরে কুরে কুরে বিকৃত করে দিয়েছে। কিন্তু কিছু যায় আসে না, যন্ত্রণা ভালো, এটা মানুষকে সচেতন রাখে।\n「দুষ্ট ভ্যাম্পায়ার」、「পরিবারের কলঙ্ক」… আমাকে বিচ্ছিন্ন করা নিঃসন্দেহে একটি বুদ্ধিমান সিদ্ধান্ত। আমার আত্মা অনেক আগেই শয়তানের নিয়ন্ত্রণে চলে গেছে, এই চিঠি লেখার সময়, আমি সবেমাত্র একজন মৃত ভবঘুরের রক্ত শুষে নিয়েছি। বাটলার ফ্রে বলেছেন, আপনার নির্দেশেই রাস্তা থেকে খুঁজে আনা হয়েছে। যদিও স্বাদটা কিছুটা বাসি ছিল, তবুও আমি খুব খুশি, দেখা যাচ্ছে আপনি আমার কথা ভাবেন।\nএছাড়া… একটা কম্বল কি দেওয়া সম্ভব? আমার কাছে এখন শরীর ঢাকার কোনো কাপড় নেই, লন্ডিনিয়েনের শীতকাল সত্যিই অসহ্য ঠান্ডা।\nএখনও আমি খুব মনে করি, ছোটবেলায় আমরা একসাথে ওয়েটিং ম্যানশনে ছুটি কাটানোর সেই সময়গুলো।\n\nআপনার আন্তরিক বোন\nরেয়া\n——《কেনসিংটন ভ্যাম্পায়ার ঘটনা·মামলা সারসংক্ষেপ：প্রমাণ C-601》থেকে উদ্ধৃত"
  },
