  AwakerStory_11314_Content = {
    Text = "A.F.31@1 সালের ডিসেম্বরের মাঝামাঝি, পুলিশ @2 গার্ডেন দ্বিতীয় থিয়েটারের ব্যবস্থাপকের কাছ থেকে একটি অভিযোগ পায়। অভিযোগকারী জানান, এক সপ্তাহের মধ্যে থিয়েটারে চারবার ছোট পরিসরে আগুন লেগেছে এবং থিয়েটার ভাড়া নেওয়া ব্যালে দলের সদস্যদের মধ্যে 「ব্যালে প্রেতাত্মা「-র গুজব ছড়িয়ে পড়েছে।\nব্যালে নাটক 「সোয়ান এলিজি「-র প্রথম মঞ্চায়ন সুষ্ঠুভাবে সম্পন্ন করার জন্য, পুলিশ ও পশ্চিম জেলা দমকল বিভাগ যৌথ তদন্ত শুরু করে।\nমঞ্চায়নের আগের দিন, মিসাগার বিশ্ববিদ্যালয় অবশেষে তদন্তের দায়িত্ব গ্রহণ করে। তদন্তকারীরা লক্ষ্য করেন যে, একাধিক অগ্নিকাণ্ডের উৎসস্থলে আধ্যাত্মিক জ্ঞানের অবশিষ্ট চিহ্ন রয়েছে। অবশেষে, @3 তদন্তকারী দ্বিতীয় থিয়েটারের ভূগর্ভস্থ ধ্বংসাবশেষে একজন জাগ্রত সত্তা আবিষ্কার করেন।\nসেই জাগ্রত সত্তা কোনো বিচারবুদ্ধিহীন ব্যক্তি ছিল না, সে নিজেকে 「লিজ「 বলে পরিচয় দেয়। আলোচনার পর, জাগ্রত সত্তা লিজ অবশেষে তার অগ্নিসংযোগের অপরাধ স্বীকার করে। 「সোয়ান এলিজি「-র প্রথম মঞ্চায়ন শেষ হওয়ার পর, @3 তদন্তকারী জাগ্রত সত্তা লিজকে মিসাগার বিশ্ববিদ্যালয়ে নিয়ে যান এবং আনুষ্ঠানিকভাবে দলে অন্তর্ভুক্ত করেন।\n\nঐতিহাসিক নথি অনুসারে, A.F.29@1 সালে @2 গার্ডেন দ্বিতীয় থিয়েটারে আগুন লাগার সময়, থিয়েটারে একটি ব্যালে নাটক মঞ্চস্থ হচ্ছিল। সেদিন অগ্নিকাণ্ডে প্রাণ হারানোদের মধ্যে দর্শকসারিতে থাকা বহু অভিজাত ব্যক্তি ছাড়াও, 「এলিজাবেথ সালার「 নামের একজন তরুণ প্রধান ব্যালেরিনাও ছিলেন।"
  },
  AwakerStory_11314_Title = {
