  AwakerStory_11316_Content = {
    Text = "তার অতিক্রম করা প্রজ্ঞা তার দেহের ওপর ভয়াবহ মাশুল তোলে; প্রতিদিন তাকে পনেরো ঘণ্টারও বেশি ঘুমোতে হয়, আর জাগ্রত সময়েও এক অদম্য অবসাদ তাকে তাড়া করে বেড়ায়।\nস্বপ্নের ভেতরে কখনও তিনি অনুভব করেন দেবতাদের ক্রোধ; কখনও ভাঙা সময়রেখার সংযোগস্থল তার চোখের সামনে খুলে যায়। কখনও বা তিনি ঘুরে বেড়ান সর্বাধিক গভীরে, মুখোমুখি হন স্বয়ং দেবত্বের।\nতিনি কখনও তাদের প্রত্যাদেশ বা ভবিষ্যদ্বাণী খোঁজেননি, তবু যতই তিনি সেগুলো এড়াতে চান না কেন, দর্শনগুলো অবধারিতভাবে বাস্তবে রূপ নেয়।\nতিনি কখনও নিবেদিত কবিতা দাবি করেননি। পূজিত হওয়া, ভীতিপ্রদ হওয়া—এই সব বোঝা অন্যেরা তার কাঁধে চাপিয়ে দিয়েছে, আর সেগুলোর প্রতি তার কোনো আগ্রহ নেই।\nপুনর্জন্ম তার কাছে ছিল কেবল এক অনন্ত স্বপ্নের অনাহূত বিঘ্ন।\nকোনো আহ্বানের প্রয়োজন নেই। কোনো প্রার্থনার প্রয়োজন নেই।"
  },
