  AwakerStory_11317_Content = {
    Text = "……\nপরীক্ষার তারিখ: A.F.@1 সাল @2 মাস\nপরীক্ষার উদ্দেশ্য: ফিউশন ইরোশন রোগীর দেহে অঙ্গ-প্রত্যঙ্গ গ্রাফটিংয়ের পর সৃষ্ট মিউটেশন প্রতিক্রিয়া পর্যবেক্ষণ ও নথিভুক্ত করা\nপরীক্ষার ধাপ: @3@4\nপরীক্ষামূলক বিষয়ের মৃত ভাইকে গ্রাফটিং পরীক্ষার জন্য নির্বাচন করা হয়েছে, সরাসরি রক্তসম্পর্কীয় আত্মীয়দের মধ্যে প্রত্যাখ্যান প্রতিক্রিয়া পর্যবেক্ষণের উদ্দেশ্যে। এই হতভাগ্য পুলিশের ধাওয়া থেকে পালানোর সময় একাধিক গুলিতে নিহত হয়েছিল@3পরীক্ষা অত্যন্ত সফল হয়েছে, ক্ষতস্থান লাল হয়ে শুঁড়ের মতো অংশ বৃদ্ধি পেয়েছে……রক্ত যেন চুনি পাথরের মতো উদ্বেলিত হয়ে বেরিয়ে এসেছে।\n@3@3\nপরীক্ষার্থী বিস্ময়কর সহনশীলতা প্রদর্শন করেছে, সে মরফিন ইনজেকশন প্রত্যাখ্যান করেছে।\nপরীক্ষার পর রক্তের প্রতি তৃষ্ণা বৃদ্ধি পেয়েছে, স্বভাব……বর্ণনাতীত, মোটকথা এটি এমন ধরনের নয় যা সামলাতে আমি পারদর্শী।\n——হার্বার্টের 《ফিউশন ইরোশন পরীক্ষার নথি · চতুর্থ গ্রুপ @1 নং》 থেকে উদ্ধৃত"
  },
