  AwakerStory_11318_Content = {
    Text = "কাছে যেও না, স্পর্শ করো না, সরাসরি তাকিও না, দয়া দেখিও না— এই জগতে হয়তো এমন কিছু সত্তা আছে যারা কেবল অন্ধকারে একাকী বাস করার জন্যই সৃষ্ট।\nযদিও এটি তার নিজের ইচ্ছা নয়, তবু যদি তুমি তার দুর্বল দেহ, ভীরু কণ্ঠস্বর আর শিশুসুলভ পোশাক দেখে মমতায় ভরে তার চোখের দিকে সরাসরি তাকাও, তবে তুমি চিরন্তন স্থবিরতা ও নীরবতার গহ্বরে তলিয়ে যাবে।"
  },
  AwakerStory_11318_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11318_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
