  AwakerStory_11319_Content = {
    Text = "নৃত্যদলে যোগ দেওয়ার পঁয়তাল্লিশতম দিনে, আমি প্রধান অভিনেত্রী হিসেবে মঞ্চে দাঁড়িয়েছিলাম।\nউজ্জ্বল আলো স্কার্টের প্রান্তে পড়ছিল, ক্ষুদ্র হীরার টুকরোগুলো মনোমুগ্ধকর সৌন্দর্য প্রতিফলিত করছিল। সেই আলো আমার দৃষ্টিকে স্বাভাবিক রাখতে দিচ্ছিল না, কিন্তু বজ্রধ্বনির মতো করতালি থেকে বুঝতে পারছিলাম যে আমার পারফরম্যান্স রত্নপাথরের চেয়েও বেশি উজ্জ্বল ছিল।\nঅবিরাম ঘূর্ণনের মধ্যে, পৃথিবীর সমস্ত ধুলো বিশুদ্ধ নৃত্যের মাধ্যমে ধুয়ে যাবে, সমগ্র বিশ্বে নৃত্যের সৌন্দর্য ও শিল্পের সৌন্দর্য পৌঁছে দেওয়া — এটাই একজন নৃত্যশিল্পী হিসেবে আমার ইচ্ছা ও দায়িত্ব——\n\nকিন্তু, মঞ্চের নিচে অন্ধকার কোণে লুকিয়ে থাকা সেই মানুষগুলো কী করছে?\n\nলিসেট, সেই অকপট ও সরলমনা মেয়েটি, সে কীভাবে সেই কুখ্যাত ভদ্রলোকের সাথে কানে কানে কথা বলছে?\nঅ্যাঞ্জেলিকা, সেই প্রতিভাবান মেয়েটি যে সবসময় অন্য নৃত্যশিল্পীদের তুচ্ছ করে দেখে, সে কেন সেই বদনামি যুবকের সামনে স্কার্ট তুলে ধরছে?\n\nএত জঘন্য... এত কলুষিত! হে দেবতা, আমার মিউজ, আমাকে বলুন, আমি কী করব, যাতে অন্ধকার থেকে আমার মঞ্চকে রক্ষা করতে পারি, এই কলুষতা দূর করতে কতটা আলোর প্রয়োজন——"
  },
