  AwakerStory_11320_Content = {
    Text = "শৈশবকাল থেকেই ক্যাসিয়া অসাধারণ অনুকরণ প্রতিভার পরিচয় দিয়েছিল।\nযত জটিল নৃত্যই হোক না কেন, একবার দেখলেই সে তা হুবহু পুনরায় করতে পারত; যত কঠিন জাদুই হোক, একবার শেখালেই সে তা দক্ষতার সাথে আয়ত্ত করে ফেলত। কণ্ঠস্বর, অভিব্যক্তি, এমনকি হাসি ও ব্যক্তিত্ব—ক্যাসিয়া সবকিছুই নিখুঁতভাবে নকল করতে পারত, এতটাই নিখুঁত যে আসল-নকলের পার্থক্য করা অসম্ভব হয়ে উঠত। যদি তার জন্ম অন্য কোথাও হতো, বা অন্য কোনো পেশায় যেত, তাহলে হয়তো এই প্রতিভা দিয়ে সে সম্পূর্ণ ভিন্ন একটি জীবন পেতে পারত।\nকিন্তু দুর্ভাগ্যবশত, সে ছিল কেবল এক অখ্যাত সার্কাস দলে বেড়ে ওঠা একটি শিশু। সার্কাসের লোকেরা শুধু তার প্রতিভাকে কাজে লাগিয়ে অর্থ উপার্জনের কথাই ভাবত, আর সার্কাসের বাইরের মানুষেরা—তারা শুধু আনন্দ কিনতে আসত, সহানুভূতি দিতে নয়।\nকেউ ক্যাসিয়ার সুখের কথা ভাবত না, তবে সৌভাগ্যবশত, ক্যাসিয়া নিজেও তাতে কিছু মনে করত না। যখনই সে হাসিখুশি দর্শকদের দিকে তাকাত, ঝগড়ারত দলের সদস্যদের দেখত, ছবির দিকে তাকিয়ে নীরবে অশ্রু ফেলা সেই মহিলা ভাগ্যগণনাকারীকে দেখত—তখন সে কেবল এক বিচ্ছিন্ন কৌতূহল অনুভব করত: তারা কেন মঞ্চের বাইরে এসব অভিব্যক্তি দেখায়? কেউ দেখছে না জেনেও কেন তারা অভিনয় চালিয়ে যায়? কেন তারা বলে এটা তাদের 'আবেগের বহিঃপ্রকাশ'?\nসুখ কী? দুঃখ কী? তার গলা কেটে দেওয়া সেই 'পৃষ্ঠপোষক' যে মৃত্যুর দ্বারপ্রান্তে হতাশা ও ভয়ের কথা বলেছিল, সেটাই বা কেমন অনুভূতি?\nমানুষ হিসেবে সে এই প্রশ্নের উত্তর খুঁজে পায়নি, কিন্তু জাদুর সন্তান হিসেবে, অন্যদের কাছ থেকে 'আবেগ' সংগ্রহ করতে সক্ষম এক সত্তা হিসেবে, হয়তো অবশেষে সে সেই অভিজ্ঞতা লাভ করতে পারবে যা কখনো তার হয়নি।\nতাই সে জাদু কার্নিভাল প্রতিষ্ঠা করল এবং এটিকে বিশ্বের প্রতিটি প্রান্তে নিয়ে গেল।\nমানুষ আনন্দ কিনতে আসত, কিন্তু মূল্য হিসেবে দিয়ে যেত তাদের সমস্ত আকাঙ্ক্ষা।\n'এসো, এসো, আমার কার্নিভালে এসো! শুধু একটুখানি সুখ, একটুখানি দুঃখ জমা দাও, আর দেখো এই শতাব্দীর সবচেয়ে অসাধারণ পরিবেশনা!'"
  },
