  AwakerStory_11321_Content = {
    Text = "শুরুতে, এটা ছিল শুধু রেড ওয়াইনের বদলে একগ্লাস আঙুরের সোডা।\nকেউ লক্ষ্য করছে না এমন এক কোণে, সোরেল করুণ ভাব ধরে দুই-তিনজন শিক্ষার্থীর সাথে পান করছিল।\nতারপর, একটি ছোট্ট বিকেলের চায়ের আসর।\nশিক্ষার্থীদের ক্যাফেটেরিয়ায়, শিক্ষার্থীরা ম্যাকারন এগিয়ে দিলে সোরেল বারবার প্রত্যাখ্যান করল, তার চোখে ফুটে উঠল কিছুটা আকুলতা আর আন্তরিকতা।\nশেষে, একটি জমকালো সালোঁর আয়োজন হলো, একটি গোলাপের পূর্ণ প্রস্ফুটন।\nবিশ্রামকক্ষ ফুল আর রত্নাভরণে সাজানো হলো, রূপসী গোলাপ আর তরুণ শিক্ষার্থীরা একসাথে পানপাত্র তুলে আনন্দে মেতে উঠল, অতিথি-আতিথেয় সকলেই তৃপ্ত।\nনবনিযুক্ত গোপনরক্ষক এই সবকিছু প্রত্যক্ষ করল, এবং মনে মনে প্রার্থনা করল যেন তার পরবর্তী পদক্ষেপ কিছুতেই 'মিসাগ বিশ্ববিদ্যালয়ের উপাচার্য হওয়া' না হয়।"
  },
  AwakerStory_11321_Title = {
