  AwakerStory_11322_Content = {
    Text = "ধূসর ঘন আদিসত্তার সাগরে কিছুই নেই, মাত্রা অতিক্রমকারী পর্যটকদের বর্ণিত ধারণাগুলোও কেবল বিমূর্ত বিবরণ ও কল্পনায় সীমাবদ্ধ।\nসে নিজের চোখে সেই মানুষদের 'আকাঙ্ক্ষিত স্থান' দেখতে চায়, মর্ত্যলোকের বর্ণিল ও মহিমান্বিত দৃশ্যাবলি স্বচক্ষে প্রত্যক্ষ করতে চায়, সুখ-দুঃখ, মিলন-বিচ্ছেদের স্বাদ নিজে অনুভব করতে চায়।\nকিন্তু এসবের ঊর্ধ্বে, সে একজন নির্দিষ্ট মানুষ চায়—যাকে লালন করা যায়, যার উপর আস্থা রাখা যায়।\nন্যায্য লেনদেন মানে সমতা, মানে বিভাজন, মানে পণ্য ও মূল্যের নিষ্পত্তি, মানে এক কণাও বেশি দেওয়া নয় আর আধা কণাও কম নেওয়া নয়। কিন্তু সে ভিন্ন কিছু কামনা করে, কামনা করে এক নিঃশর্ত আস্থা—যা দূরত্ব ঘোচাবে, যা সন্দেহের প্রাচীর ভাঙবে, যা জমাট বরফ গলিয়ে দেবে।\nসে পেয়েও হারিয়েছে, কিন্তু শেষপর্যন্ত হারিয়েও আবার ফিরে পাবে।"
  },
