  AwakerStory_11325_UnlockDesc_1 = {
    Text = "মূল গল্পের সাধারণ মোডে অধ্যায় 5 「ঝড়ের চক্ষু」 সম্পন্ন করো।"
  },
  AwakerStory_11326_Content = {
    Text = "বন্যাকাল 282 সালের জুন মাসে, মিস্টিয়া চুক্তি পর্যালোচনা কমিটির দাখিল করা তদন্ত আবেদনের ভিত্তিতে, আমরা নিউ রেও অঞ্চলে একটি তদন্ত দল পাঠাই।\nএক বছর আগে উল্কাপাত ঘটনার পর থেকে, সেই অঞ্চলে অস্বাভাবিক মৃত্যুর হার ক্রমাগত উচ্চ থাকছে।\nএছাড়াও, তদন্তকারীরা পতনস্থলে বেশ কয়েক ধরনের পরিবর্তিত উদ্ভিদ আবিষ্কার করেছেন। যন্ত্রপাতির পরিমাপে দেখা গেছে, এই উদ্ভিদগুলোতে উল্কা থেকে আসা বলে সন্দেহজনক উচ্চমাত্রার বিকিরণ রয়েছে।\nতবে উল্কাখাদের ভেতরে কোনো বহির্জাগতিক খনিজ পদার্থ পাওয়া যায়নি। গ্রামবাসীদের সাক্ষ্য অনুযায়ী, উল্কা পতনের তৃতীয় দিনে, সাদা পোশাক পরা একদল বিজ্ঞানী উল্কাটি কেটে নিয়ে চলে যান।\n（বিঃদ্রঃ: সম্ভবত বেসরকারি বৈজ্ঞানিক সংগঠন, পরিচয় সন্দেহজনক।）\nপর্যালোচনা কমিটি ও স্থানীয় সরকারের সমন্বয়ে, সমস্ত বাসিন্দাকে সরিয়ে নেওয়া হয়েছে এবং এই স্থানটিকে সরকারিভাবে বসবাস নিষিদ্ধ এলাকা ঘোষণা করা হয়েছে।\nমিসাগ বিশ্ববিদ্যালয়ের পদার্থবিজ্ঞান গবেষণাগারের হিসাব অনুযায়ী, এই অঞ্চলে বসবাস নিষেধাজ্ঞা কমপক্ষে 80 বছর বজায় রাখতে হবে।"
  },
  AwakerStory_11326_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_11326_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11327_Content = {
    Text = "প্রতিপক্ষ বাছাইয়ের ক্ষেত্রে, রোটানের নিজস্ব একটি মানদণ্ড আছে।\nশিক্ষায়তনিক যোদ্ধারা বেশিরভাগই পড়াশোনা করতে করতে মাথা খারাপ করে ফেলেছে, শুধু কাগজে-কলমে কৌশল নিয়ে ভাবে, বিরক্তিকর।\nসেনাবাহিনীর সেরারা আবার প্রায়ই আনুষ্ঠানিকতা ও নৈতিক শিক্ষার বন্ধনে আবদ্ধ, অত্যন্ত নিরস।\nশুধুমাত্র সেই ঐশ্বরিক প্রতিভাধর, জন্মগত যুদ্ধ-প্রবৃত্তিসম্পন্ন অসাধারণ ব্যক্তিরাই তার দৃষ্টি আকর্ষণ করতে পারে।\nগ্রহের সমান আয়ুষ্কাল বিশিষ্ট দৈত্য যুদ্ধের আকাঙ্ক্ষা দমন করে, প্রায় ভক্তিভরে তার নির্বাচিত প্রতিপক্ষের শীর্ষে পৌঁছানোর অপেক্ষায় থাকে——সে কী অসাধারণ প্রতিভাবান এক কিশোর! সে গভীর সমুদ্রের শক্তিকে আদেশ করে, তার শক্তিশালী আত্মা এমনকি জগতের বাইরের দেবতাদের সাথেও সংযুক্ত হতে পারে, সময় দিলে সে অবশ্যই লোভনীয় শক্তিশালী যোদ্ধায় পরিণত হবে।\nকিন্তু, সম্ভবত দীর্ঘ সময় তার বিচারশক্তি ক্ষয় করেছে, এবার বিশৃঙ্খলার আত্মা ভুল দেখেছিল। নানা কারণে, রোটান আর কারো কাছে এ বিষয়ে কিছু বলতে চায় না।\nআমরা শুধু জানি, সেই ঘটনার পর থেকে, সে যেকোনো 「উন্নতির চেষ্টা না করা」, 「অগ্রগতির কথা না ভাবা」 ব্যক্তিকে তুচ্ছ করে।"
  },
