  AwakerStory_11328_Content = {
    Text = "সিলভার কোর নম্বর：B-005\nউদ্ধার সময়：A.F.1@1 সাল @3 মাস\nউদ্ধার স্থান：ফ্ল্যান্ডার্স নিম্নভূমি গ্রামাঞ্চল, একটি অজ্ঞাত প্রাচীন রোমান সমাধি ধ্বংসাবশেষ\nবিস্তারিত বিবরণ：সিলভার কোরের অধিকারী ছিলেন লুডভিগ·প্রিন, একটি আত্মা আহ্বান ঘটনার জন্য স্থানীয় ধর্মীয় বিচারালয় তাকে অগ্নিদণ্ডে দণ্ডিত করে। প্রিন দাবি করেন যে তিনি নবম পবিত্র পূর্বাভিযানের যুদ্ধক্ষেত্রে এই সিলভার কোর পেয়েছিলেন, তারপর ব্রাবান্টের কাছে গিয়ে, 「বহির্জাগতিক সেবক」 ও 「অদৃশ্য সঙ্গী」দের সাথে মিলে, 「মহান অবর্ণনীয় সত্তা」কে আহ্বানের জন্য রক্তাক্ত আচার অনুষ্ঠান করেন।\nলিপিকার：ওয়ার্ড·ফিলিপস\n——《জাগ্রত সত্তা সিলভার কোর অধিগ্রহণ প্রতিবেদন：B-005》"
  },
  AwakerStory_11328_Title = {
    Text = "গল্প: ১"
