  AwakerStory_11329_Content = {
    Text = "একাকীত্বে, একজন মানুষকে একটি দলের মতো হতে হয়। 24-এর মাথাটা বেশ জটলাপূর্ণ — তারা অন্ধকারে ফিসফিস করে, চাপা হাসি হাসে, অবিরত 24-এর অন্তরকে ছিন্নভিন্ন করে, তাকে গ্রাস করতে আকুল। রাস্তার কোণে নর্দমা থেকে ভেসে আসা দুর্গন্ধ, কারখানা এলাকায় উড়ে বেড়ানো তুলোর আঁশ, মেয়াদোত্তীর্ণ কালো রুটি... অতীত কবেই বিলীন হয়ে গেছে, পূর্ব অঞ্চলের সেই সাধারণ নারী শ্রমিককে কেউ মনে রাখেনি। সে অবশেষে ক্লান্ত দেহ থেকে মুক্তি পেয়েছে, কিন্তু পা রেখেছে নতুন এক কর্দমাক্ত গহ্বরে।"
  },
  AwakerStory_11329_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11329_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11330_Content = {
    Text = "এই বোনদের মধ্যে, একজনের কখনোই জন্ম নেওয়া উচিত ছিল না।\nতাদের নিজ গ্রহে, যে গ্রহ এখন উজাড়, আর পৃথিবীবাসীরা যাকে লিরা নক্ষত্রপুঞ্জ বলে ডাকে, সেইখানে ফেইন্ট আর টিঙ্ক্ট তাদের জীবনের অর্ধেকটা তিক্ত বাক্য বিনিময়ে কাটিয়েছে।\nকিন্তু অবাঞ্ছিত সন্তানটি কে?\nজ্যেষ্ঠ বোন ফেইন্ট শক্তিশালী, তবু নিয়ন্ত্রণহীন; সে যে জীবনশক্তি ছিনিয়ে নেয়, তা যেন নদীর জলের মতো গড়িয়ে চলে যায়, তাকে ফেলে রাখে এমন এক অবস্থায়, যেখানে সে কেবল অবশিষ্ট শিশিরবিন্দু চেটে কোনোমতে বেঁচে থাকতে পারে।\nকনিষ্ঠ বোন টিঙ্ক্ট সুন্দরী, তবু স্বনির্ভর হতে হিমশিম খায়; তার জীবন ভাসমান আগাছার মতো একগুঁয়ে, তবু কোথাও শিকড় গাঁথে না, ফলে সে তার বোনকে কেন্দ্র করে ঘুরপাক খেতে থাকে।\nহয়তো তারা দুজনেই বিশ্বাস করে, তাদেরই কারো অস্তিত্ব থাকা উচিত ছিল না। শুধু ফেইন্ট একটু আগে সিদ্ধান্ত নিয়েছিল — আত্মবিনাশের হুমকি দিয়ে সে তার বোনকে বিদায়যাত্রায় ঠেলে দিয়েছিল।\n「চলে যা, টিঙ্ক্ট। আমাকে যেন তোমাকে আটকে রাখতে না হয়।」\n「তুমি নক্ষত্রদের মাঝে গান গাইবে, হয়ে উঠবে সবচেয়ে চোখে পড়ার মতো মূল বর্ণ।」"
  },
  AwakerStory_11330_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_11330_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11331_Content = {
    Text = "বেশিরভাগ সময় চুপচাপ কোণের একটুকু জায়গা দখল করে থাকে, প্রকৃত বাতিঘরের মতো, পথ হারানোর সময় কথা বলে সবাইকে সঠিক পথে ফিরিয়ে আনে ও দিকনির্দেশনা দেয়।\nশুধুমাত্র অন্যান্য গভীর সমুদ্রের আগন্তুকদের সাথে একই ঘরে থাকলেই, আলোর শিখা তার উন্মাদনা ও আবেশের ছায়া ফুটিয়ে তুলতে পারে।\nশান্ত ও বুদ্ধিদীপ্ত বাহ্যিক রূপের নিচে, ফালোস আশ্চর্যজনকভাবে দূর সমুদ্র যাত্রায় বেশ অভিজ্ঞ। যদিও নাবিকদের প্রলুব্ধ করা ও বলি দেওয়ার সন্দেহ এখনও দূর হয়নি এবং বর্তমানে গোপনরক্ষকের তত্ত্বাবধানে আছে, তবুও ফালোস স্কুল কর্তৃপক্ষকে অনেক নৌচালনা সংক্রান্ত তথ্য সংশোধনে সাহায্য করেছে।\n——স্কুল কর্তৃপক্ষের সহযোগী জাহাজের নাবিকদের প্রতিক্রিয়া অনুযায়ী, ফালোসের সংশোধন পরামর্শ কার্যকর হলেও, প্রায়ই ইচ্ছাকৃতভাবে বা অনিচ্ছাকৃতভাবে গতিপথ মংগ ত্রিভুজ সমুদ্র অঞ্চলের দিকে নিয়ে যায়।\nএই বিষয়ে জানার পর, স্কুল কর্তৃপক্ষ ফালোসকে সমস্ত সমুদ্র সংক্রান্ত তথ্যের সংস্পর্শে আসা নিষিদ্ধ করেছে।"
  },
  AwakerStory_11331_Title = {
    Text = "গল্প: ২"
