  AwakerStory_11332_Content = {
    Text = "ক্যালিগুলার ব্যক্তিগত আলকেমিস্ট মার্কুস·আন্তিস বিপুল সংখ্যক জীবিত মানুষের বিনিময়ে তৈরি করা 「গোলেম」।\nসৃষ্টি আচারের অসম্পূর্ণতার কারণে, প্রতিদিন প্রচুর পরিমাণে মানুষের রক্ত পান করতে হতো। ক্যালিগুলার জন্য রাজনৈতিক প্রতিদ্বন্দ্বীদের হত্যা করেছে এবং তাকে রোমান সম্রাট হিসেবে অভিষিক্ত হতে সাহায্য করেছে।\nস্বৈরাচারী ক্যালিগুলা ক্ষমতায় আসার চার বছরেরও কম সময়ে নিহত হন। তাকেও ক্রুদ্ধ ও ভীত জনতা তার ধ্বংসপ্রাপ্ত বেদির ভূগর্ভে শৃঙ্খলিত করে রেখেছিল, প্রায় হাজার বছর ধরে তৃষ্ণা সহ্য করতে বাধ্য হয়েছিল।\nদীর্ঘ সময় ধরে, সে ইঁদুরের রক্ত চুষে বেঁচে ছিল, রক্তের গভীর থেকে উত্তরাধিকারসূত্রে পাওয়া তৃষ্ণা তাকে পাগল করে দিয়েছিল।\nযথেষ্ট নয়, মোটেও যথেষ্ট নয়…\n@2 সময়কালে, একজন লেভান্তীয় জাদুকর তাকে খুঁজে পেয়েছিল, মুক্তিতে সাহায্য করার প্রতিশ্রুতি দিয়েছিল, শর্ত ছিল যুদ্ধক্ষেত্রে লেমওয়াশি জাতিকে হত্যা করা।\nএমন সুযোগ?\nসে সহজেই কাজটি সম্পন্ন করেছিল, তবে, একটি ছোট্ট ঘটনা ঘটেছিল：অত্যধিক উত্তেজনায়, সে ভুলবশত যুদ্ধক্ষেত্রের সকলকে হত্যা করে তাদের রক্ত শুষে নিয়েছিল——জাদুকর এবং তার নিজের লোকসহ।"
  },
