  AwakerStory_11333_Content = {
    Text = "জাগরণ উপাদান G752a নম্বর সিলভার কোর, লন্ডিনিয়ামের নিউগেট কারাগারের ধ্বংসাবশেষের দুর্গন্ধযুক্ত পলিস্তূপ থেকে উদ্ধার করা হয়েছে।@2তদন্তকারী অন্ধকার ও নোংরা কারাকক্ষের করিডোরে ভাঙা মাথার খুলিতে পা দিয়ে পিছলে পড়েন, এবং সেই সুযোগেই ঘটনাক্রমে এটি আবিষ্কৃত হয়।\nজাগরণের ফলাফল প্রত্যাশার বিপরীত হয়েছে — কালো ক্ষয়কারী তরল থেকে কোনো হিংস্র মৃত্যুদণ্ডপ্রাপ্ত আসামি বা বলিষ্ঠ জল্লাদ নয়, বরং আবির্ভূত হয়েছে ক্ষুদ্রাকৃতির, ধূর্ত হাসিমুখের এক কিশোরী।"
  },
