  AwakerStory_11334_Content = {
    Text = "@2এই নামটি ইতিহাসে বারবার লেখা হয়েছে।\nপুরোহিত, মা, রাজমহিষী, রানি, ডাইনি... এই নামের সাথে এত বিভিন্ন উপাধি জুড়ে দেওয়া হয়েছে যে ইতিহাসবিদরা আজও নিশ্চিত করতে পারেন না, ঠিক কোন পরিচয়টি আমরা বর্তমানে যে জাগরিত সত্তাকে চিনি তার প্রতিনিধিত্ব করে।\nতাইয়িসি নিজে তাঁর অতীত আমাদের সাথে ভাগ করে নিতে কার্পণ্য করেন না — সেসব সবই তিনি, আবার পুরোপুরি তিনি নন।\n「উচ্চ বংশে জন্ম নেওয়া সেই তিনি।」\nতাইয়িসি সবসময় মন্দিরের সবচেয়ে উজ্জ্বল মেয়ে ছিলেন, মহাপুরোহিতের সন্তান হিসেবে তিনি রাজহাঁসের মতো মার্জিত, চাঁদের আলোর মতো কোমল।\n「বৃক্ষের সামনে নতজানু হওয়া সেই তিনি।」\nতাইয়িসি ছিলেন 'বৃক্ষে'র সবচেয়ে উজ্জ্বল পাতা, তাঁর ভক্তি তাঁকে 'বৃক্ষে'র আশীর্বাদ এনে দিয়েছিল।\n「সারা শরীরের রক্ত নিংড়ে নেওয়া হয়েছিল যাঁর, সেই তিনি।」\nবিপর্যয় নেমে এলে, মহাসৌধ ধসে পড়ার সময়, প্রাচীন ও অজ্ঞ সভ্যতা বেছে নিয়েছিল সবচেয়ে শ্রেষ্ঠ তাঁকে।\n「যাঁর শিরা-উপশিরায় বৃক্ষরস প্রবাহিত, সেই তিনি।」\nসকল মানুষের শ্রদ্ধার 'বৃক্ষে'র নিজস্ব পছন্দ ছিল। শাখা-প্রশাখা শরীরে শিকড় গেড়ে, ভক্তকে দিয়েছিল প্রায় অনন্ত আয়ু।\n「কিন্তু, সভ্যতা ধ্বংস করতে চেয়েছিলেন তিনি নন।」\nতাইয়িসি যা চেয়েছিলেন, তা কখনোই পৃথিবীর ধ্বংস ছিল না।\n「কিন্তু তাইয়িসি মহোদয়া, আপনি আসলে কী চান?」\n「আরে — আমরা কি কথা দিইনি? যখন আমাদের মধ্যে ফল ধরবে, তখন তুমি উত্তর জানতে পারবে।」"
  },
  AwakerStory_11334_Title = {
    Text = "গল্প: ৩"
