  AwakerStory_11335_Content = {
    Text = "এলভা কখনো তার ন্যায়বিচারকে সন্দেহ করেনি এমন নয়, কিন্তু সেই বিভ্রান্তিকর দিনরাত্রি তাকে দিয়েছিল এক গভীর উপলব্ধি।\nভ্রমাত্মক বস্তুও বাস্তবে বিদ্যমান।\nপ্রারম্ভিক সূচনাবিন্দু কখনো পরিবর্তিত হয়নি। যে ন্যায়ের জন্য সে লড়াই করেছে, তা কোনো আক্রমণকারীতে পরিণত হওয়া সংগঠন নয়, কোনো স্লোগান-চিৎকারকারী ব্যক্তি নয়, বরং তা দৃঢ়ভাবে তার নিজের বিশ্বাসের মধ্যেই বিরাজমান।\n\nসকল প্রাণ, সকল নিষ্পাপতা, সকল স্বপ্ন, আকাঙ্ক্ষা, সুন্দর কামনা — গোলাগুলির সামনে সবই সহজেই ছাইয়ে পরিণত হতে পারে।\nযুদ্ধে যা হারিয়ে যায়, তা আর কখনো ফিরে আসে না। এটি নরকের দানবের মতো, সমস্ত সুন্দরকে গ্রাস করে।\nতাই, যারা নিজের স্বার্থে যুদ্ধ বাধায়, তাদেরও ধ্বংসের স্বাদ গ্রহণ করতে হবে। প্রকৃত বীরেরা আসবে, মহান আদর্শ বুকে ধারণ করে, নিঃস্বার্থভাবে সকলের উজ্জ্বল ভবিষ্যতের জন্য লড়াই করবে।\nএটাই তথাকথিত ন্যায়বিচারের মূল্য।\n……\n\nভুল হলে, সংশোধন করো।\nসেই সব আত্মত্যাগকে সার্থক করতে হবে, এই কাটা পা আর হারানো অঙ্গের মায়াবী যন্ত্রণাকে সার্থক করতে হবে।\nযদি কিছু দুর্ভাগ্যবশত ধ্বংস হয়ে থাকে, তবে এই নতুন কৃত্রিম অঙ্গ দিয়ে তা ফিরিয়ে আনতে হবে।\nসেই ক্ষুদ্র ও ভঙ্গুর জিনিসগুলো কখনোই তাদের দীপ্তি হারাবে না।\nসবকিছুই সেই প্রকৃত ইউটোপিয়ার জন্য — যেখানে রক্তপাত নেই, অশ্রু নেই।"
  },
  AwakerStory_11335_Title = {
    Text = "গল্প: ৪"
