  AwakerStory_11336_Content = {
    Text = "সতর্ক থাকো, সাইরেনের মোহময় আকর্ষণ তার আপাত শান্ত ও যুক্তিসঙ্গত কথার আড়ালেই ওত পেতে থাকে। তার বিকৃত হেলমেটের নিচে হয়তো ভিন্ন কোনো চেহারা লুকিয়ে আছে—সে সম্পর্কে কখনো কৌতূহল দেখিও না; কখনো ভুলো না সেই মানবাকৃতি দেহ নিয়ে তার দীর্ঘস্থায়ী অসন্তোষকে।\nতার দীপ্তিমান আলো একসময় পতঙ্গদের গলিত উষ্ণতার দিকে টেনে নিয়েছিল। তার দহনশিখা একসময় পথহারা মানুষদের নিজ ধ্বংসের দিকে পথ দেখিয়েছিল। কিন্তু এখন, তার বাতিঘরে কেবল বিভ্রান্তির ক্ষীণ ঝলকানি, দিশেহারা সাগরের ওপর নীরব প্রহরী।"
  },
  AwakerStory_11336_Title = {
    Text = "প্রাথমিক তথ্য"
