  AwakerStory_11337_Content = {
    Text = "বিশ্বজুড়ে ছড়িয়ে পড়া বন্যা সভ্যতার সঞ্চয় ভাসিয়ে নিয়ে গেলেও ইতিহাসের ধুলোও ধুয়ে দিয়েছিল।\nবিপর্যয়ের পর, মানুষ মসুলের প্রাচীন ধ্বংসাবশেষের মধ্যে বিস্মৃত ইতিহাসের কিছু আভাস খুঁজে পেয়েছিল।\n'বৃক্ষ' দুই নদীর সঙ্গমস্থলে দাঁড়িয়ে ছিল, রক্তবর্ণ রস ঝরাচ্ছিল, যা স্রোতের সাথে বয়ে গিয়ে সভ্যতাকে সিঞ্চিত করেছিল।\n'বৃক্ষ' চিরকাল অবিনশ্বর, যুগ যুগ ধরে চিরসবুজ।\nপ্রাচীন ইতিহাসবিদরা শেষ পর্যন্ত সিদ্ধান্তে পৌঁছেছিলেন যে 'বৃক্ষ'-এর কোনো বাস্তব অস্তিত্ব নেই, তিনি প্রাচীন সভ্যতার একটি রূপক, একটি আধ্যাত্মিক প্রতীক।\nকারও দৃষ্টির আড়ালে, বীজ পৃথিবীর প্রতিটি কোণে শিকড় গেড়েছিল।"
  },
  AwakerStory_11337_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_11337_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11338_Content = {
    Text = "「প্রভু, আমাকে চাবুক মারুন।」\nতার শুষ্ক হওয়া উচিত এমন চোখে কামনার আগুন জ্বলছে, গলিত মোমের তেল অশ্রুবিন্দুর মতো গড়িয়ে পড়ছে।\nতৃষ্ণা, যন্ত্রণা, অভিশাপ, কলুষতা — সে যত অপমান চেয়েছিল, সে যত আনন্দ অন্যদের দিয়েছিল, অবশেষে এই মুহূর্তে সবকিছু তার নিজের উপরেই নেমে এল।"
  },
  AwakerStory_11338_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11338_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11339_Content = {
    Text = "সে নক্ষত্রদের মাঝে গায়ক, ঝলমলে তারাধূলি।\nসে সোনার খাঁচায় বন্দী পাখি, পরিত্যক্ত ফোনোগ্রাফ।\nযখন তার জন্মগ্রহ শূন্যতায় ধসে পড়ে, তখন সে জীবনের ক্ষীণ আশাকে বুকে টেনে নেয়, অনধিকারিত মহাশূন্যের গভীরে এক ভবঘুরে হয়ে ওঠে—ঘর খোঁজার তৃষ্ণায় গেয়ে চলা এক চিরন্তন অনুসন্ধানী।\n「দিদি… আমাদের মধ্যে অবাধে চলাফেরা করতে পারি আমি, তবু সবসময় আমাকেই তুমি ভর দিয়ে দাঁড় করিয়েছ।」"
  },
  AwakerStory_11339_Title = {
    Text = "প্রাথমিক তথ্য"
