  AwakerStory_11340_Content = {
    Text = "এই ইচ্ছাশক্তি থেকে প্রক্ষেপিত দেহটি অকালে ঝরে যাওয়া এক কিশোরীর রূপে স্থির হয়ে আছে। জীর্ণ পোশাকের আঁচল, ফ্যাকাশে ত্বক, পূর্বজন্মের ছায়ায় ঢাকা দুই চোখ — নীরবে বলে যাচ্ছে রোগযন্ত্রণা ও দুর্ভোগে জড়ানো কোনো এক অতীতের কথা।"
  },
  AwakerStory_11340_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11340_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11341_Content = {
    Text = "@2 ঘটনার পর, কেকেস আমাদের সাথে সন্ধি করে জাগরণ ব্যবস্থার একজন অনানুষ্ঠানিক সদস্য হয়ে ওঠে। @1 সম্পর্কে তার জ্ঞান ছিল অত্যন্ত সীমিত, তবুও সে তা প্রদর্শন ও ভাগ করে নিতে অত্যন্ত আগ্রহী ছিল।\nসে তুলু, মিরিয়াম, গোলিয়াথ প্রমুখের সামনে বিনয়ী ছিল, কিন্তু অন্যান্য জাতি — বিশেষত মানুষদের — প্রতি বিষণ্ণ ও বিদ্বেষপূর্ণ দৃষ্টি নিক্ষেপ করত। নথিপত্র পড়া গবেষকরা তার এই পক্ষপাত বুঝতে পারতেন, তবে কিছু রগচটা জাগরিত সত্তা তা সহ্য করতে পারত না। এই উত্তেজনাপূর্ণ পরিস্থিতি সাধারণত সিলভিয়াকে এগিয়ে এসে মধ্যস্থতা ও শান্ত করতে হতো, এবং কেকেস ও সিলভিয়ার মধ্যে ধীরে ধীরে একটি বিশ্বাসের সম্পর্ক গড়ে উঠেছিল।\nসিলভিয়ার পরামর্শে, কেকেস আবার 'উচ্চতর জাতির সহনশীলতা' জাগ্রত করে এবং অন্যদের উস্কানি এড়িয়ে নীরব থাকতে শুরু করে।\n'সেই ছেলেটি প্রায়ই তার মানব মায়ের কথা আবেগপূর্ণভাবে স্মরণ করে। বলা হয় মা হলেন সন্তানের বিশ্ব চেনার মাপকাঠি, মূলত মানুষের প্রতি তার শত্রুতা পরবর্তীকালে গড়ে উঠেছে। তাই, শুধু একটু পথনির্দেশনা আর যত্নের অভাব ছিল, এটুকুই।' সিলভিয়া তার মনোবৈজ্ঞানিক পরামর্শ রেকর্ডে লিখেছিলেন।"
  },
  AwakerStory_11341_Title = {
    Text = "গল্প: ২"
