  AwakerStory_11344_Content = {
    Text = "বারো বছর আগের এক ভোরবেলা, লন্ডিনিয়ামের পূর্ব অঞ্চল। দরিদ্রাশ্রমের দরজায় একটি মেয়ে শিশু দেখা গেল, স্কার্ফে পুরোপুরি জড়ানো। সবাই নিজের জীবন নিয়েই ব্যস্ত এমন পূর্ব অঞ্চলে এটা তেমন বিরল ঘটনা ছিল না, কিন্তু কিশোরী সারাকে যা ক্ষুব্ধ করেছিল তা হলো—হাড়কাঁপানো শীতে, নিষ্ঠুর পরিত্যাগকারী শিশুটির নাক-মুখও স্কার্ফের নিচে ঢেকে রেখেছিল। তার ওপর এই শিশুটি কাঁদছিলও না, চিৎকারও করছিল না। যদি না সেই স্বচ্ছ নির্মল চোখ দুটো থাপড়ের পর কয়েকবার পিটপিট করত, সারা প্রায় ভেবেই ফেলেছিল যে সে মারা গেছে।\nসারা যখন ভাবছিল যে সে আরেকটি ভালো বাচ্চার 'দিদি' হতে চলেছে, তখন তৎকালীন প্রধান শিশুটিকে এক লেও ফ্যাংয়ের বিনিময়ে পূর্ব অঞ্চলের বাজারের এক দর্জির কাছে দিয়ে দিলেন।\n'আমরা ওই বাচ্চাকে পোষার সামর্থ্য রাখি না। দর্জির মেয়ে হলে একটু কষ্ট পাবে বটে, কিন্তু অন্তত একটা হাতের কাজ শিখতে পারবে।'\nজন্মের মাত্র দুই মাসের একটা বাচ্চার ক্ষেত্রে, কীসের 'হাতের কাজ'?\nসারা তার খালি পেটের অনুভূতি চেপে রেখে, প্রধানের সিদ্ধান্তের প্রতিবাদ করলো না।"
  },
  AwakerStory_11344_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_11344_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11345_Content = {
    Text = "A.F.2@1 সালে, সিতে আর্ট সেলন প্রদর্শনী।\n「আমি তাকে বাড়ি নিয়ে যাব!」 আক্রমণকারী একদিকে হাতুড়ি দিয়ে ভাস্কর অগুস্তের শেষ কাজ《নামহীন প্রবাল নারী》-তে আঘাত করছিল, অন্যদিকে চিৎকার করছিল। তাকে দ্রুত দর্শকরা থামিয়ে দেয়, এবং সবাই বিস্মিত হয়ে আবিষ্কার করে যে, এই বিভ্রান্ত বৃদ্ধ ব্যক্তিটি আসলে দীর্ঘদিন অবসরে থাকা স্বয়ং অগুস্ত।\nমুহূর্তেই,《নামহীন প্রবাল নারী》 নিয়ে অনুমান ও আলোচনা ঝড়ের মতো এসে পড়ে।\nলোকে বলে, এর মডেল ছিল অগুস্তের অধীনে শান নামের এক শিষ্যা, অগুস্তের সেরা কাজগুলো সবই শানের হাতে তৈরি, তিনি একজন লজ্জাজনক চুরিকারী।\nলোকে বলে, শান সম্ভ্রান্ত পরিবারের মেয়ে, তার বাবা বিখ্যাত লেখক, আর একজন কূটনীতিক ভাই আছে। ভাস্কর্য শেখার জন্য সে পরিবারের সাথে সম্পর্ক ছিন্ন করে একাই প্যারিসে যায়, মৃত্যু পর্যন্ত দারিদ্র্যে জীবন কাটায়।\nলোকে বলে, শান এক অদ্ভুত রোগে আক্রান্ত হয়, তার শরীর থেকে কালো আঠালো তরল বের হতো, প্রতিটি খোদাইয়ের সাথে তার শরীরের একটি অংশ প্রবালে পরিণত হতো,《নামহীন প্রবাল নারী》 আসলে তার প্রবালে রূপান্তরিত রূপ, কোনো ভাস্কর্য নয়।\nলোকে আরও বলে……\nগুরু-শিষ্য, অন্তরঙ্গ বন্ধু, উন্মাদনা। জনতা সরে গেলে, প্রদর্শনী কক্ষে শুধু কথার দ্বারা গড়া প্রবাল নারী রয়ে যায়। সে চাঁদের আলোয় স্নান করে, চোখ পিটপিট করে, অপেক্ষা করে, অপেক্ষা করে——বাড়ি ফেরার সেই মুহূর্তের জন্য।"
  },
  AwakerStory_11345_Title = {
    Text = "গল্প: ৩"
