  AwakerStory_11346_Content = {
    Text = "সেই ভয়ঙ্কর মহামারী আসার সময়, ওয়ান্ডা আদেশ দিল দুর্গের দরজা লোহা দিয়ে ঝালাই করে বন্ধ করে দিতে, এবং সম্পূর্ণ বিচ্ছিন্ন হয়ে আনন্দ-ফুর্তিতে জীবন কাটাতে শুরু করল।\nএখানে ছিল রসিক ভাঁড়, ছিল তাৎক্ষণিক কবিতা আবৃত্তিকারী কবি। ছিল বাদক, ছিল সুস্বাদু খাবার ও মদ।\nসব আনন্দ ও শান্তি ছিল দুর্গের ভেতরে, আর দুর্গের বাইরে ছিল @2-এ ছেয়ে যাওয়া অন্ধকার জগৎ।\nঠিক যখন দেয়ালের বাইরেটা সম্পূর্ণ মৃত্যুপুরীতে পরিণত হল, ওয়ান্ডা তার কয়েকশো অনুসারীর জন্য একটি অসাধারণ বিলাসবহুল মুখোশ নৃত্যের আয়োজন করল।\nএটি ছিল তিন দিন তিন রাত ধরে চলা এক জাঁকজমকপূর্ণ ও উচ্ছৃঙ্খল উৎসব। তৃতীয় দিন মধ্যরাতের ঘণ্টা বাজতেই কিছু অতিথি সম্পূর্ণ পাগল হয়ে গেল, কেউ কেউ কালো আঠালো তরলে পরিণত হল। ওয়ান্ডার মুখ চীনামাটির মতো ফেটে গেল, মুখোশের ফাঁক দিয়ে কালো @2 গড়িয়ে পড়তে লাগল।\nভয় পাওয়া অনুসারীরা ওয়ান্ডার পাশে কাঁপতে কাঁপতে জড়ো হল, কিন্তু সে ছিল শান্ত।\nসে লম্বা চাবুক দুলিয়ে আদেশ দিল @2 যারা সম্পূর্ণ পাগল হয়ে গেছে তাদের, বাকিরা মদ পান ও বাদ্য বাজানো চালিয়ে যাবে, থামা যাবে না।\nঅদ্ভুত ও বর্ণময় সেই নৃত্যানুষ্ঠান চতুর্থ দিন ভোরে শেষ হল, জাঁকজমকপূর্ণ হলঘর ভরে গিয়েছিল কালো @2 তরল ও লাল তাজা রক্তে।\nকেউ জানল না এখানে কী ঘটেছিল।"
  },
  AwakerStory_11346_Title = {
