  AwakerStory_11347_UnlockDesc_1 = {
    Text = "চ্যাপ্টার 1 「পূর্ব জেলার ধাঁধা」 সম্পন্ন করো: নরমাল"
  },
  AwakerStory_11348_Content = {
    Text = "মরিচার গন্ধ বাতাসে ছড়িয়ে পড়ল।\nসেটা ছিল……「খাবারের」গন্ধ।\nমেয়েটি ধীরে ধীরে চোখ খুলল। দীর্ঘদিন ধরে উচ্চ মাত্রায় প্রশমক ইনজেকশন দেওয়ার ফলে তার মস্তিষ্ক ঘোলাটে হয়ে গিয়েছিল। তার সামনে গলা কামড়ে ছিঁড়ে ফেলা একটি বিগল কুকুর পড়ে ছিল, নামটা যেন ছিল……ব্যাম্বি? ববি?\nমেয়েটি সবেমাত্র স্মৃতিতে ডুবে গিয়েছিল, তখনই পেটে তীব্র যন্ত্রণা ছড়িয়ে পড়ল——সে「খাবারের」আক্রমণের শিকার হয়েছে। এই মুহূর্তে, ধরে আনা ভবঘুরেটি কাঁপতে কাঁপতে হাত তুলে চিৎকার করছিল।\n「ভ্যাম্পায়ার! দানব……দানব!!」\nকিন্তু মেয়েটি কিছুই শুনতে পেল না, শুধু অন্যমনস্কভাবে পেটের তাজা রক্ত স্পর্শ করতে লাগল।\nপ্রচুর উষ্ণ তাজা রক্ত, পিচ্ছিল রেশমের মতো, আনন্দের সাথে ক্ষতস্থান থেকে উপচে পড়ে চারদিকে ছড়িয়ে যাচ্ছিল।\nতাহলে, সে এখনও ব্যথা অনুভব করতে পারে, এখনও তার রক্ত ঝরে।\nমেয়েটি নীরবে অশ্রু ফেলল। সে রক্তমাখা দুর্বল হাত দুটো বাড়িয়ে「শিকারের」গালে আলতো করে ছোঁয়াল।\n「এরপর, আরেকটু জোরে করতে পারবে কি?」"
  },
  AwakerStory_11348_Title = {
    Text = "গল্প: ৪"
