  AwakerStory_11348_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11349_Content = {
    Text = "হাজার হাজার শিশুর মধ্য থেকে নির্বাচিত হয়ে সিংহাসনে বসানো হলে, তুরু তখনও সেই ল্যাপিস লাজুলি সিংহাসনের চেয়ে খাটো ছিল।\nকিন্তু তার উদাসীনতা আর দীর্ঘ নিদ্রা নিয়ে কেউ মুখ খুলতে সাহস করত না——সকলেই জানত, এটাই প্রমাণ যে রাজা দেবতার বাণী শুনছেন।\nজ্ঞানী বালক-রাজার প্রতিটি সিদ্ধান্ত অবশ্যই সমস্যার সমাধান করত; তাঁর প্রতিটি ভবিষ্যদ্বাণী অবশ্যই সত্য হতো।\nতুরুও এই জীবন মেনে নিয়েছিল: 「দেবতার」 স্বপ্নে প্রবেশ করা, সেই অবোধ্য সত্তার সাথে সাক্ষাৎ করা, দেববাণী দিয়ে রাজ্য পরিচালনা করা, আবার গভীর নিদ্রায় তলিয়ে যাওয়া...\nএই সভ্যতার চলন দেবতার ইচ্ছা দ্বারা নির্ধারিত ছিল। স্রোতের সাথে বয়ে যাওয়া, নিয়তি অনুসারে কাজ করা——নিজেকে শুধু এই অদ্বিতীয় 「বার্তাবাহক」 হিসেবে ভূমিকা পালন করলেই যথেষ্ট।\nতবে, তুরুর একটিমাত্র ভবিষ্যদ্বাণী ছিল যা সে কখনো মুখে আনতে পারেনি: রাষ্ট্র বন্যায় ধ্বংস হবে, সভ্যতা শেষ পর্যন্ত সমুদ্রের তলদেশে সমাধিস্থ হবে।\nসবকিছু জানার কারণেই সে আরও ভালো করে জানত যে ধ্বংস অপরিবর্তনীয়——কিন্তু অন্তত শেষ সময়টুকুতে, তাদের ভয় আর দ্বিধার মধ্যে বাঁচতে দিও না।\nএটাই ছিল তার রাজা হিসেবে, 「দেবতার প্রতিনিধি」 হিসেবে নয়, নেওয়া সিদ্ধান্ত।"
  },
  AwakerStory_11349_Title = {
    Text = "গল্প: ৩"
