  AwakerStory_11349_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11350_Content = {
    Text = "জাগ্রত হওয়ার পর থেকে, ডেলিরিয়াম মার্ফি প্রায়ই পালিয়ে যাওয়ার একটি স্বপ্ন দেখতেন। সেই স্বপ্নের শেষে, তিনি 「মায়ের」 ছুরি হাতে, উজ্জ্বল চাঁদের আলোয় নিজের বুক ভেদ করতেন। তারপর স্বপ্ন হঠাৎ থেমে যেত, এবং চোখ খোলার মুহূর্তে ঠিক বিছানার পাশে রাখা সেই হাতির দাঁতের মূর্তিটির সাথে দৃষ্টি মিলে যেত।\n\nমিসাগে ডেলিরিয়াম মার্ফির আচরণ ছিল তার 「পালক মায়ের」 তরুণ সংস্করণের মতো। তিনি সারাদিন শোকের সাদা পোশাক পরে থাকতেন, সহজে কারো সাথে হাসি-ঠাট্টায় মিশতেন না। কেবল কথাপ্রসঙ্গে মিষ্টি খাবারের পছন্দের বিষয়টি উঠলে, সেই নিখুঁত মাদোনার মুখোশে একটি ফাটল দেখা দিত।\n(আর্কাইভিস্টের মন্তব্য: আশা করি পরের বার যখন তিনি ছোট কেক চেখে দেখতে চাইবেন, তখনই বলবেন, সবার বিকেলের চা-পর্ব শেষ হওয়ার পর একটি চিরকুট রেখে তার ঘরে পাঠানোর দাবি না করে।)\n\nতিনি সমুদ্রে-পা-দেওয়া যেকোনো জাগ্রত সত্তার সাথে দূরত্ব বজায় রাখতে অভ্যস্ত ছিলেন। অন্য জগতের নিজের থেকে আলাদা হলো এই যে, তিনি ইচ্ছাকৃতভাবে সংশ্লিষ্টদের সাথে যোগাযোগ এড়াতেন না, কিন্তু মুখে জমে থাকা শীতল অভিব্যক্তি ও অন্তর্নিহিত বৈরিতাপূর্ণ বিদ্রূপ, অজান্তেই সেই সব লোকদের দূরে সরিয়ে দিত যারা কঠিন পেরেক ঠোকার ঝামেলায় পড়তে চাইত না।"
  },
  AwakerStory_11350_Title = {
    Text = "গল্প: ২"
  },
  AwakerStory_11350_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11351_Content = {
    Text = "পঁচিশ বছর বয়সে, লেক একটি বদ্ধ ঘরে হত্যা মামলার তদন্ত করতে গিয়ে একজন অদ্ভুত সন্দেহভাজনের মুখোমুখি হয়।\nসম্পূর্ণ প্রমাণ শৃঙ্খল হাতে থাকার পর, থানায় হাতকড়া পরা সন্দেহভাজন রহস্যজনকভাবে অদৃশ্য হয়ে যায়, কিন্তু হাতকড়া অক্ষত থাকে। অবশ্য, এটা ডিউটিতে থাকা পুলিশের দায়িত্ব, লেক ঠিকই তার পারিশ্রমিক পেয়ে যায়।\nলেক সেই পারিশ্রমিক নিয়ে সমুদ্র পাড়ি দিয়ে বিদেশে ছুটি কাটাতে যায়, তারপর একটি রাস্তার পসরায় পলাতক সন্দেহভাজনের দেখা পায়। সন্দেহভাজন জুয়ার আসর বসিয়েছিল, লেককে দেখেও তাড়াহুড়ো করেনি, শুধু তাকে জুয়ায় যোগ দিতে আমন্ত্রণ জানায় এবং প্রতিশ্রুতি দেয় যে লেক জিতলে সে স্বেচ্ছায় ধরা দেবে।\n\nলেক একটিও জেতেনি।\n\nসে তার পাইপ হারায়, তার টাই হারায়, তার টুপি হারায়, তার ওভারকোট হারায়।\nসে যখন সম্পূর্ণ উলঙ্গ, সন্দেহভাজন সব পোশাক ফিরিয়ে দেয় এবং বলে এই বাজি খুব ছোট। লেক দ্বিধাহীনভাবে জিজ্ঞেস করে সন্দেহভাজন কী বাজি ধরতে চায়, এবং প্রতিপক্ষ একটি হাত বাজি রাখার প্রস্তাব দিলে সানন্দে রাজি হয়।\n\nবাজি বাড়ানোর পর, প্রতিপক্ষ একটি রিভলভার বের করে। জীবন-মৃত্যুর রুলেট জুয়ার মুখোমুখি হয়ে, লেক দ্বিধাহীনভাবে পিস্তল তুলে নিজের কানপটিতে তাক করে।\nএকটি গুলির শব্দের পর, লেক পড়ে যায়। সন্দেহভাজন তার মৃত আত্মাকে ফিরিয়ে আনে, তার অজ্ঞতা নিয়ে উপহাস করতে চায়। কিন্তু, লেকের প্রথম কথা হলো: 「এরপর কী বাজি?」\n\nতার দুঃসাহস অবশেষে দানবের আগ্রহ জাগায়। 「N@2@3」 নামের সন্দেহভাজন এই জুয়া চালিয়ে যাওয়ার সিদ্ধান্ত নেয়।\n\n「N」 তিনটি টুপি বের করে, তাকে এর মধ্যে 「সেরা পছন্দ」 করতে বলে যা তার দেহ ফিরিয়ে দেবে।\nলেক একটি টুপি বেছে নেয়, 「N」 একটি খালি টুপি খোলে এবং জিজ্ঞেস করে সে তার পছন্দ বদলাতে চায় কিনা। লেক মাথা নাড়ে।\n\n–তুমি সম্ভাব্যতা বোঝো না?\n–আমি শুধু নিজের ভাগ্যে বিশ্বাস করি।\n\n「N」 তৃতীয় টুপি খোলে, সেটিও খালি। অবশেষে, সে লেকের টুপি খোলে, ভেতরে একটি অদ্ভুত কালো কুয়াশা। কালো কুয়াশা লেকের দিকে ধেয়ে আসে, অদ্ভুত পশুর অঙ্গে রূপান্তরিত হয়। 「N」 তার অবতারের দেহ দিয়ে লেকের ইতিমধ্যে বাজি রাখা শরীর প্রতিস্থাপন করে।\n\n–পশুর মতো ঘ্রাণশক্তির অধিকারী মানুষ, এই অবতারের সাথে কি যথাযথ নয়? তাই, এটাই 「সেরা পছন্দ」!"
  },
  AwakerStory_11351_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_11351_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11352_Content = {
    Text = "এটি প্রতিশ্রুত ভূমি, এটি শিল্পের আদর্শ স্বর্গ, এটি পরম আনন্দের স্থান——নৃত্যই হওয়া উচিত নর্তকদের চূড়ান্ত আশ্রয়, চিরন্তন পবিত্রতায় অটুট থাকা উচিত।\nযতক্ষণ আমি জ্বলছি, ততক্ষণ সেই কলুষ আমাদের পবিত্র মন্দিরকে কলঙ্কিত করতে পারবে না……এটাই আমার দায়িত্ব, আমার আশা……আমাকে দাউ দাউ করে জ্বলতে দাও, আমি সবার জন্য সেই সমস্ত কলুষতা পুড়িয়ে ছাই করে দেব।"
  },
  AwakerStory_11352_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11352_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11353_Content = {
    Text = "শশশ…… আতঙ্কিত হওয়ার দরকার নেই, ওটা শুধু স্যাঁতসেঁতে তহখানায় ইঁদুর পচে যাওয়ার শব্দ। সবচেয়ে অন্ধকার অতল গহ্বরের তলদেশ থেকে জন্ম নেয় রক্তলাল কামনা। বন্দি আত্মা রক্তের জন্য তৃষ্ণার্ত, যেমন অন্ধ আলোর জন্য প্রার্থনা করে, যেমন লম্পট কামভোগে নিমগ্ন হয়। তাকে তুষ্ট করার উপায়ও খুব সহজ: মনের সুখে তাকে তিরস্কার করো, অপমান করো।"
  },
  AwakerStory_11353_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11353_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11354_Content = {
    Text = "এ পর্যন্ত, প্রাচীনতম পরিচিত মানব সভ্যতার উৎস মেসোপটেমিয়াতেই বলে বিশ্বাস করা হতো, এবং এই ধারণাকে সমর্থন করত বিপুল পরিমাণ দৃঢ় প্রত্নতাত্ত্বিক প্রমাণ।\nতবু, মানবজাতি কখনোই পরিচিত সীমারেখায় সন্তুষ্ট নয়। অসীমতার বিস্তৃত, কালো সাগরের মুখোমুখি দাঁড়িয়ে আমরা অজানার দিকে পাল তুলতে একটুও দ্বিধা করি না।\nহয়তো এ প্রথম নয়, যে আমাদের এমন সতর্কবার্তা বা ইঙ্গিত দান করা হয়েছে। একদা তত্ত্ববিদেরা এক শীতল হাইপোথিসিস পেশ করেছিলেন: মহাবিশ্ব এক ভয়াল, বিস্ময়কর চক্র, আর আমাদের বর্তমান পৃথিবী—এবং মানবতা নিজেই—সে চক্রের ক্ষণস্থায়ী এক কড়ি মাত্র।\nঅসংখ্য সত্তা এই সব চক্রের ভেতর নিঃশব্দে বিলীন হয়ে গেছে, পেছনে রেখে যায়নি কোনো প্রমাণের কণামাত্র। আসলে, এ এক প্রকার দয়া; কিছু শক্তি এতটাই প্রাচীন ও চূড়ান্ত যে, তাদের কেবল অবশিষ্ট ছায়াটুকুও আমাদের যুগের ওপর অগণন, বিধ্বংসী প্রভাব বিস্তার করতে পারে।\nউদাহরণস্বরূপ, দক্ষিণ মহাসাগরের তলদেশে প্রহরা জাহাজের নাবিকদের করা সেই আকস্মিক আবিষ্কারটিকেই ধরা যাক। তা আমাদের প্রাগৈতিহাসিক সভ্যতা সম্পর্কে ধারণাকে এক লাফে কয়েক দশ হাজার বছর পেছনে ঠেলে দিয়েছে।\nএ থেকে আমরা জানতে পেরেছি এক সভ্যতার কথা—নিজস্ব রাষ্ট্র, সম্রাট, আর অদ্ভুত এক বিশ্বাসব্যবস্থাসহ—যাকে এক বিশ্বব্যাপী প্লাবন গ্রাস করেছিল, আর যা বহু যুগ ধরে তরঙ্গের নিচে তন্দ্রাচ্ছন্ন হয়ে শুয়ে আছে।\nমিস্টিয়া চুক্তি পর্যালোচনা কমিটির সহায়তায় যদি সেই আবিষ্কারকে নিয়ন্ত্রণ ও গোপন রাখা না হতো, তবে মানব ইতিহাস হয়তো আজ অন্যরকম হতো। কিন্তু বর্তমান পৃথিবী এখনো এমন এক মহাবিপর্যয়কর প্রত্যাদেশের জন্য প্রস্তুত নয়।"
  },
