  AwakerStory_11355_Content = {
    Text = "কাসিয়া হাত ঢোকাল টুপির ভেতরে, সেখানে কিছুই নেই।\nকাসিয়া হাত ঢোকাল দরজার ওপারে, সেখানে কিছুই নেই।\nকাসিয়া হাত ঢোকাল নিজের বুকের ভেতরে, সেখানে কিছুই নেই।\nসংগ্রহ করা সুখ-দুঃখ, আনন্দ-ক্রোধ, ভয়-বিরক্তি, মানুষের উষ্ণতা ও শীতলতা, শুরুর আগের কোলাহল, মোড় ঘোরার সময়ের উল্লাস, চমৎকার মুহূর্তের শিস, সমাপ্তির করতালি, শেষে দর্শক চলে যাওয়ার নির্জনতা — সবকিছু এই শূন্য বুকের ভেতর দিয়ে গলে পড়ে গেছে, একটুও চিহ্ন রেখে যায়নি যে কখনো ছিল।\nকাসিয়া আয়নার সামনে দাঁড়িয়ে দর্শকদের অভিব্যক্তি নকল করতে লাগল — চোখের কোণের ভাঁজ, পেশীর গতিপথ, ঠোঁটের কোণের বক্ররেখা — সবকিছু হুবহু তাদের মতোই, কিন্তু এর মধ্যে কোনো প্রকৃত অনুভূতি নেই।\nযদি অনুভব করতে পারতাম... যদি শুধু নকলের ঊর্ধ্বে উঠতে পারতাম... যদি তাদের একজন হতে পারতাম... অথবা, যদি কেউ একজন থেকে যেত...\nতাহলে নিশ্চয়ই এই বুকের ভেতরের 'শূন্যতা' পূরণ হয়ে যেত।"
  },
  AwakerStory_11355_Title = {
