  AwakerStory_11356_Content = {
    Text = "ভ্রমণ তথ্য: কৌতূহলোদ্দীপক ইতিহাস অনুসন্ধান – বিলাসবহুল 7 দিনের ক্যামব্রিয়ান দুর্গ ট্যুর\nতারিখ: A. F. 3@2 18–25 জুন\nগাইড: থমাস @2@1\nসংক্ষিপ্ত ভ্রমণসূচি:\nএসো, 300 বছর আগের সবচেয়ে কুখ্যাত ভৌতিক দুর্গ— ক্যামব্রিয়ান দুর্গের রহস্য উন্মোচন করো!\nপুরোনো বই আর নির্বাক চলচ্চিত্রে সেই মোহময়ী নারী আর তার পঁচিশ সঙ্গিনীর গল্প পড়তে পড়তে আমরা ক্লান্ত; সবই একই— ভীষণ একঘেয়ে!\nএকজন নাম প্রকাশে অনিচ্ছুক মিথাগ বিশেষজ্ঞের মতে, এলাকায় নতুন এক আবিষ্কার হয়েছে! কণ্টকে আচ্ছাদিত @2@1...\nতাড়াতাড়ি ফোন করো @2@1@1। এই ভ্রমণ হবে ভোলার নয়, শীতল স্রোত নিশ্চিত!\n— 「ওরস্টার ট্যুর গ্রুপ নিখোঁজ মামলা সংক্ষিপ্ত নথি: প্রমাণ S-145」 থেকে উদ্ধৃত"
  },
  AwakerStory_11356_Title = {
    Text = "গল্প: ১"
