  AwakerStory_11356_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11357_Content = {
    Text = "ক্ষয়-গবেষণার সর্বাগ্রে থাকা একজন মানুষ হিসেবে, ডোর সবসময় স্পষ্টভাবে জানতেন যে তাঁর পেছনে ধ্বংসের পদধ্বনি ক্রমাগত তাড়া করে আসছে, তদুপরি, ক্ষয়ের শিকার হওয়ার বিষয়টি তাঁর কাছে অনেক আগেই অতি পরিচিত হয়ে উঠেছিল। \nসত্যের সন্ধানে বারবার এগিয়ে যাওয়া আর বারবার ব্যর্থ হওয়ার মধ্য দিয়ে, ডোর ধীরে ধীরে উপলব্ধি করলেন যে বর্তমান মানবদেহ হয়তো সহজাতভাবেই অন্ধ — বাস্তবের জগতে বাস করা মানুষ যতই চেষ্টা করুক, অপর পারের দৃশ্য কখনো দেখতে পায় না। \nতাহলে কি সেই কালো আঠালো তরল শরীরকে বিলীন করার সাথে সাথে আত্মাকেও সত্যের অপর পারে নিয়ে যায়? \nতিনি সেই প্রাচীন প্রস্তরফলকের বাণীগুলোর সামনে নীরবে বসে রইলেন, ক্ষয়কে তাঁর মস্তিষ্ক-পাত্র গ্রাস করতে দিলেন। সেই পথের শেষে যাই থাকুক, তিনি আর ফিরে আসতে পারবেন না। \nসৌভাগ্য আর দুর্ভাগ্য একসাথে — নিজের অস্তিত্বকে বাজি রেখে, অবশেষে তিনি বিশ্বের অন্তঃস্তরে প্রবেশের সুযোগ পেলেন, আর সেই মুহূর্তে সত্য, শূন্যতা ও ধ্বংস একযোগে তাঁকে গ্রাস করল। \nএক পলকের মধ্যে, তিনি মহাবিশ্বের সবকিছু প্রত্যক্ষ করলেন — ক্ষয়ের সারসত্তা, বিশ্বের প্রকৃত রূপ, সারাজীবন যা তিনি আকাঙ্ক্ষা করেছিলেন তার সবকিছুই সেখানে বিদ্যমান। \nবিজ্ঞানের প্রতি সকল বিশ্বাস আর যুক্তির প্রতি সকল অবিচলতা বুদবুদের মতো মিলিয়ে গেল, লোহার মতো দৃঢ় মানসিক প্রাচীর হঠাৎ ভেঙে পড়ল। \nডোর নামের সেই প্রতিভা আর নেই, এখন এখানে যে দাঁড়িয়ে আছে, সে কেবল শূন্যতায় অধিকৃত এক জীবন্ত খোলস মাত্র।"
  },
  AwakerStory_11357_Title = {
    Text = "গল্প: ৩"
