  AwakerStory_11357_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11358_Content = {
    Text = "「A.F.3@2 সালে, মিসকাটনিক বিশ্ববিদ্যালয়ের সামুদ্রিক বাস্তুতন্ত্র দল দক্ষিণ সমুদ্রে প্রজাতি পর্যবেক্ষণ করার সময়, একটি অদ্ভুত আকৃতির প্রবাল প্রাচীর আবিষ্কার করে……」\n「এই নমুনাটির বৈশিষ্ট্য অনন্য, পৃথিবীর কোনো পরিচিত মৌলের সাথে মেলে না। পানিতে নরম, কিন্তু স্থলে এলেই দ্রুত শুকিয়ে শক্ত হয়ে যায়। জীববিজ্ঞান ও জ্যোতির্বিজ্ঞান বিভাগের যৌথ গবেষণা অনুযায়ী, এটি সম্ভবত কোনো অজানা বহির্জাগতিক পদার্থ……」\n\n「A.F.3@1 সালে, জাগরণ কোডনেম সাঙ্গা।\nএই জাগ্রত সত্তা জেগে ওঠার পর থেকেই খোদাই করার আচরণ বজায় রেখেছে। সেই রহস্যময় বক্ররেখা ও রেখার জন্য বিখ্যাত শিল্পশৈলী কোনো ধারায় শ্রেণিবদ্ধ করা কঠিন। দর্শকদের মানসিক আঘাত দেওয়া ছাড়া, ক্ষয়ীভবন গবেষণায় প্রায় কোনো সাহায্য হয়নি।」"
  },
  AwakerStory_11358_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_11358_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11359_Content = {
    Text = "শিরশ্ছেদ আঘাতের মৃত্যুর শীতল তোষামোদকারীর আলিঙ্গন অতিক্রম করে, সে বেঁচে থাকে এবং রূপান্তরিত হয়। তার তরবারির ঝিলিক ম্লান হয়ে যায়। অ্যাপোস্টলের মুখোশ তার বর্বর অভিব্যক্তি আড়াল করে।\nসে সত্যিই স্বতঃস্ফূর্ত ভক্তি অনুভব করেছিল, যখন সেই অলৌকিক ঘটনা প্রকাশ পেয়েছিল। কিন্তু কোনো ঈশ্বর তার ভয়কে বন্দি করতে পারেনি, কোনো সম্প্রদায় তার বিশ্বাস অর্জন করতে পারেনি।\nএক দৈত্য অন্যের কাছে নত হওয়ার জন্য জন্মায় না। এক যোদ্ধা মাথা নিচু করার জন্য জন্মায় না।\nতার অতীত ইতিমধ্যেই ধুলোর মালা গলায় পরে আছে, তার যুদ্ধ এখনো চূড়ান্ত বিজয়ের জন্য আকুল। জয়ের বাসনা তার শিরায় শিরায় ছুটে বেড়ায়, অস্থিতে অস্থিতে খোদাই হয়ে থাকে, যেন দানকৃত শক্তির সীলমোহর। হয়তো, একদিন মৃত্যু তার আধিপত্যের অবসান ঘটাবে। হয়তো, একদিন সে নিজেই একক সর্বোচ্চতায় আরোহন করবে।"
  },
