  AwakerStory_11360_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11361_Content = {
    Text = "হান্না: আইলভা, আপনি মিসাগের বিশ্ববিদ্যালয়ে যোগ দিয়েছেন বেশ কিছুদিন হলো। আপনি শিক্ষার্থীদের মধ্যে অত্যন্ত জনপ্রিয়, অনেক মেয়ে আমার কাছে একগাদা প্রেমপত্র পাঠিয়েছে, আপনাকে পড়ে শোনাব?\nআইলভা: এটা সত্যিই… কাশি, আমি বলতে চাইছি, সবাইকে ধন্যবাদ? কিন্তু আমি কি, উম, আমার একটি দিন শেয়ার করতে আসিনি?\nহান্না: প্রশিক্ষণ কর্মকর্তার এমন মিষ্টি দিকও আছে ভাবতে পারিনি, মনে হচ্ছে সাক্ষাৎকার প্রকাশের পর আমাকে ক্যাম্পাসের বাইরে লুকাতে হবে, ঈর্ষান্বিত মেয়েদের ঘেরাও থেকে বাঁচতে! তাহলে মূল বিষয়ে ফিরে আসি, আপনি কি আমাদের পাঠকদের সাথে অসীম আকর্ষণীয় প্রশিক্ষণ কর্মকর্তার একটি দিন শেয়ার করবেন?\nআইলভা: আমাকে আপনাদের হতাশ করতে হবে বোধহয়, আমার দিন খুবই সাধারণ। প্রতিদিন সকাল 4টায় আমি উঠে ব্যায়াম করি, এই পাটিকে চলাফেরার অবস্থায় অভ্যস্ত করতে।\n6টায় আমি ক্যান্টিনে যাই, যদিও জাগ্রত সত্তার দেহে খাওয়ার প্রয়োজন নেই, তবুও আমি… এটাকে একটা অভ্যাস বলুন।\nসকাল 8 থেকে 12টা পর্যন্ত, আমি তদন্তকারীদের যুদ্ধ কৌশল নির্দেশনা দিই, মাঝে মাঝে গোপনরক্ষকদের অতিরিক্ত প্রশিক্ষণ দিই। বিকেলের প্রশিক্ষণের সময় পাঠ্যক্রম অনুযায়ী পরিবর্তিত হয়, কখনো 1টায় শুরু, কখনো 3টায়।\nপ্রতি সপ্তাহে আমি নোটিরার কাছে যাওয়ার সময় বের করি, আমার কৃত্রিম অঙ্গ সমন্বয় করাতে। যদিও সে জিনিস ভুলে যায়, কিন্তু কাজ ভালো করে, প্রতিবার তার মেরামতের পর আমার ব্যথা অনেক কমে।\nহান্না: তাহলে আপনি বিনোদনের জন্য কী করেন?\nআইলভা: বিনোদন… এটা আসলে আমার কাছে এখনও বেশ অপরিচিত ধারণা। তবে সম্প্রতি আমি ওরেটা তাদের সাথে সমুদ্রতীরে জলকেলি করতে গেছি, এই সরল বাচ্চাদের সাথে থাকলে সবসময় খুব স্বস্তি লাগে। তাছাড়া সাঁতার শরীরের শক্তি বাড়াতেও সাহায্য করে, আমি যখন নতুন সৈনিক ছিলাম, আমার প্রশিক্ষক——\nহান্না: ঠিক আছে তাহলে আজকের কলাম এখানেই শেষ! আইলভার অতীত জানতে চাইলে, পরবর্তী সংখ্যার 《মিসাগের দৈনন্দিন শেয়ার》 অনুসরণ করুন!\n——《মিসাগের দৈনিক》 বিশেষ সাক্ষাৎকার কলাম, 《মিসাগের দৈনন্দিন শেয়ার》 থেকে উদ্ধৃত"
  },
