  AwakerStory_11363_Content = {
    Text = "ড্যাফোডিল অত্যন্ত উচ্চ মূল্যে নিজেকে মিসাগার্ড বিশ্ববিদ্যালয়ের সিলভার কোর গবেষণাগারের কাছে বিক্রি করেছিল।\nতার আগে, গবেষণাগারের প্রধান ডোর ইতিমধ্যেই একাধিকবার শুধুমাত্র ড্যাফোডিলের পক্ষ থেকে শুরু হওয়া একমুখী যোগাযোগ নিয়ে তীব্র অসন্তোষ প্রকাশ করেছিলেন।\nকিন্তু শুধুমাত্র ড্যাফোডিল এবং মিসাগার্ড বিশ্ববিদ্যালয়ের এক প্রয়াত উচ্চপদস্থ কর্মকর্তাই জানতেন যে, এই ধরনের 'একমুখী যোগাযোগ' কতটা বিপজ্জনক লেনদেনের মাধ্যমে প্রতিষ্ঠিত হয়েছিল।"
  },
  AwakerStory_11363_Title = {
    Text = "গল্প: ১"
