  AwakerStory_11363_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11364_Content = {
    Text = "অহংকারী, খামখেয়ালি, আত্মকেন্দ্রিক……যারা তার সংস্পর্শে এসেছে, তাদের অনেকেই তার ব্যক্তিত্ব সম্পর্কে এমন মূল্যায়ন দিয়েছে। আগে যে পরিবেশে সে বাস করত, সেখানে মনে হয় সবসময় তাকে তারকার মতো যত্ন-আত্তি করা হতো, সম্ভবত সেই অতিরিক্ত আদরযত্নই তার এই উদ্ধত স্বভাব গড়ে তুলেছে।\n「এই! কী দেখছ? আগেই বলেছি না, তিনবার ডাকার মধ্যেই এই মহিলাকে সাড়া দিতে হবে!」\n——নথিপত্র পড়ার সময়ও খুব সাবধান থাকতে হবে।"
  },
