  AwakerStory_11366_Content = {
    Text = "তার ঘরে ফেরা, নিজের উৎসের দিকে ফিরে যাওয়া, হারিয়ে যাওয়া স্বপ্নের সঙ্গে পুনর্মিলন—তার ইচ্ছা মানুষের কথায় কীভাবে প্রতিফলিত হয়, সে বিষয়ে তার বিন্দুমাত্র পরোয়া নেই। তার দেহ জেগে‑ওঠাদের রূপে বদলে গেলেও, শ্বেত পাখির দেশের জোয়ার এখনো তার আত্মায় গর্জন তোলে।\nসমুদ্রতলের আগ্নেয়গিরির নিঃশ্বাস তার কানের ভেতর থেকে মিলিয়ে গেছে। উন্মত্ত উল্লাসে মোচড়ানো সাগরের স্বপ্ন তার চোখ থেকে আড়াল হয়ে গেছে। কেবল দেবলোকের প্রতি তার আবেশই এখনো ঝলমল করছে, আগের যেকোনো সময়ের চেয়ে অধিক জ্যোতির্ময়।\nতার নম্রতাকে লক্ষ্য করো—এ কেবল সাময়িক এক ছদ্মবেশ। তার রাজার সিংহাসন তাকে ডাকে, যেন এক বাতিঘর যুগের পর যুগ ভেদ করে হাত বাড়িয়ে আছে; তার উৎসর্গ সর্বদাই হবে সর্বস্ব, যেমন সলতের ভক্তি আলোকে।"
  },
  AwakerStory_11366_Title = {
    Text = "গল্প: ৪"
