  AwakerStory_11367_Content = {
    Text = "ডোর মিসাগের বিশ্ববিদ্যালয়, এমনকি সমগ্র শিক্ষাজগতের জন্যই অপরিহার্য একজন ব্যক্তি।\nবিশ্ববিদ্যালয়ের পরিচালনাধীন জাগ্রত সত্তাদের মধ্যে, ডোর সবচেয়ে স্থিতিশীল নোস সূচকের অধিকারী নয়, সবচেয়ে শক্তিশালী যুদ্ধ ক্ষমতারও নয়, কিন্তু সে অবশ্যই সবচেয়ে শান্ত ও যুক্তিবাদী।\nকিছু প্রাক্তন মানব জাগ্রত সত্তার জন্য, 「মৃত্যু থেকে পুনরুত্থান「 এর প্রাথমিক পর্যায়ে সাধারণত বিভ্রান্তি, আতঙ্ক ও উত্তেজনার মতো আবেগ থাকে। তবে, ডোর এই 「যন্ত্রণাকাল「 দ্বারা প্রভাবিত হয়নি বলে মনে হয়।\nজাগ্রত হওয়ার পরের দিনই, সে আবার গবেষণাগারে ফিরে যায় এবং এক বছরের মধ্যে বহির্জাগতিক জ্ঞান ও মানবীয় প্রজ্ঞার সমন্বয়ে একটি প্রযুক্তি নির্দেশিকা সংকলন করে।\nবর্তমানে ডোর, অর্ধেক সময় 「সিলভার কোর প্রযুক্তি「 উদ্ভাবনে এবং অর্ধেক সময় 「বোকা শিক্ষার্থীদের জগাখিচুড়ি সামলাতে「 ব্যয় করে।\n——উল্লেখ্য, উচ্চমাত্রিক সত্তার প্রভাবে, ডোর সেই 《প্রযুক্তি নির্দেশিকা》 লেখার সময় একটি অজানা ভাষা ব্যবহার করেছিল, অনুবাদ কাজ ডোরের অবসর সময়ে সুশৃঙ্খলভাবে চলছে।"
  },
  AwakerStory_11367_Title = {
    Text = "গল্প: ১"
