  AwakerStory_11367_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11368_Content = {
    Text = "「ঈশ্বরের কন্যা, একই সাথে ঈশ্বরের জন্মদাত্রী।」\nএটাই ছিল তার কর্তৃত্ব প্রতিষ্ঠার উপায়, কেবল সকলের দৃষ্টির কেন্দ্রবিন্দুতে থাকা সেই সম্মান বজায় রেখেই সে টিকিয়ে রাখতে পারে এই টলটলায়মান ভারসাম্য। ভণ্ডামি হলেই বা কী? মিথ্যা হলেই বা কী? কে না বাঁচে 「বর্তমান」 মুহূর্তে?\nমার্ফি কোলে ধরে আছে সেই কাপড়ে জড়ানো কুৎসিত পবিত্র ভ্রূণকে, ঈশ্বরের ইচ্ছা পালন করতে গিয়ে উচ্চারণ করে একের পর এক মিথ্যা।\n「তিনি অবতীর্ণ হয়েছেন।」\n「দেবরাজ্য অবশ্যই উত্থিত হবে।」\n「দয়া করে শান্তভাবে অপেক্ষা করুন পরবর্তী নক্ষত্র সুস্থিতির মুহূর্তের জন্য।」\nঅন্য ভণ্ডদের মনগড়া মায়াজাল তৈরি করতে দেওয়ার চেয়ে, বরং নিজ হাতে এই খাঁচাটাকে নিজের পছন্দমতো সাজিয়ে তোলাই ভালো। যতক্ষণ তার কাঙ্ক্ষিত 「মা」, 「সঙ্গী」, 「সেবক」 সবাই তার পাশে আছে, ততক্ষণ মুখোশ পরা বশ্যতাই হোক আর মুখে এক মনে আর ছলনাপূর্ণ রহস্যময়তাই হোক, সে সবকিছু সানন্দে গ্রহণ করে, এমনকি তৃপ্তির সাথে উপভোগ করে।\n「আমার নাম মার্ফি, আমি সেই রাজকন্যা যে দেবতার জন্ম দিয়েছে। লেমুরিয়া সম্পর্কে, সমুদ্রে পদচারীদের চিরকালীন আকাঙ্ক্ষা সম্পর্কে... তোমার খোঁজ করার দরকার নেই, আমার নিজের পরিকল্পনা আছে।」"
  },
