  AwakerStory_11369_Content = {
    Text = "A.F.3@2 সালের 2 এপ্রিল, আশদোদ অঞ্চলের একটি মন্দিরের ধ্বংসাবশেষে ভাঙচুরের ঘটনা ঘটে।\nসেখানে বিশ্ববিদ্যালয়-শিক্ষা প্রাপ্ত একমাত্র ব্যক্তি হওয়ায়, আমি—একজন সামান্য ভ্রমণকারী—কে আঞ্চলিক প্রশাসক ধ্বংসাবশেষের স্থাপত্যগত মূল্যায়নে অংশ নিতে আমন্ত্রণ জানালেন। হা হা, তাদের কখনোই জানতে দেওয়া যাবে না যে আমার সেই 「বিশ্ববিদ্যালয়」 আসলে মোটেই যা মনে হয়, তা নয়।\n3 এপ্রিল বিকেলে আমি মন্দিরের কেন্দ্রে প্রবেশ করি। প্রাচীন সেমিটিকরা একে উপাসনালয় হিসেবে ব্যবহার করত, আর তাদের পৌত্তলিক বিশ্বাস একসময় স্তম্ভগুলোর ফাঁকে ফাঁকে বিকশিত হয়েছিল, পরে ইতিহাসের অন্ধকারে হারিয়ে যায়।\nকিন্তু আমার সামনে যে ভাস্কর্যটি উদ্ভাসিত হলো, তা ভুল করার মতো কিছুই ছিল না। আমি স্পষ্টই জানতাম, তার পোশাকের ভাঁজগুলো আসলে ডোরা-কাটা লিনেন কাপড়ের বুননকে নির্দেশ করার কথা।\nতবু তার দুই হাত ভাঙা, মাথা দেহ থেকে বিচ্ছিন্ন, আর নিম্নাঙ্গ দোরগোড়ায় গুঁড়িয়ে পড়ে আছে। আঠালো শামুকের চলার দাগের মতো এক ধরনের লেসদার পদার্থ সর্বত্র লেপ্টে আছে। নিবিড় পর্যবেক্ষণে দেখা গেল, তার ভেতরে চাপা পড়ে আছে কিছু অদ্ভুত আঁচড়ের চিহ্ন, আর তার সঙ্গে রয়েছে এক বিশাল, ঝিল্লিযুক্ত পদচিহ্ন।\nসম্ভবত এই অঞ্চলে এখনো সেই পৌত্তলিক বিশ্বাস গোপনে ঘুরে বেড়ায়, কিন্তু আনুষ্ঠানিক তদন্ত আপাতত জরুরি নয়। আমি আশদোদ অঞ্চলে আমার অবস্থান বাড়িয়ে দেব।\nফিন@1@2সেন, 「ফিলিস্তিনের পাঁচ নগরী প্রদক্ষিণের এক ভ্রমণবৃত্তান্ত」"
  },
  AwakerStory_11369_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_11369_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11370_Content = {
    Text = "লাইব্রেরির ভূগর্ভ, সমাধিক্ষেত্র এবং রেয়া থেকে দূরে থাকা——এটা সবসময়ই ছাত্রদের মধ্যে একটি সর্বসম্মত ধারণা ছিল।\nফ্যাকাশে ও দুর্বল এই মেয়েটি অন্যদের ক্ষুব্ধ করতে পছন্দ করত, তারপর আনন্দের সাথে তাদের ক্রোধ উপভোগ করত, ঠিক ইডেন উদ্যানের সর্পিণীর মতো, সঠিক সময়ে গোপন টোপ ছুড়ে দিত: এসো আমাকে আঘাত করো… এসো…\nবেশিরভাগ সময়, সে পেত তাচ্ছিল্যের দৃষ্টি, বিভ্রান্তি আর গালাগালি। শুধু একবারই, সে অবশেষে তার ইচ্ছা পূরণ হতে দেখেছিল——ইউউহাশি বিন্দুমাত্র দ্বিধা না করে তাকে একটা ভালো মার দিয়েছিল, এমনকি তার একটা দাঁতও তুলে নিয়েছিল। এই লোকটা অন্যদের প্রতি কোনো কৌতূহলই রাখে না, তার কাছে সবকিছুই স্বাভাবিক।\nযোদ্ধার দৃপ্ত পদক্ষেপে চলে যাওয়ার দিকে তাকিয়ে, রেয়া তৃপ্তির হাসি হাসল, নরম প্রভাতের আলো তার গায়ে পড়ল, আরেকটি রৌদ্রোজ্জ্বল দিন।\nতার আরও অনেক অনেক দাঁত আছে, সব তুলে নাও… যে কেউ হোক, সব তুলে নাও…"
  },
  AwakerStory_11370_Title = {
    Text = "গল্প: ২"
  },
  AwakerStory_11370_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11371_Content = {
    Text = "「…কনস্তান ফেডারেশনের দক্ষিণে বেন্দোসে 「আশীর্বাদ বিশপ」এর কিংবদন্তি প্রচলিত ছিল। মহাপ্লাবনের আগে, 「আশীর্বাদ বিশপ」 কেন্দ্রীয় ধর্মসভা থেকে এসেছিলেন, ধার্মিক ও দয়ালু, নিজ হাতে স্থানীয় একমাত্র এতিমখানা গড়ে তুলেছিলেন, এবং মহামারী ছড়িয়ে পড়ার সময় আশ্রয়হীন রোগী ও শরণার্থীদের আশ্রয় দিয়েছিলেন।\nমহামারী ভয়ংকর ছিল, সবাই কষ্টে ছিল, প্রতিনিধি দিনরাত প্রার্থনা করলেন, অবশেষে পিতৃদেবতার কৃপায় জীবন ফলক লাভ করলেন, নিজের রক্তমাংস উৎসর্গ করে মর্ত্যে অলৌকিক কাজ সম্পাদন করলেন। তিনি মৃতকে জীবিত করলেন, গুরুতর রোগীকে সুস্থ করলেন। তবে এই দয়ালু প্রতিনিধি শয়তানের ষড়যন্ত্রে পড়লেন, শেষ পর্যন্ত অগ্নিদণ্ডে মৃত্যুবরণ করলেন।\nকাকতালীয়ভাবে, কিংবদন্তির 「আশীর্বাদ বিশপ」 সক্রিয় থাকার একই সময়কালে, মূল @2 এর মধ্যভাগে @1 (বর্তমান কনস্তান ফেডারেশনের দক্ষিণে বেন্দোস অঞ্চলের কাছে) একজন বিশেষ 「রক্তের ধর্মদ্রোহী」 বিদ্যমান ছিল। 《মহাদেশীয় বিচারালয় ধর্মদ্রোহী বিচার নথি》 অনুসারে, এই ধর্মদ্রোহী শয়তানের চিহ্ন খোদাই করা একটি ফলক ধারণ করত, রক্তমাংস উৎসর্গ করত, চাঁদ ঢাকা পড়া রাতে নিজেকে পুষ্ট করতে অশুভ আচার অনুষ্ঠান করত। এই ধর্মদ্রোহীকে মহাপ্লাবনের 107 বছর আগে বিচারালয় গ্রেপ্তার করে, ধর্মদ্রোহী অনুতপ্ত হয়ে একমাত্র পিতৃদেবতার কাছে আন্তরিকভাবে অনুশোচনা করে, এবং অগ্নিদণ্ডে মৃত্যুবরণ করে।\nএকই যুগ, একই অঞ্চল, একইভাবে ফলক ও উৎসর্গ ব্যবহার করে গুপ্তবিদ্যা প্রয়োগ——অস্বীকার করা যায় না যে, 「আশীর্বাদ বিশপ」 ও 「রক্তের ধর্মদ্রোহী」র মধ্যে অনেক মিল রয়েছে। বিচারালয়ের শক্তিশালী বিষয়গত পক্ষপাতিত্ব বিবেচনা করলে, যাদের তারা ধর্মদ্রোহী মনে করে তাদের কলঙ্কিত করার সম্ভাবনা অত্যন্ত বেশি, লেখক সন্দেহ করতে বাধ্য যে, কিংবদন্তির 「আশীর্বাদ বিশপ」 সত্যিই বাস্তব ব্যক্তি হতে পারেন, এমনকি বিচারালয়ের নথিতে উল্লিখিত 「রক্তের ধর্মদ্রোহী」ই হতে পারেন…」\n——《আমাদের দেবতারা：কনস্তান ফেডারেশনের দক্ষিণাঞ্চলীয় ধর্ম ও লোকবিশ্বাস》থেকে উদ্ধৃত"
  },
  AwakerStory_11371_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_11371_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11372_Content = {
    Text = "যে সত্ত্বাকে সে 「মা「 বলে ডাকে, তার জন্য আকুল এই মেয়েটি বাধ্যগতভাবে তার 「প্রভু「র আদেশ মেনে চলে।\nতার প্রকৃত নাম পৃথিবী থেকে হারিয়ে গেছে, এখন সে পরিচিত কেবল তার বর্তমান রূপের নামে: এক কোমল সাদা তন্তু, যেন লিলি ফুলের স্মৃতি, যা ফুটে আছে কালো পঙ্কিল কাদায় গঠিত এক বিশাল চোখের মণির কেন্দ্রে। সেই কারণেই, তারা তার নাম রেখেছে লিলি।"
  },
  AwakerStory_11372_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_11372_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_11373_Content = {
    Text = "লিজ একজন নিশ্চিন্ত জাগ্রত সত্তা। যদিও তার মনোভাবকে কোনোভাবেই 「উৎসাহী」 বলা যায় না, তবুও সে স্কুলের সমস্ত কার্যক্রমে যথেষ্ট সহযোগিতা দেখিয়েছে।\nএকমাত্র উদ্বেগের বিষয় হলো, লিজ দিনরাত নৃত্য শিক্ষাকক্ষে কাটালেও, কেউ কখনো তার প্রকৃত নৃত্য দেখেনি।\nএকজন অসামান্য ব্যালে শিল্পী হিসেবে, লিজের নাম কিছু সংশ্লিষ্ট সংবাদপত্রে প্রকাশিত হয়েছিল। দুর্ভাগ্যবশত, ক্ষয় প্রভাবের কারণে, জাগ্রত সত্তা গোয়েন্দা বিভাগ কেবল এটুকুই নিশ্চিত করতে পেরেছে যে লিজ A. F. 29@1 সালে দ্বিতীয় থিয়েটারের মঞ্চে উঠেছিলেন।\nস্কুল সংবাদপত্রের সাংবাদিক হান্না পিসলি একটি প্রস্তাব দিয়েছিলেন — স্কুলের মধ্যে নৃত্যপ্রেমীদের একত্রিত করে, তাদের নৃত্যের প্রতি ভালোবাসা দিয়ে 「জাগ্রত সত্তা লিজের অন্তরের দরজা খোলা」।\nবর্তমানে, এই প্রস্তাবটি জাগ্রত সত্তা ব্যবস্থাপনা বিভাগ দ্বারা এখনো অনুমোদিত হয়নি।"
  },
  AwakerStory_11373_Title = {
    Text = "গল্প: ২"
  },
  AwakerStory_11373_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_11374_Content = {
    Text = "সোরেল জানত সে সুন্দরী, মনে মনে সে এই সৌন্দর্যকে ঈশ্বরের আশীর্বাদ বলে মনে করত।\nশুধু চোখে জল নিয়ে অনুনয় করলেই মানুষ তার প্রতি সহানুভূতি দেখাত; একটু করুণ ভাব দেখালেই তার প্রতি গোপন অনুরাগ পোষণকারী খেলার সাথীরা নিঃশর্তভাবে তার পক্ষ নিত।\nকিন্তু, প্রকৃত ক্ষমতার সামনে সৌন্দর্য সম্পূর্ণ মূল্যহীন।\nতাকে অভিজাতদের কাছে উৎসর্গ করে নিজেদের ভাগ্য ফেরাতে চাওয়া বাবা-মায়ের সামনে, সোরেলের চোখের জল প্রথমবারের মতো ব্যর্থতার স্বাদ পেল।\nকেউ কি তাকে সাহায্য করতে পারে? কেউ কি তাকে এই মূর্খ ও পশ্চাৎপদ নিয়তি থেকে পালাতে সাহায্য করতে পারে?\nএমন কিছু, এমন কোনো জায়গা... যেখানে এই সৌন্দর্য সত্যিকারের অস্ত্র হয়ে উঠতে পারে?\nসোরেল যখন মুখ ঢেকে কাঁদছিল, তখন নিয়তির গভীর জলাশয়ে আলোড়ন সৃষ্টিকারী দূত তার সামনে আবির্ভূত হলো।"
  },
  AwakerStory_11374_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_11374_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_11375_Content = {
    Text = "——এটা তার দোষ না হয়ে যায় কী করে? সে যা করেছে তা এখনও অনেক অনেক কম।\nএই চরম আত্মদোষের আবেগ নিয়ে, ওজিয়ের অন্যান্য জাগ্রতদের তুলনায় দ্বিগুণ হারে মিশন সম্পাদন করত, সকলের প্রশংসিত 「সদ্গুণ」 দিয়ে 「মৃত্যু」কে সমাহিত করত।\nঅতিরিক্ত কাজ আর তরুণ তদন্তকারীদের কৃতজ্ঞতার কথা, যেন সত্যিই আত্মায় খোদাই করা শোককে ধুয়ে দিতে পারত।\nপুরনো ক্ষত অন্তরের ছায়ায় ঠেলে দেওয়া হয়েছিল, সেগুলো পচনের দুর্গন্ধ ছড়াচ্ছিল, গোপনে নাইটকে গভীর কালো জলাভূমির দিকে টেনে নিয়ে যাচ্ছিল।\n「মাফ করবেন? হ্যালো?」\nকেউ একজন এক ফালি সূর্যালোক, কিংবা এক পশলা হাওয়া নিয়ে ওজিয়েরের সামনে এসে দাঁড়াল।\n「সিনিয়র বলেছেন, ওজিয়ের আমার এবং রামোনার সাথে যোগ দেবেন, একসাথে আমার প্রথম তদন্ত মিশন পরিচালনা করবেন, তাই তো?」\nসে রাজকুমারীকে দ্বিতীয়বার রক্ষা করতে পারেনি, কিন্তু ঈশ্বর তাকে আবার একজন 「গোপনরক্ষক」কে রক্ষা করার সুযোগ দিয়েছেন।\n「আমার নাম ওজিয়ের, আপনার সাথে চুক্তিবদ্ধ হতে পেরে আমি সম্মানিত। আমি আমার আত্মা দিয়ে আপনার জীবন রক্ষা করব, আজকের এই শপথ, চিরকাল অবিস্মরণীয়।」"
  },
  AwakerStory_11375_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_11375_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_11376_Content = {
    Text = "「সাধারণ পার্কে বিরক্ত হয়ে গেছেন? একঘেয়ে পশু প্রদর্শনীতে ক্লান্ত? তাহলে চলে আসুন ক্যাসিয়ার ম্যাজিক কার্নিভালে! পশুপ্রেমী শিশুরা, এখানে আছে টেনর গলায় গান গাওয়া সিংহ, ব্যালে নাচা ফ্লেমিঙ্গো, অ্যাক্রোব্যাটিক্স দেখানো হাতি, এবং পৃথিবীর একমাত্র গাধা পশু প্রশিক্ষক! যে প্রেমিক জুটিরা সম্পর্ক গভীর করতে চান, তারা আমাদের অনন্য ঘূর্ণায়মান জীবন্ত ঘোড়ায় চড়ে দেখুন, এক বিরল রোমান্টিক অভিজ্ঞতা অর্জন করুন! যে সাহসীরা মনে করেন জীবনে আসল রোমাঞ্চের অভাব, তারা কার্নিভালের মালিকের নিজ হাতে ডিজাইন করা আয়না গোলকধাঁধায় চ্যালেঞ্জ নিতে পারেন — যদি সেই 41 জন দুষ্টু অতিথিকে বের করে আনতে পারেন যারা ঢুকেছে কিন্তু বের হয়নি, তাহলে পাবেন দারুণ পুরস্কার!\nএই সব বিশ্ব-একমাত্র বিনোদন সুবিধার পাশাপাশি, ম্যাজিক মাস্টার ক্যাসিয়া আপনাকে দেখাবেন এক অদ্ভুত উৎসবের জগৎ, নিয়ে আসবেন মানবদেহ কর্তন, মানুষ অদৃশ্য করা, চরম পলায়ন এবং আরও অনেক জাদু! ভাগ্যবান দর্শকরা মঞ্চে উঠে নিজে পারফরম্যান্সে অংশ নেওয়ার সুযোগ পাবেন, অনুভব করবেন মাস্টার ক্যাসিয়ার অসাধারণ কাটিং কৌশল। গ্যারান্টি দিচ্ছি আপনার ধারণা উল্টে যাবে, এবং আপনার দৈনন্দিন জীবন আরও বেশি নীরস মনে হবে! আরও চমৎকার ব্যাপার হলো, এই সবকিছু বিনামূল্যে, একদম ফ্রি! আপনার আনন্দই মাস্টার ক্যাসিয়ার সেরা পারিশ্রমিক!\nমিসাগ বিশ্ববিদ্যালয়ের সবাই, এই সপ্তাহান্তে ক্যান্টিনের পেছনের খোলা মাঠে মাস্টার ক্যাসিয়া আপনার জন্য অপেক্ষা করছেন!\n\nদ্রষ্টব্য: কার্নিভালে একবার প্রবেশ করলে সম্পূর্ণ অভিজ্ঞতা নিতে হবে, মাঝপথে বের হওয়া যাবে না। কম সহনশীলতা এবং দুর্বল মানসিক ও হৃদরোগীরা সতর্কতার সাথে প্রবেশ করুন।\nকার্নিভালের পরে ক্ষুধামন্দা, অঙ্গহানি, চোখ হারানো এবং পেট ফেটে যাওয়া ইত্যাদি উপসর্গের জন্য এই কার্নিভাল কোনো দায়িত্ব নেবে না।」\n——《ম্যাজিক মাস্টার ক্যাসিয়ার ম্যাজিক কার্নিভালের মহা উদ্বোধন!》"
  },
  AwakerStory_11376_Title = {
    Text = "গল্প: ২"
