  AwakerStory_11377_Content = {
    Text = "「সালোঁ」কখন থেকে যে শুরু হয়েছিল কেউ জানে না, নীরবে লন্ডিনিয়েনের উচ্চবিত্ত সমাজে জনপ্রিয় হয়ে উঠেছিল।\nএই রহস্যময় সালোঁতে, কেউ মহান শিল্পীর কাছে প্রতিকৃতি আঁকানোর সুযোগ পেয়েছে, কেউ প্রধানমন্ত্রীর সাথে রাতের খাবার খেতে পেরেছে, এমনকি কেউ কেউ রানীর কাছ থেকে একটি প্রতিশ্রুতি পেয়েছে।\nআয়োজক, স্থান, সময়——সবই রহস্য, মানুষ শুধু জানে যে, প্রত্যেকেই সালোঁতে তার সবচেয়ে কাঙ্ক্ষিত জিনিস পেতে পারে।\nকিন্তু কেউ জানে না, কোন ধরনের অতিথি গৃহকর্তার দৃষ্টি আকর্ষণ করে একটি আমন্ত্রণপত্র পেতে পারে।\nএমনকি সর্বত্র পরিচিত লর্ড ডেক্সটারও সালোঁর গৃহকর্তার সামনে দরজায় বাধা পেয়েছেন।\n「অত্যন্ত দুঃখিত, গৃহকর্তা এখন শিল্প জগতের বিখ্যাত ব্যক্তিদের আমন্ত্রণ জানাতে বেশি আগ্রহী।」\n「অভিজাত? অনুগ্রহ করে ভবিষ্যতের আমন্ত্রণের জন্য অপেক্ষা করুন।」"
  },
  AwakerStory_11377_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_11377_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_11378_Content = {
    Text = "উচ্চাসনে বসা সেই মহিলা তার হাত ধরে বলেছিলেন, তিনি তাকে পৃথিবীর সমস্ত ভালোবাসা দেবেন।\nসে বিশ্বাস করেছিল মহিলার কোমলতা আর প্রভুর আদরকে, বিশ্বাস করেছিল প্রতিটি হাসি, প্রতিটি আলিঙ্গনকে, কিন্তু জানত না যে তাদের চোখে সে ছিল নিছক একটি পোষা প্রাণী, যাকে নিজেদের জন্য হুমকি হলে যেকোনো মুহূর্তে ছুড়ে ফেলা যায়।\nতারা নিজ হাতে তাকে কারাগারে নিক্ষেপ করেছিল, তার বিশ্বাসকে চূর্ণবিচূর্ণ করেছিল—কিন্তু কারারক্ষীর চাবুক কিংবা গোষ্ঠীর নির্যাতন, কোনোটিই নিকটতম আপনজনের বিশ্বাসঘাতকতার মতো এতটা যন্ত্রণাদায়ক ছিল না।\nঘৃণা, প্রচণ্ড ঘৃণা, ঘৃণা তাদের প্রতি যারা মিথ্যা দিয়ে তার সত্যিকারের হৃদয় কিনেছিল, ঘৃণা তাদের প্রতি যারা তার জীবন দিয়ে এই যন্ত্রণাময় প্রহসন রচনা করেছিল। যদি অন্যকে বিশ্বাস করার পরিণতি এটাই হয়, তবে সে চিরকাল নিজেই নিজের ভরসা হবে।\nতার আস্থা কেবল তার নিজের জন্যই।"
  },
  AwakerStory_11378_Title = {
    Text = "গল্প: ৪"
