  AwakerStory_123301_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_123302_Content = {
    Text = "বেশিরভাগ শিক্ষার্থীর চোখে, মোশিয়া নিঃসন্দেহে বন্ধু হওয়ার জন্য সবচেয়ে উপযুক্ত ব্যক্তি। সে সবসময় হাসিমুখে থাকে, উৎসাহের সাথে কথোপকথনে সায় দেয়, এবং সহজে কারো অনুরোধ প্রত্যাখ্যান করে না, তাই সবসময় কেউ না কেউ তাকে একসাথে ঘুরতে, আড্ডা দিতে বা খেতে যেতে আমন্ত্রণ জানায়।\nকিন্তু মাত্র কয়েকজনই তার আসল রূপ জানে। এদের সামনে তাকে আর বন্ধুত্বপূর্ণ ভান করতে হয় না, নিয়ম ও শৃঙ্খলার প্রতি তার অবজ্ঞা লুকাতে হয় না।\n「বন্ধু? শুধু সময় কাটানোর জন্য বিরক্তি দূর করা। এটা না করলে সমস্যাযুক্ত শিক্ষার্থী হিসেবে চিহ্নিত হয়ে ডিন হেলেটের কাছে জিজ্ঞাসাবাদের জন্য নিয়ে যাওয়া হবে——সত্যিই ঝামেলা।」"
  },
  AwakerStory_123302_Title = {
    Text = "গল্প: ২"
