  AwakerStory_123302_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_123303_Content = {
    Text = "তার জীবন যেন সবসময় অপ্রত্যাশিত ঘটনায় ভরপুর: প্রথমে অজানা কুয়াশার তাণ্ডবের মুখোমুখি হওয়া, তারপর অদ্ভুতভাবে অন্য জগতে তলব হওয়া।\nযখন আহ্বান অনুষ্ঠান সম্পন্ন হলো এবং প্রথমবার অন্য জগতের মাটিতে পা রাখল, মোশা দেখল পরিচিত ঘন কুয়াশা, আর সেই কুয়াশার মধ্যে মানুষের আর্তচিৎকার।\nসেটি ছিল বলিদানের মানুষেরা, যারা ধর্মান্ধদের হাত থেকে পালাচ্ছিল।\nবলিদানের মানুষ? ধর্মান্ধ? কতটা… রোমাঞ্চকর নতুন শব্দ।\nএর মানে নতুন এই জগৎ চলছে দুর্বলকে শক্তিশালী গ্রাস করার জঙ্গলের নিয়মে, আর ঠিক তাই — সে কখনো দুর্বল ছিল না।\nসে শান্তভাবে কুয়াশার মধ্যে ধর্মান্ধদের শিকার করতে লাগল, এতটাই আনন্দিত যে গুনগুন করে গান ধরল।\n「একে একে আরও একজন… কেউ না জানা ঘন কুয়াশায়, আমি মনের সুখে উগরে দিচ্ছি♪」\n「তোমার মাথার খুলি ভেঙে, মস্তিষ্কের গভীরে ঢুকে, চলো তাড়া করতে করতে সময় কাটাই♪」\nএই অনায়াস গুনগুনের মাঝে, মোশা অনুভব করল তার ভেতরের শূন্যতার ক্ষুধা —\nএই পাগলাটে জগৎ তার মনের শূন্যতা পূরণ করতে পারছে না, কিন্তু তার আত্মার ধ্বংস ও উন্মাদনার ক্ষুধাকে কিছুটা হলেও প্রশমিত করতে পারছে।"
  },
  AwakerStory_123303_Title = {
    Text = "গল্প: ৩"
