  AwakerStory_123303_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_123304_Content = {
    Text = "কঠোরভাবে বলতে গেলে, সে এই ধ্বংসের দ্বারপ্রান্তে দাঁড়ানো উন্মাদ জগতের অংশ নয়, তবে সে এই জায়গাটিকে প্রশংসা করে।\nএই জগতের দাউদাউ জ্বলে ওঠা মহিমান্বিত দৃশ্যের প্রশংসা করে, এই মানুষদের হতাশায় ভোগা যন্ত্রণা ও ভেঙে পড়ার প্রশংসা করে।\nবিশ্বাস মৃত, সমাজ স্থবির, নৈতিকতা ধ্বংস — তাই আর বিরক্তিকর 'স্বাভাবিক মানুষ'-এর মুখোশ পরার প্রয়োজন নেই——\nসে অবশেষে ন্যায়সঙ্গতভাবে তার অন্তরের পশুকে মুক্ত করতে পারে, তার প্রকৃত স্বরূপ প্রকাশ করতে পারে, প্রকৃত নিজেকে হয়ে উঠতে পারে।"
  },
  AwakerStory_123304_Title = {
    Text = "প্রাথমিক তথ্য"
