  AwakerStory_123304_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_126929_Content = {
    Text = "খুব কম মানুষই সত্যিকার অর্থে জানত যে শু কখন ক্যাম্পাসে এসেছিল, ঠিক যেমন সে সুদূর প্রাচ্যে স্বাভাবিকভাবেই রাজদরবার, রাজশিবির এবং বিভিন্ন সংগঠনে বিচরণ করত।\nসবাই স্বাভাবিকভাবেই তার প্রতি এক ধরনের পরিচিতি অনুভব করত, যেন বহু বছরের পুরনো বন্ধু, এমনকি হৃদয়ের প্রিয়জন, যদিও তারা কখনো একসাথে কিছু অনুভব করেনি।\nকেবল অত্যন্ত কম সংখ্যক উদ্বোধিত সত্তা শুর প্রতি অস্বাভাবিক সতর্কতা প্রদর্শন করত, বা বলা যায় কেবল অত্যন্ত শক্তিশালী উদ্বোধিত সত্তারাই শুর কুয়াশার মতো ছড়িয়ে পড়া এবং প্রতিপক্ষের স্মৃতিতে প্রবেশ করার অস্বাভাবিক ক্ষমতা অনুভব করতে পারত।\nমিসাগ একাডেমির প্রশাসন বিভাগ একবার গুরুত্বের সাথে আলোচনা করেছিল যে এটি সীমাবদ্ধ করা প্রয়োজন কিনা, এমনকি এর জন্য আলাদাভাবে প্রতিরোধক সরঞ্জাম তৈরি করার কথাও ভেবেছিল, কিন্তু শু কিছু চুক্তি এবং একটি প্রতিশ্রুতির মাধ্যমে সেই উদ্বেগ দূর করে দিয়েছিল।\n「এই ছোট্ট প্রাণীগুলোর উপর আমার কোনো অভিপ্রায় নেই।」"
  },
  AwakerStory_126929_Title = {
