  AwakerStory_126929_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_126930_Content = {
    Text = "A.F.@16@1 সালে, একটি মালবাহী জাহাজ — যার যাত্রাপথের কোনো চিহ্ন কোনো অনুসন্ধান পদ্ধতিতে ধরা পড়েনি এবং যা কোনো আনুষ্ঠানিক অনুমোদনও পায়নি — নীরবে লন্ডিনিয়ামের মালবাহী বন্দরে এসে ভিড়ল।\nপরবর্তীতে নিশ্চিত করা হয় যে জাহাজটি এসেছিল সুদূর পূর্বাঞ্চলের প্রাচীন পানলং রাজ্যের @2 বন্দর থেকে।\nজাহাজটি বন্দরে প্রবেশের রাতে, সেই বন্দরে কর্মরত কর্মীরা এবং আশেপাশের বাসিন্দারা সকলেই জানায় যে তারা স্বপ্নে কালো চুল ও কালো চোখবিশিষ্ট, হাতির দাঁতের মতো ত্বকের এক প্রাচ্য নারীকে দেখেছে। সেই নারীর চেহারা বর্ণনা করতে গিয়ে প্রত্যক্ষদর্শীরা একযোগে 「মোহনীয়「, 「পরিচিত「 প্রভৃতি শব্দ ব্যবহার করেছে। একই সাথে, একাধিক পুরুষ প্রত্যক্ষদর্শী বর্ণনা করার সময় স্তব্ধতার লক্ষণ প্রদর্শন করেছে।\nমিসাগার্ড তদন্তকারীরা দ্রুত জাহাজটি তল্লাশি করে। আশ্চর্যের বিষয়, সর্বত্র বিদ্যমান ফিসফিস হাসির শব্দ এবং স্পষ্টভাবে শনাক্তকৃত আধ্যাত্মিক প্রতিক্রিয়া ছাড়া, সিলভার কোরের কোনো চিহ্ন পাওয়া যায়নি।\nপরদিন লর্ড ডেক্সটার জাহাজের মালখানায় প্রবেশ করেন এবং একটি 「একাধিকবার তল্লাশি করা হয়েছে「 এমন সিরামিকের ফুলদানির ভেতরে পাতলা কুয়াশায় আবৃত একটি সিলভার কোর আবিষ্কার করেন।\nA.F. ৩১৪ সাল পর্যন্ত, এই সিলভার কোরটি কোনো উপায়েই জাগ্রত করা সম্ভব হয়নি বলে নিশ্চিত করা হয়।\nবর্তমান কিপার অফ সিক্রেটস @3 মিসাগার্ডে প্রবেশ করার পর, সিলভার কোরটি স্বয়ংক্রিয়ভাবে জাগরণ অনুষ্ঠান সম্পন্ন করে এবং নিজেকে 「সু「 বলে দাবি করা একটি অ্যাওয়েকেনার হিসেবে জাগ্রত হয়, এবং স্বেচ্ছায় @3-এর সাথে লিংক স্থাপনের অনুরোধ করে।\n——《মিসাগার্ড বিশ্ববিদ্যালয় সিলভার কোর সংরক্ষণ নথি》 থেকে উদ্ধৃত"
  },
  AwakerStory_126930_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_126930_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_126931_Content = {
    Text = "তোমার কি কখনো মনে হয়েছে পৃথিবী এত নীরব যে কিছু একটা ভেঙে ফেলতে চাও শুধু একটু শব্দ শোনার জন্য?\nকামনা হলো তার ছুড়ে দেওয়া একটি রৌপ্য পাত্র, আর এই রৌপ্য পাত্রের শব্দে চমকে ওঠা শিকার... ভালোবাসার জন্য হত্যা করে, ভালোবাসার হাতেই নিহত হয়, যতক্ষণ না মন ও আত্মা ক্ষয়ে যায়, শুধু খোলসটুকু পড়ে থাকে।\nতারপর, এই নিংড়ে নেওয়া খোলসগুলো আরও বেশি, আরও উচ্চতর ক্ষমতা তার হাতে তুলে দেয়, দৃষ্টিসীমার সবকিছুকে রক্তাক্ত ও সুস্বাদু বিশৃঙ্খলায় রাঙিয়ে দেয়।\nকখনো থামে না এই বিশৃঙ্খলা।"
  },
