  AwakerStory_126932_Content = {
    Text = "……যা পূজার যোগ্য নয় তার পূজা করাকে বলা হয় অশুদ্ধ পূজা, যা মানুষকে বিভ্রান্ত করে এবং সম্পদ নষ্ট করে, বারবার নিষেধ করা সত্ত্বেও থামানো যায় না।\nউপকূলীয় অঞ্চলের মানুষদের মধ্যে বিভিন্ন দেবতার পূজা এবং অশুদ্ধ মন্দির ও গ্রামীণ মন্দির নির্মাণের পুরনো রীতি রয়েছে। প্রচুর অর্থ ব্যয় হয়, চাষাবাদ ও বয়নকাজ পড়ে থাকে, তবুও গ্রামবাসীরা এটিকে সমস্যা মনে করে না। শাসকরা বারবার মন্দির ভেঙে দেয়, কিন্তু সৈন্যরা সরে যেতেই কিছুদিনের মধ্যে আবার জ্বলে ওঠে।\nএমনকি বিদেশি শরণার্থীরা গ্রামে বসতি স্থাপন করে, বিদেশি ধর্মের প্রতীক উল্টো করে ঝুলিয়ে, @3 অক্ষরের সাথে আকৃতিগত মিল খুঁজে নিয়ে, তাকে 「কূপ」 বলে ডেকে নিজেদের কাজে ব্যবহার করে।\nমন্দিরে পূজিত প্রধান ও সহায়ক দেবতারা সবাই জীবনকালে যাচাইযোগ্য ব্যক্তি, অধিকাংশই অন্যায়ভাবে মৃত নারী, প্রাথমিকভাবে ভক্তরাও ছিল কৃষক নারী, অভিনেত্রী ও পথের বেশ্যাদের মতো শ্রেণির মানুষ।\nস্ত্রী স্বামীকে নিয়ে আসে, মা সন্তানকে নিয়ে আসে, বেশ্যা খদ্দেরকে নিয়ে আসে। যখন শক্তিশালী হয়ে ওঠে, তখন দলবাজি ও স্বার্থপরতা শুরু হয়, বহুবার দেখা গেছে কয়েকটি গ্রাম মিলে একজনকে তুলে ধরার অদ্ভুত দৃশ্য। কেউ সরকারি পদে প্রবেশ করে, কেউ ব্যক্তিগতভাবে সশস্ত্র বাহিনী পোষে, পরস্পর প্রতিযোগিতা ও সংঘর্ষে লিপ্ত হয়।\n@4@4@3@2\nনিচের লেখাগুলো সব অস্পষ্ট হয়ে গেছে, তবে কয়েক লাইন অত্যন্ত সুশৃঙ্খল @3 লিপি রয়েছে, ভাষাতত্ত্ব বিভাগের অনুবাদ অনুযায়ী অনুবাদ নিম্নরূপ:\n「নির্লজ্জ বৃদ্ধ, পক্ষপাতদুষ্ট মনোভাব, বড়ই বিরক্তিকর। আমি বিরক্ত হয়ে কিছু ঝিঁঝিঁ পোকা পুষে লড়াই করাচ্ছিলাম, তাতেও কিছু কথা বলতে হবে।」\n「তোমার কী এসে যায়।」\n——《ইয়েহু স্টুডিও বিবিধ পত্রিকার পাণ্ডুলিপি থেকে নির্বাচিত অংশ》 থেকে উদ্ধৃত"
  },
  AwakerStory_126932_Title = {
    Text = "গল্প: ৩"
