  AwakerStory_126932_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_126933_Content = {
    Text = "মার্জিত, মোহনীয়, মারাত্মক আকর্ষণের অধিকারী প্রাচ্যের এক「দেবী」। কিংবদন্তি বলে, যখন তিনি তাঁর পাখা সরান, তখন পাখার আড়ালে আপনি আপনার সবচেয়ে প্রিয় মানুষের মুখ দেখতে পাবেন।\nতবে কিংবদন্তি তো কিংবদন্তিই, প্রার্থনা করুন যেন তাঁর দৃষ্টি আপনার উপর না পড়ে। কারণ যখন তিনি সর্বব্যাপী রাতের কুয়াশার মতো আপনার স্মৃতিতে প্রবেশ করবেন, উন্মত্ত আচ্ছন্নতা ছাড়া... আপনার মস্তিষ্কে আর কিছুই অবশিষ্ট থাকবে না।"
  },
  AwakerStory_126933_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_126933_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_129596_Content = {
    Text = "মস উদ্বোধিত সত্তার পরিস্থিতি বিশেষ ধরনের; অনিয়ন্ত্রিত অবস্থায়, ক্ষমতার প্রকাশ উদ্বোধিত সত্তার নিজের ইচ্ছার উপর নির্ভর করে না। তার চারপাশে অনিয়মিতভাবে ঘূর্ণি M-এর মতো বিশেষ শক্তিক্ষেত্র তৈরি হয়, যা শক্তিক্ষেত্রের ভেতরে থাকা বস্তুগুলোকে চূর্ণ করে দেয়।\nযখন মস ভেতরে জল (রক্ত সহ অন্যান্য শারীরিক তরল) ধারণকারী মানুষ বা বস্তুর সংস্পর্শে আসে, তখন সেই স্থানে শক্তিক্ষেত্র দ্রুত তৈরি হয়। যেহেতু এই ঘটনা মস নিজে নিয়ন্ত্রণ করতে পারে না, এবং উদ্বোধনের প্রাথমিক পর্যায়ে সে দীর্ঘ সময় উন্মাদ অবস্থায় ছিল, তাই বিপদের মাত্রা অত্যন্ত উচ্চ ছিল।\nএই কারণে, উদ্বোধিত সত্তা বিভাগ পদার্থবিজ্ঞান বিভাগ, রসায়ন বিভাগ সহ একাধিক বিভাগের সাথে আন্তঃবিভাগীয় সহযোগিতা করে, বহু প্রচেষ্টার পর অবশেষে তার ধ্বংসাত্মক শক্তি প্রতিরোধ করতে সক্ষম সংশ্লেষিত ধাতু 「মস স্টিল」 তৈরি করে, এবং এটি দিয়ে মুখের খাঁচা ও বন্ধনী তৈরি করে মসকে পরিয়ে দেয়।\nমস উদ্বোধিত সত্তার মানসিক অবস্থা গবেষক কডওয়েলের পরিচালিত একাদশতম 「O-1841 উদ্বোধিত সত্তা যোগাযোগ পরীক্ষা」-র পর স্থিতিশীল হতে শুরু করে; সেই পরীক্ষায় মস ঘূর্ণি M-মেস্কস্-এর প্রভাব নিজের মধ্যে স্থানান্তরিত করে, যা আশেপাশের ক্ষতি অত্যন্ত হ্রাস করে।\nতবে এটিও লক্ষ্য রাখা প্রয়োজন যে মস নিজে থেকে দীর্ঘ সময় এই অবস্থা বজায় রাখতে পারে না; কেবল 「মস স্টিল」 বন্ধনীর সাহায্যে মস দীর্ঘমেয়াদে স্থিতিশীলভাবে ঘূর্ণি M-এর প্রভাব নিজের মধ্যে ধরে রাখতে এবং একই সাথে তার ক্ষমতাকে যুদ্ধে পরিচালিত করতে পারে।\nজ্ঞান ফিরে পাওয়ার পর, মস তার প্রফুল্ল স্বভাব প্রকাশ করে, এবং নোডিলা উদ্বোধিত সত্তার প্রতি অজানা কারণে ঘনিষ্ঠতা প্রদর্শন করে। এটি সম্ভবত উভয়ের আত্মিক উৎসের অভিজ্ঞতার সাথে সম্পর্কিত।\n——《মস উদ্বোধিত সত্তা প্রতিবেদন》 থেকে নির্বাচিত অংশ"
  },
  AwakerStory_129596_Title = {
