  AwakerStory_129597_Content = {
    Text = "এমনকি সে যদি জানতও কীভাবে সঠিকভাবে বাক্য গঠন করতে হয়, তবুও সে তোমাকে বলতে পারত না সে কোথায় জন্মেছে। আসলে, যে কোনো ঘরের কথাই হোক, এখন সে কেবল ধবধবে সাদা বালুতট, ঘন জঙ্গল আর অসীম সমুদ্রের কথাই মনে করতে পারে।\nকিন্তু তুমি যদি তাকে জিজ্ঞেস করো তার ঘর কোথায়, সে জড় শব্দ আর উদ্দীপ্ত অঙ্গভঙ্গিতে তোমাকে বলবে: ঘর সমুদ্রের উপর, সমুদ্রস্রোতের সাথে চারদিকে ভেসে বেড়ায়।\nদীর্ঘদিন সঙ্গীহীন মানুষ একাকীত্ব কাকে বলে তা বুঝতে পারে না, কিন্তু সেই জাহাজে সে আত্মীয়তার স্বাদ পেয়েছিল, বন্ধুত্বও অর্জন করেছিল: সে তার নটিলাস নামের সঙ্গীর সাথে ভাগ করে নিত সুস্বাদু ভাজা মাছ, সুন্দর ঝিনুক, ভাগ করে নিত স্থলভূমি সম্পর্কে, দূরযাত্রা সম্পর্কে, অভিযান সম্পর্কে একটি স্বপ্ন, এবং শেষে ভাগ করে নিত কালো ঢেউ আর ঘূর্ণিতে বিলীন হওয়া এক মৃত্যু।"
  },
  AwakerStory_129597_Title = {
    Text = "গল্প: ৩"
