  AwakerStory_129597_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_129598_Content = {
    Text = "উত্তর আটলান্টিক ঘূর্ণি M-মেস্কস্ প্রথম A.F. 1■■ সালে আবির্ভূত হয়, এবং পরবর্তী কয়েকশো বছরে এর আকার ক্রমশ বৃদ্ধি পায়। A.F. 29■ নাগাদ, M-মেস্কস্ প্রায় ২৬০-৩০০ ফুট (৮০-৯০ মিটার) ব্যাসের এবং প্রায় ৫ মাইল (৮ কিলোমিটার) প্রশস্ত স্রোতের এক বিশাল ঘূর্ণিতে পরিণত হয়।\nস্রোতের শক্তিশালী আকর্ষণ ও তার প্রভাব ছাড়াও (আশেপাশের জলে মাছ ও মাছ ধরার নৌকা সবই এর শিকার হয়েছে), M-মেস্কস্-এর নিচে আরও একটি বড় হুমকি বিদ্যমান ছিল——ক্ষয়কারী ফাটল। একাডেমির সদস্যদের দীর্ঘ পর্যবেক্ষণ ও গবেষণার পর নিশ্চিত করা হয় যে M-মেস্কস্-এর গঠন তার নিচের ক্ষয়কারী ফাটলের সাথে সরাসরি সম্পর্কিত, এবং A.F. 313 সালে আনুষ্ঠানিকভাবে এটি অপসারণ করা হয়।\nফাটলের মধ্যে একাডেমি প্রচুর পরিমাণে জীব ও জাহাজের ধ্বংসাবশেষ আবিষ্কার করে, এবং O-1841 নম্বরযুক্ত রূপালি কোর সংগ্রহ করে।\n——《M-মেস্কস্ ঘটনার রেকর্ড》 থেকে নির্বাচিত অংশ"
  },
  AwakerStory_129598_Title = {
    Text = "গল্প: ১"
