  AwakerStory_129598_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_129599_Content = {
    Text = "ভাষা বোঝা যাচ্ছে না? কোনো সমস্যা নেই, হাত-পা নেড়ে ইশারায়ও যোগাযোগ করা যায়। ক্ষমতা নিয়ন্ত্রণ করতে পারছ না? এই স্কুলে এটা ভাতের মতোই সাধারণ ব্যাপার, কয়েকদিনের পরীক্ষা-নিরীক্ষাতেই সমাধান হয়ে যায়।\nপ্রাণবন্ত হাসি আর প্রায় বন্য বলা যায় এমন সরল স্বভাবের জোরে, মস খুব দ্রুতই অন্যান্য জাগরিতদের মধ্যে জনপ্রিয় হয়ে উঠল। যদিও সে প্রায়ই নিজের ক্ষমতার কথা ভুলে গিয়ে বিশাল ধ্বংসযজ্ঞ ঘটিয়ে ফেলত (ঈশ্বর সেই ফোয়ারাটিকে রক্ষা করুন যেটা ৩ বার পুনর্নির্মাণ করতে হয়েছে), কিন্তু তাতে কী এসে যায়? সে তো ইচ্ছে করে করেনি।\nসম্ভবত।"
  },
  AwakerStory_129599_Title = {
    Text = "প্রাথমিক তথ্য"
