  AwakerStory_129599_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_129600_Content = {
    Text = "সব কিছু স্রোতে ডুবে যাওয়ার আগে, অসীম সমুদ্র ও হালকা নোনা সমুদ্রের বাতাসের মধ্যে, সেই জাহাজে, রক্তের সম্পর্ক না থাকা পরিবার ও বন্ধুরা তাকে একাকীত্বের অর্থ বুঝিয়েছিল, এবং সে আর সেই অবস্থায় ফিরে যেতে চায়নি।\nকিন্তু তার সবচেয়ে ভালো বন্ধুর জন্য, তার ছোট্ট পরিবারের জন্য, সে স্বেচ্ছায় আবার সেই ঘুটঘুটে অন্ধকার নীরবতায় ফিরে গিয়েছিল।\nসব কিছু অন্ধকারে ঢেকে যাওয়ার পর, সে ভিন্ন রূপে নতুন জীবন পেয়েছিল। যদিও এই জীবন বেশ অসুবিধাজনক——সে প্রায়ই ভুলে যায় যে তার শক্তি আশেপাশের জিনিসপত্রে বিশাল ক্ষতি করতে পারে——তবুও আরও বেশি বন্ধু পাওয়ার সম্ভাবনা তাকে অপরিসীম আনন্দ দেয়।\nঅবশ্যই, যদি তার সবচেয়ে ভালো বন্ধু তাদের পুরনো গল্প মনে করতে পারত, তাহলে আরও ভালো হত।\n「আরও ভালোর চেয়েও ভালো, আরও আরও আরও ভালো!」"
  },
  AwakerStory_129600_Title = {
    Text = "গল্প: ৪"
