  AwakerStory_129600_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_134315_Content = {
    Text = "জালে আবদ্ধ জালবুননকারী, ভাগ্যের নাট্যশালার নাট্যকার ও চিরন্তন দর্শক।\nআঙুলের ফাঁক থেকে সুতো ঝরে পড়ে, জড়িয়ে যায় পর্দায়, পাণ্ডুলিপিতে ও খাঁচায়—প্রতিটি সুতো আরাকনে নিজ হাতে কেটেছে, আবার সেই সুতোই তাকে স্তরে স্তরে বেঁধে রেখেছে।\nদর্শকাসন চিরকাল শূন্য, কেবল সে নিজেই মঞ্চের নিচে বসে মঞ্চের উপর আত্মতুষ্টির অভিনয় দেখে, চক্রাকারে, কখনো শেষ না হওয়া।\nতার অস্তিত্ব নাট্যশালার ভূত, আবার ভাগ্যের মূর্ত প্রকাশও।"
  },
  AwakerStory_134315_Title = {
    Text = "প্রাথমিক তথ্য"
