  AwakerStory_134315_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_134316_Content = {
    Text = "আরাকনে প্রথমে বুঝতে পারেনি যে সে ভাগ্য দেখতে পায়। \nপৃথিবী তার কাছে অন্য সবার মতোই ছিল — অস্পষ্ট, কোলাহলপূর্ণ, আকস্মিকতায় ভরা।\nদুই বছর বয়সে, সে তার জীবনের প্রথম কথা বলেছিল। \nসেটা 「মা」 ছিল না, 「বাবা」ও ছিল না — বরং বারান্দার নিচে দাঁড়িয়ে, পরিবারের কয়েক প্রজন্ম ধরে সেবা করা বৃদ্ধ দারোয়ানকে আস্তে বলেছিল: 「শুভ রাত্রি।」 \nসেই রাতেই দারোয়ান হৃদরোগে আকস্মিকভাবে মারা গেলেন। সে তার রেখে যাওয়া পকেট ঘড়িটা মুঠো করে ধরে, দরজার বাইরে কাঁদতে কাঁদতে ঘুমিয়ে পড়েছিল। তখন সে মৃত্যু বা ভাগ্য বুঝত না, তবু ভাগ্যের আগাম ফাঁস করা তিক্ততার স্বাদ পেয়েছিল।\nপাঁচ বছর বয়সে, নৈশভোজের অতিথিদের উৎসাহী উল্লাসের মাঝে, সে মায়ের মতো পায়ের আঙুলে ভর দিয়ে আনাড়িভাবে ওয়াল্টজ নাচতে শুরু করেছিল। \nপায়ে পরা লাল জুতোজোড়া রক্তের মতো উজ্জ্বল ছিল, যেন কোনো পূর্বাভাস। ঘুরতে গিয়ে সে পড়ে গিয়েছিল, কিন্তু কেউ তার চোখে ক্ষণিকের জন্য ভেসে ওঠা দৃশ্যটা দেখেনি — যেন পড়ে যাওয়াটা নির্ধারিতই ছিল।\nসাত বছরের জন্মদিনে, বাবা তাকে 「মোইরাই」 নামের একটি সুতো কাটার চরকা উপহার দিলেন — ভাগ্যের তিন দেবীর নাম। \nসে বনের মধ্যে দিয়ে দৌড়াচ্ছিল, হাসি ছিল স্বচ্ছ, কিন্তু হোঁচট খেতেই একটা মড়মড় শব্দ শুনল — চরকাটা ভেঙে গেল। \nসে ঝরা পাতার মাঝে বসে আঙুল দিয়ে ফাটলটা ছুঁয়ে দেখল, আর হঠাৎ মনে হলো যেন অসংখ্য সুতো সেই ফাটল থেকে বেরিয়ে তার আঙুলে জড়িয়ে যাচ্ছে, সোজা অদৃশ্য দূরত্বের দিকে চলে যাচ্ছে।\nতারপর, সে প্রথমবার অপেরা হাউসে গেল, প্রথমবার প্রিয় বন্ধু পেল, প্রথমবার নিজের হাতে প্রিয় কুকুরকে কবর দিল…… \nপ্রতিটি 「প্রথমবার」-এর সাথে, নীরব পরিসমাপ্তি তার চোখের সামনে ভেসে উঠত। সে বুঝতে শুরু করল: যাকে শুরু বলা হয়, তার পরিণতি আগে থেকেই নির্ধারিত।\nতারপর থেকে, তার দৃষ্টি আর বাইরের রূপে থামতে পারত না। মানুষের মুখ পাতলা পর্দার মতো হয়ে গেল, একনজরেই সে তার নিচে বহমান ভাগ্য দেখতে পেত: কে গ্রীষ্মের শেষে রোগে মারা যাবে, কে বিয়ের আগের রাতে ফাঁসি নেবে, কার সন্তান দশ বছর পরে তাকে নিজের হাতে কবর দেবে…… আনন্দ মিলিয়ে গেল, প্রত্যাশা শুকিয়ে গেল। তথাকথিত 「ভবিষ্যৎ」 তার কাছে আগেভাগে খুলে ফেলা মৃত্যুসংবাদ ছাড়া আর কিছু ছিল না।\nসে একবার আশেপাশের মানুষদের আসন্ন দুর্ভাগ্যের কথা জানাতে চেষ্টা করেছিল, কিন্তু কথা বের হওয়ার মুহূর্তেই ভবিষ্যদ্বাণী সত্যি হয়ে যেত। \nতাদের ভয়ে পিছিয়ে যাওয়া দৃষ্টির সামনে, সেই মুহূর্তে সে অবশেষে বুঝল: \n「দেখতে পাওয়া মানেই বদলাতে পারা নয়।」\nভাগ্যের জাল আগেই বোনা হয়ে গেছে, তার 「পূর্বজ্ঞান」 শুধু জালের ফাঁক দিয়ে ঘটনাক্রমে বেরিয়ে আসা এক ঝলক আলো — পরিণতি দেখায়, কিন্তু তানা-বানা পাল্টানোর ক্ষমতা নেই।\nতাই সে সেই 「মোইরাই」 নামের চরকাটা তুলে নিল। \nভাঙা চরকা অনেক আগেই মেরামত হয়েছিল, কিন্তু ফাটল রয়ে গিয়েছিল। সে দিনের পর দিন বুনতে থাকল, আর ভাগ্য সম্পর্কিত তার অদ্ভুত প্রতিভা অদ্ভুতভাবে এই চরকার সাথে মিলে গেল। \nতারপর থেকে, সকলের ভাগ্য তার আঙুলের মাঝ দিয়ে বয়ে গেল, একে অপরের সাথে জড়িয়ে, সময় ও স্থান পেরিয়ে এক বিশাল জাল বুনে উঠল। অদৃশ্যভাবে, সেও এই চিরন্তন জালে আটকে পড়ল। সে অগণিত হাসি ও অশ্রু প্রত্যক্ষ করল, অন্তহীন সম্ভাবনা ও অনিবার্য ধ্বংস বারবার মঞ্চস্থ হতে দেখল……\nকিন্তু আরাকনে থামবে না। বোনার জন্য নয়, বরং টিকিয়ে রাখার জন্য — সে থামলে, পুরো ভাগ্যের জাল ভেঙে পড়তে পারে, লক্ষ লক্ষ জীবনকে শূন্যে মিলিয়ে দিতে পারে। তবু সে দেখতে পাচ্ছে, যখন ভাগ্যের জাল সম্পূর্ণ হবে, তখন তাঁর জাগরণ অনিবার্য ধ্বংস নিয়ে আসবে……\nসে বুননকারী হয়েও বন্দী, দর্শক হয়েও কারাবন্দী, নাট্যকার হয়েও নাটকের চরিত্র।\nঅন্যের ভাগ্য স্পষ্ট দেখতে পাওয়া — এটা কি ভালো না খারাপ? \nআরাকনে আর এই প্রশ্ন করে না।"
  },
