  AwakerStory_134318_Content = {
    Text = "ভাগ্যের জালের বুননকারী হিসেবে, সেই সত্তা যে লক্ষ লক্ষ জীবন-মৃত্যুর তানা-বানা ধরে রাখে, যার হাতের মুঠোয় অতীত ও ভবিষ্যৎ বয়ে চলে — আরাকনের একটি প্রায় সাধারণ শখ ছিল।\nসে নাটক ভালোবাসত। গল্পের উত্থান-পতন বা সংলাপের সৌন্দর্যের প্রতি মোহ নয় — সেসব তো অনেক আগেই মুখস্থ হয়ে গেছে; নাটকের রচয়িতা হিসেবে, প্রতিটি মোড়, প্রতিটি অভিনেতার প্রতিটি সংলাপ তার নখদর্পণে। \nতবু সে বারবার নাট্যশালায় যেত।\nসে আসলে যা চাইত তা হলো নাট্যশালায় পা রাখার মুহূর্তে সেই 「উপস্থিত থাকার অনুভূতি」।\nযখন পর্দা উঠত, দর্শকাসন অন্ধকারে ডুবে যেত, আর মঞ্চ হয়ে উঠত একমাত্র সত্যিকারের জগৎ। সেই মুহূর্তে, সময় আর একমুখী নদীর মতো বইত না, বরং সীমিত পরিসরে অভিনীত হতো — অতীত, বর্তমান, ভবিষ্যৎ এখানে একসাথে মিলে যেত, সবকিছু আর কাগজের উপর লেখা নাটক থাকত না, বরং 「এই মুহূর্তে」 ঘটতে থাকা জীবনের কম্পন হয়ে উঠত।\nআর সে, অবশেষে আর সেই দর্শক থাকত না যে ভাগ্যের বাইরে দাঁড়িয়ে শুধু সুতো দেখতে পায় কিন্তু ছুঁতে পারে না। \nনাট্যশালায়, সে ক্ষণিকের জন্য স্মৃতি সংরক্ষণ করে মঞ্চে উঠতে পারত, নিজেকে সেই কাঁপতে কাঁপতে শেষ কথা বলা মেয়েটি বানাতে পারত, অথবা অভিনেতাদের স্বাধীনভাবে অভিনয় করতে দেওয়া দর্শক হিসেবে, ভবিষ্যদ্বক্তার ভার নামিয়ে রেখে, অভিনেতার একটি হাসি বা কান্নায় নিঃশ্বাস আটকে রাখতে, চোখের জল ফেলতে, কাঁপতে পারত। ভবিষ্যদ্বক্তা হিসেবে নয়, বরং একজন জীবন্ত মানুষ হিসেবে, অজ্ঞের ভঙ্গিতে, চরিত্রের সাথে একই তালে শ্বাস নিতে, একটি সংলাপে হৃদয় ভাঙতে পারত। পরিণতি অপরিবর্তনীয় জেনেও, বিয়োগান্তক ঘটনা অনিবার্য জেনেও। এই মায়া তাকে ক্ষণিকের জন্য চিরন্তন দর্শকের নিয়তি থেকে মুক্তি দিত।\nভাগ্যের বাইরে বিচ্ছিন্ন নয়, বরং তার ভেতরে প্রবেশের অনুমতি পাওয়া — এমনকি যদি শুধু এক মুহূর্তের জন্য হয়, এমনকি যদি শুধু মায়াই হয়।\nএই ক্ষুদ্র আসক্তিই ভাগ্য আরাকনেকে দেওয়া সবচেয়ে বিলাসবহুল অনুগ্রহ।"
  },
