  AwakerStory_139857_Content = {
    Text = "যখন সবকিছু রক্ত-মাংসে ক্ষয়ে যায়, যখন দৈনন্দিন জীবন বিপর্যস্ত হয়ে ওঠে, চিৎকারের কোলাহলের মাঝে, ড্যান্ডেলিয়ন এই বিরান ভূমিতে ভেসে নামল।\nহাত বাড়াও, তাকে ধরো।\nভালোবাসা বাইরের রূপ ভেদ করে, তোমাকে এবং তোমার প্রিয়জনকে, আবার একসাথে নোঙর করবে।"
  },
  AwakerStory_139857_Title = {
    Text = "প্রাথমিক তথ্য"
