  AwakerStory_139857_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_139858_Content = {
    Text = "যা ঘটতে চলেছে, যা এখনো ঘটেনি তার মতোই, হৃদয়ে গেঁথে থাকা, কখনো ভোলা যাবে না এমন সব কথার মতোই।\nবাইরের চেহারা যাই হোক না কেন, পৃথিবী যাই হয়ে যাক না কেন, অত্যন্ত আলাদা অথচ অত্যন্ত একই রকম দুজন মানুষ একই উত্তরে পৌঁছাবে।\n「আমাদের এমন মানুষ আছে যাদের দেখতে চাই।」\n「আমরা সবকিছু উপেক্ষা করে তাদের খুঁজে পাব, এমন একটি পৃথিবী খুঁজে পাব যেখানে আমরা তাদের সাথে থাকতে পারব।」\n「যদি সেই পথ অনেক দূরের হয়, তাহলে আমরা তাদের খুঁজে পাওয়ার পথেই থাকব, অনুসন্ধানের মধ্যে দিয়ে দীর্ঘ জীবন কাটিয়ে দেব।」\nহয়তো এই কারণেই, রক্ত-মাংসের চিৎকারের মাঝে, সেই উজ্জ্বল রুপালি কোর রক্ষকের হাতের মুঠোয় রাখা হয়েছিল।"
  },
  AwakerStory_139858_Title = {
    Text = "গল্প: ১"
