  AwakerStory_139858_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_139859_Content = {
    Text = "「সায়া」আসলে কী? উত্তরের চাবিকাঠি লুকিয়ে আছে কোনো এক সুদূর প্রান্তে।\n「……সায়া নামে পরিচিত সেই সত্তা—এই মহাবিশ্বে তার আবির্ভাবের কারণ কোনো দৈবঘটনা নয়, বরং এটি একটি জীবের মধ্যে পূর্বনির্ধারিত সহজাত প্রবৃত্তির ফল। যা নির্দেশ করে সকল জীবের চূড়ান্ত লক্ষ্যকে—প্রজনন। সে এবং তার অনুগামীরা এমন সত্তা যারা ভিন্ন মাত্রার দেয়াল অতিক্রম করে বীজ বপন করতে সক্ষম। ……」\n「……অনুমান করা হয় যে, সায়া নামক এই সত্তা কি তার নিজ প্রজাতির মধ্যেও একটি ব্যতিক্রমী অস্তিত্ব? মানুষ এমন একটি প্রজাতি যারা বুদ্ধিমত্তার দ্বারা সহজাত প্রবৃত্তিকে উল্টে দিয়েছে—এই প্রজাতির ত্রুটি কি সায়াও উত্তরাধিকারসূত্রে পেয়েছে? মানুষকে জানার প্রক্রিয়ায়, মানুষের প্রবৃত্তিবিরোধী আবেগ ও ধারণাগুলো হয়তো সায়ার প্রজনন-প্রবৃত্তিকেও ধ্বংস করে দিয়েছে……」\n「——একদিন না একদিন, ভালোবাসার নামে আশীর্বাদ তার উপর নেমে আসবে। তার হৃদয়ে জ্বলে উঠবে উত্তপ্ত প্রেম, এবং সে গর্বের সাথে পৃথিবী ভ্রমণ করতে পারবে, আবার ফিরে পাবে তার দীপ্তি ও আভা।」\n তাকে কি ভালো-মন্দের মাপকাঠিতে বিচার করা উচিত? নাকি ভালোবাসার সত্যতা দিয়ে পরিমাপ করা উচিত?\nহয়তো এসবের কোনো উত্তরই নেই। সেই জগতের অমীমাংসিত উত্তর বহন করে, অনেক আগে অপ্রত্যাশিতভাবে এই মহাবিশ্বে এসে পড়া সায়া—যেখানে তখনও কিছুই ঘটেনি—স্মৃতির উত্তরে পরিচালিত হয়ে, বিস্মৃতির ওপারের দিকে তাকিয়ে, এগিয়ে চলেছে।\nসে অপেক্ষা করছে সেই দিনের জন্য যেদিন ড্যান্ডেলিয়ন ফুলে উঠবে।"
  },
  AwakerStory_139859_Title = {
    Text = "গল্প: ৩"
