  AwakerStory_139859_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_139860_Content = {
    Text = "শায়ে খুব দ্রুতই একজন জনপ্রিয় শিক্ষার্থী হয়ে উঠল — অসাধারণ শেখার ক্ষমতা, জ্ঞানের প্রতি তৃষ্ণা — মিসাগে, এই গুণাবলী সম্পন্ন একজন উদ্বোধিত সত্তা তার বিশেষ শারীরিক গঠনের চেয়েও বিরল ছিল।\nঅপ্রত্যাশিতভাবে, শায়ে রামোনার প্রতি অস্বাভাবিক আগ্রহ দেখাল — হয়তো রামোনা ও রক্ষকের মধ্যেকার বন্ধনের কারণে, অথবা হয়তো রামোনা ও ডেক্সটারের মধ্যেকার বিশেষ পিতা-কন্যা সম্পর্কের কারণে।\nশায়ের ভালো-মন্দ ও নৈতিকতার দৃষ্টিভঙ্গি মানুষের থেকে সম্পূর্ণ আলাদা হওয়ায়, একসময় একাডেমি রামোনাকে বিশেষ নিরাপত্তা ব্যবস্থা নেওয়ার পরামর্শ দিয়েছিল, কিন্তু সংশ্লিষ্ট ব্যক্তি সেই প্রস্তাব প্রত্যাখ্যান করলেন।\nতাদের কথোপকথনের বিষয়বস্তু কেউ জানত না, কিন্তু মাঝে মাঝে, মিসাগের কোনো উষ্ণ বিকেলে, মাঠের উপর দিয়ে বয়ে যাওয়া মৃদু বাতাস তাদের অজানা দীর্ঘ আলাপে অংশ নিত।"
  },
  AwakerStory_139860_Title = {
