  AwakerStory_139861_Content = {
    Text = "মানবজাতি থেকে সবচেয়ে দূরবর্তী প্রজাতি, মানুষ হয়ে ওঠার প্রক্রিয়ায়, এমনকি সহজাত প্রবৃত্তির বিরুদ্ধ যাওয়া দিকগুলোতেও মানুষের মতো হয়ে উঠেছে।\nযদি ভালোবাসা না থাকে, তাহলে যে জগৎ সৃষ্টি করতে চাওয়া হয়েছিল তা সম্পূর্ণ অর্থহীন।\nযদি ভালোবাসা থাকে, তাহলে কেবল দুজনের জন্য একটি জগৎ সৃষ্টি করাই অর্থবহ।\nএটা কেবল এতটাই ভয়ংকর ও নিষ্ঠুর, কেবল এতটাই নিষ্পাপ ও উজ্জ্বল।"
  },
  AwakerStory_139861_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_139861_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_142869_Content = {
    Text = "পন্টোস অনেক দীর্ঘ সময় ব্যয় করেছিল লেইসার মৃত্যুর কারণ খুঁজে বের করতে। সে অনেক কঠিন যুদ্ধের অভিজ্ঞতা নিয়েছিল, অনেক অসাধারণ জয় পেয়েছিল — হয়তো ওষুধ, হয়তো অজানা কোনো জাদু, নিশ্চয়ই কোনো একটা কারণ ছিল, এমন একটা কারণ যা লেইসাকে একটা দুর্বল সমুদ্র দানবের হাতে মৃত্যুর দিকে ঠেলে দিয়েছিল।\nঅনেক, অনেক পরে, তার এমন একজন মানব সঙ্গী যে এপোয়ান্সে যোগ দেয়নি, তার মাথায় প্রথম সাদা চুল গজাল।\nধীরে ধীরে পিছিয়ে পড়া শারীরিক শক্তি, ধীরে ধীরে মন্থর হয়ে আসা প্রতিক্রিয়া, এবং মুখে না বললেও স্পষ্ট বোঝা যাওয়া শান্ত ও স্থির জীবনের আকাঙ্ক্ষা — সবকিছুই এত পরিচিত লাগছিল।\nপন্টোস হঠাৎ বুঝতে পারল সেই চিরঅদৃশ্য শত্রুর নাম — 「বার্ধক্য」।\nলেইসার নির্জনবাসের কারণ, লেইসার পরাজয়ের কারণ, যা তার সারাজীবনের সম্ভাবনাকে মুছে দিয়ে শুধু ঘৃণা রেখে গেছে — সেই কারণটা ছিল এতটাই সর্বত্র বিদ্যমান, অথচ প্রতিরোধ করা অসম্ভব।\nকিন্তু এতে কিছু যায় আসে না, তার ধ্বংস এসেছিল অনেক আগেই, আর যে শক্তি সে পেয়েছিল তা তাকে পুরোপুরি সন্তুষ্ট করেছিল।\nযে সত্তার প্রতিই আনুগত্য করতে হোক, যে মূল্যই দিতে হোক — এপোয়ান্সে এটা আর কখনো ঘটবে না।"
  },
  AwakerStory_142869_Title = {
    Text = "গল্প: ৩"
