  AwakerStory_142870_Content = {
    Text = "「তুমি কি বার্ধক্যকে ঘটতে দিতে চাও না, নাকি তোমার নিয়ন্ত্রণের বাইরে যেকোনো কিছুকে ঘটতে দিতে চাও না？」\nসে উত্তর দিল না, উত্তর দেওয়ার প্রয়োজনও ছিল না তার।\nঅতল গহ্বর বিপর্যয়ের আগেই তাকে বেছে নিয়েছিল, কারণ তার অনুচ্চারিত আবেশ অতল গহ্বরের সাথে এতটাই সামঞ্জস্যপূর্ণ ছিল।\nআনুগত্য, সঙ্গ, অপরিবর্তনীয়তা — যেন অতল গহ্বর থেকে মুক্তি নেই, যেন অতল গহ্বর সবকিছুকে শ্বাসরোধ করে, তবু সবকিছুকে ধরে রাখে।"
  },
  AwakerStory_142870_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_142870_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_142871_Content = {
    Text = "মিথাগের বেশিরভাগ শিক্ষক-শিক্ষার্থী মাঠকর্মের সময় পন্টোসের সাহায্য নিতে খুবই আগ্রহী ছিলেন, এবং পন্টোসও কখনো সাহায্যের হাত বাড়াতে কার্পণ্য করতেন না।\nউদার, প্রাণবন্ত, স্থিরচিত্ত ও নির্ভরযোগ্য — বিশ্ববিদ্যালয়ের কিছু সদস্যের সাথে স্পষ্ট গুরুতর মতবিরোধ থাকলেও, এই জাগরণকারীর প্রথম ছাপ ছিল অবাক করার মতো ভালো।\nতবে, যদিও পন্টোস নিজে মিথাগের সাথে চুক্তি করেছিলেন যে এপোয়ান্সের বাসিন্দাদের সংখ্যা আর বাড়াবেন না, তবু বেশ কয়েকটি 「সমাপ্তি পথ বিশেষ」 মাঠকর্ম অ্যাকশনের পরে, বিপুল সংখ্যক স্থানান্তর আবেদন বিশ্ববিদ্যালয় দপ্তরে জমা পড়তে লাগল।\nসিলভিয়া আবেদনকারীদের সম্মিলিত মনোবৈজ্ঞানিক পরামর্শ দেওয়ার পাশাপাশি, বিশ্ববিদ্যালয় দপ্তর দ্রুত নিম্নলিখিত দুটি মাঠকর্ম বিধি সংযোজন করল।\n১। অত্যন্ত জরুরি পরিস্থিতি ছাড়া পন্টোসের কাছে সাহায্য চাওয়া কঠোরভাবে নিষিদ্ধ।\n২। অত্যন্ত বিশেষ পরিস্থিতি ছাড়া এপোয়ান্সে প্রবেশ করা কঠোরভাবে নিষিদ্ধ।"
  },
