  AwakerStory_142872_Content = {
    Text = "রাতের আকাশে উড়ে বেড়ানোর কথা ছিল যে বীরগাথার, তা হঠাৎ থেমে গেল — সে বেছে নিল অতল গহ্বরে পতন, নিজেকে উৎসর্গ করল এক মহত্তর ও রহস্যময় সত্তার কাছে।\nসেই থেকে তাকে আর মুখোমুখি হতে হলো না বিচ্ছেদের, সাধারণত্বের, কিংবা অনিবার্য অবক্ষয়ের।\nতার স্বজন, বন্ধু, শত্রু — সকলকে সে চিরকালের জন্য রেখে গেল সেই এপোয়ান্সে, যা তার সাথে একীভূত হয়ে গেছে।"
