  AwakerStory_142873_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_146395_Content = {
    Text = "যেকোনো মাত্রার লোটানই যেন কথা বলতে পছন্দ করেন না, আর ক্ষয়·রোটান তো আরও বেশি তাই। তার সামনে ভাষা অপ্রয়োজনীয়, শক্তি নিজেই সবচেয়ে নিখুঁত অলংকার।\nরাজার মতো স্থির ও মার্জিত বাহ্যিক আবরণের নিচে, মৃত্যুপথযাত্রী নক্ষত্রের মতো তার বিভিন্ন রঙের দুই চোখে দহন করে তার সবচেয়ে সত্য আকাঙ্ক্ষা — সে তারার সমুদ্রের গভীর থেকে উঠে আসা সুপ্রাচীন শক্তি, কেওসের ক্রোধে গড়া শ্বেত অস্থির ব্লেড। তার চোখে সমস্ত কিছু মাত্র দুই ভাগে বিভক্ত: যুদ্ধের যোগ্য, আর তরবারি তোলার অযোগ্য।\nতারাকাশের তিমির হাড় দিয়ে তৈরি সেই বিশাল দুই তরবারি সর্বদা ক্ষুধার্ত, ঠিক যেমন শক্তির শীর্ষের প্রতি তার আকাঙ্ক্ষা কখনো তৃপ্ত হয় না।"
  },
  AwakerStory_146395_Title = {
    Text = "প্রাথমিক তথ্য"
