  AwakerStory_146395_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_146396_Content = {
    Text = "তার প্রথম স্মৃতিতে শুধু ক্রোধ ছিল।\nকোনো মুখ নেই, কোনো দেহের সীমানা নেই, শুধু অনন্ত, ফুটন্ত হিংসার প্রবৃত্তি। সে ছিল তারাসমুদ্রের গভীরে জমাট বাঁধা কেওস, কোটি কোটি বছরে পরিপক্ব হওয়া ক্লাদেস। সে ছিন্ন করত, দহন করত, গ্রাস করত — কোনো উদ্দেশ্যে নয়, শুধু কারণ এটাই ছিল তার একমাত্র জানা কাজ।\nতারপর সেই শ্বেত-বস্ত্রাবৃত 「神明」 এলেন। যেন একটি নক্ষত্রকে তার কোর থেকে দুই ভাগ করা হলো, সে অনুভব করল তার শক্তি জোয়ারের মতো সরে যাচ্ছে, কারো ও অস্থি মন থেকে শিকড়সহ উপড়ে নেওয়া হচ্ছে, উত্তাল ক্রোধের শিখা জীবন্তভাবে আত্মা থেকে ছিঁড়ে নেওয়া হচ্ছে।\n\nদেবতা তার ক্রোধ প্রশমিত করতে পারলেন না, তাই তার আত্মা ও দেহের বিচ্ছেদ ঘটানো বেছে নিলেন।\nকেওসের পশু আর রইল না, তার দেহ লেভিয়াথানে পরিণত হলো, তার সমস্ত শক্তি নিয়ে শূন্যতায় ডুবে গেল। আর সে — শুধু মন অবশিষ্ট একটি ধ্বংসাবশেষ — শূন্য চেতনায় জেগে উঠল।\nক্রোধের আগুন নেভেনি, বরং আরও দীর্ঘস্থায়ী, আরও ভয়ঙ্কর কিছুতে রূপান্তরিত হলো: আকাঙ্ক্ষা। শক্তির অনন্ত আকাঙ্ক্ষা তাকে আবার উঠে দাঁড়াতে তাড়িত করল।\nসে হাঁটতে শুরু করল, যুদ্ধ করতে শুরু করল। সে বিরান তারাসমুদ্রের মধ্যে ঘুরে বেড়াল, সামনে আসা সকল শক্তিশালীকে চ্যালেঞ্জ করল। প্রতিটি জয় যেন ফাঁকা খোলে এক মুঠো বালি ঢালার মতো ছিল, সে ধীরে ধীরে সেই বালি থেকে একটি আকৃতি, একটি ইচ্ছাশক্তি, 「蚀灭·萝坦」-এর একটি রূপরেখা তৈরি করল।\n\nতারপর, সে সেই তিমির গান শুনল।\nযে তারাকাশের তিমি তার দেহকে সমগ্র জগৎ বানিয়েছিল, যে বিশাল সত্তা হাজারো প্রাণীকে দাসত্বে বেঁধে রেখেছিল — তার মধ্যে সে লোভ বা ভয় দেখল না, দেখল পরিচিতি। তার স্মৃতি ফিরে আসতে লাগল, সে জানল এটাই তার শক্তি, সে জানল, শুরু থেকে শেষ পর্যন্ত, তিনি ছিলেন তারই।\nতাই, সে তাঁর সামনে এলো।\nতাই, সে তাঁর দিকে তরবারি তুলল।\n\nবিশাল তিমির ক্ষমতা বাঁধ ভাঙা বন্যার মতো তার দেহে প্রবেশ করল, প্রায় তাকে ছিন্ন করে দিল, কিন্তু শুরু থেকে শেষ পর্যন্ত সে দাঁড়িয়ে রইল। তারাসমুদ্রে যোগ হলো একটি বিশাল তিমির অস্থিকঙ্কাল।\nদাসত্বে বন্দী গ্রহগুলো মুক্তি পেল। লোভে মৃত আত্মারা মাথা তুলে ঊর্ধ্বদৃষ্টি দিল, তাকে ত্রাণকর্তা, রক্ষাকর্তা বলল, তার সামনে মুকুট পাঠাল।\nক্ষয়·রোটান সেই প্রশংসায় সাড়া দিল না। সে শুধু বিশাল তিমির মৃতদেহের উপর দাঁড়িয়ে রইল, দেহের ভেতরে উথলে ওঠা নবজন্মের শক্তি অনুভব করল, আত্মার গভীরে সেই কখনো না-মেলানো আহ্বান আগের চেয়ে অনেক স্পষ্ট হয়ে উঠতে শুনল।\nএটি ছিল তারাকাশের তিমির কণ্ঠস্বর, এটি ছিল তার নিজের কারো যা তাকে আহ্বান করছিল।\n\nতার হাত লেভিয়াথানের মাথার খুলি স্পর্শ করল, অগণিত যুগ ধরে বিচ্ছিন্ন আত্মা ও দেহ পুনরায় মিলিত হলো। অস্থির বর্ম তার দেহ ঢেকে ফেলল, শক্তি তার সত্তাকে পূর্ণ করল।\nকেওসের পশু পুনর্জন্ম নিল, কিন্তু সে আর সেই আদিম ক্রোধে অন্ধ ক্লাদেস নয়। দীর্ঘ পরিভ্রমণ, অসংখ্য যুদ্ধ, যে প্রতিদ্বন্দ্বীরা তার কাছে পরাজিত হয়েছিল এবং যারা তাকে পরাজিত করেছিল — তারা এই বিশুদ্ধ কেওসকে ইচ্ছাশক্তিসম্পন্ন একটি ধারালো ফলায় পরিণত করেছিল।\nসে চোখ বন্ধ করল, দেহের ভেতরে উথলে ওঠা, সম্পূর্ণ শক্তি উপভোগ করল, কিন্তু সে স্পষ্টভাবে জানত, এটি শেষ নয়।\n\nতারাকাশের তিমির ক্ষমতা, লেভিয়াথানের শক্তি, যে নক্ষত্রগুলো গ্রাস করা হয়েছিল… সবই পেছনের সিঁড়ি। সে অস্থি তরবারি তুলে নিল, ঘুরে দাঁড়িয়ে পরবর্তী অজানা তারাসমুদ্রের দিকে হাঁটতে লাগল।\nসে আকাঙ্ক্ষা করছিল — পরবর্তী সেই যুদ্ধের জন্য যা তাকে উত্তাল করে তুলবে।"
  },
