  AwakerStory_146397_Content = {
    Text = "ক্ষয়·রোটান কখনো পেছনের মৃতদেহের দিকে ফিরে তাকায় না।\nপরাজিত প্রতিদ্বন্দ্বী, পদদলিত বিরান প্রান্তর, গ্রাস করা নক্ষত্র… সে একে একে সেগুলো পেরিয়ে যায়, পরবর্তী গন্তব্য খুঁজতে থাকে।\n\nকেউ তাকে জিজ্ঞেস করেছিল, শক্তির শেষ প্রান্তে পৌঁছানোর পর কী করবে।\nসে উত্তর দেয়নি, কারণ এই প্রশ্নটি সম্পূর্ণ অর্থহীন — যেমন জিজ্ঞেস করা যে আগুন নিভে গেলে কোথায় যাবে। আগুনের কোনো 「পরে」 নেই, দহনই তার অস্তিত্বের সবটুকু।\n\nসে হাঁটে, সে যুদ্ধ করে, সে বারবার তরবারি তোলে — কখনো প্রমাণের জন্য নয়, রক্ষার জন্য নয়, প্রতিশোধের জন্য নয়, ক্ষমতার লোভে নয়, বা অন্য কোনো বিরক্তিকর কারণে নয়।\nশুধু কারণ, তরবারি ও তরবারির সংঘর্ষের সেই মুহূর্তে, শক্তি ও শক্তির মুখোমুখি হওয়ার সেই ক্ষণে, সে সবচেয়ে স্পষ্টভাবে অনুভব করতে পারে যে সে বেঁচে আছে।\n\nশক্তির সন্ধানের পথ → শূন্য। আর সে এতেই আনন্দিত।"
  },
