  AwakerStory_146399_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_147418_Content = {
    Text = "গোল্ডপোর্ট শহরের পশ্চিম পাহাড়ে অবস্থিত খামারবাড়িটি এখন এক জনশূন্য মরুভূমিতে পরিণত হয়েছে, আর কেউ সেখানে বাস করে না।\n@2 সালের 15ই জুন, একটি উল্কাপিণ্ড এখানে পতিত হয়। কয়েক সপ্তাহ পর, উল্কাপতন এলাকার বাস্তুতন্ত্র বিকৃত হতে শুরু করে—গাছপালা অস্বাভাবিকভাবে বেড়ে উঠে উদ্ভট ফল ধরে; প্রাণীরা রূপান্তরিত হয়, এবং একটি পরিবারের সকল সদস্য মানসিকভাবে বিপর্যস্ত হয়ে রহস্যজনকভাবে মৃত্যুবরণ করে।\nমিসাগার্ড তদন্তকারীরা সেই এলাকায় ব্যাপক অনুসন্ধান চালায় এবং অবশেষে একটি কূপের তলদেশে অদ্ভুত বর্ণ বিকিরণকারী একটি সিলভার কোর আবিষ্কার করে। সেই সময়ের দায়িত্বপ্রাপ্ত তদন্তকারীর স্মৃতিচারণ অনুযায়ী, সেই সিলভার কোরের বর্ণ ছিল 「বিশুদ্ধ, সর্বত্র প্রবাহমান রঙ, যা পরিচিত বর্ণালীর কোনো রঙের সাথেই পুরোপুরি মেলে না।」\n\n——মিসাগার্ড বিশ্ববিদ্যালয় সিলভার কোর সংরক্ষণ নথি থেকে উদ্ধৃত"
  },
  AwakerStory_147418_Title = {
    Text = "গল্প: ১"
  },
  AwakerStory_147418_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_147419_Content = {
    Text = "1. D03–এর সঙ্গে সরাসরি চোখাচোখি এড়িয়ে চলুন, নইলে সে প্রতি সেকেন্ডে 20 ইয়ার্ড বেগে ছুটে আসবে, তার বোনকে খুঁজে পেতে সাহায্য চাইতে।\n2. সে ক্রমাগত তাপ বিকিরণ করে; একবার দেখেছি, তার হাতে ধরা একটি ড্যাফোডিল মুহূর্তেই কুঁকড়ে শুকিয়ে গেল। আহা, পরিবেশবাদীদের জন্য কী ভয়াবহ দুঃস্বপ্ন!\n3. সে সত্যিই রাতে জ্বলে ওঠে! এত উজ্জ্বল! D03 থাকলে মিথাগ–এর সত্যিই আর রাস্তার বাতির দরকার নেই। আমার চোখ আর সইতে পারে না!\n4. ক্যাফেটেরিয়ায় ভুল করে D03–এর হাতে ছুঁয়ে গিয়েছিলাম—কসম, ইচ্ছে করে না! অনুভূতিটা ছিল অদ্ভুত... যদি বর্ণনা করতেই হয়, তবে বলব, যেন মাল্ট সিরাপ, ছাগলের চিজ আর আপেল পুডিং ছুঁয়ে দেখছি... উফ, এখন তো আবার ক্ষুধা লাগছে।\n5. শুনেছি শ্যাডো কায়ার একবার D03–কে দলে টানতে চেয়েছিল, কিন্তু যত দ্রুত ডেকেছিল, তার চেয়েও দ্রুত বের করে দিয়েছে। বোঝাই যায়—মানুষের স্বরযন্ত্রেরও তো সীমা আছে, তাদের ধাক্কাটা আমি অনুভব করতে পারি।\n\n—হান্না–র 「জাগরণ পর্যবেক্ষণ নোটসD03」 থেকে উদ্ধৃত"
  },
