  AwakerStory_147420_Content = {
    Text = "তার গানে নিজ গ্রহে অগণিত মানুষের হৃদয় নড়ে উঠত।\nনিদ্রাহীন রাতে, বালকেরা তার গানের সুরে ভেসে স্বপ্নে ডুবে যেত।\nগুঁড়ি গুঁড়ি বৃষ্টিতে, পথিকেরা তার সুর শুনে দীর্ঘশ্বাস ফেলত।\nহারানো প্রেমের হাওয়ায়, প্রেমিকেরা তার কণ্ঠে শেষ অশ্রু ঝরাত।\nএখন, তার শ্রোতারা বাতাসে বিলীন, রেখে গেছে অসমাপ্ত সব গল্প..."
  },
  AwakerStory_147420_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_147420_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_147421_Content = {
    Text = "「গাও! গানটি এক মৃদু বাতাস\nমেঘের ওপারে উড়ে যায়, নক্ষত্র পেরিয়ে যায়\nএই পৃথিবী আর আমাকে স্পর্শ করে না।「\n— অ্যালবাম 「তারার রঙ」 ওভারচার থেকে\n\nএকসময় উজাড় গ্রহের এক খ্যাতিমান গায়ক ছিল সে।\nবিপর্যয় নেমে এলে, সে নিজের টিকিটটি ম্যানেজারকে দিয়ে দেয়, কারণ সে 「বোনকে ছেড়ে যেতে পারবে না।」\nসে নির্লিপ্ত চোখে দেখল অভিজাতদের জাহাজ ধীরে ধীরে সরে যাচ্ছে। একদা উন্মুক্ত সেই জাঁকজমকপূর্ণ দরজা এখন সম্পূর্ণ বন্ধ। যা রয়ে গেল, তা কেবল মরুভূমি, তার বোন, আর অগণিত স্বজাতি।\nতারা নীরবে মৃত্যুর কাউন্টডাউন শুনল।\n\nদশ বছর, কুড়ি বছর, একশ বছর... টিঙ্ক্ট তার গানে সকলে」কে সান্ত্বনা দিয়েছে।\nতার গলা রক্তাক্ত হওয়া পর্যন্ত, সে বদলাতে পারেনি বোন আর স্বজাতিদের একে একে মৃত্যুর বাস্তবতা।\n\nগায়িকা টিঙ্ক্ট একা হাঁটত সাদা মরুভূমিতে, প্রায়ই কল্পনা করত তার বোন এখনো বেঁচে আছে।\nতারা আগের মতোই একে অপরকে তোষামোদকারীর আলিঙ্গনে জড়িয়ে ধরে, টুকরো টুকরো হয়ে পড়তে থাকা নক্ষত্রের দিকে তাকিয়ে থাকে, নীরবে জ্বলতে থাকা যুদ্ধজাহাজের অবশিষ্টাংশ।\nসে কখনো গান থামায়নি। কর্কশ কণ্ঠ নিয়েও, প্রতিটি শ্বাসে আশপাশের সব প্রাণ গ্রাস করত।\nগায়ক কেবলই নিস্তেজভাবে গেয়ে গেছে, দিন গুনে গুনে।\nযতক্ষণ সে গান গেয়েছে, 「এই পৃথিবী আর তাকে স্পর্শ করেনি।」"
  },
  AwakerStory_147421_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_147421_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_147422_Content = {
    Text = "「যখন একজন মানুষ সবসময় অতীত স্মরণ করে, তার মানে সে বৃদ্ধ হয়ে গেছে।」\nএই পুরনো প্রবাদ অনুসারে বিচার করলে, টিঙ্কটের বয়স মহাবিশ্বে যুগ যুগ ধরে প্রদক্ষিণরত নক্ষত্রের মতো প্রাচীন হওয়া উচিত।\nতার চেতনায় কোনো বর্তমান নেই, ভবিষ্যতও নেই, আছে শুধু অর্থহীনভাবে দীর্ঘায়িত, অবিরাম পুনরাবৃত্ত অতীত।\n\nসে একদা দেখেছিল সোনালি আতশবাজি সুনামির মতো উঠে মহাজাগতিক তারকাপুঞ্জে তার ডানা মেলে ধরছে;\nসে একদা দেখেছিল অসংখ্য ভিন্ন ভিন্ন মুখ অন্ধকারে লুকিয়ে তার সুরের তালে উন্মত্ত নৃত্য করছে;\nসে একদা দেখেছিল সমস্ত আকাশ তাকে ডাকছে, তাকে ঘিরে আবর্তিত হচ্ছে, তাকে দেখাচ্ছে তাদের চিরন্তন মহিমা।\nকিন্তু তার দুই চোখ শুধু এই দুঃখক্লিষ্ট ভূমির দিকেই নিবদ্ধ ছিল।"
  },
  AwakerStory_147422_Title = {
    Text = "গল্প: ৪"
