  AwakerStory_147422_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_148397_Content = {
    Text = "এই সিলভার কোরটি মিথাগ রক্ষক %player% কর্তৃক @2 শৃঙ্গ ধ্বংস ঘটনার পর উদ্ধার করা হয়েছে। যেহেতু এর মূল মাত্রাটি আর পর্যবেক্ষণযোগ্য নয়, তাই সিলভার কোর নিষ্কাশনের পরবর্তী প্রভাব এবং প্রকৃত জাগরণ পদ্ধতি এখনো অজানা। \nনিচের বিষয়বস্তু রক্ষক %player%-এর সাথে বহন করা কাগজের নোটবুকে লিপিবদ্ধ: \nখালি চোখে পর্যবেক্ষণ করলে সিলভার কোরের গঠন অত্যন্ত বিশুদ্ধ, কোনো দৃশ্যমান অপদ্রব্য নেই। বাহ্যিক শক্তির হস্তক্ষেপ না থাকলে সামগ্রিক কাঠামো নিয়মিত আকার ধারণ করে, মনে হয় যেন কোনো এক ইচ্ছাশক্তি এটিকে দৃঢ় ও স্থিতিশীল দেখাতে চেষ্টা করছে, এবং এটি হীরার আগুনের মতো উজ্জ্বল দীপ্তি বিকিরণ করে। তবে এই সিলভার কোরের নস্টিক সূচক প্রায় সীমার নিচের মানে পৌঁছে গেছে, প্রকৃত অভ্যন্তরীণ কাঠামো অত্যন্ত ভঙ্গুর ও আলগা। পর্যবেক্ষণ দূরত্ব 1/@1 ইঞ্চির কম হলে সিলভার কোরের আত্মরক্ষামূলক আচরণ সক্রিয় হয়, পর্যবেক্ষক হঠাৎ বরফকণার মতো প্রবাহমান অসংখ্য কণা দেখতে পাবেন। ধারণা করা হচ্ছে এগুলো এর আগে অত্যন্ত বিশেষ উপায়ে বাইরের আলো প্রতিফলিত করে সিলভার কোরের কেন্দ্রকে আড়াল করছিল। \nঅন্য কথায়, যদিও এটা খুব একটা পেশাদার মন্তব্য নয়, আমি মনে করি এটি 「প্রতারণায়」 পরিপূর্ণ একটি সিলভার কোর। \nসিলভার কোরের আত্মরক্ষামূলক প্রক্রিয়া সক্রিয় হওয়ার পর পর্যবেক্ষকের শরীর সাময়িক অসাড় অবস্থায় পড়ে, চোখের মণি ধীরে ধীরে বিবর্ণ হয়ে শেষ পর্যন্ত সম্পূর্ণ ফ্যাকাশে হয়ে যায়। এই সময়ের মধ্যে সিলভার কোর নিজেকে পুনর্বিন্যস্ত করে, পর্যবেক্ষণের আগের স্থিতিশীল অবস্থায় ফিরে আসে। একাধিক পরীক্ষার পর দেখা গেছে, এই আত্মরক্ষামূলক প্রক্রিয়া প্রকৃত ক্ষতি করে না, তবে এর ফলে সৃষ্ট হাইপোথার্মিয়ার লক্ষণ এখনো কিছুটা বিপজ্জনক। দ্রষ্টব্য: সময়মতো মিষ্টি খাওয়া, বিশেষত আপেল জাতীয় মিষ্টান্ন উল্লেখযোগ্যভাবে উপশম দেয়, কারণ... এখনো স্পষ্ট নয়, তাই না? সুখবর হলো, এই সব ঘটনার পরেও এই স্বার্থপর, মনে মনে স্তরে স্তরে সতর্কতায় ভরা ছোট্ট প্রতারকটির আমাদের প্রতি আসলে কোনো দুরভিসন্ধি নেই। \n——《মিসাগ বিশ্ববিদ্যালয় সিলভার কোর সংরক্ষণ রেকর্ড》 থেকে উদ্ধৃত"
  },
