  AwakerStory_148397_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_148398_Content = {
    Text = "নিচের বিষয়বস্তু কারাবুর বর্ণনা অনুযায়ী মিথাগ জাগরণকারী সিস্টেম পটভূমি তদন্ত দল কর্তৃক সংকলিত ও লিপিবদ্ধ: \nকারাবুর শৈশবকালে ক্রুসেডের উত্তাল সময় চলছিল। নিঃসঙ্গ ও অসহায় সে পূর্বদিকে আন্টিওক রাজ্যে চাচার পরিবারের কাছে যাওয়ার সিদ্ধান্ত নেয়। শোনা যেত পূর্বের নতুন ভূমি স্বাধীনতা ও স্বপ্নের প্রতীক, সেখানে নিঃস্ব মানুষও নিজের পথ খুঁজে নিতে পারে। খালা রোজা এমনকি একটি বাগান পরিচালনা করতেন এবং বেশ ভালোই ছিলেন। শৈশবে কারাবু খালা রোজার সাথে অত্যন্ত ঘনিষ্ঠ ছিল, সে মনে মনে ঠিক করল আন্টিওকে যাওয়ার ভাড়া জমাবে। \nকারাবু শহরের বস্তিতে ঘুরে বেড়াত, কোনো পরিচয় না থাকায় চুরি-প্রতারণার মাধ্যমে টিকে থাকতে হত, তার সহজ-সরল দিকটি ধীরে ধীরে মুছে গেল। পরে সে জাদুকর আইভার্গের সাথে পরিচিত হয়, সে কারাবুকে প্রতিশ্রুতি দিল যে তার সাথে কাজ করলে ভক্তদের নৈবেদ্য তিন-সাত ভাগে ভাগ হবে, এভাবে সে পূর্বে যাওয়ার ভাড়া জমাতে পারবে এবং প্রিয় ক্যান্ডিও কিনতে পারবে। দুজনে মিলে একটি প্রতারক জুটি গঠন করল, কারাবু ছোট্ট পরী গডমাদার হিসেবে গ্রামে অস্থায়ীভাবে নির্মিত মন্দিরে থাকত, আর আইভার্গ তার প্রধান পুরোহিতের পরিচয়ে ভক্ত সংগ্রহ করত। \nস্থানীয়ভাবে কারাবুর নাম-ডাক বাড়তে থাকায় সে বিদ্যমান ভাগ নিয়ে আর সন্তুষ্ট রইল না, সহযোগিতা থেকে সরে যাওয়ার হুমকি দিয়ে আইভার্গকে বাধ্য করল নৈবেদ্যর ভাগ সাত-তিনে পরিবর্তন করতে। অবশেষে সুবিধা পেয়ে কারাবু নকল গডমাদার হিসেবে আরামে দিন কাটাচ্ছিল, যতক্ষণ না সে আবিষ্কার করল আইভার্গ তার নৈবেদ্যর অর্থ আত্মসাৎ করে গোপনে তিনটি বিয়ে করেছে এবং চারটি ছেলেও হয়েছে। প্রতারণার মুখে কারাবু রাগ করল না, সে আবেগভরে আইভার্গকে বলল যে পূর্বে যাওয়া শুধু একটি অলীক স্বপ্ন, অর্থ তার কোনো কাজে আসবে না, বরং আইভার্গের কাছেই থাকুক, শুধু চায় আইভার্গের পরিবারের সাথে একসাথে রাতের খাবার খেতে এবং ভবিষ্যতের প্রতারণা ব্যবসা নিয়ে আলোচনা করতে। \nকারাবু অবশেষে বুদ্ধিমান হয়েছে দেখে অবাক ও খুশি হয়ে আইভার্গ তাকে ভোজে আমন্ত্রণ জানাল। রাতের খাবার শেষ হওয়ার কাছাকাছি সময়ে কারাবু হঠাৎ মুখ পাল্টাল, তার একটি নির্দেশে আশেপাশের গ্রামবাসী, তার বিশ্বস্ত ভক্তরা হঠাৎ ঢুকে পড়ল এবং কৃষি ও রান্নাঘরের সরঞ্জাম হাতে জাদুকরের আট সদস্যের পরিবারকে অর্ধমৃত করে পিটিয়ে বাড়ির মূল্যবান সব কিছু লুট করে নিয়ে গেল। \"আমাকে ঠকাতে এখনো অনেক দেরি\"——কারাবু তৃপ্তিভরে চলে গেল, তখনো খেয়াল করেনি তার কপালে ছোট্ট কালো ত্রিভুজটি......"
  },
  AwakerStory_148398_Title = {
