  AwakerStory_148400_Content = {
    Text = "সে যেন সবচেয়ে বুদ্ধিমান শিশু, সর্বদা তোমার সবচেয়ে গোপন মনের কথা বুঝতে পারে, সবসময় তোমাকে বিশ্বাস করতে ও মনের কথা বলতে বাধ্য করে, তারপর ঠিক সঠিক মুহূর্তে তোমাকে সেই কাঙ্ক্ষিত 「আশীর্বাদ」 প্রদান করে। কিন্তু মনে রেখো, তার ছোট্ট কোমল দেহ ও করুণ চাহনি দেখে কখনো দয়া করো না, নইলে সেই শুভ্র দেহ যে লোভী অতৃপ্ত আত্মাদের গ্রাস করেছে, তুমিও তাদের একজন হয়ে যাবে।"
  },
  AwakerStory_148400_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_148400_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_148401_Content = {
    Text = "তুমি কি কখনো মিথ্যা বলেছ? প্রথম মিথ্যাটি মুখ থেকে বেরোনোর সময় সবসময় সাথে থাকে আড়ষ্ট ঠোঁট-জিভ, প্রায় গলা ছেড়ে বেরিয়ে আসা হৃদস্পন্দন আর হাতের তালুর ঘাম, এমনকি উষ্ণ রোদও মাথা ঘোরানো ঝলমলে আলোয় পরিণত হয়। \nকিন্তু যখন মিথ্যা দশ হাজার বার পুনরাবৃত্তি হয়, ভয় মিলিয়ে যায়। বলা কথাগুলো সাবলীল হয়ে ওঠে, চিন্তা ক্রমশ স্বচ্ছ হয়, হাসিও স্বাভাবিক হয়ে স্থায়ী হয়ে যায়। \nপরী সাজা, গডমাদার সাজা, কোনো ক্ষমতাধরের আত্মীয় সাজা, সে তার নিজের তৈরি হাজারো পরিচয়ে পারদর্শী হয়ে উঠেছে, মিথ্যার আড়ালে নিজেকে লুকিয়ে রাখতে অভ্যস্ত হয়ে গেছে, এমনকি নিজেও মিথ্যার একটি অংশ হয়ে গেছে। \nকিন্তু সেই প্রথম বন্য খরগোশটি এখনো স্মৃতির মধ্যে সন্ধ্যার আলোয় ভেসে থাকা ছোট্ট বাগানে লুকিয়ে আছে। \nবরফ গলা রাতে, চুপিচুপি মাথা তুলে উঁকি দেয়।"
  },
  AwakerStory_148401_Title = {
    Text = "গল্প: ৪"
