  AwakerStory_148401_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_148994_Content = {
    Text = "দেহ একই থাকলেও, মানুষ এক নজরেই বুঝতে পারত তার আর সেই পরিচিত ছোট্ট নাইটের মধ্যে পার্থক্য।\nআগের সেই স্বচ্ছ দুটি চোখ আর উজ্জ্বল নয়, শুভ্র পোশাক কলুষিত হয়ে গেছে, আর সে সবসময় ইচ্ছাকৃতভাবে সকলের থেকে দূরত্ব বজায় রাখে।\nকিন্তু ভয়ের কিছু নেই — সেই ভয়ঙ্কর কালো কাদার নিচে এখনও সেই পরিচিত হৃদয় স্পন্দিত হচ্ছে, বিশ্বস্ততা ও ন্যায়ের জন্য।\nএকসময় ভুলে গেলেও, শেষ পর্যন্ত সে সেই নাইটের শপথগুলো আবার কুড়িয়ে নিয়েছে।\nসে লড়াই চালিয়ে যাবে — তার ভেতরের সেই অন্য কণ্ঠস্বরের বিরুদ্ধে, আর যা কিছু তার প্রিয় জিনিসকে আঘাত করে তার বিরুদ্ধে।"
  },
  AwakerStory_148994_Title = {
    Text = "প্রাথমিক তথ্য"
