  AwakerStory_149051_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_149052_Content = {
    Text = "প্রিয় পাঠকগণ, এটি একটি উপসংহার, এবং একইসাথে আমার স্বীকারোক্তি।\nএই পুরনো ধাঁচের ক্লাসিক নাইট উপন্যাসটি সম্পূর্ণ করতে, আমি বিশাল অর্থ ব্যয় করে সেই রহস্যময় শিরস্ত্রাণটি নিলামে কিনেছিলাম — বলা হয়, এটি ইতিহাসে নথিভুক্ত কোনো রাজ্যের নয়। আপনারা দেখতেই পাচ্ছেন, তার কল্যাণে আমার অনুপ্রেরণা অবিরাম প্রবাহিত হয়েছে, যেন সত্যিই এক বিশাল প্রাচীন রণক্ষেত্র দেখতে পাচ্ছিলাম, যেখানে বর্মধারী নাইটরা তরবারি নিয়ে মুখোমুখি। এই অদ্ভুত দর্শনের উপর ভর করেই আমি আমার মনের সবচেয়ে নিখুঁত রচনাটি সম্পূর্ণ করেছি।\nকিন্তু আমি কখনো ভাবিনি যে এই প্রাচীন বস্তুটি আমাকে অনুপ্রেরণা দেওয়ার পাশাপাশি একটি ভয়ঙ্কর দানবকেও লুকিয়ে রেখেছে।\nপাঠকগণ, একটু কল্পনা করুন — একটি কণ্ঠস্বর, বিশৃঙ্খল, অবিরাম, দিনরাত থামে না। তারপর কল্পনা করুন আপনার অঙ্গ-প্রত্যঙ্গ নিয়ন্ত্রণের বাইরে চলে যাচ্ছে, চেতনা বারবার ছিন্ন হচ্ছে — না, ছিন্ন নয়, বরং যেন ইচ্ছাশক্তি দেহ ছেড়ে বেরিয়ে গেছে, আপনি স্পষ্ট বুঝতে পারছেন কী হচ্ছে, কিন্তু কেবল দর্শক হয়ে থাকতে পারছেন......অথচ এটা স্পষ্টতই আমার শরীর।\nগতকাল রাতে, যখন আমি এইমাত্র উপন্যাসটি শেষ করলাম, আমি আবার তাঁকে শুনলাম।\nতারপর, অভিশাপ, আমি সেই দৃশ্যগুলো মনে করতে চাই না——\nআমি এমন পাপ করেছি যা আর ফেরানো যাবে না, সংবাদপত্র এই বইয়ের আগেই আপনাদের জানিয়ে দেবে......\nতিনি, আবার, আবার শুরু——\n(অক্ষর বাঁকা হয়ে গেছে)\nনা না না না না না না না, আমি আর পারছি না——\n......\n\n(অক্ষর আবার স্পষ্ট হয়েছে)\nআশ্চর্যজনক, তিনি থেমেছেন, যেন কিছু একটা তাঁকে চেপে ধরেছে, আমি জানি না সেটা কী, কিন্তু সেই প্রতিরোধের জন্য আমি কৃতজ্ঞ।\nহয়তো ঈশ্বর আমাকে শেষ একটি সুযোগ দিচ্ছেন, যাতে আমি সম্পূর্ণ শয়তানে পরিণত না হই।\n\nআমার বন্দুকে ইতিমধ্যে গুলি ভরা আছে।\nঈশ্বর আমাকে ক্ষমা করুন।\n\n\n——লেখক ক্লার্ক জিরোসের শেষ রচনা 《ছায়াহীন নাইট》-এর উপসংহার থেকে উদ্ধৃত"
  },
  AwakerStory_149052_Title = {
    Text = "গল্প: ১"
