  AwakerStory_149052_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_149064_Content = {
    Text = "পাপের প্রতীক সেই গাঢ় কালো কাদা এখনো তার ভেতরে ফুটছে, এই দেহটিকে আবার নিয়ন্ত্রণ করতে মরিয়া, তাকে সেই ভঙ্গুর সুতো আঁকড়ে ধরতে হয় অবিরাম, নইলে হেরে যাবে।\nআর সে নিজের জন্য নতুন করে যা খুঁজে পেয়েছে — রক্ষা করার যোগ্য জিনিস — তা-ই হয়ে উঠেছে বিবেক ধরে রাখার একমাত্র নোঙর।\nসে আর মাতৃভূমিতে ফিরতে পারবে না, কিন্তু মিথাগ তার নতুন দুর্গ হয়ে উঠেছে।\nসে আর রাজকুমারীকে রক্ষা করতে পারবে না, কিন্তু ভাগ্য নতুন সাক্ষাতের সুযোগ তৈরি করবে।\nকোনো সাক্ষী ছাড়া একাকী জায়গায়, কিশোর এক হাঁটু গেড়ে বসল, একটি হাত ঠান্ডা বুকের উপর রেখে, অনুপস্থিত প্রভুর উদ্দেশ্যে ঘোষণা করল।\n「আমি আপনার আদেশ মেনে চলব, চিরকাল আপনাকে ও আপনার জগতকে রক্ষা করব, জীবন পুড়িয়ে দিলেও, আত্মা নিঃশেষ হয়ে গেলেও।」\n「......এটাই, আমার নতুন করে কাঁধে তুলে নেওয়া শপথ।」"
  },
  AwakerStory_149064_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_149064_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_149065_Content = {
    Text = "সে-ও একসময় ঘুমানোর আগের রূপকথার মতো নিজের যাত্রায় বেরিয়েছিল।\nকিন্তু সে ন্যায়ের গুণগান করা নাইট ছিল না, আর পৃথিবীতেও উদ্ধারের অপেক্ষায় থাকা কোনো রাজকুমারী ছিল না।\nসে যাদের হত্যা করেছিল, তারা ভয়ঙ্কর দুষ্ট ড্রাগন নয়, বরং আর্তনাদ করতে করতে পালানো, নিরস্ত্র সাধারণ মানুষ।\n「তরুণ নাইট দুষ্ট জাদুকরকে হত্যা করল, একগুঁয়ে শত্রুসেনাকে পরাজিত করল, দানবের দুর্গ পুড়িয়ে দিল......\nসে ছিল সাহসী, শক্তিশালী, অজেয়। এই অন্তহীন পথে, শুধু একটি দীর্ঘ রক্তের দাগ রেখে গেল।」\nযদি পৃথিবীতে স্বপ্ন আর বাস্তবের পার্থক্য করতে না পারা কোনো ভ্রমণকারী কবি থাকত, সে নিশ্চয়ই এই অভিজ্ঞতাকে এভাবেই সাজিয়ে তুলত।\nকিন্তু গল্পের নায়ক আসলে সজাগ ছিল, সেই দুটি চোখে কখনো মিথ্যার প্রতিফলন পড়েনি।\nসে জানত, তার বন্দুকের ডগা বৃদ্ধের বুক ভেদ করেছে, কালো কাদা ইতিমধ্যে আত্মসমর্পণ করা পরাজিত সৈনিকদের গ্রাস করেছে, সেই সুন্দর ছোট্ট বাড়িটি — কোনো এক পরিবারের — তার পথ পেরিয়ে যাওয়ার পর ছাইয়ে পরিণত হয়েছে......শুধু কারণ এরা সবাই সেই মানুষের সাথে সম্পর্কিত যে তার রক্ষিত জিনিস কেড়ে নিয়েছিল।\nসে জানত, সে কখনো রূপকথার মধ্যে ছিল না, সেই রোমান্টিক কল্পনাগুলো মাতৃভূমির সাথেই সম্পূর্ণ মরে গিয়েছিল — হয়তো সেই মুহূর্তে সে বড় হয়ে গিয়েছিল, হয়তো এখনো অপরিপক্ব শিশু।\nযতক্ষণ না সে অবশেষে জেগে উঠল, অপরিচিত মানুষদের জন্য জীবন উৎসর্গ করতে গিয়ে হঠাৎ নিজের অশ্রুতে দেখল এমন এক ছায়া যা থাকার কথাই নয়।\n「ওজিয়ার, আমি তোমার প্রতি হতাশ, তুমি শুধু নামেমাত্র উপাধিধারী, সবচেয়ে অযোগ্য নাইট।」\n「রাজকুমারী」র মুখ যেন ঘোমটায় ঢাকা, কিন্তু তার কণ্ঠস্বর অস্বাভাবিকভাবে স্পষ্ট, পৃথিবীর যেকোনো তরবারির চেয়ে তীক্ষ্ণ, তার হৃদয় খুঁড়ে খাচ্ছে।\nএই নিষ্ঠুর দর্শন আজও তাকে যন্ত্রণা দেওয়া দুঃস্বপ্ন হয়ে আছে, মৃত্যুর সাথেও মিলিয়ে যায়নি।\nসে চিরকাল শপথ ভঙ্গের অনুশোচনায় বেঁচে থাকবে।"
  },
