  AwakerStory_60980_Content = {
    Text = "প্রথম দর্শনে, হামেল্ন তোমার মনে সবসময় এক ধরনের প্রাচ্য চীনামাটির বাসনের কথা জাগিয়ে দিত—শুভ্র, বিলাসবহুল, সুশোভিত বাঁক আর ঢেউয়ের মতো কোমল দীপ্তি নিয়ে, তবু স্পর্শে কিছুটা শীতল।\nওই সম্মানজনক, নিখুঁত বাহ্যিকতার নিচে লুকিয়ে আছে চূড়ান্ত, শূন্য পবিত্রতার এক আত্মা। তার সমগ্র জীবন ঘুরপাক খেয়েছে একটিমাত্র চিন্তাকে কেন্দ্র করে, যেন এক যন্ত্র, যার প্রোগ্রামে লেখা আছে কেবল একটি কমান্ড, অন্য সব প্রতিক্রিয়া মুছে ফেলা।\nতার কাছে, সবকিছুই ছিল কেবল সুরের ক্রমমাত্র।\nবাজাও, বাজিয়ে যাও, অন্তহীনভাবে বাজিয়ে যাও।"
  },
  AwakerStory_60980_Title = {
    Text = "প্রাথমিক তথ্য"
