  AwakerStory_60981_Content = {
    Text = "হ্যামলিন সবসময় ছাত্রদের সামনে উপস্থিত হন না, যদিও তিনি মিসাগারের আয়োজিত সংগীত সন্ধ্যায় উপস্থিত থাকতে রাজি, ছাত্রদের দুর্বল মানের সংগীত ক্লাসে নির্দেশনা দিতে রাজি, কিন্তু বেশিরভাগ সময়, তিনি একাই শব্দরোধী শ্রেণিকক্ষে, অথবা নির্জন বনের মধ্যে একা বাজান, বা বলা যায় অনুশীলন করেন।\nআনুষ্ঠানিক অনুষ্ঠান ছাড়া, তিনি সবসময় তার সমস্ত বাদনকে অনুশীলন বলে অভিহিত করেন, যেন সেই অনুশীলনের কোনো শেষ নেই, নিখুঁত সুরের ঝংকার কখনোই আসবে না।\n「সত্যিই চিরকাল শিক্ষানবিশের মনোভাব ধরে রাখা এক পরিশ্রমী ও বিনয়ী ওস্তাদ।」 সেই সংগীতে মুগ্ধ মানুষেরা এভাবে প্রশংসা করত।\nকিন্তু, হ্যামলিন কখনো জানেন না বিনয় কী জিনিস, তিনি সবসময় সেসব সামাজিক শিষ্টাচারের কথা ভাবতে অলস, বরং বলা যায় তার কথা সবসময় অতিরিক্ত সরাসরি, অতিরিক্ত কঠোর।\nসংগীতের ব্যাপারে তিনি সবসময় সবচেয়ে গুরুতর শুচিবায়ুতে ভোগেন, এতটাই যে সংগীত ক্লাসের মতো বিনোদনমূলক ও শিথিলকরণ কোর্সটি ছাত্রদের মধ্যে সবচেয়ে চাপের তালিকায় শীর্ষে উঠে গেছে, এবং হ্যামলিন নিজেও শয়তান শিক্ষকের 「সুনাম」 অর্জন করেছেন।\nএই শীতল সংগীতজ্ঞের দৃষ্টি আকর্ষণ করতে চাইলে, শুধু বাজানোর সময় একটি অর্ধস্বর ভুল বাজালেই যথেষ্ট, সেই মুখ সঙ্গে সঙ্গে ভ্রু কুঁচকে এদিকে তাকাবে।\nআসলে তিনি যাদের 「যন্ত্রণা」 দিয়েছেন তাদের প্রতি তার কোনো আপত্তি নেই, শুধু সেই উন্মত্ত বলা যায় এমন সাধনা ও মানদণ্ড অন্যদের উপর চাপিয়ে দিয়েছেন, যদিও সেটা তিনি নিজের প্রতি যা প্রয়োগ করেন তার চেয়ে অনেক বেশি সহনশীল।\nতিনি যেন মাথার উপরে গাজর ঝুলিয়ে রাখা ঘোড়ার বাচ্চার মতো, নিজের জন্য এমন এক লক্ষ্যরেখা ঝুলিয়ে রেখেছেন যা কখনো পৌঁছানো যায় না।\nসেই মার্জিত নৃত্যশিল্পীর জন্য থামা ছাড়া, তিনি প্রায় কখনোই অন্য জাগরিত সত্তাদের সাথে নিজে থেকে কথা বলেন না, কিন্তু অন্যদের সাহায্যের অনুরোধ ও কথোপকথনের মুখে, তিনি সবসময় অপ্রত্যাশিত ধৈর্য দেখান।\nসম্ভবত তাকে আটকে রাখে ঔদাসীন্য নয়, বরং অতিরিক্ত একমুখী জ্ঞানভাণ্ডার।"
  },
