  AwakerStory_60984_Content = {
    Text = "তার জীবন ছিল একঘেয়ে ও নিষ্প্রভ, সঙ্গী ছিল কেবল নিঃসঙ্গতা, আর বহু আগে, স্মৃতিরও পূর্বে হজম হয়ে যাওয়া বিদ্বেষ, বিভ্রান্তি ও ঘৃণার অনুভূতিগুলো।\nএখন, সে সঙ্গীতের সঙ্গে একাত্ম হয়ে গেছে, নিছক আবেগকেও অতিক্রম করে—অনিবার্য, অনিবার্যভাবে অবধারিত।\nতার কাছে যা অবশিষ্ট দেহ, তা কেবল সঙ্গীত।\nউর্ধ্বমুখী হতে থাকো; পেছনে ফেলে আসা নয়শ নিরানব্বইটি সিঁড়ির দিকে আর তাকিও না।\nঅবশেষে, সে তো ইতিমধ্যেই স্পর্শ করেছে চূড়ান্ত সুর, নিয়তির বাঁশি।\nএই অন্তহীন সঙ্গীতধারাকে গ্রহণ করো, আর তাকে তোমার আত্মা ও স্বপ্নলোক ভিজিয়ে দিতে দাও।\nকারণ অনেক আগেই সে নিজের আত্মাকেই ব্যবহার করেছে এক যন্ত্র হিসেবে, তোমার আত্মার সঙ্গে অনুরণনে।"
