  AwakerStory_66033_Content = {
    Text = "মিথ্যাগে টাওইল মাত্র তিনবার অবতার নিয়েছেন।\nপ্রথমবার, টাওইল প্রজ্বলিত করেছিলেন 「প্রজ্ঞা」-র স্ফুলিঙ্গ। দ্বাররক্ষক স্বপ্নের পথে পথ খুলে দিয়েছিলেন, অজ্ঞ প্রতিষ্ঠাতাদের বিরল জ্ঞান দান করেছিলেন। তাঁরা মিথ্যাগের প্রাথমিক 「থিঙ্ক ট্যাঙ্ক」 গড়ে দিয়েছিলেন, সঙ্গে দিয়েছিলেন ডিজলিউশন সম্পর্কে সূত্র ও অন্তর্দৃষ্টি।\nদ্বিতীয়বার, টাওইল এনেছিলেন 「পরিবর্তন」-এর ভবিষ্যদ্বাণী। কালো পুকুর উত্তাল হয়ে উঠেছিল, স্বাগত জানিয়েছিল সেই আগমনীকে, যে এই বিশ্বকে 「রূপান্তরিত」 করবে।\nতৃতীয়বার, তাঁরা প্রেরণ করেছিলেন 「সমাপ্তি」-র সংকেত। তাঁদের আর্তনাদ আর বিলাপ প্রতিধ্বনিত হয়েছিল সমগ্র পৃথিবী জুড়ে, তবু তা থামাতে পারেনি অনিবার্য বিশৃঙ্খলা ও ধ্বংসের অবতরণ।"
  },
  AwakerStory_66033_Title = {
    Text = "গল্প: ২"
