  AwakerStory_66034_Content = {
    Text = "কাদাথই তাওইলের রক্ষার একমাত্র স্বপ্ন নয়।\nদ্বাররক্ষক অসংখ্য গ্রহ ও ছায়াপথের জন্ম ও ধ্বংস প্রত্যক্ষ করেছে; অতীত ও ভবিষ্যতের ইতিহাস স্তরীভূত হয়ে জ্ঞানে পরিণত হয়েছে, শোষিত হয়েছে তাঁদের পশ্চাতে দাঁড়িয়ে থাকা চরমের দ্বারে। করুণায় পূর্ণ দৃষ্টিতে তাওইল এই সব দৃশ্যের দিকে নিচে তাকায়; সেগুলো তাঁদের স্বপ্নে ক্ষণিক ঝলকের মতো দ্রবীভূত হয়ে বিলীন হয়, অতল অন্ধকারে হারিয়ে যায়।\nএকদা তাওইল একখণ্ড ভূমিতে পদার্পণ করেছিল, কিন্তু যে মুহূর্তে তারা পেছনে ফিরে তাকাল, 「পরম ইচ্ছাশক্তি」-র নিঃশ্বাসে তাদের সব প্রিয় জিনিস ভেঙে গুঁড়িয়ে গেল।\nঅন্তহীন পুনরাবৃত্তির পর, তারা অবশেষে এক নির্মম সত্য অনুধাবন করল: তাদের অস্তিত্ব নিজেই এক দুঃস্বপ্নের প্রস্তাবনা; তাদের বিপুল উপস্থিতি মাত্রই 「পরম ইচ্ছাশক্তি」-র দৃষ্টি টেনে আনে। তাদের সম্মুখ হস্তক্ষেপ কেবল আরও গভীর অমঙ্গল ডেকে আনবে সেই জগতের ওপর, যাকে তারা হৃদয়ে লালন করে।\nঅতএব, তাওইল সরে গেল। তাওইল নীরব হলো।\nযতক্ষণ না তারা অসীম বিস্তারে ভাসমান চেতনার খণ্ডাংশের মধ্যে 「তার」 থেকে নির্গত এক ক্ষীণ পরিবর্তনের আভাস অনুভব করল..."
