  AwakerStory_66035_Content = {
    Text = "এক রহস্যময় স্বপ্নে, প্রথমবার আমি তাঁদের দেখেছিলাম।\nএক অন্তহীন, কুয়াশায় ঢাকা বিস্তারে তাঁরা পাহারা দিচ্ছিলেন এক মহিমান্বিত ও চিরন্তন দ্বার, যা অসংখ্য বিশাল মহাবিশ্বকে একসূত্রে বেঁধে রেখেছে। দ্বারের গভীর ফাটলের ওপারে অদ্ভুত মায়াস্বপ্ন মিটমিট করছিল, যেন অপঠিত সংকেতের ঝলক। একটি সংকেত ধরতেই অনুভব করলাম, আমার দেহ বিলীন হয়ে গেছে, আমি দিকহীন ভেসে বেড়াচ্ছি নক্ষত্রদের মাঝে, অবিশ্বাস্য এক অন্ধকারে মোড়া। আমি আতঙ্কিত; স্বপ্নটি প্রচণ্ডভাবে কেঁপে উঠল, ভারী দ্বারটি অপ্রতিরোধ্য শক্তিতে খুলে গেল, আর তার ওপারে অসংখ্য গোলক-সদৃশ বস্তু নক্ষত্রের মতো ঝলমল করছিল। সেই বিপুল, অগাধ দৃশ্য আমাকে মাথা ঘোরানো বিভ্রমে ডুবিয়ে দিল... আর দ্বারের রক্ষাকারী—টাওইল—নিঃশব্দে, চিরকালীন দৃষ্টিতে আমাকে দেখছিলেন।\n— ওয়ার্ড ফিলিপস, রৌপ্য চাবি নোটস"
