  AwakerStory_66036_Content = {
    Text = "প্রজ্ঞার যুগের প্রতিনিধি ও দ্বাররক্ষক হিসেবে টাওইলের নিজের সত্তা অনুসন্ধানের আকাঙ্ক্ষার কোনো অভাব ছিল না। টাওইল আকুল হয়ে চান, যাঁদের উপর নজর রাখেন, তাঁদের মতোই এই পৃথিবীতে হেঁটে বেড়াতে; সভ্যতার রূপান্তর, ইতিহাসের উত্থান-পতন নিজ চোখে দেখতে, আর যা কিছু দেখেন, সব সঞ্চয় করতে 「সর্বজ্ঞতা」 নামের এক ভাণ্ডারে। কিন্তু তাঁদের অস্তিত্ব তাঁদের প্রহর ত্যাগ করতে দেয় না। টাওইলের হৃদয়ের গভীরে, হয়তো যাকে তাঁরা সবচেয়ে বেশি হিংসা করেন, সে সেই মেয়েটি, যে বহন করে তাঁর ইচ্ছাশক্তির এক সূক্ষ্ম সুতো..."
