  AwakerStory_66037_Content = {
    Text = "বর্তমান জগতে টাওইল বলে কিছু নেই। তাঁদের অস্তিত্বই 「পরম ইচ্ছাশক্তি」র দৃষ্টি আকর্ষণ করত, তাই তাঁরা নেই, থাকতে পারেন না, থাকা উচিতও নয়। এই ক্লান্তিহীন অনুসন্ধানীদের জন্য দ্বাররক্ষক যা দিতে পারেন, তা কেবল প্রজ্ঞা আর নীরবতা। প্রতিদিনের নীরব প্রহরে টাওইল নিঃশব্দে মানবতার দীপ্তির ভাগ্যে বর্ষণ করে চলেছেন তাঁর প্রজ্ঞা, সাহস, আর নীরব আশীর্বাদ।"
  },
  AwakerStory_66037_Title = {
    Text = "প্রাথমিক তথ্য"
