  AwakerStory_66037_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_76412_Content = {
    Text = "আমি বিশ্বাস করি না যে রবার্ট বন্দুক মুখে দিয়ে আত্মহত্যা করেছে। হ্যাঁ, আমি বিশ্বাস করি না।\n\nসে সাহসিকতার পদক পেয়েছিল, একাধিক জটিল হত্যা মামলা সমাধান করেছিল, সে ছিল দৃঢ় মনোবলের একজন অভিজ্ঞ গোয়েন্দা। সবচেয়ে গুরুত্বপূর্ণ বিষয় হলো, সে শীঘ্রই বিয়ে করতে যাচ্ছিল, মেয়েটি আর সে পরস্পরকে গভীরভাবে ভালোবাসত, তাই এখানে নিশ্চয়ই কোনো ষড়যন্ত্র আছে! কেউ তাকে খুন করে আত্মহত্যার ছদ্মবেশ দিয়েছে!\n\nখুনি যেই হোক না কেন, আমি তাকে খুঁজে বের করব এবং তাকে মূল্য চোকাতে বাধ্য করব। ছোট ভাই হিসেবে, একজন গোয়েন্দা হিসেবে এটা আমার অবশ্য কর্তব্য।\n\n……\n\nঘটনাস্থলে কোনো সূত্র ছিল না, তাই আমাকে নিজের জন্মভূমিতে ফিরে আসতে হয়েছে, এটাই সেই শেষ জায়গা যেখানে রবার্ট আত্মহত্যার আগে গিয়েছিল। বিভিন্ন দিক থেকে খোঁজখবর নিয়ে জানতে পারলাম যে সে গভীর পাহাড়ে প্রবেশ করেছিল।\n\nসেখানে যাওয়ার কারণ সম্পর্কে আমার ধারণা, এটা স্থানীয় প্রথার সাথে সম্পর্কিত: প্রতিটি পরিবারের প্রথম সন্তানকে তার প্রাপ্তবয়স্ক হওয়ার অনুষ্ঠানে বাবা-মা পাহাড়ে নিয়ে যায়।\n\nযেহেতু আমাদের বাবা-মা আমরা ছোট থাকতেই এখান থেকে চলে গিয়েছিলেন, তাই রবার্ট কখনো এই প্রথা পালন করেনি। আমার মনে হয়, সংসার গড়ার দায়িত্ববোধই তার মধ্যে প্রথার প্রতি আনুগত্য জাগিয়ে তুলেছিল।\n\nযাই হোক না কেন, আমাকে গভীর পাহাড়ে যেতেই হবে। এই লেখা শেষ করেই রওনা দেব।\n\n……\n\nপাহাড়ের ভেতরে একটি বিশাল স্থাপনা খোদাই করা হয়েছে, আমি জানি না এটা কোন যুগের, আমি বুঝতে পারছি না। আমি শুধু জানি এখানে বিরতিহীনভাবে নৃশংস আচার-অনুষ্ঠান চলছে, সেই ছিন্ন অঙ্গ-প্রত্যঙ্গ আর পোকার মূককীট……ওয়াক, আমি আর লিখতে পারছি না।\n\n……\n\nএই মূককীটগুলো……না, না, ওরা আমার দাদা-দাদি নয়, আমার পূর্বপুরুষ নয়……আমার শরীরে দানবের রক্ত বইতে পারে না। আহ——\n\n……\n\n……আচার পালনকারী দানবরা আমাকে আবিষ্কার করেছে, তারা আমাকেও দানবে পরিণত করতে চায়!\n\n……\n\nযদি এই ডায়েরি কেউ দেখো, আমাকে মেরে ফেলো, এখনই……@2\n\n……\n\nমহান @2-এর জয়গান, হিস্স্স্স @2……অন্ধ মূঢ়তার জয়গান @4……হিস্স্স্স হিস্স্স্স হিস্স্স্স……@1 হিস্স্স্স……\n\n——প্রয়াত সংশ্লিষ্ট গোয়েন্দা @3-এর ডায়েরি থেকে উদ্ধৃত, সংক্ষেপিত"
  },
  AwakerStory_76412_Title = {
    Text = "গল্প: ১"
