  AwakerStory_76412_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_76413_Content = {
    Text = "「ধন্যবাদ, ক্লেমেন্টাইন, আমি অনেক ভালো অনুভব করছি। তুমিই এই পৃথিবীতে আমাকে সবচেয়ে ভালো বোঝো।」\n\nক্লেমেন্টাইনের মনোবিদ্যা পরামর্শকক্ষে যাতায়াতের সময়, গোপনরক্ষক প্রায়ই এমন কথা শুনতে পেত। সেই রোগী ও জাগ্রতসত্তারা ঢোকার আগে যেমনই থাকুক না কেন, বের হওয়ার সময় সবার পায়ে থাকত হালকা ছন্দ, মুখে উজ্জ্বল হাসি।\n\nএমনকি একবার পাশ দিয়ে যাওয়ার সময়, গোপনরক্ষক দেখেছিল ক্লেমেন্টাইন ভুল করে পরামর্শকক্ষে ঢুকে পড়া একটি পথবিড়ালকে মানসিক পরামর্শ দিচ্ছে।\n\nফলাফল ছিল সুস্পষ্ট — যারাই মানসিক পরামর্শ নিয়েছিল, সবাই ক্লেমেন্টাইনের ভূয়সী প্রশংসা করত। এতে ক্লেমেন্টাইনের প্রভাব দ্রুত ছড়িয়ে পড়ল, আর সেই সাথে এলো ঝামেলাও——\n\n「গোপনরক্ষক, শুভ দুপুর।」\n\nক্লেমেন্টাইন হাসিমুখে তোমার চলার পথে দেখা দিল, আর তুমি অবাক হলে না। তার অবিরাম বেজে চলা যোগাযোগ যন্ত্রই সব বলে দিচ্ছিল। তার ওপর আস্থা রাখা সেই রোগীরা, অজান্তেই তার চোখ-কান হয়ে উঠেছিল, প্রত্যক্ষ বা পরোক্ষভাবে তার একের পর এক উদ্দেশ্য পূরণে সাহায্য করছিল।\n\n「আমার মনে হয়, তুমি যদি এই শহরের মেয়র হতে চাও, তাহলেও যারা পরামর্শ নিয়েছে তারা নিঃশর্তভাবে তোমাকে সেটা অর্জনে সাহায্য করবে।」\n\nগোপনরক্ষকের রসিকতার জবাবে, ক্লেমেন্টাইন নির্বিকারভাবে হাসল।\n\n「এসবে আমার কোনো আগ্রহ নেই।」\n\nহ্যাঁ, ক্লেমেন্টাইনের এসবে আগ্রহ নেই। আর ভাগ্যিস তার আগ্রহ নেই।\n\nনইলে মানসিক পরামর্শে উজাড় করে বলা সেই অন্ধকার গোপনীয়তাগুলো, এই শহরকে তোলপাড় করে দিতে যথেষ্ট ছিল।\n\n「এখন, আমি শুধু তোমার হৃদয়ের গভীরে লুকানো রহস্য জানতে চাই, গোপনরক্ষক।」\n"
  },
  AwakerStory_76413_Title = {
    Text = "গল্প: ২"
  },
  AwakerStory_76413_UnlockDesc = {
    Text = "সমসংস্থান হার ৫"
  },
  AwakerStory_76414_Content = {
    Text = "প্রথমদিকে, সামান্য কিছু তুচ্ছ যন্ত্রণাই তাকে তৃপ্ত করতে পারত।\n\nতারপর, সেই মধুর স্বাদের তীব্র আকাঙ্ক্ষা তাকে মানসিক পরিচালনায় ক্রমশ আরও বেশি বিদ্বেষ মেশাতে প্ররোচিত করল।\n\nসেই বিদ্বেষ যেন নদীর মতো জমে উঠে উন্মত্ত হয়ে প্রবাহিত হলো, বন্যার মতো ছড়িয়ে পড়ল, একের পর এক মনের দ্বীপকে ডুবিয়ে দিল।\n\nতবুও যথেষ্ট নয়। মোটেও যথেষ্ট নয়।\n\nকেবল সেই আদিম দীর্ঘ স্বপ্ন যখন জেগে উঠবে, তখনই সমগ্র বিশ্ব যন্ত্রণার মহাসাগরে পরিণত হবে, এনে দেবে চরম আনন্দ।\n\nতাই, সে উত্তেজিত, সে প্রার্থনা করে, সে অপেক্ষা করে।\n\nযখন সবকিছু বিশৃঙ্খলায় পরিণত হবে, সে মাথা নত করবে, সানন্দে আস্বাদন করবে এই জগতের সবচেয়ে চরম শোক।\n\nএমনকি যদি সেই যন্ত্রণার মহাসাগর তাকেও ডুবিয়ে মারে।\n"
  },
  AwakerStory_76414_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_76414_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_76415_Content = {
    Text = "প্রত্যেকেরই আলাদা আলাদা মুখোশ থাকে, আর সে বেছে নিয়েছে সেটি যা মানুষের মনকে সবচেয়ে বেশি অসাড় করে দিতে পারে——\n\nসে কোমলভাবে হাসে, মৃদু হেসে কথা বলে, তার প্রতিটি অভিব্যক্তি, প্রতিটি কথা এতটাই সান্ত্বনাদায়ক যে মানসিক পরামর্শ নিতে আসা রোগীরা অন্তর থেকে বিশ্বাস করে যে তারা জীবনের সবচেয়ে বিশ্বস্ত বন্ধু ও পথপ্রদর্শকের দেখা পেয়েছে।\nএটুকুই যথেষ্ট।\n\nধ্বংসের জন্য নির্ধারিত পতঙ্গের পরিণতি জানার দরকার নেই, শুধু তার নির্দেশনা অনুসারে এগিয়ে যেতে হবে।\n\nসেই আপাত উষ্ণ মুক্তির আড়ালে, প্রলয়ের আগুনে দগ্ধ হয়ে, আর কখনো ফেরার পথ থাকে না।\n"
  },
