  AwakerStory_76416_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_81334_Content = {
    Text = "ক্যাস্টরের সাথে থাকার অনুভূতি সাধারণত দুটি অদ্ভুত চরম রূপে প্রকাশ পায়।\nবাহ্যিকভাবে দেখলে, তার অতিরিক্ত গম্ভীর ও স্থিতিশীল স্বভাব অনেকটা লন্ডিনিয়ামের কোনো ব্যাংকে বিশ বছর ধরে ডেস্কে বসে থাকা মধ্যবয়সী কর্মচারীর মতো — নিয়মনিষ্ঠ, রসবোধহীন, একঘেয়ে কাজে সমস্ত প্রাণশক্তি নিংড়ে যাওয়া। যখন সে কঠোর মুখ করে, তখন সত্যিই এক ধরনের ক্রোধ ছাড়াই প্রতাপ বিকিরণকারী পবিত্র পুত্রের আভা ফুটে ওঠে।\nকিন্তু একটু গভীরভাবে মেলামেশা করলেই বোঝা যায়, তার আপাতদৃষ্টিতে রক্ষণশীল আচরণগুলো সবই তার অত্যন্ত সীমিত সাধারণ জ্ঞান, অতুলনীয় মোটা স্নায়ু এবং সরলতা থেকে উদ্ভূত — এমনকি যে কেউ তাকে যে রসিকতাই বলুক না কেন, সে তা পুরোপুরি সত্য বলে মেনে নেয়।\nসে প্রায়ই একটা মোটা নোটবই হাতে নিয়ে গোপনরক্ষকদের ধরে অবিরাম প্রশ্নের পর প্রশ্ন করে যায়, ঠিক যেন একটি সদ্য কথা বলতে শেখা শিশু। সেই অত্যন্ত আন্তরিক ও অকপট দৃষ্টির সামনে, বেশিরভাগ মানুষের পক্ষে এসব অজ্ঞতাপূর্ণ প্রশ্নের প্রতি কোনো তুচ্ছতাসূচক কথা বলা কঠিন হয়ে পড়ে।\nবিভিন্ন ধর্মবিশ্বাস সম্পর্কিত ধর্মগ্রন্থ ছাড়া, ক্যাস্টর যেকোনো নতুন জ্ঞানের প্রতি তীব্র জ্ঞানপিপাসু, বিশেষ করে আধুনিক সমাজ ও আধুনিক বিজ্ঞানের নানা বিষয়ে। এমনকি সে পরীক্ষামূলক গবেষণার প্রতিও গভীর আগ্রহ দেখিয়েছিল, কিন্তু মেল্টডাউন·ডোর দ্বারা নির্দয়ভাবে উপেক্ষিত হওয়ার পর, সে বেচারা উইনকোরকে এমনভাবে জ্বালাতন করতে শুরু করে যে সে প্রতিদিন তার নাম শুনলেই পালিয়ে যায়।\nযদি সে কোনো স্কুলের ক্লাসরুমে বসত, তাহলে সে হতো সেই ধরনের পরিশ্রমী ছাত্র যাকে শিক্ষকরা অত্যন্ত পছন্দ করেন। সে পড়াশোনাকে কষ্টকর বা ক্লান্তিকর কিছু মনে করে না, বরং স্বাধীনভাবে আগ্রহের বিষয়ে জ্ঞান আহরণ করতে পারাকে হৃদয়ের গভীর থেকে এক সুখ বলে মনে করে।\nতবে শিক্ষকের তৃপ্তির তুলনায়, কিছু বড়াই করতে পছন্দ করা জাগ্রত সত্তা এমন যুক্তিপূর্ণ অন্তহীন প্রশ্নের সম্মুখীন হলে, পরবর্তী উত্তর দিতে না পেরে বরং লজ্জায় ক্রুদ্ধ হয়ে ওঠে — আর পড়ে থাকে কিছুই বুঝতে না পারা ক্যাস্টর, জ্ঞানার্জনের গভীরতা ও কঠিনতা নিয়ে আক্ষেপ করতে করতে, দীর্ঘ পথ এখনও বাকি বলে দীর্ঘশ্বাস ফেলতে।"
  },
  AwakerStory_81334_Title = {
