  AwakerStory_81335_Content = {
    Text = "যদি একটি সাধারণ পরিবারে জন্মগ্রহণ করতেন, ক্যাস্টর হয়তো এমন একজন যুবক হয়ে বেড়ে উঠতেন যিনি কথায় অপটু, কিন্তু গাছের মতো সদয় ও বিশ্বস্ত। কিন্তু এখন, তিনি যমজদের মধ্যে একমাত্র যিনি অক্ষত দেহ ও আত্মা নিয়ে টিকে আছেন। তিনি একটি পাথরের মতো নীরব, অপেক্ষমাণ — কৈশোরে দুজনের ভাগ করা সেই অগ্নিশিখা হৃদয়ে গোপন রেখে, কখনো হাল ছাড়েননি, কখনো পিছু হটেননি।\nসেই পরিণত, ঝড় তোলার ক্ষমতাসম্পন্ন ডানাদুটি গুটিয়ে লুকিয়ে আছে — একটি পাখি নীরবে অপেক্ষা করছে সেই খাঁচার দরজা খোলার জন্য, আবারও আকাশে উড়ে যাওয়ার সেই মুহূর্তের জন্য।"
  },
  AwakerStory_81335_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_81335_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_81336_Content = {
    Text = "লন্ডিনিয়াম থেকে অনেক দূরে, সেই দারিদ্র্যের কারণে স্বল্পপরিচিত উচ্চভূমিতে মিশন পালনের সময়, আমি ঘটনাক্রমে এক প্রায় জনশূন্য পাহাড়ি গ্রামে এমন একটি বিস্ময়কর ঘটনা আবিষ্কার করলাম।\nসেই দানব আবির্ভাবের রাতে, আকাশ যেন কোনো অদ্ভুত ছায়ায় ঢেকে গিয়েছিল, কুয়াশা মাটিতে গড়াগড়ি খাচ্ছিল, আর মেঘের গভীরে ফুটে উঠেছিল এক ম্লান সবুজ আভা, সেটা নিছক প্রাকৃতিক ঘটনা ছিল না, বরং ছিল এক জীবিত, শ্বাসরত সত্তার প্রতিচ্ছবি।\nউঁচু গাছে ঘেরা জনশূন্য পর্বতমালার গভীর থেকে হঠাৎ ভেসে এল এক গর্জন, হুংকারের মতো শব্দতরঙ্গ, কোনো প্রাণীর নয় এমন সেই চিৎকার মানুষের সহজাত প্রবৃত্তির গভীরতম ভয় জাগিয়ে তুলতে পারে।\nএক বিশাল ছায়া দ্রুতগতিতে উড়ে গেল, পুরো পাহাড় সেই আকাশ ঢেকে দেওয়া ছায়ার সাথে কেঁপে উঠল, সব গাছের পাতাও একসাথে কেঁপে উঠল, সমস্বরে ফিসফিসের মতো মর্মর শব্দ তুলল।\n「আমি দেখেছি! সেই লম্বা লম্বা, ঘন ঘন শুঁড়গুলো, সেই সবুজ আলো ছড়ানো চোখ দুটো, সেটাই নিশ্চিতভাবে আকাশের সেই ভয়ংকর ছায়ার উৎস। সে আমাকে দেখে ফেলেছিল, এমনকি আমাকে একদৃষ্টে তাকিয়ে ছিল! আমি সত্যিই ভেবেছিলাম সেই মুহূর্তেই আমার জীবন শেষ, কিন্তু হয়তো সে সবেমাত্র পেট ভরে খেয়েছিল, আমি শ্বাসরোধে অজ্ঞান হওয়ার আগেই, সে দয়া করে ঘুরে চলে গেল।」\nএটি একমাত্র আনুষ্ঠানিক প্রত্যক্ষদর্শীর সাক্ষাৎকার, আজও দুঃস্বপ্নে ডুবে থাকা গ্রামবাসী আরও বিস্তারিত মনে করতে অস্বীকার করেছেন। কিন্তু বিদ্যমান প্রমাণ থেকে পর্যবেক্ষণ করলে, এই বিশাল গাঢ় সবুজ দানবটি ঘূর্ণিঝড়ের মতো কিছু বনভূমি ধ্বংস করা এবং কেবল রক্তের চিহ্ন অবশিষ্ট কয়েকটি বন্যপ্রাণীর কঙ্কাল রেখে যাওয়া ছাড়া, বৃহত্তর আক্রমণাত্মকতা দেখায়নি, যেন একটি স্বাভাবিকভাবে খাদ্যগ্রহণকারী শিকারি পশু। সম্ভবত গ্রামের কাছে আসার আচরণটি কেবল কৌতূহলজনিত উঁকিঝুঁকি ছিল।\nকিন্তু যেকোনো অজানা আতঙ্কের মুখে, আমাদের স্পষ্টতই সবচেয়ে খারাপ পরিস্থিতি অনুমান করা উচিত, আমি @3 উচ্চভূমিতে আরও পনেরো দিনের তদন্ত চালিয়ে যাব, যদি অন্য কোনো উল্লেখযোগ্য বিপদের চিহ্ন থাকে, আমি যেকোনো সময় মিশন রিপোর্টে সংযোজন করব।\n\n——《মিসাগার সীমান্ত বহির্ভূত তদন্ত নোট A.F.3@2 সালের সংকলন》 থেকে উদ্ধৃত"
  },
