  AwakerStory_81336_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_81337_Content = {
    Text = "স্বাধীনতার সন্ধান, চার্চ থেকে পালানোর মূল্য কী? যমজেরা ভয়ংকর শাস্তির কথা কল্পনা করেছিল, এমনকি নিজেদের জীবন হারানোর কথাও ভেবেছিল, কিন্তু তারা যা ভাবতে পারেনি তা হলো — সবচেয়ে যন্ত্রণাদায়ক কখনোই শারীরিক নির্যাতন নয়, বরং আত্মার উপর চালানো ক্ষুরের আঘাত।\nক্যাস্টর চোখ ফেটে যাওয়ার মতো তাকিয়ে দেখছিল পলিডিউসিসের সেই অত্যন্ত লালিত, প্রাণবন্ত ও মনোরম ডানা জোড়া জোর করে ছিঁড়ে ফেলা হচ্ছে — তার ঠোঁট ইতিমধ্যেই নিজের দাঁতে কামড়ে ছিন্নভিন্ন হয়ে গিয়েছিল। সে উন্মত্ত ও অপরাধবোধে ভরা হয়ে অপেক্ষা করছিল, এমনকি আকাঙ্ক্ষা করছিল একই যন্ত্রণা তার নিজের উপরেও নেমে আসুক।\nকিন্তু ইউরিয়েত শুধু হাত নাড়লেন, আর ছেঁড়া বস্তার মতো গুরুতর আহত ক্যাস্টরকে তার ডানা অক্ষত রেখেই নিয়ে যাওয়া হলো, ক্ষয়কারী তরলে ভরা একটি পুকুরে ফেলে দেওয়া হলো 'পাপমোচন চিকিৎসা' প্রয়োগের জন্য।\nকালো আঠালো তরল আহত দেহকে ভিজিয়ে দিল, প্রতিটি ক্ষতের মধ্যে প্রবেশ করল, প্রতিটি পালককে ঢেকে দিল, ক্যাস্টরের শ্বাস নেওয়া আরও কঠিন করে তুলল।\nক্ষতস্থানে বারবার ক্ষয় ও নিরাময়ের চক্রের মধ্যে, ক্যাস্টরের বিভ্রান্ত মনে সেই ছিঁড়ে ফেলা ডানার দৃশ্য ঘুরপাক খাচ্ছিল। সে সংকীর্ণ কারাকক্ষে অস্থিরভাবে নিশ্চল বসে ছিল, ভাইয়ের সমস্ত যন্ত্রণা নিজে বহন করতে চাইছিল। সে কতটাই না চেয়েছিল সেদিন যার ডানা ছেঁড়া হয়েছে সে যেন সে নিজেই হতো। পরে সে দৃঢ়ভাবে সংকল্প করল, এই ডানা দিয়েই সে অবশ্যই তার ভাইকে আবার স্বাধীনতার আকাশে উড়িয়ে নিয়ে যাবে।\nক্যাস্টর এই নরকসম জলাশয়ে দিনের পর দিন টিকে রইল, যন্ত্রণার মধ্যে সময়ের সঠিক অনুভূতি হারিয়ে গেল। যেন কয়েক দশক অপেক্ষা করেছে এমন দীর্ঘ সময় পর, ক্যাস্টর প্রায় একবার মৃত্যুবরণ করে সেই ঘোর অন্ধকার নরক থেকে আবার বেরিয়ে এলে, তার উদ্বিগ্ন চোখের সামনে যা দেখা গেল তা ছিল একটি শীতল ও অবজ্ঞাপূর্ণ দৃষ্টি।\n「তোমার সেই বিতৃষ্ণাকর চাহনি সরাও। আর একটা উপদেশ দিই, মহামান্য ক্যাস্টর, তুমি আর আমি কেবলমাত্র প্রদীপধারীর সেবায় নিয়োজিত পবিত্র পুত্র, কারো চোখের আড়ালে অবসর সময়ে এত অন্তরঙ্গ হওয়ার দরকার নেই, এটা শুধু বিরক্তিই বাড়ায়।」\nক্যাস্টর বুঝতে পারল না কেন তার ভাই তাকে সম্পূর্ণ ভুলে গেছে, কিন্তু সে অবশেষে বুঝল পাপের জলাশয় থেকে বেরোনোর সময় ইউরিয়েতের সেই গভীর অর্থবহ দৃষ্টির আসল মানে কী ছিল — কারণ তিনি ইতিমধ্যেই তাকে নিয়ন্ত্রণ করার সবচেয়ে কার্যকর শিকল নিজের হাতে শক্ত করে ধরে ফেলেছিলেন, নির্ভয়ে ও নিশ্চিন্তে।"
  },
  AwakerStory_81337_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_81337_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_81338_Content = {
    Text = "যমজরা জন্ম থেকেই একে অপর ছাড়া আর কিছুই পায়নি, তবুও ক্যাস্টর সর্বদা হারানোর স্বাদ চেখে চলেছে।\nআঘাত পেয়েছে, বিস্মৃত হয়েছে, বিশ্বাসঘাতকতার শিকার হয়েছে — সেই নীরব হৃদয় পাথরের নয়, তবুও সে বারবার উঠে দাঁড়িয়েছে।\n「কিন্তু কিছু যায় আসে না, তোমার অংশটুকুও আমি বহন করে এগিয়ে যাব।」ক্যাস্টর তার সম্পূর্ণ বদলে যাওয়া ভাইয়ের দিকে তাকিয়ে অন্ধভাবে বিশ্বাস করে চলেছে।\nতার হৃদয়ে সেই ক্ষীণ অগ্নিশিখাটিকে শক্ত করে আঁকড়ে ধরে, ছুরির মতো ধারালো তুষারঝড়ের বিপরীতে সে অবিরাম এগিয়ে চলেছে।\nএকদিন, সে সেই স্বাধীনতার শিখরে আরোহণ করবে, ডানা দিয়ে আকাশের ঝুলে পড়া পর্দা স্পর্শ করবে।\nসে বিশ্বাস করে যে সেই কণ্টকময় পথের শেষে, নিশ্চয়ই সেই উজ্জ্বল আলো অপেক্ষা করছে — যা শৈশবে তার ভাই প্রতিশ্রুতি দিয়েছিল।"
  },
  AwakerStory_81338_Title = {
    Text = "গল্প: ৪"
  },
  AwakerStory_81338_UnlockDesc = {
    Text = "সমসংস্থান হার ৯"
  },
  AwakerStory_81615_Content = {
    Text = "তিনি সেই পতাকা যা জাহাজ চলার সময় উঁচুতে উড়ে পথ দেখায়, আবার জাহাজ ডুবে যাওয়ার সময় শেষ মুহূর্ত পর্যন্ত কর্তব্যে অবিচল থেকে গাওয়া শোকগাথা।\n\nতাঁর দায়িত্ব, তাঁর কর্তব্য, তাঁর জীবন — সবকিছুই জাহাজের সাথে বাঁধা, এর বাইরে আর কিছুই নেই।\n\nকারণ, পথ দেখানোই তাঁর অস্তিত্বের অর্থ।\n"
  },
  AwakerStory_81615_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_81615_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_81616_Content = {
    Text = "কথা বলা শেখার আগেই, জাহাজে বেড়ে ওঠা ক্রিসান্থ সমুদ্রের ঢেউ জাহাজে আছড়ে পড়ার ধ্বনি অনুকরণ করতে পারত।\n\nকখনো সেই ধ্বনি ছিল 「ছলছল」, কখনো সেই ধ্বনি ছিল 「গুড়গুড়」, যেন প্রকৃতি তার জন্য গেয়ে ওঠা ঘুমপাড়ানি গান, যা তাকে নিরাপদ মনে করাত, যা তাকে আপন মনে করাত, যা তাকে আকৃষ্ট করত।\n\nসে সবসময় অন্যদের চেয়ে দ্রুত সমুদ্রের 「মেজাজ」 বুঝতে পারত, সবসময় অন্যদের চেয়ে দ্রুত মেঘের 「ভাষা」 পড়তে পারত, সবাই বলত সে জন্মগত 「পথপ্রদর্শক」।\n\nআসলে, প্রথমবার এই শব্দটি শোনার সময়, ছোট্ট ক্রিসান্থ এর অর্থ বুঝতে পারেনি, সে কেবল সহজাতভাবে তাকে আশ্রয় দেওয়া ক্যাপ্টেন ও নাবিকদের সাহায্য করতে চেয়েছিল, তাদের নিরাপদে ঘরে ফিরতে দিতে চেয়েছিল, ঝড় বা জাহাজের অন্য কোনো বিপদে তাদের হারাতে চায়নি।\n\nতার ইচ্ছা বুঝতে পেরে পথপ্রদর্শক তখন বললেন: 「পথপ্রদর্শক হও, ক্রিসান্থ, পথপ্রদর্শক হও, তোমার কর্তব্য পালন করো, তাহলে তোমার ইচ্ছা পূরণ হবে।」\n\nঅবুঝ ক্রিসান্থ মাথা নাড়ল, এভাবেই, সেই পথপ্রদর্শক তার গুরু হলেন। তিনি তাকে শেখালেন কীভাবে তারার আকাশ পর্যবেক্ষণ করতে হয়, কীভাবে সেক্সট্যান্ট ক্যালিব্রেট করতে হয়, এবং তাকে বললেন পথপ্রদর্শকদের প্রজন্ম থেকে প্রজন্মে চলে আসা সেই গান, সেই অশুভ গান।\n\n「আমি লোনা পানির কোলে জড়িয়ে পড়তে চাই না, সেটা খুব ঠান্ডা, আর কোনো ফসফরাসের আলোতেও পরিণত হতে চাই না।」 ছোট্ট ক্রিসান্থ আপত্তি জানাল।\n\nতার গুরু তাকে কিছু শেখাননি, শুধু তার মাথায় হাত বুলিয়ে হেসেছিলেন।\n\nকারণ সময়, তাকে শেখাবে 「পথপ্রদর্শক」-এর কর্তব্যের অর্থ——\n\nসে গভীর সমুদ্রের উপর, একমাত্র পথনির্দেশ, একমাত্র আশা।\n"
  },
  AwakerStory_81616_Title = {
    Text = "গল্প: ৩"
  },
  AwakerStory_81616_UnlockDesc = {
    Text = "সমসংস্থান হার ৭"
  },
  AwakerStory_81617_Content = {
    Text = "কেউ জানে না সেই ভূতুড়ে জাহাজটি কোথায়, আর কেউ নিশ্চিত করতে পারে না 「সেটি「 আদৌ অস্তিত্বশীল কিনা। বর্তমানে আমার হাতে থাকা একমাত্র সূত্র হলো সেই হাতির দাঁতের মাথার খোদাই, যেটিতে কোনো এক অদ্ভুত জাদুকরী শক্তি বিদ্যমান বলে মনে হয়।\n\nএটি পাওয়ার পর থেকে, আমি প্রতিদিন একই স্বপ্ন দেখছি — হ্যাঁ, সেই ভূতুড়ে জাহাজ, যার অবস্থান কেউ জানে না। 「সেটির「 জাহাজের কাঠামো জুড়ে জীবন্ত কিছুর মতো কিলবিল করা দীপ্তি জ্বলছে, যেন মর্ত্যবাসীদের অজানা কোনো মাত্রার দ্বারপথ। ঘুম ভাঙার পরও, আমি সেই অপবিত্র ও বিকৃত ফিসফিসানিগুলো মনে রাখতে পারি।\n\nআমি কতটাই না চাই যে আমি পাগল হয়ে যেতাম, অথবা এই উদ্ভট, মানুষের পক্ষে উচ্চারণ অসম্ভব ধ্বনিগুলো ভুলে যেতাম — কিন্তু পারি না।\n\nসেই অভিশপ্ত স্বপ্ন, সেই অভিশপ্ত বুদ্ধিদীপ্ত আভা আমাকে যন্ত্রণা দিচ্ছে, তাই আমাকে 「সেটিকে「 খুঁজে বের করতেই হবে, হাতির দাঁতের মাথার খোদাইয়ের নির্দেশনায়। সৌভাগ্যবশত, মিসকাটোনিক বিশ্ববিদ্যালয়ের অধ্যাপকরা আমার সাথে যাবেন, একসাথে ভূতুড়ে জাহাজ ও সেন্ট এলমোর আগুন অনুসন্ধান করতে — তারা সেই কিলবিল করা দীপ্তিকে এই নামেই ডাকেন।\n\nআমার জন্য শুভকামনা করুন। ঈশ্বর আমাদের রক্ষা করুন।\n\n——《মিসকাটোনিক অতিপ্রাকৃত ঘটনা তদন্ত নথি》থেকে উদ্ধৃত"
  },
