  AwakerStory_81617_UnlockDesc = {
    Text = "জাগরণকারী স্তর ৩"
  },
  AwakerStory_81618_Content = {
    Text = "ক্লেপার্সান্টের দৈনিক সময়সূচি অত্যন্ত নির্দিষ্ট। আপনাকে শুধু নির্দিষ্ট সময়ে, নির্দিষ্ট স্থানে যেতে হবে, তাহলেই তাকে খুঁজে পাবেন।\n\nসাধারণত, ক্লেপার্সান্ট সকাল ৬:০০-এ ঘুম থেকে ওঠেন এবং ঠান্ডা জলে স্নান ও ব্যায়াম করেন। ৭:০০-এ প্রাতঃরাশের সময়, ওটমিল পোরিজ ও আচারযুক্ত মাছের পাশাপাশি প্রচুর পরিমাণে ক্যাফেইন সাপ্লিমেন্ট সরবরাহ করতে হবে।\n\n৯:০০-১২:০০ হলো ক্লেপার্সান্টের অধ্যয়নের সময়, এই সময়ে তিনি সামুদ্রিক মানচিত্র সংশোধন বা যন্ত্রপাতি ক্যালিব্রেট করেন। যখন ছুটির ঘণ্টা বাজে, ক্লেপার্সান্ট বাইরে এসে পতাকা নেড়ে ট্রাফিক নিয়ন্ত্রকের ভূমিকা পালন করেন, যা দুপুরের খাবারের সময় একাডেমির রাস্তায় যানজটের সমস্যা অনেকটাই কমিয়ে দিয়েছে।\n\nক্লেপার্সান্টের দুপুরের খাবারের সময় 「রাস্তার অবস্থার」 উপর নির্ভর করে, তবে সর্বশেষ ১২:৩০-এর পরে হয় না। সংক্ষিপ্ত বিশ্রামের পর, ১৪:০০-এ ক্লেপার্সান্ট ঠিক সময়ে সমুদ্রতীরে উপস্থিত হন, বাতাসের দিক ও আবহাওয়া পর্যবেক্ষণ করেন। এই সময়ে ক্লেপার্সান্ট, ফ্যালোস এবং হিলেস্ট—এই তিনজনের গতিবিধির দিকে নজর রাখতে হবে, যাতে তারা জাদুঘরের মডেল জাহাজ 「বাজেয়াপ্ত」 না করেন, অথবা পথচারীদের সমুদ্রে যেতে প্রলুব্ধ না করেন।\n\n১৯:০০-এ রাতের খাবারের সময়। দীর্ঘ সমুদ্রযাত্রায় সম্পূর্ণরূপে ধ্বংস হওয়া ঘুমের চক্রকে অসাড় করতে, ক্লেপার্সান্টকে প্রচুর পরিমাণে অ্যালকোহল ও ঘুমের ওষুধ সেবন করতে হয়। একমাত্র এভাবেই তিনি ২২:০০-এ সফলভাবে ঘুমাতে পারেন, অন্যথায় ক্লেপার্সান্ট জোর করে নিজেকে জাগিয়ে রাখেন, সমুদ্রযাত্রায় ঘটতে পারে এমন 「অপ্রত্যাশিত পরিস্থিতি」 মোকাবেলা করতে।\n\nএর ফলে যে পরিস্থিতি সৃষ্টি হয় তার মধ্যে রয়েছে কিন্তু সীমাবদ্ধ নয়: সেন্ট এলমোর আগুনের ঘটনা নিয়ন্ত্রণের বাইরে চলে যাওয়া, যার ফলে পুরো এলাকা দিনের আলোর মতো উজ্জ্বল হয়ে ওঠে, অথবা এলাকার ভোল্টেজ অস্বাভাবিক ও অনিয়ন্ত্রিত হওয়া, যন্ত্রপাতি অস্বাভাবিকভাবে চলা, আগুন লাগা ইত্যাদি।\n\n<Red:সতর্কতা, এই সময়ে কোনোভাবেই এরিকাকে ক্লেপার্সান্টের সাথে যোগাযোগ করতে দেবেন না!>\n\nশেষ বিজ্ঞপ্তি—একটি সমালোচনা:\n\nক্লেপার্সান্ট আসার পর, উইনকোর একাধিকবার ক্লেপার্সান্টের বুকের @2 আলোর উৎস হিসেবে নিষ্কাশন ও গবেষণা করার চেষ্টা করেছেন। মৌখিক সমালোচনা করা হয়েছে। কেউ কোনো অস্বাভাবিকতা লক্ষ্য করলে, অনুগ্রহ করে অবশ্যই সময়মতো গোপনরক্ষককে জানান।\n\n——গোপনরক্ষক %player%"
