  AwakerStory_95009_Content = {
    Text = "ক্যাটিগুলা তার স্বতন্ত্র হাসি দিয়ে প্রতিটি দর্শকের চেতনার গভীরতম প্রান্ত থেকে সেই নিষ্ঠুর, উন্মাদ শীতলতা বের করে আনতে পারদর্শী।\nতার অবিচ্ছেদ্য সঙ্গী যমজ পিস্তলদ্বয়, তাদের নলের চারপাশে ঘূর্ণায়মান বারুদের ধূলিকণা দিয়ে সকল দুঃসাহসী ক্ষুদ্র অপরাধীদের সতর্ক করে দেয় — নামহীনদের আত্মত্যাগই সকল মহত্ত্বের ভিত্তিপ্রস্তর।\nতবে যারা একবার তার সাথে লেনদেন করেছে, তারা বুঝতে পারবে যে সূর্যালোকবঞ্চিত এই সাধারণ মানুষদের শিকার করা তার কাছে নিছক একঘেয়ে সময়ের বিনোদন মাত্র।\nসর্বোপরি, যখন সে সত্যিই গুলি চালায়, তখন বন্দুকের নলে কোনো বারুদ থাকে না।"
  },
