  AwakerStory_95094_Content = {
    Text = "তার সমগ্র জীবন কাটিয়েছে কারো দ্বারা নিয়ন্ত্রিত সুতোর নিচে, সেই আগে থেকেই লেখা চিত্রনাট্য ছিল এক হাস্যকর মিথ্যা, যা তাকে বারবার হারাতে, ভুলতে এবং সুযোগ হাতছাড়া করতে বাধ্য করেছে।\nকিশোর বয়সে তার সবচেয়ে তীব্র আকাঙ্ক্ষা ছিল স্বাধীনভাবে ডানা মেলে সেই হ্রদের ওপারের জগৎটা দেখতে যাওয়া।\nকিন্তু এই ইচ্ছার জন্য সবকিছু হারানোর পর, সেই হালকা, নিশ্চিন্ত জীবনকে আর সম্পূর্ণ স্বপ্ন হিসেবে মানতে পারেনি সে।\nঅন্তহীন ক্রোধ সেই কালো হৃদয়কে প্রজ্বলিত করেছে, তার রক্তে জমাট বাঁধা যন্ত্রণা ও ঘৃণা কেবল সেই ভণ্ড বিশ্বাসীদের মৃত্যুর মাধ্যমেই ধুয়ে মুছে পরিশোধ করা সম্ভব।"
