  AwakerStory_95097_Content = {
    Text = "সে বিকৃতভাবে জন্ম নেওয়া রক্তমাংস, চিরে আবার সেলাই করা ত্বক, শূন্য বক্ষগহ্বর, কলুষিত হৃদয় এবং অদৃশ্য শৃঙ্খল দিয়ে গঠিত।\nতাকে উচ্চ মঞ্চে তুলে ধরা হয়েছিল, মানুষ তার পায়ের কাছে প্রণত হয়েছিল, দাবি করেছিল তার আত্মা নিষ্কলুষ।\nসে আসলে কী? অসংখ্য স্বপ্নে সে বিভ্রান্তভাবে প্রশ্ন করেছে, সেই গাঢ় সবুজ হ্রদের জল আর শূন্য ঘন কুয়াশার মধ্যে, কেবল তার কণ্ঠস্বরই একাকী প্রতিধ্বনিত হয়েছে।"
