  AwakerStory_96418_Content = {
    Text = "সমাধি-অস্থি নগরীর প্রতিষ্ঠাতা, ঘুলদের চিরন্তন রাজা।\nতাঁর ভোজসভা গভীরতম প্রত্যাশার যোগ্য — জাঁকজমকপূর্ণ ভোজনকক্ষ, মার্জিত নৃত্যপদক্ষেপ, আর সেই সব পরিশীলিত পদ যা তিনি নিজ হাতে মৃতদেহ থেকে প্রস্তুত করেছেন — নিশ্চিতভাবেই তা আপনার চিরস্মরণীয় হয়ে থাকবে।"
  },
  AwakerStory_96418_Title = {
    Text = "প্রাথমিক তথ্য"
  },
  AwakerStory_96418_UnlockDesc = {
    Text = "জাগরণকারী স্তর ১"
  },
  AwakerStory_96419_Content = {
    Text = "সমাধি নগরী ছেড়ে আসার পর, দুলেসাইন মানব সমাজে অত্যন্ত শক্তিশালী অভিযোজন ক্ষমতা প্রদর্শন করেছে। এটা অনিবার্য ছিল, মানব সমাজ তার কাছে নতুন শুরু নয়, বরং এক ধরনের প্রত্যাবর্তন।\nবাচনভঙ্গি, আচরণ, মর্যাদা, শিষ্টাচার……দুলেসাইনের সবকিছুই নিখুঁত, একজন রাজার যথাযোগ্য আভা বজায় রেখেও, দীর্ঘকাল উচ্চ পদে থাকার অহংকারের লেশমাত্র নেই।\nদুলেসাইন সামাজিকতা এড়িয়ে চলে না, কিন্তু রাজনীতি, অর্থনীতি, শিক্ষা প্রভৃতি বিষয়ে তার আগ্রহ নেই বললেই চলে, এসব অনুষ্ঠানে তাকে আকৃষ্ট করার একমাত্র কারণ——সুস্বাদু খাবার।\nস্বাদ গ্রহণের পাশাপাশি, দুলেসাইন রান্নাঘর সংক্রান্ত কাজেও অংশ নিতে উৎসাহী। উপকরণ নির্বাচন থেকে প্রক্রিয়াকরণ পদ্ধতি, মশলার ব্যবহার থেকে আঁচ নিয়ন্ত্রণ, দুলেসাইনের খাদ্য বিষয়ে গভীর জ্ঞান ও চমৎকার রুচি তার সাথে কথা বলা প্রতিটি মানুষকে মুগ্ধ করেছে, তারা আবিষ্কার করেছে যে, এর আগে তাদের কয়েক দশকের আহার ছিল শুধু বেঁচে থাকার জন্য গোগ্রাসে গেলা, বেঁচে থাকার জন্য খাওয়া একটি প্রাণীর সাথে কোনো পার্থক্য নেই। এমনকি জন্মগতভাবে স্বাদহীন হতভাগ্যরাও তার বর্ণনায় খাদ্যের শিল্প অনুভব করতে পারে, স্বাদের নবজন্ম লাভ করতে পারে।\nএটা অবশ্যই দুলেসাইনের শিষ্টাচারের সাথে সম্পর্কিত, সে স্পষ্টভাবে জানে মানুষ ও ঘুলের খাদ্য রুচির পার্থক্য। দুলেসাইন বিভিন্ন প্রজাতির মধ্যে পার্থক্যকে সম্মান করে, নিজের রুচি সবার উপর চাপিয়ে দেওয়ার ইচ্ছা তার নেই।\n「কেউ কেউ ভিন্নতাকে বিধর্মী বলে মনে করতে পছন্দ করে, আমার নগরীতে, এটা অত্যন্ত অমার্জিত আচরণ। আমি মানুষে মানুষে পার্থক্যকে সম্মান করি। এই পার্থক্যের মধ্যেই, আমরা খাদ্যের সৌন্দর্যের আরও বেশি সম্ভাবনা দেখতে পাই।」\n「কিন্তু তুমি আলাদা, গোপনরক্ষক। এই পৃথিবীতে এত বিশেষ একটি অস্তিত্ব হিসেবে……আমি মনে করি, তুমি নিশ্চয়ই আমার মতো, এই ধরনের আহারে, অতুলনীয় সৌন্দর্য অনুভব করতে পারবে……」\nএই কথা বলার সময়, দুলেসাইনের হাসি বেগুনি কুয়াশায় মিটমিট করছিল, যেন একটি মার্জিত বিষধর সাপ তোমার কানে ফিসফিস করছে, সেই দিনের অপেক্ষায় যখন সে তোমাকে ইডেন উদ্যান থেকে বের করে আনবে, অথবা সেখানে প্রলুব্ধ করে নিয়ে যাবে।"
  },
