  AwakerStory_96422_Content = {
    Text = "সে একসময় মনে করত, তার জীবন কেবল পরম স্বাদের সন্ধানে উৎসর্গিত।\nযুবরাজের দায়িত্ব, নিকটজনদের সাথে দূরত্ব, নৈতিকতার শৃঙ্খল... সে এই সমস্ত যন্ত্রণা পেছনে ফেলে স্বাদশিল্পের চরম সীমানা খুঁজে বেড়িয়েছে। যুবরাজ থেকে সম্রাট, মানব থেকে দেবতা — একটি মুহূর্তও থামেনি সে। সে রন্ধনের সকল পদ্ধতিতে পারদর্শী হয়ে উঠেছিল, প্রতিটি মৃতদেহের সূক্ষ্মতম পার্থক্য অনুভব করতে পারত। তার ইচ্ছা পূরণ হয়েছিল, কিন্তু আনন্দের পর, সে সবসময় অনুভব করত যেন কিছু একটা বাদ পড়ে গেছে।\nসেলিনের মৃতদেহ গ্রহণ করে তার আত্মার সাক্ষাৎ পাওয়ার সেই মুহূর্তেই সে সত্যিকার উপলব্ধিতে পৌঁছেছিল। সেই মৃতদেহগুলোর জীবদ্দশার কাহিনী, সেই আত্মাদের অপূর্ণ আকাঙ্ক্ষা — এগুলোই ছিল যা সে চিরকাল খুঁজে চলেছিল, চিরকাল আস্বাদন করে চলেছিল।\nভোজন হলো স্মরণের জন্য, প্রতিটি ভোজসভা হলো মৃতদের সাথে জীবিতদের পুনর্মিলন — দুলসাইন এই কথাগুলো সমাধি-নগরীর সিংহাসনে খোদাই করেছিলেন। যারা তাঁর আশ্রয় প্রার্থনা করে, তিনি তাদের দান করবেন স্মরণ ও চিরশান্তি।"
